# 3. CORS - Allow Frontend to connect
# NOTE: `allow_origins=["*"]` + `allow_credentials=True` is a CORS spec
# violation — Starlette silently drops the Access-Control-Allow-Origin
# header on preflight, browser rejects, request hangs until Railway 502s.
# List real origins explicitly and cover Vercel preview URLs with a regex.
_cors_origins = list({
    "http://localhost:5173",
    "http://127.0.0.1:5173",
    "https://ttmpc-thesis.vercel.app",
    "https://ttmpc-thesis-xi.vercel.app",
    FRONTEND_BASE_URL,
})

# Added before CORS so CORS wraps it: preflight (OPTIONS) requests are answered
# by CORS and never counted, and rate-limit 429s still get CORS headers.
app.add_middleware(SlowAPIMiddleware)

app.add_middleware(
    CORSMiddleware,
    allow_origins=_cors_origins,
    allow_origin_regex=r"https://ttmpc-thesis(?:-[a-zA-Z0-9-]+)?-gtabs2004s-projects\.vercel\.app",
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# Rate limiting + payload size guard
app.state.limiter = limiter
app.add_exception_handler(RateLimitExceeded, _rate_limit_exceeded_handler)
app.add_middleware(_MaxBodySizeMiddleware)


@app.exception_handler(RequestValidationError)
async def _validation_exception_handler(request: Request, exc: RequestValidationError):
    """Return a structured 422 with all field errors instead of FastAPI's default."""
    # A model_validator/field_validator that raises ValueError leaves that
    # exception object in the error's `ctx`. Handing it to JSONResponse raw
    # raised TypeError inside this handler, so every such validation failure
    # (e.g. a 72-month Consolidated loan on /api/loans/compute) came back as a
    # bare 500 "Internal Server Error" instead of a readable 422.
    return JSONResponse(
        status_code=422,
        content={
            "detail": jsonable_encoder(exc.errors(), custom_encoder={Exception: str}),
            "body": None,
        },
    )


@app.exception_handler(json.JSONDecodeError)
async def _json_decode_handler(request: Request, exc: json.JSONDecodeError):
    return JSONResponse(status_code=400, content={"detail": "Malformed JSON in request body."})


def _require_service_role():
    """Raise 503 on admin endpoints when no service role key is configured."""
    if not _has_service_role:
        raise HTTPException(
            status_code=503,
            detail="This admin endpoint requires a service role key. Set SUPABASE_SERVICE_ROLE_KEY in your environment.",
        )

