TWOPLACES = Decimal("0.01")
CBU_STARTING_CAPITAL = Decimal("0")
CBU_SHARE_VALUE = Decimal("1000")


# ============================================================================
# SECTION: Utility Helpers (Money, Dates, ID Generation, Loan Type Resolution)
# Pure helper functions for currency rounding, date math, sequence-ID builders
# (savings, CBU, BOD resolution), and loan-type/interest-rate lookups.
# ============================================================================

def money(value: Decimal) -> Decimal:
    return value.quantize(TWOPLACES, rounding=ROUND_HALF_UP)


def add_months(base_date: date, months_to_add: int) -> date:
    month_index = base_date.month - 1 + months_to_add
    new_year = base_date.year + month_index // 12
    new_month = month_index % 12 + 1
    max_day = calendar.monthrange(new_year, new_month)[1]
    new_day = min(base_date.day, max_day)
    return date(new_year, new_month, new_day)


def _month_end(year: int, month: int) -> date:
    return date(year, month, calendar.monthrange(year, month)[1])


def next_bonus_month_end(from_date: date) -> date:
    """The next Bonus due date (end of May or end of November) on/after
    from_date. Bonus always targets the nearest upcoming bonus (Q13/D6)."""
    for year in (from_date.year, from_date.year + 1):
        for month in (5, 11):
            candidate = _month_end(year, month)
            if candidate >= from_date:
                return candidate
    # Unreachable: the loop above always finds a candidate within 12 months.
    return _month_end(from_date.year + 1, 5)


def months_between_rounded_up(start: date, end: date) -> int:
    """Whole calendar months from start to end, rounding any partial month
    up (Q5: a partial first month is charged as a full month). Always >= 1."""
    whole_months = (end.year - start.year) * 12 + (end.month - start.month)
    if end.day < start.day:
        whole_months -= 1
    whole_months = max(0, whole_months)
    if end > add_months(start, whole_months):
        whole_months += 1
    return max(1, whole_months)


def decimal_to_float(value) -> float:
    return float(value) if value is not None else 0.0


def normalize_cashier_loan_type(loan_type_name: str | None) -> str:
    text = str(loan_type_name or "").strip().lower()
    if "consolidated" in text:
        return "consolidated"
    if "emergency" in text:
        return "emergency"
    if "bonus" in text:
        return "bonus"
    return "consolidated"


LOAN_TYPE_NAME_VARIANTS = {
    "CONSOLIDATED": ["consolidated", "consolidated loan"],
    "EMERGENCY": ["emergency", "emergency loan"],
    "BONUS": ["bonus", "bonus loan"],
    "NONMEMBER_BONUS": ["nonmember bonus loan", "non-member bonus loan", "non member bonus loan"],
    "KOICA": ["koica", "koica loan", "agri-business financial facility loan", "abff loan"],
}


def resolve_loan_type_code(loan_type: str, member_category: str | None = None) -> str:
    normalized_type = str(loan_type or "").strip().lower()
    normalized_category = str(member_category or "").strip().lower().replace("-", "_")

    if normalized_type == "consolidated":
        return "CONSOLIDATED"
    if normalized_type == "emergency":
        return "EMERGENCY"
    if normalized_type == "bonus":
        return "BONUS" if normalized_category == "regular" else "NONMEMBER_BONUS"

    return str(loan_type or "").strip().upper()


def fetch_loan_type_interest_rate_percent(loan_type_code: str | None, loan_type_name: str | None = None) -> Decimal | None:
    if not supabase:
        return None

    code = str(loan_type_code or "").strip().upper()
    name_text = str(loan_type_name or "").strip().lower()

    if not code and not name_text:
        return None

    def normalize_rate_percent(raw_rate: Decimal, row: dict | None, fallback_code: str) -> Decimal:
        rate_value = Decimal(str(raw_rate))
        if rate_value <= 0:
            return Decimal("0")
        # The `interest_rate` column stores the monthly rate in PERCENT
        # (e.g., 0.83 means 0.83%/month → 0.0083 decimal).
        # Do not auto-scale: a value < 1 is a legitimate sub-1% rate, not a decimal.
        return rate_value

    def extract_rate(row: dict | None) -> Decimal | None:
        if not row:
            return None

        raw_rate = next(
            (
                value
                for value in (
                    row.get("interest_rate"),
                    row.get("InterestRate"),
                    row.get("interestrate"),
                    row.get("interestRate"),
                )
                if value is not None
            ),
            None,
        )
        if raw_rate is None:
            return None

        rate = normalize_rate_percent(Decimal(str(raw_rate)), row, code)
        return rate if rate > 0 else None

    try:
        try:
            response = supabase.table("loan_types").select("*").execute()
            rows = response.data or []
        except Exception:
            response = supabase.table("loan_types").select("*").execute()
            rows = response.data or []

        matched_row = None

        if code:
            for row in rows:
                row_code = str(row.get("code") or "").strip().upper()
                if row_code and row_code == code:
                    matched_row = row
                    break

        if not matched_row and code:
            variants = LOAN_TYPE_NAME_VARIANTS.get(code, [])
            for row in rows:
                row_name = str(row.get("name") or "").strip().lower()
                if row_name in variants:
                    matched_row = row
                    break

        if not matched_row and name_text:
            for row in rows:
                row_name = str(row.get("name") or "").strip().lower()
                if row_name == name_text or (name_text and name_text in row_name):
                    matched_row = row
                    break

        if not matched_row:
            return None

        return extract_rate(matched_row)
    except Exception:
        return None


def build_sequence_id(prefix: str, sequence_number: int) -> str:
    safe_seq = max(int(sequence_number), 1)
    return f"{prefix}{safe_seq:03d}"


def build_savings_id(sequence_number: int) -> str:
    safe_seq = max(int(sequence_number), 1)
    return f"TTMPCRS_{safe_seq:03d}"


def build_savings_cashier_transaction_id(sequence_number: int) -> str:
    safe_seq = max(int(sequence_number), 1)
    return f"TTMPSVTXN_{safe_seq:06d}"


def parse_savings_id_sequence(value: str | None) -> int:
    text = str(value or "").strip()
    if not text.startswith("TTMPCRS_"):
        return 0
    sequence_part = text.split("TTMPCRS_", 1)[1]
    return int(sequence_part) if sequence_part.isdigit() else 0


def parse_savings_cashier_transaction_sequence(value: str | None) -> int:
    text = str(value or "").strip()
    if not text.startswith("TTMPSVTXN_"):
        return 0
    sequence_part = text.split("TTMPSVTXN_", 1)[1]
    return int(sequence_part) if sequence_part.isdigit() else 0


def get_next_savings_id() -> str:
    response = (
        supabase.table("Savings_Transactions")
        .select("Savings_ID")
        .execute()
    )
    max_sequence = 0
    for row in response.data or []:
        max_sequence = max(max_sequence, parse_savings_id_sequence(row.get("Savings_ID")))
    return build_savings_id(max_sequence + 1)


def get_next_savings_cashier_transaction_id() -> str:
    response = (
        supabase.table("savings_transaction_queue")
        .select("transaction_id")
        .execute()
    )
    max_sequence = 0
    for row in response.data or []:
        max_sequence = max(max_sequence, parse_savings_cashier_transaction_sequence(row.get("transaction_id")))
    return build_savings_cashier_transaction_id(max_sequence + 1)


def resolve_legacy_savings_id(account_number: str | None) -> str | None:
    """Inverse of resolve_savings_account_number: SA-NNNNNN -> legacy Savings_ID.

    Returns None when the bridge row has no legacy_savings_id (CSV-migrated
    accounts that were never opened in the legacy table)."""
    key = str(account_number or "").strip()
    if not key or not supabase:
        return None
    try:
        response = (
            supabase.table("savings_accounts")
            .select("legacy_savings_id")
            .eq("account_number", key)
            .limit(1)
            .execute()
        )
    except Exception:
        return None
    row = (response.data or [None])[0]
    return str(row["legacy_savings_id"]) if row and row.get("legacy_savings_id") else None


def resolve_savings_account_number(legacy_savings_id: str | None) -> str | None:
    """Map a legacy Savings_Transactions.Savings_ID to savings_accounts.account_number.

    Returns None if no bridge row exists yet (e.g. queue inserted before backfill ran).
    Callers should treat None as a non-fatal skip — legacy table remains authoritative
    until Phase 3 of the savings consolidation.
    """
    key = str(legacy_savings_id or "").strip()
    if not key or not supabase:
        return None
    try:
        response = (
            supabase.table("savings_accounts")
            .select("account_number")
            .eq("legacy_savings_id", key)
            .limit(1)
            .execute()
        )
    except Exception:
        return None
    row = (response.data or [None])[0]
    return str(row["account_number"]) if row and row.get("account_number") else None


def _receipt_no_for(source_type: str, source_id) -> str | None:
    """The receipt a database trigger issued for one transaction, or None
    (receipts SQL not applied yet, or the transaction gets no receipt)."""
    if not supabase or not source_id:
        return None
    try:
        rows = (
            supabase.table("receipts").select("receipt_no")
            .eq("source_type", source_type).eq("source_id", str(source_id))
            .limit(1).execute()
        ).data or []
        return rows[0].get("receipt_no") if rows else None
    except Exception as exc:  # noqa: BLE001
        logger.warning("receipt lookup failed for %s/%s: %s", source_type, source_id, exc)
        return None


def _insert_with_optional(table: str, row: dict, optional: dict):
    """Insert `row` plus `optional` columns; if the optional columns don't exist
    yet (receipts SQL not applied), insert without them."""
    payload = {**row, **{k: v for k, v in optional.items() if v}}
    try:
        return supabase.table(table).insert(payload).execute()
    except Exception as exc:
        if not any(k in str(exc) for k in optional):
            raise
        return supabase.table(table).insert(row).execute()


def mirror_savings_ledger_entry(
    *,
    account_number: str | None,
    entry_type: str,
    amount: Decimal,
    transaction_id: str,
    posted_by: str | None,
    remarks: str | None,
    recorded_by: str | None = None,
) -> None:
    """Best-effort write to public.savings_ledger.

    Failures are swallowed and logged — the legacy Savings_Transactions update
    is still the source of truth until Phase 3. The savings_ledger trigger
    auto-updates savings_accounts.balance, so a successful insert keeps the
    new tables in sync with the legacy ones.
    """
    if not account_number or not supabase or amount <= 0:
        return
    try:
        _insert_with_optional("savings_ledger", {
            "account_number": account_number,
            "entry_type": entry_type,
            "amount": decimal_to_float(amount),
            "reference": transaction_id,
            "source": "savings_queue_mirror",
            "remarks": remarks,
            "posted_by": posted_by or "system",
        }, {"recorded_by": recorded_by})
    except Exception as exc:  # noqa: BLE001
        print(f"[savings_ledger mirror] skipped ({entry_type} {amount} on {account_number}): {exc}")


def build_bod_resolution_number(reference_value: str | None, membership_date_value: str | None) -> str:
    clean_ref = "".join(ch for ch in str(reference_value or "").upper() if ch.isalnum())
    suffix = clean_ref[-6:] if clean_ref else datetime.utcnow().strftime("%H%M%S")
    year = str(membership_date_value or "")[:4]
    if not year.isdigit():
        year = str(datetime.utcnow().year)
    return f"BOD-RES-{year}-{suffix}"


def compute_missed_due_dates(due_date: str | None) -> Decimal:
    if not due_date:
        return Decimal("0")

    try:
        due_dt = datetime.fromisoformat(str(due_date).replace("Z", "+00:00"))
    except ValueError:
        return Decimal("0")

    now_dt = datetime.utcnow()
    if now_dt <= due_dt.replace(tzinfo=None):
        return Decimal("0")

    month_diff = (now_dt.year - due_dt.year) * 12 + (now_dt.month - due_dt.month)
    crossed_day = 1 if now_dt.day >= due_dt.day else 0
    return Decimal(max(month_diff + crossed_day, 1))


def parse_date_value(value: str | None) -> date | None:
    if not value:
        return None

    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00")).date()
    except ValueError:
        return None


def count_consecutive_zero_payment_periods(
    schedules: list[dict],
    payment_dates: list[date],
    as_of: date,
) -> int:
    """How many consecutive elapsed billing periods ended with no payment at all.

    A "period" is one unpaid schedule whose due date has passed. Counting runs
    backwards from the most recent elapsed period and stops at the first period
    that saw any payment, so a single partial payment breaks the streak.
    """
    elapsed_dues = sorted(
        d for d in (parse_date_value(s.get("due_date")) for s in schedules) if d and d <= as_of
    )
    if not elapsed_dues:
        return 0

    streak = 0
    for index in range(len(elapsed_dues) - 1, -1, -1):
        period_end = elapsed_dues[index]
        period_start = elapsed_dues[index - 1] if index > 0 else None
        paid_in_period = any(
            (period_start is None or pay_date > period_start) and pay_date <= period_end
            for pay_date in payment_dates
        )
        if paid_in_period:
            break
        streak += 1
    return streak


# Canonical penalty accrual (cooperative rule, confirmed 2026-10-13): the first
# penalty applies once THREE consecutive due dates have passed unpaid -- i.e. on
# the 3rd missed due date, which is the earliest unpaid due + 2 months -- and
# one more charge is added each month the loan stays behind. Each charge is the
# penalty rate (2%, 1% for bonus) of ONE installment, not of the whole balance.
# A loan can have only one schedule row at a time, so the missed due dates are
# counted from the earliest unpaid due rather than from separate rows.
# Legacy loans (any loan_payments_legacy row) are exempt entirely -- historical
# delinquency on migrated loans is not chargeable retroactively.
PENALTY_ZERO_PAYMENT_PERIODS = 3
PENALTY_GRACE_MONTHS = PENALTY_ZERO_PAYMENT_PERIODS - 1


def penalty_clock_start(earliest_unpaid_due: date | None, payment_dates: list[date] | None) -> date | None:
    """First missed due date of the CURRENT no-payment streak.

    Any validated payment resets the 3-month count (user rule, 2026-10-13):
    the clock starts at the first monthly due date after the last payment,
    counted on from the earliest unpaid due date. With no payment after that
    date, it is the earliest unpaid due date itself.
    """
    if not earliest_unpaid_due:
        return None
    last_payment = max(payment_dates) if payment_dates else None
    if not last_payment or last_payment < earliest_unpaid_due:
        return earliest_unpaid_due
    step = 0
    candidate = earliest_unpaid_due
    while candidate <= last_payment and step < 600:
        step += 1
        candidate = add_months(earliest_unpaid_due, step)
    return candidate


def penalty_installment_base(loan_row: dict | None, remaining_balance: Decimal) -> Decimal:
    """The one-installment amount a penalty charge is computed on.

    monthly_amortization, falling back to total payable / term for rows that
    never stored it; never more than what is still owed.
    """
    row = loan_row or {}
    installment = Decimal(str(row.get("monthly_amortization") or 0))
    if installment <= 0:
        term = int(row.get("term") or row.get("term_months") or 0)
        if term > 0:
            installment = money(_loan_total_payable(row) / Decimal(term))
    return max(min(installment, max(remaining_balance, Decimal("0"))), Decimal("0"))


def compute_loan_penalty(
    *,
    loan_type_code: str,
    remaining_balance: Decimal,
    earliest_unpaid_due: date | None,
    schedules: list[dict],
    payment_dates: list[date],
    is_legacy: bool,
    as_of: date | None = None,
    installment_amount: Decimal = Decimal("0"),
    original_principal: Decimal = Decimal("0"),
) -> Decimal:
    if is_legacy or not earliest_unpaid_due:
        return Decimal("0")

    today = as_of or datetime.utcnow().date()
    is_bonus = "bonus" in str(loan_type_code).strip().lower()

    if is_bonus:
        # Q2: missed = the day after the due date, no grace period (unlike
        # every other loan type's 3-month grace). Q3: base = original
        # principal only, fixed regardless of partial payments.
        grace_end = earliest_unpaid_due
        if today <= grace_end:
            return Decimal("0")
        base = max(original_principal, Decimal("0"))
    else:
        clock_start = penalty_clock_start(earliest_unpaid_due, payment_dates)
        grace_end = add_months(clock_start, PENALTY_GRACE_MONTHS)
        if today <= grace_end:
            return Decimal("0")
        base = min(max(installment_amount, Decimal("0")), max(remaining_balance, Decimal("0")))

    months_overdue = max(
        1,
        (today.year - grace_end.year) * 12 + (today.month - grace_end.month)
        + (1 if today.day >= grace_end.day else 0),
    )

    # 1% for bonus loans (incl. NONMEMBER_BONUS), 2% for everything else.
    rate = Decimal("0.01") if is_bonus else Decimal("0.02")
    return money(base * rate * Decimal(months_overdue))


def _server_side_penalty_for_loan(*, loan_id: str, loan_row: dict, schedules: list[dict]) -> Decimal:
    """Authoritative penalty for one loan, read straight from the database.

    Used on the write path so a client-supplied penalty is never trusted.
    Returns 0 rather than raising if history can't be read -- a lookup failure
    must not block the cashier from recording money that was actually handed over.
    """
    try:
        today = datetime.utcnow().date()

        legacy_rows = (
            supabase.table("loan_payments_legacy")
            .select("id")
            .eq("loan_id", loan_id)
            .limit(1)
            .execute()
        ).data or []
        if legacy_rows:
            return Decimal("0")

        payment_rows = (
            supabase.table("loan_payments")
            .select("amount_paid,payment_date,confirmation_status")
            .eq("loan_id", loan_id)
            .execute()
        ).data or []

        already_paid = Decimal("0")
        payment_dates: list[date] = []
        for row in payment_rows:
            if not is_validated_payment_status(row.get("confirmation_status")):
                continue
            already_paid += Decimal(str(row.get("amount_paid") or 0))
            parsed = parse_date_value(row.get("payment_date"))
            if parsed:
                payment_dates.append(parsed)

        remaining_balance = max(_loan_total_payable(loan_row) - already_paid, Decimal("0"))
        if remaining_balance <= 0:
            return Decimal("0")

        unpaid = [
            s for s in schedules
            if str(s.get("schedule_status") or "").strip().lower() not in {"paid", "completed", "closed"}
        ]
        earliest_unpaid_due = None
        for sched in unpaid:
            due = parse_date_value(sched.get("due_date"))
            if due and due < today and (earliest_unpaid_due is None or due < earliest_unpaid_due):
                earliest_unpaid_due = due

        loan_type_name = (loan_row.get("loan_type") or {}).get("name")
        original_principal = Decimal(str(loan_row.get("principal_amount") or loan_row.get("loan_amount") or 0))
        return accrue_loan_penalties(
            loan_id=loan_id,
            loan_type_code=resolve_loan_type_code(normalize_cashier_loan_type(loan_type_name)),
            remaining_balance=remaining_balance,
            schedules=unpaid,
            payment_dates=payment_dates,
            is_legacy=False,
            as_of=today,
            installment_amount=penalty_installment_base(loan_row, remaining_balance),
            original_principal=original_principal,
        )
    except Exception:
        return Decimal("0")


def build_cbu_deposit_id(sequence_number: int) -> str:
    safe_seq = max(int(sequence_number), 1)
    return f"CBUD_{safe_seq:03d}"


def resolve_member_full_name(member_row: dict) -> str:
    parts = [
        str(member_row.get("first_name") or "").strip(),
        str(member_row.get("middle_initial") or "").strip(),
        str(member_row.get("last_name") or "").strip(),
    ]
    name = " ".join(part for part in parts if part)
    return name or "Unknown Member"


def resolve_member_by_ref(member_ref: str) -> dict | None:
    clean_ref = str(member_ref or "").strip()
    if not clean_ref:
        return None
    try:
        by_uuid_response = (
            supabase.table("member")
            .select("*")
            .eq("id", clean_ref)
            .limit(1)
            .execute()
        )
        by_uuid_row = (by_uuid_response.data or [None])[0]
        if by_uuid_row:
            return by_uuid_row

        by_membership_response = (
            supabase.table("member")
            .select("*")
            .eq("membership_id", clean_ref)
            .limit(1)
            .execute()
        )
        by_membership_row = (by_membership_response.data or [None])[0]
        if by_membership_row:
            return by_membership_row

        by_membership_ilike_response = (
            supabase.table("member")
            .select("*")
            .ilike("membership_id", clean_ref)
            .limit(1)
            .execute()
        )
        return (by_membership_ilike_response.data or [None])[0]
    except Exception:
        return None


def resolve_personal_data_sheet_by_ref(member_ref: str) -> dict | None:
    clean_ref = str(member_ref or "").strip()
    if not clean_ref:
        return None
    try:
        by_membership_response = (
            supabase.table("personal_data_sheet")
            .select("*")
            .eq("membership_number_id", clean_ref)
            .limit(1)
            .execute()
        )
        by_membership_row = (by_membership_response.data or [None])[0]
        if by_membership_row:
            return by_membership_row

        by_pds_id_response = (
            supabase.table("personal_data_sheet")
            .select("*")
            .eq("personal_data_sheet_id", clean_ref)
            .limit(1)
            .execute()
        )
        return (by_pds_id_response.data or [None])[0]
    except Exception:
        return None


def accrue_loan_penalties(
    *,
    loan_id: str,
    loan_type_code: str,
    remaining_balance: Decimal,
    schedules: list[dict],
    payment_dates: list[date],
    is_legacy: bool,
    as_of: date | None = None,
    installment_amount: Decimal = Decimal("0"),
    original_principal: Decimal = Decimal("0"),
) -> Decimal:
    """Write one penalty row per overdue period, then return the unpaid total.

    Each row holds that single month's charge, so the accumulated penalty is the
    SUM of unpaid rows and keeps growing for every month the loan stays unpaid
    (spec 10). The unique key on (loan_id, period_due_date) makes repeated calls
    idempotent, so refreshing a screen cannot create duplicates (spec 11).

    Penalty starts on the 3rd consecutive missed due date (earliest unpaid due
    + PENALTY_GRACE_MONTHS); each charge is rate x one installment. Bonus loans
    (Q2/Q3) use no grace period and a fixed original-principal base instead —
    see the is_bonus branch below.
    """
    today = as_of or datetime.utcnow().date()
    is_bonus = "bonus" in str(loan_type_code).strip().lower()

    if is_legacy or remaining_balance <= 0:
        return _unpaid_penalty_total(loan_id)

    unpaid = [
        s for s in schedules
        if str(s.get("schedule_status") or "").strip().lower() not in {"paid", "completed", "closed"}
    ]
    earliest_unpaid_due = None
    for sched in unpaid:
        due = parse_date_value(sched.get("due_date"))
        if due and due < today and (earliest_unpaid_due is None or due < earliest_unpaid_due):
            earliest_unpaid_due = due
    if not earliest_unpaid_due:
        return _unpaid_penalty_total(loan_id)

    if is_bonus:
        grace_end = earliest_unpaid_due
    else:
        # A payment restarts the count of months without payment.
        grace_end = add_months(penalty_clock_start(earliest_unpaid_due, payment_dates), PENALTY_GRACE_MONTHS)
    if today <= grace_end:
        return _unpaid_penalty_total(loan_id)

    rate = Decimal("0.01") if is_bonus else Decimal("0.02")

    base = max(original_principal, Decimal("0")) if is_bonus else min(max(installment_amount, Decimal("0")), remaining_balance)
    if base <= 0:
        return _unpaid_penalty_total(loan_id)

    # One charge for the 3rd missed month as soon as its due date passes, then
    # one additional charge per completed month after that.
    period = grace_end
    charges: list[dict] = []
    while True:
        if period > today:
            break
        charges.append({
            "loan_id": loan_id,
            "period_due_date": period.isoformat(),
            "amount": decimal_to_float(money(base * rate)),
            "basis_balance": decimal_to_float(money(base)),
            "rate_percent": decimal_to_float(rate * Decimal("100")),
        })
        period = add_months(period, 1)

    for charge in charges:
        try:
            supabase.table("loan_penalties").upsert(
                charge, on_conflict="loan_id,period_due_date"
            ).execute()
        except Exception:
            # Table not migrated yet, or the row already exists -- neither is
            # worth failing a payment over.
            pass

    return _unpaid_penalty_total(loan_id)


@lru_cache(maxsize=512)
def _unpaid_penalty_total_cached(loan_id: str, cache_bucket: int) -> Decimal:
    try:
        rows = (
            supabase.table("loan_penalties")
            .select("amount,paid_amount,is_paid")
            .eq("loan_id", loan_id)
            .eq("is_paid", False)
            .execute()
        ).data or []
        return sum(
            (Decimal(str(r.get("amount") or 0)) - Decimal(str(r.get("paid_amount") or 0)))
            for r in rows
        ) or Decimal("0")
    except Exception:
        return Decimal("0")


def _unpaid_penalty_total(loan_id: str) -> Decimal:
    """Accumulated unpaid penalty for a loan: the sum of its unsettled charges.

    Cached in 5-second buckets so the several early-return paths in
    accrue_loan_penalties() don't each issue their own query for the same loan
    within one request. Short enough that a settlement is reflected promptly.
    """
    return _unpaid_penalty_total_cached(loan_id, int(time.time()) // 5)


def allocate_payment(
    *,
    payment_amount: Decimal,
    penalty_due: Decimal,
    arrears_due: Decimal,
    current_due: Decimal,
) -> dict[str, Decimal]:
    """Split a payment: penalty -> arrears -> current installment -> credit.

    Charges are cleared first, then the oldest debt, then the current period;
    whatever survives becomes credit against the next installment (spec 13/14).
    """
    remaining = max(payment_amount, Decimal("0"))

    to_penalty = min(remaining, max(penalty_due, Decimal("0")))
    remaining -= to_penalty

    to_arrears = min(remaining, max(arrears_due, Decimal("0")))
    remaining -= to_arrears

    to_current = min(remaining, max(current_due, Decimal("0")))
    remaining -= to_current

    return {
        "penalty": money(to_penalty),
        "arrears": money(to_arrears),
        "current": money(to_current),
        "credit": money(remaining),
    }


def settle_penalties_with_payment(loan_id: str, amount: Decimal, payment_id: str | None) -> None:
    """Apply `amount` to the oldest unpaid penalty rows first."""
    if amount <= 0:
        return
    try:
        rows = (
            supabase.table("loan_penalties")
            .select("id,amount,paid_amount")
            .eq("loan_id", loan_id)
            .eq("is_paid", False)
            .order("period_due_date")
            .execute()
        ).data or []
    except Exception:
        return

    left = amount
    for row in rows:
        if left <= 0:
            break
        owed = Decimal(str(row.get("amount") or 0)) - Decimal(str(row.get("paid_amount") or 0))
        if owed <= 0:
            continue
        applied = min(left, owed)
        left -= applied
        new_paid = Decimal(str(row.get("paid_amount") or 0)) + applied
        update = {"paid_amount": decimal_to_float(money(new_paid))}
        if new_paid + Decimal("0.005") >= Decimal(str(row.get("amount") or 0)):
            update["is_paid"] = True
            update["paid_at"] = datetime.utcnow().isoformat()
            if payment_id:
                update["paid_by_payment_id"] = payment_id
        try:
            supabase.table("loan_penalties").update(update).eq("id", row.get("id")).execute()
        except Exception:
            pass


def current_installment_no_can_roll(schedule_row: dict, term_months: int) -> bool:
    """True when a later installment exists to carry a shortfall into.

    On the final installment there is nothing to roll forward to, so the period
    must stay open for the remaining amount instead of being closed as
    partially_paid -- otherwise the shortfall would drop off the schedule.
    """
    try:
        installment_no = int(schedule_row.get("installment_no") or 1)
    except (TypeError, ValueError):
        return False
    return term_months > 0 and installment_no < term_months


def build_single_schedule_row(
    loan_type: str,
    principal: Decimal,
    term_months: int,
    monthly_rate_decimal: Decimal,
    due_date: date,
    loan_id: str,
    installment_no: int,
    remaining_principal_before: Decimal,
    start_sequence_number: int,
    carried_arrears: Decimal = Decimal("0"),
    applied_credit: Decimal = Decimal("0"),
) -> dict:
    if term_months <= 0:
        raise ValueError("term_months must be greater than zero")

    penalty_rate_percent = Decimal("1") if loan_type == "bonus" else Decimal("2")

    if loan_type == "emergency":
        # Mirror /api/loans/compute: equal principal in centavos with a
        # last-month cleanup, interest on the balance AFTER the principal
        # payment for the month.
        total_principal_cents = int(
            (principal * Decimal("100")).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
        )
        monthly_principal_cents = int(Decimal(total_principal_cents) / Decimal(term_months))
        balance_before_cents = int(
            (max(remaining_principal_before, Decimal("0")) * Decimal("100")).quantize(
                Decimal("1"), rounding=ROUND_HALF_UP
            )
        )

        if installment_no >= term_months:
            principal_cents = balance_before_cents
        else:
            principal_cents = min(monthly_principal_cents, balance_before_cents)

        ending_balance_cents = balance_before_cents - principal_cents
        interest_cents = int(
            (Decimal(ending_balance_cents) * monthly_rate_decimal).quantize(
                Decimal("1"), rounding=ROUND_HALF_UP
            )
        )

        principal_component = Decimal(principal_cents) / Decimal("100")
        interest_component = Decimal(interest_cents) / Decimal("100")
        expected_amount = Decimal(principal_cents + interest_cents) / Decimal("100")
        remaining_after = Decimal(ending_balance_cents) / Decimal("100")
    elif loan_type == "bonus":
        # Saka upfront-deduction model (Bookkeeper-confirmed 2026-10-18):
        # interest for the whole term was already deducted from proceeds at
        # release, so only the principal is owed at the bonus month. There
        # is only ever installment #1 (no next row is created after payoff).
        principal_component = max(remaining_principal_before, Decimal("0"))
        interest_component = Decimal("0")
        expected_amount = principal_component
        remaining_after = Decimal("0")
    else:
        principal_component = money(principal / Decimal(term_months))
        interest_component = money(principal * monthly_rate_decimal)
        expected_amount = money(principal_component + interest_component)
        remaining_after = max(remaining_principal_before - principal_component, Decimal("0"))

    # Net the two carry-forwards against each other -- a period either fell
    # short or ran over, never both -- so the row records one or the other.
    net_carry = money(max(carried_arrears, Decimal("0")) - max(applied_credit, Decimal("0")))
    row_arrears = net_carry if net_carry > 0 else Decimal("0")
    row_credit = -net_carry if net_carry < 0 else Decimal("0")

    # Every installment always asks for its full amortization (confirmed
    # 2026-10-17): credit only ever closes a WHOLE installment outright
    # (Prepaid, 0 due) -- it never partially discounts one. The moment what's
    # left is less than a full installment, it is NOT applied here; the
    # caller banks it instead (loans.banked_credit) until the loan's final
    # installment, which is the only place a partial credit amount may land.
    if row_credit >= expected_amount:
        applied_now, leftover_credit = expected_amount, money(row_credit - expected_amount)
    else:
        applied_now, leftover_credit = Decimal("0"), row_credit
    row_credit = applied_now

    return {
        "schedule_id": build_sequence_id("TTMPCLP_SI_", start_sequence_number),
        "loan_id": loan_id,
        "installment_no": installment_no,
        "due_date": due_date.isoformat(),
        "expected_amount": decimal_to_float(expected_amount),
        "expected_principal": decimal_to_float(principal_component),
        "expected_interest": decimal_to_float(interest_component),
        "penalty": decimal_to_float(penalty_rate_percent),
        "salary_schedule_id": None,
        "remaining_principal": decimal_to_float(remaining_after),
        "principal_component": decimal_to_float(principal_component),
        "interest_component": decimal_to_float(interest_component),
        "carried_arrears": decimal_to_float(row_arrears),
        "applied_credit": decimal_to_float(row_credit),
        "schedule_status": "Unpaid",
        # Not a DB column -- read by the caller to update loans.banked_credit,
        # then discarded before the dict is inserted into loan_schedules.
        "_leftover_credit": decimal_to_float(leftover_credit),
    }


# ---------------------------------------------------------------------------
# Roll-forward of missed installments (cooperative rule, confirmed 2026-10-13).
#
# A loan keeps ONE open schedule row. When its due date passes with nothing
# paid, the month is MISSED: the row is closed as 'partially_paid' (zero paid)
# and its full bill is carried into the next installment as carried_arrears.
# This repeats until the open row is the installment that is not yet past due,
# so a payment always lands on the CURRENT installment, with every missed
# amount accumulated on it. Once a payment clears the carried arrears,
# close_settled_missed_installments() flips the missed rows to Paid -- that is
# also what stops the penalty clock (penalty counts from the earliest row that
# is not Paid).
#
# Runs when the cashier opens a loan, when a payment is submitted and when the
# Bookkeeper approves one -- never on a timer. Legacy loans (any
# loan_payments_legacy row) are skipped: their reconstructed due dates are
# years old and must not generate rows.
# ---------------------------------------------------------------------------
OPEN_SCHEDULE_STATUSES = {"unpaid", "pending", "overdue"}
_ROLL_FORWARD_MAX_STEPS = 120


def roll_forward_missed_installments(loan_id: str, as_of: date | None = None) -> int:
    """Close past-due unpaid installments and carry them forward. Returns how
    many installments were rolled. Never raises: a failure leaves the loan as
    it was, which is the pre-roll-forward behaviour."""
    if not supabase or not loan_id:
        return 0
    today = as_of or datetime.utcnow().date()
    rolled = 0
    try:
        legacy = (
            supabase.table("loan_payments_legacy").select("id").eq("loan_id", loan_id).limit(1).execute()
        ).data or []
        if legacy:
            return 0

        loan_row = (
            supabase.table("loans")
            .select(
                "control_number,loan_amount,principal_amount,interest_rate,term,loan_status,banked_credit,"
                "loan_type:loan_type_id(name)"
            )
            .eq("control_number", loan_id)
            .limit(1)
            .execute()
        ).data
        loan_row = (loan_row or [None])[0]
        if not loan_row:
            return 0
        if str(loan_row.get("loan_status") or "").strip().lower() in {"fully paid", "completed", "closed"}:
            return 0

        principal = Decimal(str(loan_row.get("principal_amount") or loan_row.get("loan_amount") or 0))
        term_months = int(loan_row.get("term") or 0)
        if principal <= 0 or term_months <= 0:
            return 0
        loan_type_name = (loan_row.get("loan_type") or {}).get("name")
        normalized_loan_type = normalize_cashier_loan_type(loan_type_name)
        stored_rate = loan_row.get("interest_rate")
        monthly_rate_decimal = resolve_monthly_rate_decimal(
            normalized_loan_type,
            Decimal(str(stored_rate)) if stored_rate is not None else None,
            loan_type_code=resolve_loan_type_code(normalized_loan_type),
            loan_type_name=loan_type_name,
        )
        if monthly_rate_decimal <= 0:
            return 0

        for _ in range(_ROLL_FORWARD_MAX_STEPS):
            open_rows = (
                supabase.table("loan_schedules")
                .select(
                    "id,installment_no,due_date,schedule_status,expected_amount,"
                    "remaining_principal,carried_arrears,applied_credit"
                )
                .eq("loan_id", loan_id)
                .in_("schedule_status", ["Unpaid", "unpaid", "Pending", "pending", "Overdue", "overdue"])
                .order("installment_no")
                .limit(1)
                .execute()
            ).data or []
            if not open_rows:
                break
            row = open_rows[0]
            due = parse_date_value(row.get("due_date"))
            installment_no = int(row.get("installment_no") or 0)
            # Not past due yet (it is the current installment), or it is the
            # last one -- nothing to carry into, it simply stays overdue.
            if not due or due >= today or installment_no <= 0 or installment_no >= term_months:
                break

            # Only a month with NOTHING validated against it is a missed month.
            # A short payment is closed by the approval step, not here.
            paid_rows = (
                supabase.table("loan_payments")
                .select("amount_paid")
                .eq("schedule_id", row.get("id"))
                .in_("confirmation_status", ["validated", "confirmed", "bookkeeper_confirmed", "approved"])
                .execute()
            ).data or []
            if any(Decimal(str(p.get("amount_paid") or 0)) > 0 for p in paid_rows):
                break

            row_bill = (
                Decimal(str(row.get("expected_amount") or 0))
                + Decimal(str(row.get("carried_arrears") or 0))
                - Decimal(str(row.get("applied_credit") or 0))
            )
            carry_arrears = money(max(row_bill, Decimal("0")))
            carry_credit = money(max(-row_bill, Decimal("0")))

            try:
                count_resp = (
                    supabase.table("loan_schedules").select("id", count="exact").limit(1).execute()
                )
                next_sequence_number = int(count_resp.count or 0) + 1
            except Exception:
                next_sequence_number = 0

            next_row = build_single_schedule_row(
                loan_type=normalized_loan_type,
                principal=principal,
                term_months=term_months,
                monthly_rate_decimal=monthly_rate_decimal,
                due_date=add_months(due, 1),
                loan_id=loan_id,
                installment_no=installment_no + 1,
                remaining_principal_before=Decimal(str(row.get("remaining_principal") or 0)),
                start_sequence_number=next_sequence_number,
                carried_arrears=carry_arrears,
                applied_credit=carry_credit,
            )
            leftover_credit = Decimal(str(next_row.pop("_leftover_credit", 0) or 0))
            if leftover_credit > 0:
                try:
                    supabase.table("loans").update(
                        {"banked_credit": decimal_to_float(
                            Decimal(str(loan_row.get("banked_credit") or 0)) + leftover_credit
                        )}
                    ).eq("control_number", loan_id).execute()
                except Exception:
                    logging.exception("Could not bank leftover credit for loan %s.", loan_id)

            # Close first: only one open row per loan is allowed (unique index).
            supabase.table("loan_schedules").update(
                {"schedule_status": "partially_paid"}
            ).eq("id", row.get("id")).execute()

            inserted = False
            for _attempt in range(3):
                try:
                    supabase.table("loan_schedules").insert(next_row).execute()
                    inserted = True
                    break
                except Exception as insert_err:
                    text = str(insert_err).lower()
                    if "duplicate" in text or "unique" in text:
                        next_row["schedule_id"] = f"TTMPCLP_SI_{uuid4().hex[:12].upper()}"
                        continue
                    break
            if not inserted:
                # Put the loan back exactly as it was rather than leave it with
                # no open installment.
                supabase.table("loan_schedules").update(
                    {"schedule_status": "Unpaid"}
                ).eq("id", row.get("id")).execute()
                logging.warning("Roll-forward stopped for loan %s at installment %s.", loan_id, installment_no)
                break
            rolled += 1
    except Exception:
        logging.exception("Roll-forward failed for loan %s; left unchanged from that point.", loan_id)
    return rolled


def close_settled_missed_installments(loan_id: str) -> None:
    """Once the carried arrears are paid off, the missed months they came from
    are settled: mark them Paid so the penalty clock (earliest row not Paid)
    stops."""
    try:
        supabase.table("loan_schedules").update({"schedule_status": "Paid"}).eq(
            "loan_id", loan_id
        ).eq("schedule_status", "partially_paid").execute()
    except Exception:
        logging.exception("Could not close settled missed installments for loan %s.", loan_id)


def sanitize_monthly_rate_percent(
    stored_rate,
    loan_type_rate,
    sanity_max_percent: float = 5.0,
) -> float:
    """
    Return a clean monthly interest rate in PERCENT for display/reporting.
    Legacy data may hold a corrupted snapshot (e.g., 8.3 stored when 0.83 was
    intended). If the stored value exceeds the realistic ceiling, fall back to
    the loan_types row which is the current source of truth.
    """
    try:
        stored = float(stored_rate) if stored_rate is not None else None
    except (TypeError, ValueError):
        stored = None
    try:
        lt_rate = float(loan_type_rate) if loan_type_rate is not None else None
    except (TypeError, ValueError):
        lt_rate = None

    if stored is not None and 0 < stored <= sanity_max_percent:
        return stored
    if lt_rate is not None and 0 < lt_rate <= sanity_max_percent:
        return lt_rate
    return stored if stored is not None else (lt_rate or 0.0)


def resolve_monthly_rate_decimal(
    loan_type: str,
    interest_rate_percent: Decimal | None,
    loan_type_code: str | None = None,
    loan_type_name: str | None = None,
) -> Decimal:
    if interest_rate_percent is not None and interest_rate_percent > 0:
        return Decimal(str(interest_rate_percent)) / Decimal("100")

    resolved_code = str(loan_type_code or "").strip().upper() or resolve_loan_type_code(loan_type)
    configured_rate_percent = fetch_loan_type_interest_rate_percent(resolved_code, loan_type_name)
    if configured_rate_percent is not None and configured_rate_percent > 0:
        return configured_rate_percent / Decimal("100")

    return Decimal("0")


_FEE_POLICY_FALLBACKS = {
    "CONSOLIDATED": {
        "service_fee_mode": "bracket",
        "service_fee_per_bracket": Decimal("100"),
        "service_fee_bracket_size": Decimal("50000"),
        "cbu_rate": Decimal("0.02"),
        "insurance_per_thousand": Decimal("1.35"),
        "notarial_fee": Decimal("100"),
    },
    "EMERGENCY": {
        "service_fee_mode": "flat",
        "service_fee_per_bracket": Decimal("100"),
        "service_fee_bracket_size": Decimal("999999999"),
        "cbu_rate": Decimal("0.02"),
        "insurance_per_thousand": Decimal("0"),
        "notarial_fee": Decimal("0"),
    },
    "BONUS": {
        "service_fee_mode": "flat",
        "service_fee_per_bracket": Decimal("100"),
        "service_fee_bracket_size": Decimal("999999999"),
        "cbu_rate": Decimal("0"),
        "insurance_per_thousand": Decimal("0"),
        "notarial_fee": Decimal("0"),
    },
    "NONMEMBER_BONUS": {
        "service_fee_mode": "flat",
        "service_fee_per_bracket": Decimal("100"),
        "service_fee_bracket_size": Decimal("999999999"),
        "cbu_rate": Decimal("0"),
        "insurance_per_thousand": Decimal("0"),
        "notarial_fee": Decimal("0"),
    },
}


def resolve_fee_policy(loan_type_code: str) -> dict:
    """Fetch the fee policy row for the given loan type code, falling back
    to the seeded defaults if the table is unavailable or has no row."""
    code = str(loan_type_code or "").strip().upper()
    if not code:
        return _FEE_POLICY_FALLBACKS.get("CONSOLIDATED", {})
    if supabase is not None:
        try:
            response = (
                supabase.table("loan_fee_policies")
                .select(
                    "service_fee_mode,service_fee_per_bracket,service_fee_bracket_size,"
                    "cbu_rate,insurance_per_thousand,notarial_fee"
                )
                .eq("loan_type_code", code)
                .limit(1)
                .execute()
            )
            row = (response.data or [None])[0]
            if row:
                return {
                    "service_fee_mode": row.get("service_fee_mode") or "none",
                    "service_fee_per_bracket": Decimal(str(row.get("service_fee_per_bracket") or 0)),
                    "service_fee_bracket_size": Decimal(str(row.get("service_fee_bracket_size") or 0)),
                    "cbu_rate": Decimal(str(row.get("cbu_rate") or 0)),
                    "insurance_per_thousand": Decimal(str(row.get("insurance_per_thousand") or 0)),
                    "notarial_fee": Decimal(str(row.get("notarial_fee") or 0)),
                }
        except Exception:
            pass
    return _FEE_POLICY_FALLBACKS.get(code, _FEE_POLICY_FALLBACKS["BONUS"])


def compute_service_fee(policy: dict, principal: Decimal) -> Decimal:
    mode = str(policy.get("service_fee_mode") or "none").lower()
    if mode == "none":
        return Decimal("0")
    per = Decimal(str(policy.get("service_fee_per_bracket") or 0))
    if mode == "flat":
        return money(per)
    size = Decimal(str(policy.get("service_fee_bracket_size") or 0))
    if size <= 0 or per <= 0 or principal <= 0:
        return Decimal("0")
    brackets = ((int(principal) - 1) // int(size)) + 1
    return money(Decimal(brackets) * per)


# ============================================================================
# SECTION: Loan Computation
# Endpoint that returns amortization schedules, fees, insurance, service fees,
# and monthly breakdowns for Consolidated / Bonus / Emergency loan payloads.
# ============================================================================

@app.post("/api/loans/compute")
async def compute_loan(payload: LoanComputeRequest):
    principal = Decimal(str(payload.principal))
    term = payload.term_months
    first_due_date = payload.first_due_date or date.today()

    monthly_breakdown: list[MonthlyBreakdownRow] = []

    service_fee = Decimal("0")
    cbu_deduction = Decimal("0")
    insurance_fee = Decimal("0")
    notarial_fee = Decimal("0")

    monthly_amortization = Decimal("0")

    if payload.loan_type == "consolidated":
        monthly_rate = resolve_monthly_rate_decimal("consolidated", None, loan_type_code="CONSOLIDATED")
        if monthly_rate <= 0:
            raise HTTPException(status_code=400, detail="Interest rate for CONSOLIDATED is not configured in loan_types.")

        principal_component = money(principal / Decimal(term))
        interest_component = money(principal * monthly_rate)
        monthly_amortization = money(principal_component + interest_component)

        fee_policy = resolve_fee_policy("CONSOLIDATED")
        service_fee = compute_service_fee(fee_policy, principal)
        insurance_fee = money((principal * fee_policy["insurance_per_thousand"]) / Decimal("1000"))
        cbu_deduction = money(principal * fee_policy["cbu_rate"])
        notarial_fee = money(fee_policy["notarial_fee"])

        for installment_no in range(1, term + 1):
            monthly_breakdown.append(
                MonthlyBreakdownRow(
                    installment_no=installment_no,
                    due_date=add_months(first_due_date, installment_no - 1),
                    expected_amount=monthly_amortization,
                    principal_component=principal_component,
                    interest_component=interest_component,
                )
            )

    elif payload.loan_type == "emergency":
        monthly_rate = resolve_monthly_rate_decimal("emergency", None, loan_type_code="EMERGENCY")
        if monthly_rate <= 0:
            raise HTTPException(status_code=400, detail="Interest rate for EMERGENCY is not configured in loan_types.")

        fee_policy = resolve_fee_policy("EMERGENCY")
        service_fee = compute_service_fee(fee_policy, principal)
        cbu_deduction = money(principal * fee_policy["cbu_rate"])
        insurance_fee = money((principal * fee_policy["insurance_per_thousand"]) / Decimal("1000"))
        notarial_fee = money(fee_policy["notarial_fee"])

        # Equal-principal, declining-interest schedule (matches client UI).
        # Interest each month is computed on the balance AFTER the principal
        # payment for that month. Final month does a cents cleanup so the
        # ending balance lands exactly on zero. Work in integer centavos to
        # avoid floating drift.
        total_principal_cents = int((principal * Decimal("100")).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        monthly_principal_cents = int(Decimal(total_principal_cents) / Decimal(term))
        accumulated_principal_cents = 0
        balance_cents = total_principal_cents
        first_total_payment = Decimal("0")

        for installment_no in range(1, term + 1):
            starting_balance_cents = balance_cents

            if installment_no < term:
                principal_paid_cents = monthly_principal_cents
            else:
                principal_paid_cents = total_principal_cents - accumulated_principal_cents

            ending_balance_cents = starting_balance_cents - principal_paid_cents
            interest_paid_cents = int(
                (Decimal(ending_balance_cents) * monthly_rate).quantize(
                    Decimal("1"), rounding=ROUND_HALF_UP
                )
            )
            total_payment_cents = principal_paid_cents + interest_paid_cents

            balance_cents = ending_balance_cents
            accumulated_principal_cents += principal_paid_cents

            principal_component = Decimal(principal_paid_cents) / Decimal("100")
            interest_component = Decimal(interest_paid_cents) / Decimal("100")
            expected_amount = Decimal(total_payment_cents) / Decimal("100")

            if installment_no == 1:
                first_total_payment = expected_amount

            monthly_breakdown.append(
                MonthlyBreakdownRow(
                    installment_no=installment_no,
                    due_date=add_months(first_due_date, installment_no - 1),
                    expected_amount=expected_amount,
                    principal_component=principal_component,
                    interest_component=interest_component,
                )
            )

        monthly_amortization = first_total_payment

    elif payload.loan_type == "bonus":
        # Bonus uses upfront "Saka" interest deduction, confirmed by the
        # Bookkeeper (2026-10-18): the full interest spanning release to the
        # target bonus month is deducted at release. The borrower receives
        # principal minus that upfront interest (and other fees) as net
        # proceeds, and owes only the full principal at the bonus month —
        # interest is already fully satisfied at release. See
        # BONUS_LOAN_BOOKKEEPER_SPEC.md.
        member_category = str(payload.member_category).strip().lower()
        loan_type_code = resolve_loan_type_code("bonus", member_category)
        monthly_rate = resolve_monthly_rate_decimal("bonus", None, loan_type_code=loan_type_code)
        if monthly_rate <= 0:
            raise HTTPException(status_code=400, detail=f"Interest rate for {loan_type_code} is not configured in loan_types.")

        upfront_interest = money(principal * monthly_rate * Decimal(term))
        principal_component = principal
        interest_component = upfront_interest
        # What the borrower owes at the bonus month: principal only, since
        # interest was already deducted at release.
        expected_amount = principal_component
        monthly_amortization = expected_amount

        fee_policy = resolve_fee_policy(loan_type_code)
        service_fee = compute_service_fee(fee_policy, principal)
        cbu_deduction = money(principal * fee_policy["cbu_rate"])
        insurance_fee = money((principal * fee_policy["insurance_per_thousand"]) / Decimal("1000"))
        notarial_fee = money(fee_policy["notarial_fee"])

        monthly_breakdown.append(
            MonthlyBreakdownRow(
                installment_no=1,
                due_date=add_months(first_due_date, term - 1),
                expected_amount=expected_amount,
                principal_component=principal_component,
                interest_component=interest_component,
            )
        )

    total_interest = money(sum((row.interest_component for row in monthly_breakdown), Decimal("0")))
    if payload.loan_type == "bonus":
        # Upfront interest is deducted from proceeds at release, same as the
        # other fee deductions — net proceeds must not go negative.
        total_deductions = money(service_fee + cbu_deduction + insurance_fee + notarial_fee + total_interest)
        net_proceeds = money(principal - total_deductions)
        if net_proceeds <= 0:
            raise HTTPException(
                status_code=400,
                detail="Net proceeds would be zero or negative after upfront interest and fees — reduce the term or principal.",
            )
    else:
        total_deductions = money(service_fee + cbu_deduction + insurance_fee + notarial_fee)
        net_proceeds = money(principal - total_deductions)

    deductions_out = {
        "service_fee": service_fee,
        "cbu_deduction": cbu_deduction,
        "insurance_fee": insurance_fee,
        "notarial_fee": notarial_fee,
    }
    if payload.loan_type == "bonus":
        deductions_out["bonus_upfront_interest"] = total_interest

    return {
        "success": True,
        "data": LoanComputeResponse(
            loan_type=payload.loan_type,
            principal=money(principal),
            term_months=term,
            monthly_amortization=monthly_amortization,
            total_interest=total_interest,
            total_deductions=total_deductions,
            net_proceeds=net_proceeds,
            deductions=deductions_out,
            monthly_breakdown=monthly_breakdown,
        ).model_dump(mode="json"),
    }


# ============================================================================
# SECTION: Cashier — Loan Payments & Disbursements
# Cashier portal endpoints for listing payable/disbursable loans, creating loan
# payments, and disbursing approved loans.
# ============================================================================

# Bonus loan policy: 2%/month for members, 3%/month for non-members. Stored
# loans.interest_rate on imported Bonus loans holds the whole-term total.
BONUS_MONTHLY_RATE_MEMBER = 2.0
BONUS_MONTHLY_RATE_NONMEMBER = 3.0


def _nonmember_payments_by_loan(loan_ids: list[str]) -> dict[str, list[dict]]:
    """loan_id -> payment rows from nonmember_loan_payments (oldest first).
    Empty if the table isn't migrated yet (nonmember_bonus_payments_schema.sql)."""
    out: dict[str, list[dict]] = {}
    ids = [i for i in dict.fromkeys(loan_ids) if i]
    for i in range(0, len(ids), 300):
        try:
            rows = (
                supabase.table("nonmember_loan_payments")
                .select("id,loan_id,amount_paid,payment_date,or_no,source")
                .in_("loan_id", ids[i:i + 300])
                .order("payment_date")
                .execute()
            ).data or []
        except Exception as e:
            logger.warning("nonmember_loan_payments lookup failed: %s", e)
            return {}
        for r in rows:
            out.setdefault(str(r.get("loan_id")), []).append(r)
    return out


def _ledger_says_fully_paid(loan_row: dict | None) -> bool:
    # Imported historical loans carry principal-only installments (interest was
    # settled at release or via renewal offset), so replaying them against the
    # add-on total_payable never reaches zero. The coop ledger's own
    # loan_status is authoritative for these.
    return str((loan_row or {}).get("loan_status") or "").strip().lower() == "fully paid"


@app.get("/api/cashier/loan-payments/loans")
async def get_cashier_loans_for_payments():
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        _cols_full = (
            "control_number,member_id,loan_amount,principal_amount,interest_rate,term,loan_status,application_date,disbursal_date,monthly_amortization,total_interest,"
            "member:member_id(first_name,last_name,is_bona_fide),loan_type:loan_type_id(name,interest_rate)"
        )
        _cols_min = _cols_full.replace("monthly_amortization,", "")

        # Paginated: PostgREST caps each response at 1000 rows, which silently
        # dropped every collectible loan older than the newest 1000.
        def _fetch_all_loans(cols: str) -> list[dict]:
            out: list[dict] = []
            offset = 0
            while True:
                batch = (
                    supabase.table("loans").select(cols)
                    .order("application_date", desc=True)
                    .range(offset, offset + 999)
                    .execute()
                ).data or []
                out.extend(batch)
                if len(batch) < 1000:
                    return out
                offset += 1000

        try:
            loans_rows = _fetch_all_loans(_cols_full)
        except Exception:
            loans_rows = _fetch_all_loans(_cols_min)

        loans_rows = [
            row for row in loans_rows
            if str(row.get("loan_status") or "").strip().lower() not in {"rejected", "cancelled"}
            and not _ledger_says_fully_paid(row)
        ]

        # Prior-version count per loan. Computed BEFORE the active-loan filter
        # below (which hides restructured predecessors) so the cashier can see
        # whether the loan they're collecting on is a restructured successor.
        # Chain = same (member_id, loan_type_name); older = earlier
        # application_date. Predecessors themselves aren't returned to the
        # cashier, but the count travels with the successor.
        prior_versions_by_loan: dict[str, int] = {}
        try:
            chains: dict[tuple, list[dict]] = {}
            for row in loans_rows:
                mid = row.get("member_id")
                ltype = ((row.get("loan_type") or {}).get("name")) or ""
                if not mid or not ltype:
                    continue
                chains.setdefault((mid, ltype), []).append(row)
            for items in chains.values():
                sorted_items = sorted(
                    items,
                    key=lambda r: str(r.get("application_date") or ""),
                )
                for idx, r in enumerate(sorted_items):
                    cn = str(r.get("control_number") or "")
                    if cn:
                        prior_versions_by_loan[cn] = idx
        except Exception:
            prior_versions_by_loan = {}

        # Cashier view = only ACTIVE (collectible) loans — any loan with at
        # least one Unpaid/Pending/Overdue schedule row. This used to be
        # computed in Python by pulling the *entire* loan_schedules table
        # (6,080+ legacy rows plus live) — that full-table read was the
        # dominant cost of this endpoint (10+ seconds).
        # get_active_cashier_loan_ids() does the same filter in one indexed
        # SQL query instead, and everything below only fetches
        # schedules/payments for the resulting (small) loan-id set.
        #
        # No per-(member, loan_type) dedup here: an earlier version of this
        # endpoint (and this RPC) collapsed each member+type down to only
        # their newest loan, on the assumption a renewal always closes out
        # its predecessor. In practice some members have multiple concurrent
        # loans of the same type that were never cleanly closed out, and
        # deduping silently hid real outstanding balances from the cashier.
        # A loan that *was* properly superseded by a renewal has all its
        # schedules marked Paid, so it already drops out of the active-
        # schedule filter above without needing an explicit dedup step.
        _active_loan_ids: set[str] = set()
        try:
            _active_rpc = supabase.rpc("get_active_cashier_loan_ids").execute()
            _active_loan_ids = {
                str(r.get("control_number") or "")
                for r in (_active_rpc.data or [])
                if r.get("control_number")
            }
        except Exception:
            _active_loan_ids = set()

        if _active_loan_ids:
            loans_rows = [
                row for row in loans_rows
                if str(row.get("control_number") or "") in _active_loan_ids
            ]
        else:
            # RPC missing/failed (e.g. migration not applied yet) — fall back
            # to the old in-Python filter so the endpoint still works, just
            # slower, instead of silently returning nothing.
            _active_scheds = (
                supabase.table("loan_schedules")
                .select("loan_id")
                .in_("schedule_status", ["Unpaid", "unpaid", "Pending", "pending", "Overdue", "overdue"])
                .execute()
            ).data or []
            _sched_active_ids = {str(r.get("loan_id") or "") for r in _active_scheds if r.get("loan_id")}
            if _sched_active_ids:
                loans_rows = [
                    row for row in loans_rows
                    if str(row.get("control_number") or "") in _sched_active_ids
                ]
            _active_loan_ids = {str(row.get("control_number") or "") for row in loans_rows}

        # Fetch loan_schedules only for the active loans we're about to display
        # (instead of paging through the whole table). Falls back to a full
        # paged read only if we somehow have no active-id set to filter by.
        schedules_by_loan: dict[str, list[dict]] = {}
        try:
            wide_cols = "id,schedule_id,loan_id,installment_no,due_date,expected_amount,expected_principal,expected_interest,penalty,remaining_principal,schedule_status,carried_arrears,applied_credit"
            narrow_cols = "id,loan_id,installment_no,due_date,expected_amount,principal_component,interest_component,schedule_status"

            def _fetch_schedules(cols: str):
                # Supabase/PostgREST caps a single .execute() at 1000 rows
                # regardless of filtering — 445 active loans across many
                # installments each easily exceeds that, so this must stay
                # paginated with .range() even when narrowed to active IDs.
                # (Narrowing to active IDs is still what makes this fast:
                # far fewer total rows than the old full-table page-through.)
                rows: list[dict] = []
                page = 1000
                offset = 0
                query_base = supabase.table("loan_schedules").select(cols)
                if _active_loan_ids:
                    query_base = query_base.in_("loan_id", list(_active_loan_ids))
                while True:
                    batch = (
                        query_base
                        .order("due_date")
                        .range(offset, offset + page - 1)
                        .execute()
                    ).data or []
                    if not batch:
                        break
                    rows.extend(batch)
                    if len(batch) < page:
                        break
                    offset += page
                return rows

            try:
                batch = _fetch_schedules(wide_cols)
            except Exception:
                batch = _fetch_schedules(narrow_cols)

            for row in batch:
                schedules_by_loan.setdefault(str(row.get("loan_id") or ""), []).append(row)
        except Exception:
            schedules_by_loan = {}

        schedule_display_by_internal_id: dict[str, str] = {}
        schedule_by_internal_id: dict[str, dict] = {}
        for loan_schedules in schedules_by_loan.values():
            for sched in loan_schedules:
                internal_id = str(sched.get("id") or "")
                display_id = str(sched.get("schedule_id") or internal_id)
                if internal_id:
                    schedule_display_by_internal_id[internal_id] = display_id
                    schedule_by_internal_id[internal_id] = sched

        # loan_payments (live) — filtered to the active loan-id set instead of
        # paging through the whole table (which is what made this endpoint
        # 10+ seconds as loan_payments grew). Falls back to a full paged read
        # only if we have no active-id set to filter by.
        payments_rows: list[dict] = []
        _active_ids_list = list(_active_loan_ids)
        try:
            # Supabase/PostgREST caps a single .execute() at 1000 rows no
            # matter how the query is filtered — with 400+ active loans this
            # is easily exceeded, so pagination must stay even when narrowed
            # to active IDs (narrowing is what makes this fast; skipping
            # pagination on top of it silently truncated payment history and
            # under-counted confirmed_paid_by_loan for real loans).
            page = 1000
            offset = 0
            query_base = supabase.table("loan_payments").select(
                "id,loan_id,schedule_id,amount_paid,penalties,payment_date,deficiency,confirmation_status,payment_reference,transaction_reference,applied_to_current,applied_to_credit"
            )
            if _active_ids_list:
                query_base = query_base.in_("loan_id", _active_ids_list)
            while True:
                batch = (
                    query_base
                    .order("payment_date", desc=True)
                    .range(offset, offset + page - 1)
                    .execute()
                ).data or []
                if not batch:
                    break
                payments_rows.extend(batch)
                if len(batch) < page:
                    break
                offset += page
        except Exception:
            payments_rows = []
            offset = 0
            query_base = supabase.table("loan_payments").select(
                "id,loan_id,schedule_id,amount_paid,penalties,payment_date,deficiency"
            )
            if _active_ids_list:
                query_base = query_base.in_("loan_id", _active_ids_list)
            while True:
                batch = (
                    query_base
                    .order("payment_date", desc=True)
                    .range(offset, offset + 999)
                    .execute()
                ).data or []
                if not batch:
                    break
                payments_rows.extend(batch)
                if len(batch) < 1000:
                    break
                offset += 1000

        # Also union loan_payments_legacy — historical payments migrated from
        # the coop's pre-app records. Always treated as validated. Same
        # active-id filtering as loan_payments above.
        try:
            def _fetch_legacy_payments():
                # Same 1000-row-per-.execute() cap as loan_payments above —
                # must stay paginated even when narrowed to active IDs.
                rows: list[dict] = []
                page = 1000
                offset = 0
                query_base = supabase.table("loan_payments_legacy").select(
                    "id,loan_id,amount_paid,payment_date,payment_code,or_cdv_no"
                )
                if _active_ids_list:
                    query_base = query_base.in_("loan_id", _active_ids_list)
                while True:
                    batch = (
                        query_base
                        .order("payment_date", desc=True)
                        .range(offset, offset + page - 1)
                        .execute()
                    ).data or []
                    if not batch:
                        break
                    rows.extend(batch)
                    if len(batch) < page:
                        break
                    offset += page
                return rows

            for legacy in _fetch_legacy_payments():
                payments_rows.append({
                    "id": legacy.get("id"),
                    "loan_id": legacy.get("loan_id"),
                    "schedule_id": None,
                    "amount_paid": legacy.get("amount_paid"),
                    "penalties": 0,
                    "payment_date": legacy.get("payment_date"),
                    "deficiency": 0,
                    "confirmation_status": "validated",
                    "payment_reference": legacy.get("payment_code") or legacy.get("or_cdv_no"),
                    "transaction_reference": legacy.get("or_cdv_no") or legacy.get("payment_code"),
                    "_is_legacy": True,
                })
        except Exception:
            pass

        confirmed_paid_by_loan: dict[str, Decimal] = {}
        principal_paid_by_loan: dict[str, Decimal] = {}
        unallocated_paid_by_loan: dict[str, Decimal] = {}
        last_payment_date_by_loan: dict[str, str] = {}
        payment_dates_by_loan: dict[str, list[date]] = {}
        legacy_loan_ids: set[str] = set()
        for payment in payments_rows:
            loan_key = str(payment.get("loan_id") or "")
            if payment.get("_is_legacy") and loan_key:
                legacy_loan_ids.add(loan_key)
            status = str(payment.get("confirmation_status") or "confirmed").strip().lower()
            is_confirmed = status in {"validated", "confirmed", "bookkeeper_confirmed", "approved"}
            if not is_confirmed:
                continue
            amount_paid_dec = Decimal(str(payment.get("amount_paid") or 0))
            confirmed_paid_by_loan[loan_key] = confirmed_paid_by_loan.get(loan_key, Decimal("0")) + amount_paid_dec

            # Same allocation rule as the Bookkeeper ledger and the SOA view: an
            # overpayment (applied_to_credit) is a straight principal prepayment,
            # not interest -- only applied_to_current (capped at that
            # installment's own due) carries that installment's interest share.
            applied_current = payment.get("applied_to_current")
            applied_credit = payment.get("applied_to_credit")
            if applied_current is not None or applied_credit is not None:
                applied_current_dec = Decimal(str(applied_current or 0))
                applied_credit_dec = Decimal(str(applied_credit or 0))
                sched = schedule_by_internal_id.get(str(payment.get("schedule_id") or "")) or {}
                expected_amount = Decimal(str(sched.get("expected_amount") or 0))
                expected_interest = Decimal(str(sched.get("expected_interest") or sched.get("interest_component") or 0))
                interest_share = (expected_interest / expected_amount) if expected_amount > 0 else Decimal("0")
                interest_part = money(applied_current_dec * interest_share)
                principal_part = (applied_current_dec - interest_part) + applied_credit_dec
                principal_paid_by_loan[loan_key] = principal_paid_by_loan.get(loan_key, Decimal("0")) + principal_part
            else:
                # No allocation on file (legacy/pre-migration): fall back to the
                # loan-wide interest ratio once total_interest is known below.
                unallocated_paid_by_loan[loan_key] = unallocated_paid_by_loan.get(loan_key, Decimal("0")) + amount_paid_dec
            # payments are pre-sorted by payment_date DESC, so first hit per loan is newest.
            pay_date = payment.get("payment_date")
            if loan_key and pay_date and loan_key not in last_payment_date_by_loan:
                last_payment_date_by_loan[loan_key] = pay_date
            parsed_pay_date = parse_date_value(pay_date)
            if loan_key and parsed_pay_date:
                payment_dates_by_loan.setdefault(loan_key, []).append(parsed_pay_date)

        # Accumulated unpaid penalty for every loan in ONE query, rather than a
        # per-loan lookup inside the render loop below (that was ~445 sequential
        # round-trips and made the cashier page crawl).
        unpaid_penalty_by_loan: dict[str, Decimal] = {}
        try:
            _penalty_rows = (
                supabase.table("loan_penalties")
                .select("loan_id,amount,paid_amount")
                .eq("is_paid", False)
                .execute()
            ).data or []
            for _row in _penalty_rows:
                _lid = str(_row.get("loan_id") or "")
                if not _lid:
                    continue
                _owed = Decimal(str(_row.get("amount") or 0)) - Decimal(str(_row.get("paid_amount") or 0))
                if _owed > 0:
                    unpaid_penalty_by_loan[_lid] = unpaid_penalty_by_loan.get(_lid, Decimal("0")) + _owed
        except Exception:
            # Table not migrated yet -- every loan simply shows no penalty.
            unpaid_penalty_by_loan = {}

        mapped_loans = []
        for loan in loans_rows:
            control_number = str(loan.get("control_number") or "").strip()
            if not control_number:
                continue

            member = loan.get("member") or {}
            member_name = f"{member.get('first_name') or ''} {member.get('last_name') or ''}".strip() or "Unknown Member"
            loan_type_name = (loan.get("loan_type") or {}).get("name")
            normalized_loan_type = normalize_cashier_loan_type(loan_type_name)

            principal_amount = Decimal(str(loan.get("principal_amount") or loan.get("loan_amount") or 0))
            confirmed_paid = confirmed_paid_by_loan.get(control_number, Decimal("0"))
            principal_paid_so_far = principal_paid_by_loan.get(control_number, Decimal("0"))
            unallocated_paid = unallocated_paid_by_loan.get(control_number, Decimal("0"))
            total_interest_amount = Decimal(str(loan.get("total_interest") or 0))
            if total_interest_amount <= 0:
                term_months_val = int(loan.get("term") or 0)
                monthly_amort_val = Decimal(str(loan.get("monthly_amortization") or 0))
                if term_months_val > 0 and monthly_amort_val > 0:
                    if normalized_loan_type == "bonus":
                        total_interest_amount = max(monthly_amort_val - principal_amount, Decimal("0"))
                    else:
                        total_interest_amount = max(monthly_amort_val * term_months_val - principal_amount, Decimal("0"))
            total_payable_amount = principal_amount + total_interest_amount
            remaining_balance = max(total_payable_amount - confirmed_paid, Decimal("0"))
            if _ledger_says_fully_paid(loan):
                remaining_balance = Decimal("0")

            # Unallocated (legacy/pre-migration) payments fall back to the
            # loan-wide interest ratio, same as the Bookkeeper ledger.
            unallocated_interest_share = (
                total_interest_amount / total_payable_amount if total_payable_amount > 0 else Decimal("0")
            )
            unallocated_principal = unallocated_paid - money(unallocated_paid * unallocated_interest_share)
            outstanding_principal = max(
                principal_amount - principal_paid_so_far - unallocated_principal, Decimal("0")
            )
            if _ledger_says_fully_paid(loan):
                outstanding_principal = Decimal("0")

            schedules = schedules_by_loan.get(control_number, [])
            next_schedule = None
            for sched in schedules:
                sched_status = str(sched.get("schedule_status") or "").strip().lower()
                if sched_status in {"unpaid", "pending", "overdue", ""}:
                    next_schedule = sched
                    break
            if not next_schedule and schedules:
                next_schedule = schedules[0]

            # Payments should only be posted once disbursement has generated schedules.
            if not next_schedule:
                continue

            # Count schedules whose due_date is already past today and are not
            # marked paid. This catches loans where the *next* unpaid schedule
            # is in the future but earlier installments were skipped.
            today_for_missed = datetime.utcnow().date()
            missed_count = 0
            for sched in schedules:
                sched_status = str(sched.get("schedule_status") or "").strip().lower()
                if sched_status in {"paid", "completed", "closed"}:
                    continue
                sched_due = parse_date_value(sched.get("due_date"))
                if sched_due and sched_due < today_for_missed:
                    missed_count += 1

            due_date_value = parse_date_value(next_schedule.get("due_date") if next_schedule else None)
            grace_deadline = (due_date_value + timedelta(days=3)) if due_date_value else None
            # When schedules earlier than `next_schedule.due_date` were missed,
            # treat the *earliest* missed one as the reference for delay flags
            # — otherwise a loan with skipped May payments but a June 27 next-
            # due ends up flagged "On Time" until June 27.
            earliest_missed_due = None
            for sched in schedules:
                sched_status = str(sched.get("schedule_status") or "").strip().lower()
                if sched_status in {"paid", "completed", "closed"}:
                    continue
                d = parse_date_value(sched.get("due_date"))
                if d and d < datetime.utcnow().date():
                    if earliest_missed_due is None or d < earliest_missed_due:
                        earliest_missed_due = d
            # Delay/penalty flags count months WITHOUT any payment: a payment
            # restarts the clock at the next due date after it.
            reference_due_for_flags = (
                penalty_clock_start(earliest_missed_due, payment_dates_by_loan.get(control_number, []))
                or due_date_value
            )
            # Missed months are counted the same way: only those since the last
            # payment, so paying resets the "Past Due (n)" count too.
            if earliest_missed_due and reference_due_for_flags:
                missed_count = sum(
                    1 for sched in schedules
                    if str(sched.get("schedule_status") or "").strip().lower() not in {"paid", "completed", "closed"}
                    and (lambda d: d is not None and reference_due_for_flags <= d < today_for_missed)(
                        parse_date_value(sched.get("due_date"))
                    )
                )
            # "No-payment warning" — 1 month past due date, no money charged.
            no_payment_warn_deadline = add_months(reference_due_for_flags, 1) if reference_due_for_flags else None
            # "Penalty starts" -- on the 3rd consecutive missed due date.
            penalty_start_deadline = add_months(reference_due_for_flags, PENALTY_GRACE_MONTHS) if reference_due_for_flags else None
            today_date = datetime.utcnow().date()
            is_delayed = bool(no_payment_warn_deadline and today_date > no_payment_warn_deadline)
            is_overdue_for_penalty = bool(penalty_start_deadline and today_date > penalty_start_deadline)
            last_payment_iso = last_payment_date_by_loan.get(control_number)

            # Penalty is computed here, server-side, and sent to the cashier UI
            # for display. The browser must never decide what is chargeable.
            is_legacy_loan = control_number in legacy_loan_ids
            unpaid_schedules = [
                s for s in schedules
                if str(s.get("schedule_status") or "").strip().lower() not in {"paid", "completed", "closed"}
            ]
            zero_payment_streak = count_consecutive_zero_payment_periods(
                unpaid_schedules,
                payment_dates_by_loan.get(control_number, []),
                today_date,
            )
            # Read-only here: use persisted rows when available, but calculate
            # the current charge when the payment path has not created those
            # rows yet. Without this fallback an overdue loan is correctly
            # flagged while the modal still shows zero penalty.
            accrued_penalty = unpaid_penalty_by_loan.get(control_number, Decimal("0"))
            if accrued_penalty <= 0:
                accrued_penalty = compute_loan_penalty(
                    loan_type_code=resolve_loan_type_code(normalized_loan_type),
                    remaining_balance=remaining_balance,
                    earliest_unpaid_due=earliest_missed_due,
                    schedules=unpaid_schedules,
                    payment_dates=payment_dates_by_loan.get(control_number, []),
                    is_legacy=is_legacy_loan,
                    as_of=today_date,
                    installment_amount=penalty_installment_base(loan, remaining_balance),
                    original_principal=principal_amount,
                )

            is_migs = bool(member.get("is_bona_fide"))
            # Use the same sanitizer used by disbursement/treasurer endpoints so legacy
            # snapshots (e.g., 83 stored where 0.83 was meant) don't bleed into the UI.
            loan_type_row = loan.get("loan_type") or {}
            displayed_rate = sanitize_monthly_rate_percent(
                loan.get("interest_rate"),
                loan_type_row.get("interest_rate"),
            )
            resolved_interest_rate_percent = Decimal(str(displayed_rate or 0))
            if resolved_interest_rate_percent <= 0:
                fallback_rate = fetch_loan_type_interest_rate_percent(
                    resolve_loan_type_code(normalized_loan_type),
                    loan_type_name,
                )
                if fallback_rate is not None and fallback_rate > 0:
                    resolved_interest_rate_percent = fallback_rate

            if remaining_balance <= 0:
                repayment_status = "Fully Paid"
            elif confirmed_paid > 0:
                repayment_status = "Partially Paid"
            else:
                repayment_status = "Unpaid"

            mapped_loans.append(
                {
                    "loan_id": control_number,
                    "schedule_id": next_schedule.get("schedule_id") or next_schedule.get("id") if next_schedule else None,
                    "member_id": loan.get("member_id"),
                    "member_name": member_name,
                    "loan_type": normalized_loan_type,
                    "is_migs_member": is_migs,
                    "loan_amount": decimal_to_float(principal_amount),
                    "interest_rate": decimal_to_float(resolved_interest_rate_percent),
                    "term_months": int(loan.get("term") or 0),
                    "amortization": decimal_to_float((loan.get("monthly_amortization") or 0)),
                    "disbursal_date": loan.get("disbursal_date"),
                    "due_date": next_schedule.get("due_date") if next_schedule else None,
                    "grace_deadline": grace_deadline.isoformat() if grace_deadline else None,
                    "delayed_deadline": no_payment_warn_deadline.isoformat() if no_payment_warn_deadline else None,
                    "penalty_start_deadline": penalty_start_deadline.isoformat() if penalty_start_deadline else None,
                    "is_delayed": is_delayed,
                    "is_overdue_for_penalty": is_overdue_for_penalty,
                    "missed_count": missed_count,
                    "last_payment_date": last_payment_iso,
                    "expected_installment": decimal_to_float(next_schedule.get("expected_amount") or 0),
                    "carried_arrears": decimal_to_float(Decimal(str(next_schedule.get("carried_arrears") or 0))),
                    "applied_credit": decimal_to_float(Decimal(str(next_schedule.get("applied_credit") or 0))),
                    "penalty_rate_percent": decimal_to_float(next_schedule.get("penalty") or 0),
                    "accrued_penalty": decimal_to_float(accrued_penalty),
                    "zero_payment_streak": zero_payment_streak,
                    "is_legacy": is_legacy_loan,
                    "remaining_balance": decimal_to_float(remaining_balance),
                    "outstanding_principal": decimal_to_float(outstanding_principal),
                    "total_payable": decimal_to_float(total_payable_amount),
                    "total_interest": decimal_to_float(total_interest_amount),
                    "loan_status": repayment_status,
                    "prior_versions": prior_versions_by_loan.get(control_number, 0),
                }
            )

        mapped_payment_records = []
        for idx, row in enumerate(payments_rows, start=1):
            mapped_payment_records.append(
                {
                    "payment_id": row.get("payment_reference") or build_sequence_id("TTMPCLP-", idx),
                    "loan_id": row.get("loan_id"),
                    "schedule_id": schedule_display_by_internal_id.get(str(row.get("schedule_id") or ""), row.get("schedule_id")),
                    "installment_no": (schedule_by_internal_id.get(str(row.get("schedule_id") or "")) or {}).get("installment_no"),
                    "transaction_id": row.get("transaction_reference") or build_sequence_id("TTMPCLP_TXN_", idx),
                    "amount_paid": decimal_to_float(row.get("amount_paid") or 0),
                    "payment_date": row.get("payment_date"),
                    "penalties": decimal_to_float(row.get("penalties") or 0),
                    "deficiency": decimal_to_float(row.get("deficiency") or 0),
                    "confirmation_status": row.get("confirmation_status") or "pending_bookkeeper",
                }
            )

        # Open non-member Bonus loans (non_member_loans); payments go to
        # nonmember_loan_payments via /api/cashier/nonmember-loan-payments.
        try:
            non_member_open = (
                supabase.table("non_member_loans")
                .select("control_number,full_name,loan_amount,term,loan_status,application_date,disbursal_date")
                .eq("loan_status", "released")
                .execute()
            ).data or []
        except Exception as e:
            logger.warning("non_member_loans lookup failed for cashier list: %s", e)
            non_member_open = []
        nm_pays = _nonmember_payments_by_loan([str(k.get("control_number")) for k in non_member_open])
        for k in non_member_open:
            amount = decimal_to_float(Decimal(str(k.get("loan_amount") or 0)))
            paid = sum(float(p.get("amount_paid") or 0) for p in nm_pays.get(str(k.get("control_number")), []))
            remaining = round(max(amount - paid, 0.0), 2)
            mapped_loans.append({
                "loan_id": k.get("control_number"),
                "member_id": "",
                "member_name": k.get("full_name") or "Unknown Applicant",
                "loan_type": "non-member bonus",
                "is_migs_member": False,
                "is_nonmember": True,
                "loan_amount": amount,
                "interest_rate": BONUS_MONTHLY_RATE_NONMEMBER,
                "term_months": int(k.get("term") or 0),
                "amortization": 0.0,
                "disbursal_date": k.get("disbursal_date") or k.get("application_date"),
                "due_date": None,
                "missed_count": 0,
                "accrued_penalty": 0.0,
                "remaining_balance": remaining,
                "total_payable": amount,
                "total_interest": 0.0,
                "loan_status": "Partially Paid" if paid > 0 else "Unpaid",
                "last_payment_date": (nm_pays.get(str(k.get("control_number"))) or [{}])[-1].get("payment_date"),
            })

        return {
            "success": True,
            "data": {
                "loans": mapped_loans,
                "payment_records": mapped_payment_records,
            },
        }
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load cashier loan payment data: {err}")


@app.get("/api/cashier/disbursements/ready-loans")
async def get_cashier_ready_for_disbursement_loans():
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        # Page through the full table — PostgREST caps an unbounded response
        # at its max-rows setting, which can drop older loans off the end.
        rows = []
        page_size = 1000
        offset = 0
        while True:
            batch = (
                supabase.table("loans")
                .select(
                    "control_number,loan_amount,principal_amount,interest_rate,term,loan_status,application_status,application_date," \
                    "applicant_full_name," \
                    "member:member_id(first_name,last_name)," \
                    "loan_type:loan_type_id(name,interest_rate)"
                )
                .order("application_date", desc=True)
                .range(offset, offset + page_size - 1)
                .execute()
            ).data or []
            if not batch:
                break
            rows.extend(batch)
            if len(batch) < page_size:
                break
            offset += page_size

        filtered = [
            row
            for row in rows
            if str(row.get("loan_status") or "").strip().lower() == "ready for disbursement"
        ]

        mapped = []
        for row in filtered:
            member = row.get("member") or {}
            loan_type_row = row.get("loan_type") or {}
            displayed_rate = sanitize_monthly_rate_percent(
                row.get("interest_rate"),
                loan_type_row.get("interest_rate"),
            )
            # Non-member Bonus loans (Step 8) have no member join; fall back
            # to the applicant name typed in at intake.
            member_name = (
                f"{member.get('first_name') or ''} {member.get('last_name') or ''}".strip()
                or row.get("applicant_full_name")
                or "Unknown Member"
            )
            mapped.append(
                {
                    "loan_id": row.get("control_number"),
                    "member_name": member_name,
                    "loan_type": loan_type_row.get("name") or "N/A",
                    "loan_amount": decimal_to_float(row.get("loan_amount") or 0),
                    "principal_amount": decimal_to_float(row.get("principal_amount") or row.get("loan_amount") or 0),
                    "interest_rate": displayed_rate,
                    "term_months": int(row.get("term") or 0),
                    "loan_status": row.get("loan_status") or "ready for disbursement",
                    "application_status": row.get("application_status") or row.get("loan_status") or "ready for disbursement",
                    "application_date": row.get("application_date"),
                }
            )

        return {"success": True, "data": mapped}
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to fetch ready disbursement loans: {err}")


def _classify_migs(member: dict) -> str:
    if not member:
        return "Non-Member"
    if member.get("is_bona_fide"):
        return "MIGS"
    return "Non-MIGS"


def _normalize_disbursement_loan_type(raw: str) -> str:
    text = (raw or "").strip().lower()
    if "emergency" in text:
        return "Emergency"
    if "consolidated" in text:
        return "Consolidated"
    if "abff" in text or "koica" in text:
        return "ABFF"
    if "bonus" in text:
        return "Bonus"
    return (raw or "Other").title()


# Priority-queue rank per TTMPC disbursement policy. Same rules as the ones
# hard-coded on the Disbursement page (Disbursement.jsx PRIORITY_RULES) — keep
# these in sync if the policy changes.
DISBURSEMENT_PRIORITY_RULES = (
    (1, "Emergency",                   lambda t, m: t == "Emergency"),
    (2, "Consolidated (MIGS)",         lambda t, m: t == "Consolidated" and m == "MIGS"),
    (3, "Consolidated (Non-MIGS)",     lambda t, m: t == "Consolidated" and m == "Non-MIGS"),
    (4, "Bonus (MIGS)",                lambda t, m: t == "Bonus" and m == "MIGS"),
    (5, "Bonus (Non-MIGS)",            lambda t, m: t == "Bonus" and m == "Non-MIGS"),
    (6, "Non-member Bonus Loan",       lambda t, m: t == "Bonus" and m == "Non-Member"),
)


def _compute_disbursement_rank(loan_type: str, migs: str) -> tuple[int, str]:
    for rank, label, match in DISBURSEMENT_PRIORITY_RULES:
        if match(loan_type, migs):
            return rank, label
    return 99, "Unranked"


# ============================================================================
# SECTION: Treasurer — Disbursements
# Endpoints that surface loans already released by the cashier for treasurer
# accounting and reconciliation.
# ============================================================================

@app.get("/api/treasurer/disbursements/released-loans")
async def get_treasurer_released_loans():
    """Read-only audit feed of loans already released by the Cashier."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        response = (
            supabase.table("loans")
            .select(
                "control_number,loan_amount,principal_amount,interest_rate,term,loan_status,application_status," \
                "application_date,disbursal_date,release_method,released_by,raw_payload,applicant_full_name," \
                "member:member_id(membership_id,first_name,last_name,is_bona_fide)," \
                "loan_type:loan_type_id(name,interest_rate)"
            )
            .order("disbursal_date", desc=True)
            .execute()
        )
        rows = response.data or []
    except Exception:
        # Fallback if release_method / released_by columns are not present in the schema.
        response = (
            supabase.table("loans")
            .select(
                "control_number,loan_amount,principal_amount,interest_rate,term,loan_status,application_status," \
                "application_date,disbursal_date,raw_payload,applicant_full_name," \
                "member:member_id(membership_id,first_name,last_name,is_bona_fide)," \
                "loan_type:loan_type_id(name,interest_rate)"
            )
            .order("disbursal_date", desc=True)
            .execute()
        )
        rows = response.data or []

    released = [
        row for row in rows
        if str(row.get("loan_status") or "").strip().lower() in {"released", "disbursed", "fully paid", "partially paid", "unpaid"}
        and row.get("disbursal_date")
    ]

    def _document_status(loan_row: dict) -> tuple[bool, int]:
        """Return (has_documents, document_count) from attached supporting documents.

        A loan is considered complete once it has at least one file uploaded to
        Supabase Storage under raw_payload.optionalFields.bookkeeper_loan_details.supporting_documents.
        """
        payload = loan_row.get("raw_payload") or {}
        if not isinstance(payload, dict):
            return False, 0
        docs = (
            (payload.get("optionalFields") or {}).get("bookkeeper_loan_details", {}) or {}
        ).get("supporting_documents")
        if not isinstance(docs, list):
            return False, 0
        count = sum(1 for d in docs if isinstance(d, dict) and str(d.get("storage_path") or "").strip())
        return count > 0, count

    mapped = []
    total_released = Decimal("0")
    today_iso = datetime.utcnow().date().isoformat()
    released_today_total = Decimal("0")

    for row in released:
        member = row.get("member") or {}
        loan_type_name = (row.get("loan_type") or {}).get("name")
        loan_type = _normalize_disbursement_loan_type(loan_type_name)
        migs = _classify_migs(member)
        member_name = (
            f"{member.get('first_name') or ''} {member.get('last_name') or ''}".strip()
            or row.get("applicant_full_name")
            or "Unknown Member"
        )
        amount = Decimal(str(row.get("principal_amount") or row.get("loan_amount") or 0))
        total_released += amount
        disbursal_date = str(row.get("disbursal_date") or "")[:10] or None
        if disbursal_date == today_iso:
            released_today_total += amount

        control_number = row.get("control_number")
        has_documents, document_count = _document_status(row)

        mapped.append({
            "loan_id": control_number,
            "member_id": member.get("membership_id"),
            "member_name": member_name,
            "loan_type": loan_type,
            "loan_type_raw": loan_type_name,
            "migs": migs,
            "amount": decimal_to_float(amount),
            "interest_rate": sanitize_monthly_rate_percent(
                row.get("interest_rate"),
                (row.get("loan_type") or {}).get("interest_rate"),
            ),
            "term_months": int(row.get("term") or 0),
            "method": row.get("release_method") or "Cash",
            "released_by": row.get("released_by") or "Cashier",
            "approved_date": row.get("application_date"),
            "released_date": disbursal_date,
            "has_documents": has_documents,
            "document_count": document_count,
            "status": "Released",
        })

    summary = {
        "total_released_count": len(mapped),
        "total_released_amount": decimal_to_float(total_released),
        "released_today_amount": decimal_to_float(released_today_total),
    }

    return {"success": True, "data": mapped, "summary": summary}


@app.get("/api/treasurer/disbursements/priority-queue")
async def get_treasurer_priority_queue(limit: int = 10, offset: int = 0):
    """Loans waiting to be released, ranked by TTMPC disbursement policy.

    Returned rows are ordered by (rank asc, application_date asc). The rank
    encodes the coop's priority rules — Emergency first, then MIGS-heavy
    products, ABFF loans, etc. See DISBURSEMENT_PRIORITY_RULES for the
    canonical mapping.

    Query params:
      - limit:  page size (default 10, max 100)
      - offset: page offset for pagination

    Also returns a `summary` with totals + per-rank aggregates so the
    dashboard can show "N loans / ₱X pending" without a second query.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        # Page through the full table — PostgREST caps an unbounded response
        # at its max-rows setting, which silently drops the newest loans off
        # the end of an oldest-first query once the table passes that cap.
        rows = []
        page_size = 1000
        page_offset = 0
        while True:
            batch = (
                supabase.table("loans")
                .select(
                    "control_number,loan_amount,principal_amount,loan_status,application_status,application_date,"
                    "applicant_full_name,"
                    "member:member_id(membership_id,first_name,last_name,is_bona_fide),"
                    "loan_type:loan_type_id(name)"
                )
                .order("application_date", desc=False)  # oldest first within a rank
                .range(page_offset, page_offset + page_size - 1)
                .execute()
            ).data or []
            if not batch:
                break
            rows.extend(batch)
            if len(batch) < page_size:
                break
            page_offset += page_size
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to fetch priority queue: {err}")

    now = datetime.now()
    queue = []

    for row in rows:
        # Only loans genuinely waiting for treasurer/cashier action.
        status = str(row.get("loan_status") or "").strip().lower()
        if status not in {"ready for disbursement", "approved", "awaiting disbursement"}:
            continue

        member = row.get("member") or {}
        loan_type_row = row.get("loan_type") or {}
        raw_type = loan_type_row.get("name") or ""
        loan_type = _normalize_disbursement_loan_type(raw_type)
        migs = _classify_migs(member)
        rank, rank_label = _compute_disbursement_rank(loan_type, migs)

        app_date_str = row.get("application_date")
        days_waiting = None
        if app_date_str:
            try:
                app_dt = datetime.fromisoformat(str(app_date_str).replace("Z", "+00:00"))
                days_waiting = max(0, (now - app_dt.replace(tzinfo=None)).days)
            except (ValueError, TypeError):
                days_waiting = None

        amount = decimal_to_float(row.get("principal_amount") or row.get("loan_amount") or 0)
        member_name = (
            f"{member.get('first_name') or ''} {member.get('last_name') or ''}".strip()
            or row.get("applicant_full_name")
            or "Unknown Member"
        )

        queue.append({
            "rank": rank,
            "rank_label": rank_label,
            "loan_id": row.get("control_number"),
            "member_name": member_name,
            "membership_id": member.get("membership_id"),
            "loan_type": loan_type,
            "migs": migs,
            "amount": amount,
            "application_date": app_date_str,
            "days_waiting": days_waiting,
            "loan_status": row.get("loan_status"),
        })

    # Sort by (rank asc, days_waiting desc → oldest first). Rows without
    # days_waiting sink to the bottom of their rank.
    queue.sort(key=lambda r: (r["rank"], -(r["days_waiting"] or 0)))

    # Summary — before slicing, so totals reflect the full queue not just the page.
    total_count = len(queue)
    total_amount = sum(r["amount"] for r in queue)
    per_rank: dict[int, dict] = {}
    for r in queue:
        bucket = per_rank.setdefault(r["rank"], {
            "rank": r["rank"],
            "rank_label": r["rank_label"],
            "count": 0,
            "amount": 0.0,
        })
        bucket["count"] += 1
        bucket["amount"] += r["amount"]

    # Pagination — clamp inputs then slice AFTER ranking so page N still
    # reflects the correct priority order.
    limit_clean = max(1, min(int(limit), 100))
    offset_clean = max(0, int(offset))
    paged = queue[offset_clean : offset_clean + limit_clean]

    return {
        "success": True,
        "data": paged,
        "summary": {
            "total_count": total_count,
            "total_amount": round(total_amount, 2),
            "per_rank": sorted(per_rank.values(), key=lambda x: x["rank"]),
        },
        "pagination": {
            "limit": limit_clean,
            "offset": offset_clean,
            "total": total_count,
            "has_more": (offset_clean + limit_clean) < total_count,
        },
    }


# ============================================================================
# SECTION: Treasurer — Vault (cash-on-hand ledger)
# Append-only ledger of vault cash movements. Current balance = SUM(amount).
# Backing table: public.vault_entries (see vault_entries_schema.sql).
# Auth is enforced by RLS via is_vault_reader() / is_vault_writer() — the
# supabase client here uses the anon key, so the user's JWT (forwarded from
# the frontend) drives policy evaluation. If policies reject, Supabase returns
# an empty result / insert error which we surface as HTTP 403.
# ============================================================================

@app.get("/api/treasurer/vault")
async def get_treasurer_vault_balance():
    """Return the current vault balance from the vault_balance_v view."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    try:
        response = supabase.table("vault_balance_v").select("*").limit(1).execute()
        rows = response.data or []
        if not rows:
            return {
                "success": True,
                "data": {"current_balance": 0.0, "last_updated_at": None, "entry_count": 0},
            }
        row = rows[0]
        return {
            "success": True,
            "data": {
                "current_balance": float(row.get("current_balance") or 0),
                "last_updated_at": row.get("last_updated_at"),
                "entry_count": int(row.get("entry_count") or 0),
            },
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to fetch vault balance: {e}")


@app.get("/api/treasurer/vault/available")
async def get_treasurer_vault_available():
    """{balance, committed, available} — see _compute_vault_available().

    `committed` is what the raw vault_balance_v balance alone can't tell you:
    the sum of net cash already spoken for by loans sitted 'ready for
    disbursement' (Treasurer-approved, awaiting the Cashier's release). Two
    loans can each look affordable against the raw balance individually while
    together exceeding it — RESCHEDULED_LOANS_PLAN.md §3.1.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    try:
        figures = _compute_vault_available()
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to compute available vault funds: {e}")
    return {
        "success": True,
        "data": {
            "balance": decimal_to_float(figures["balance"]),
            "committed": decimal_to_float(figures["committed"]),
            "available": decimal_to_float(figures["available"]),
        },
    }


@app.get("/api/treasurer/disbursements/rescheduled")
async def get_treasurer_rescheduled_loans():
    """Loans the Treasurer parked (`loan_status = 'pending rescheduling'`) for
    insufficient vault funds, plus the vault figures to judge them against.

    Each row's `shortfall` is recomputed live against `available`, never
    stored — it self-heals the moment the vault refills or other committed
    loans are released, with no stale number and no manual re-check
    (RESCHEDULED_LOANS_PLAN.md §7).
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        all_loans = []
        page_size = 1000
        offset = 0
        while True:
            batch = (
                supabase.table("loans")
                .select(
                    "control_number,member_id,loan_amount,principal_amount,term,loan_status,application_date," \
                    "application_type,rescheduled_at,reschedule_note,applicant_full_name," \
                    f"{LOAN_FEE_SNAPSHOT_COLUMNS}," \
                    "member:member_id(first_name,last_name)," \
                    "loan_type:loan_type_id(name,code)"
                )
                .range(offset, offset + page_size - 1)
                .execute()
            ).data or []
            if not batch:
                break
            all_loans.extend(batch)
            if len(batch) < page_size:
                break
            offset += page_size
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to load loans: {e}")

    rescheduled_loans = [
        r for r in all_loans
        if str(r.get("loan_status") or "").strip().lower() == "pending rescheduling"
    ]
    ready_loans = [
        r for r in all_loans
        if str(r.get("loan_status") or "").strip().lower() == "ready for disbursement"
    ]

    # non_member_loans mirrors the Treasurer's main queue (Treasurer_Approval.jsx
    # combines both tables), but the Cashier's disbursement endpoints never
    # touch non_member_loans, so its rows have no real fee/renewal computation
    # available — shown at gross loan_amount, flagged `is_estimated`.
    try:
        non_member_resp = (
            supabase.table("non_member_loans")
            .select(
                "control_number,loan_amount,term,loan_status,application_date,full_name,loan_type_code," \
                "rescheduled_at,reschedule_note"
            )
            .range(0, 999)
            .execute()
        )
        non_member_rows = [
            r for r in (non_member_resp.data or [])
            if str(r.get("loan_status") or "").strip().lower() == "pending rescheduling"
        ]
    except Exception as e:
        logger.warning("non_member_loans lookup failed for rescheduled tab: %s", e)
        non_member_rows = []

    try:
        balance_resp = supabase.table("vault_balance_v").select("current_balance").limit(1).execute()
        balance = Decimal(str((balance_resp.data or [{}])[0].get("current_balance") or 0))
    except Exception as e:
        logger.warning("vault balance lookup failed for rescheduled tab: %s", e)
        balance = Decimal("0")

    net_cash_out_by_control = _net_cash_out_for_rows(ready_loans)
    committed = money(sum(net_cash_out_by_control.values(), Decimal("0")))
    available = money(balance - committed)

    rescheduled_net_cash_out = _net_cash_out_for_rows(rescheduled_loans)
    rescheduled_payoff_lookup = _resolve_renewal_predecessors(rescheduled_loans)
    payoff_balances = _outstanding_balances(list(rescheduled_payoff_lookup.values()))

    rows = []
    for r in rescheduled_loans:
        cn = str(r.get("control_number") or "")
        member = r.get("member") or {}
        net_cash_out = rescheduled_net_cash_out.get(cn, Decimal("0"))
        predecessor = rescheduled_payoff_lookup.get(cn)
        renewal_payoff = (
            payoff_balances.get(str(predecessor.get("control_number")), Decimal("0")) if predecessor else Decimal("0")
        )
        shortfall = money(max(net_cash_out - available, Decimal("0")))
        rows.append({
            "loan_id": cn,
            "source": "loans",
            "member_name": (
                f"{member.get('first_name') or ''} {member.get('last_name') or ''}".strip()
                or r.get("applicant_full_name")
                or "Unknown Member"
            ),
            "loan_type": (r.get("loan_type") or {}).get("name") or "N/A",
            "loan_amount": decimal_to_float(r.get("loan_amount") or 0),
            "net_cash_out": decimal_to_float(net_cash_out),
            "is_renewal": str(r.get("application_type") or "").strip().lower() == "renewal",
            "renewal_payoff": decimal_to_float(renewal_payoff),
            "is_estimated": False,
            "term_months": int(r.get("term") or 0),
            "application_date": r.get("application_date"),
            "rescheduled_at": r.get("rescheduled_at"),
            "reschedule_note": r.get("reschedule_note"),
            "shortfall": decimal_to_float(shortfall),
        })

    for r in non_member_rows:
        gross = Decimal(str(r.get("loan_amount") or 0))
        shortfall = money(max(gross - available, Decimal("0")))
        rows.append({
            "loan_id": r.get("control_number"),
            "source": "non_member_loans",
            "member_name": r.get("full_name") or "Unknown Applicant",
            "loan_type": "Non-member Bonus Loan",
            "loan_amount": decimal_to_float(gross),
            "net_cash_out": decimal_to_float(gross),
            "is_renewal": False,
            "renewal_payoff": 0.0,
            "is_estimated": True,
            "term_months": int(r.get("term") or 0),
            "application_date": r.get("application_date"),
            "rescheduled_at": r.get("rescheduled_at"),
            "reschedule_note": r.get("reschedule_note"),
            "shortfall": decimal_to_float(shortfall),
        })

    rows.sort(key=lambda x: str(x.get("rescheduled_at") or x.get("application_date") or ""), reverse=True)

    return {
        "success": True,
        "data": {
            "vault": {
                "balance": decimal_to_float(balance),
                "committed": decimal_to_float(committed),
                "available": decimal_to_float(available),
            },
            "rows": rows,
        },
    }


@app.get("/api/treasurer/disbursements/decision-queue")
async def get_treasurer_decision_queue(limit: int = 5):
    """Dashboard summary of loans awaiting the Treasurer's funding decision
    (`loan_status = 'to be disbursed'` — the Loan Approval page's Awaiting tab),
    each judged against the vault the same way Treasurer_ApprovalDetails does:
    shortfall = max(net_cash_out − available, 0).

    Read-only. No new math: net cash out comes from _net_cash_out_for_rows(),
    the vault figures from _compute_vault_available(), the order from
    _compute_disbursement_rank() (rank asc, then longest-waiting first).
    Non-member rows have no fee/renewal computation (the Cashier flow never touches
    non_member_loans), so they're shown at gross and flagged `is_estimated` — their
    funding status is "review", never "fundable".
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        # PostgREST can cap an unbounded response at its max-rows setting.
        # Page through the full table so newer queue entries are not hidden
        # behind older loans.
        all_loans = []
        page_size = 1000
        offset = 0
        while True:
            batch = (
                supabase.table("loans")
                .select(
                    "control_number,member_id,loan_amount,principal_amount,loan_status,application_date,"
                    f"application_type,applicant_full_name,{LOAN_FEE_SNAPSHOT_COLUMNS},"
                    "member:member_id(first_name,last_name,is_bona_fide),"
                    "loan_type:loan_type_id(name,code)"
                )
                .range(offset, offset + page_size - 1)
                .execute()
            ).data or []
            if not batch:
                break
            all_loans.extend(batch)
            if len(batch) < page_size:
                break
            offset += page_size
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to load loans: {e}")

    awaiting_loans = [
        r for r in all_loans
        if str(r.get("loan_status") or "").strip().lower() == "to be disbursed"
    ]
    rescheduled_loans = [
        r for r in all_loans
        if str(r.get("loan_status") or "").strip().lower() == "pending rescheduling"
    ]

    try:
        non_member_resp = (
            supabase.table("non_member_loans")
            .select("control_number,loan_amount,loan_status,application_date,full_name,loan_type_code")
            .execute()
        )
        non_member_all = non_member_resp.data or []
    except Exception as e:
        logger.warning("non_member_loans lookup failed for decision queue: %s", e)
        non_member_all = []
    non_member_awaiting = [r for r in non_member_all if str(r.get("loan_status") or "").strip().lower() == "to be disbursed"]
    non_member_rescheduled = [r for r in non_member_all if str(r.get("loan_status") or "").strip().lower() == "pending rescheduling"]

    figures = _compute_vault_available()
    available = figures["available"]
    now = datetime.now()

    def _days_waiting(app_date_str):
        if not app_date_str:
            return None
        try:
            app_dt = datetime.fromisoformat(str(app_date_str).replace("Z", "+00:00"))
            return max(0, (now - app_dt.replace(tzinfo=None)).days)
        except (ValueError, TypeError):
            return None

    def _funding(net_cash_out: Decimal, is_estimated: bool) -> tuple[str, Decimal]:
        shortfall = money(max(net_cash_out - available, Decimal("0")))
        if is_estimated:
            return "review", shortfall
        return ("fundable" if shortfall <= 0 else "insufficient"), shortfall

    queue = []
    awaiting_net = _net_cash_out_for_rows(awaiting_loans)
    for r in awaiting_loans:
        cn = str(r.get("control_number") or "")
        member = r.get("member") or {}
        loan_type = _normalize_disbursement_loan_type((r.get("loan_type") or {}).get("name") or "")
        migs = _classify_migs(member)
        rank, rank_label = _compute_disbursement_rank(loan_type, migs)
        net_cash_out = awaiting_net.get(cn, Decimal("0"))
        status, shortfall = _funding(net_cash_out, False)
        queue.append({
            "loan_id": cn,
            "source": "loans",
            "member_name": (
                f"{member.get('first_name') or ''} {member.get('last_name') or ''}".strip()
                or r.get("applicant_full_name")
                or "Unknown Member"
            ),
            "migs": migs,
            "loan_type": loan_type,
            "rank": rank,
            "rank_label": rank_label,
            "loan_amount": decimal_to_float(r.get("principal_amount") or r.get("loan_amount") or 0),
            "net_cash_out": decimal_to_float(net_cash_out),
            "is_renewal": str(r.get("application_type") or "").strip().lower() == "renewal",
            "is_estimated": False,
            "days_waiting": _days_waiting(r.get("application_date")),
            "funding_status": status,
            "shortfall": decimal_to_float(shortfall),
        })

    for r in non_member_awaiting:
        loan_type = _normalize_disbursement_loan_type(
            "Non-member Bonus Loan"
        )
        rank, rank_label = _compute_disbursement_rank(loan_type, "Non-Member")
        gross = Decimal(str(r.get("loan_amount") or 0))
        status, shortfall = _funding(gross, True)
        queue.append({
            "loan_id": r.get("control_number"),
            "source": "non_member",
            "member_name": r.get("full_name") or "Unknown Applicant",
            "migs": "Non-Member",
            "loan_type": loan_type,
            "rank": rank,
            "rank_label": rank_label,
            "loan_amount": decimal_to_float(gross),
            "net_cash_out": decimal_to_float(gross),
            "is_renewal": False,
            "is_estimated": True,
            "days_waiting": _days_waiting(r.get("application_date")),
            "funding_status": status,
            "shortfall": decimal_to_float(shortfall),
        })

    # Same ordering as the priority queue: rank asc, then longest-waiting first.
    queue.sort(key=lambda r: (r["rank"], -(r["days_waiting"] or 0)))

    total_net = sum((Decimal(str(r["net_cash_out"])) for r in queue), Decimal("0"))
    counts = {"fundable": 0, "review": 0, "insufficient": 0}
    for r in queue:
        counts[r["funding_status"]] += 1

    # Rescheduled loans whose shortfall has cleared (same live recompute as
    # the Rescheduled tab) — worth surfacing so they don't sit forgotten.
    rescheduled_net = _net_cash_out_for_rows(rescheduled_loans)
    rescheduled_now_fundable = sum(1 for v in rescheduled_net.values() if v <= available)
    rescheduled_now_fundable += sum(
        1 for r in non_member_rescheduled if Decimal(str(r.get("loan_amount") or 0)) <= available
    )

    limit_clean = max(1, min(int(limit), 50))
    return {
        "success": True,
        "data": {
            "vault": {
                "balance": decimal_to_float(figures["balance"]),
                "committed": decimal_to_float(figures["committed"]),
                "available": decimal_to_float(available),
            },
            "rows": queue[:limit_clean],
            "summary": {
                "total_count": len(queue),
                "total_net_cash_out": decimal_to_float(money(total_net)),
                "fundable_count": counts["fundable"],
                "review_count": counts["review"],
                "insufficient_count": counts["insufficient"],
                # Loans that individually fit in `available` (non-member rows judged at gross).
                "fits_count": sum(1 for r in queue if r["shortfall"] <= 0),
                "rescheduled_count": len(rescheduled_loans) + len(non_member_rescheduled),
                "rescheduled_now_fundable": rescheduled_now_fundable,
            },
        },
    }


@app.get("/api/treasurer/vault/entries")
async def get_treasurer_vault_entries(
    limit: int = 50,
    offset: int = 0,
    change_type: str | None = None,
):
    """Paginated ledger of vault entries, newest first.

    Query params:
      - limit:       page size (max 200)
      - offset:      row offset for pagination
      - change_type: optional filter (deposit / withdrawal / disbursement / adjustment / opening_balance)
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    limit_clean = max(1, min(int(limit), 200))
    offset_clean = max(0, int(offset))

    try:
        query = (
            supabase.table("vault_entries")
            .select("id,amount,change_type,note,reference_id,entered_by,entered_at", count="exact")
            .order("entered_at", desc=True)
            .range(offset_clean, offset_clean + limit_clean - 1)
        )
        if change_type:
            query = query.eq("change_type", change_type.strip().lower())
        response = query.execute()
        rows = response.data or []
        total = getattr(response, "count", None)
        return {
            "success": True,
            "data": [
                {
                    "id": r.get("id"),
                    "amount": float(r.get("amount") or 0),
                    "change_type": r.get("change_type"),
                    "note": r.get("note"),
                    "reference_id": r.get("reference_id"),
                    "entered_by": r.get("entered_by"),
                    "entered_at": r.get("entered_at"),
                }
                for r in rows
            ],
            "pagination": {"limit": limit_clean, "offset": offset_clean, "total": total},
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to fetch vault entries: {e}")


@app.post("/api/treasurer/vault/entries")
async def create_treasurer_vault_entry(
    payload: dict = Body(...),
    current_user: dict = _Depends(_get_current_user),
):
    """Append a new entry to the vault ledger.

    Body:
      - amount:       required. Signed peso amount (positive for cash in, negative for cash out).
                      The frontend should compute the sign from the chosen change_type so the
                      treasurer never has to type a negative number.
      - change_type:  required. One of the CHECK-constraint values.
      - note:         optional but STRONGLY recommended for 'adjustment'.
      - reference_id: optional. Loans.id when this entry ties to a specific loan.

    `entered_by` is NOT read from the body — this endpoint used to take the
    caller's identity as a bare claim, with no auth check at all (anyone able
    to reach the API could post a `deposit` and attribute it to any user;
    RESCHEDULED_LOANS_PLAN.md §8.2). It is now resolved from the verified
    bearer token, and only a treasurer or BOD may call this at all. Sign vs.
    change_type and the negative-balance guard are also enforced by a DB
    trigger (rescheduled_loans_and_vault_hardening.sql) so the Treasurer's
    direct-Supabase write in Vault.jsx is covered the same way (§8.3-§8.5).
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role not in {"treasurer", "bod"}:
        raise HTTPException(status_code=403, detail="Only the Treasurer or BOD may record vault entries.")

    valid_types = {"deposit", "withdrawal", "disbursement", "adjustment", "opening_balance"}
    # A caller posts what physically happened, not the ledger's arithmetic
    # sign — matches what the sign-fixed types actually mean in cash terms.
    required_sign = {"deposit": 1, "withdrawal": -1, "disbursement": -1, "opening_balance": 1}

    try:
        amount = float(payload.get("amount"))
    except (TypeError, ValueError):
        raise HTTPException(status_code=400, detail="`amount` is required and must be numeric.")
    if amount == 0:
        raise HTTPException(status_code=400, detail="`amount` must be non-zero.")

    change_type = str(payload.get("change_type") or "").strip().lower()
    if change_type not in valid_types:
        raise HTTPException(
            status_code=400,
            detail=f"Invalid change_type. Must be one of: {', '.join(sorted(valid_types))}.",
        )

    if change_type == "adjustment" and not str(payload.get("note") or "").strip():
        raise HTTPException(status_code=400, detail="`note` is required for adjustment entries.")

    expected_sign = required_sign.get(change_type)
    if expected_sign is not None and (amount > 0) != (expected_sign > 0):
        raise HTTPException(
            status_code=400,
            detail=f"`amount` must be {'positive' if expected_sign > 0 else 'negative'} for change_type '{change_type}'.",
        )

    row = {
        "amount": amount,
        "change_type": change_type,
        "note": (payload.get("note") or None),
        "reference_id": payload.get("reference_id"),
        "entered_by": current_user["id"],
    }

    try:
        response = supabase.table("vault_entries").insert(row).execute()
        inserted = (response.data or [{}])[0]
        return {"success": True, "data": inserted}
    except Exception as e:
        msg = str(e)
        if "negative" in msg.lower():
            raise HTTPException(status_code=409, detail="This entry would take the vault balance negative.")
        # RLS rejection (should no longer fire now that role is checked above,
        # but the service-role key means RLS was never actually the gate here)
        # or the DB guard trigger.
        raise HTTPException(status_code=403, detail=f"Failed to insert vault entry: {e}")


# ============================================================================
# SECTION: Treasurer — Cash Ledger (all cash movements, read-only)
# Aggregates every cash-affecting transaction the Cashier processes into a
# single ledger view for the Treasurer. Distinct from the Bookkeeper Payments
# page, which is loan-payments only. This ledger uses formal accounting
# convention from the cooperative's cash-account perspective:
#   Debit  = cash IN  (loan payments, savings deposits, CBU, membership fees, vault deposits)
#   Credit = cash OUT (savings withdrawals, loan disbursals, vault withdrawals)
# No running balance — this endpoint is display-only, not a source of truth
# for cash on hand (vault_balance_v owns that).
# ============================================================================

@app.get("/api/treasurer/cash-ledger")
async def get_treasurer_cash_ledger(
    start_date: str | None = None,
    end_date: str | None = None,
    type_filter: str | None = None,
    limit: int = 500,
    offset: int = 0,
):
    """Return a unified cash ledger for the Treasurer.

    Query params:
      - start_date (YYYY-MM-DD): inclusive. Defaults to 30 days ago.
      - end_date   (YYYY-MM-DD): inclusive. Defaults to today.
      - type_filter: optional tag to filter — one of:
          loan_payment, loan_disbursal, savings_deposit, savings_withdrawal,
          cbu_contribution, membership_payment, vault_adjustment
      - limit / offset: pagination. Default 500 rows per page.

    Returns rows shaped as:
      {
        date, reference, description, type,
        member_name, debit, credit, source_table
      }
    Sorted DESC by date so newest entries appear first.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    today = date.today()
    try:
        end_d = date.fromisoformat(end_date) if end_date else today
        start_d = date.fromisoformat(start_date) if start_date else (end_d - timedelta(days=30))
    except ValueError:
        raise HTTPException(status_code=400, detail="Dates must be YYYY-MM-DD.")

    if start_d > end_d:
        raise HTTPException(status_code=400, detail="start_date must be on or before end_date.")

    # Inclusive end-of-day for timestamp columns.
    start_ts = f"{start_d.isoformat()}T00:00:00"
    end_ts = f"{end_d.isoformat()}T23:59:59"

    entries: list[dict] = []

    def _member_name(m: dict | None) -> str:
        if not m:
            return ""
        first = str(m.get("first_name") or "").strip()
        last = str(m.get("last_name") or "").strip()
        return f"{first} {last}".strip()

    want = (type_filter or "").strip().lower() or None
    valid_types = {
        "loan_payment", "loan_disbursal", "savings_deposit", "savings_withdrawal",
        "cbu_contribution", "membership_payment", "vault_adjustment",
    }
    if want and want not in valid_types:
        raise HTTPException(status_code=400, detail=f"Invalid type_filter. Must be one of: {', '.join(sorted(valid_types))}.")

    def _include(t: str) -> bool:
        return want is None or want == t

    # ---- 1) Loan payments (live) — DEBIT (cash in)
    if _include("loan_payment"):
        try:
            resp = (
                supabase.table("loan_payments")
                .select(
                    "id, amount_paid, payment_date, payment_reference, confirmation_status, "
                    "loan:loan_id(control_number, member:member_id(first_name, last_name))"
                )
                .eq("confirmation_status", "validated")
                .gte("payment_date", start_ts)
                .lte("payment_date", end_ts)
                .order("payment_date", desc=True)
                .execute()
            )
            for r in (resp.data or []):
                loan = r.get("loan") or {}
                entries.append({
                    "date": r.get("payment_date"),
                    "reference": r.get("payment_reference") or f"PMT-{r.get('id')}",
                    "description": f"Loan payment · {loan.get('control_number') or '—'}",
                    "type": "loan_payment",
                    "member_name": _member_name(loan.get("member")),
                    "debit": float(r.get("amount_paid") or 0),
                    "credit": 0.0,
                    "status": r.get("confirmation_status"),
                    "source_table": "loan_payments",
                })
        except Exception:
            pass

    # ---- 2) Loan payments (legacy) — DEBIT
    if _include("loan_payment"):
        try:
            resp = (
                supabase.table("loan_payments_legacy")
                .select("id, loan_id, amount_paid, payment_date, payment_code, or_cdv_no")
                .gte("payment_date", start_d.isoformat())
                .lte("payment_date", end_d.isoformat())
                .order("payment_date", desc=True)
                .execute()
            )
            for r in (resp.data or []):
                entries.append({
                    "date": r.get("payment_date"),
                    "reference": r.get("payment_code") or r.get("or_cdv_no") or f"LEG-{r.get('id')}",
                    "description": f"Loan payment (legacy) · {r.get('loan_id') or '—'}",
                    "type": "loan_payment",
                    "member_name": "",
                    "debit": float(r.get("amount_paid") or 0),
                    "credit": 0.0,
                    "status": "validated",
                    "source_table": "loan_payments_legacy",
                })
        except Exception:
            pass

    # ---- 3) Loan disbursals — CREDIT (cash out)
    if _include("loan_disbursal"):
        try:
            resp = (
                supabase.table("loans")
                .select(
                    "control_number, loan_amount, disbursal_date, loan_status, "
                    "member:member_id(first_name, last_name), loan_type:loan_type_id(name)"
                )
                .gte("disbursal_date", start_d.isoformat())
                .lte("disbursal_date", end_d.isoformat())
                .not_.is_("disbursal_date", "null")
                .order("disbursal_date", desc=True)
                .execute()
            )
            for r in (resp.data or []):
                loan_type = (r.get("loan_type") or {}).get("name") or "Loan"
                entries.append({
                    "date": r.get("disbursal_date"),
                    "reference": r.get("control_number") or "—",
                    "description": f"{loan_type} disbursal · {r.get('control_number') or '—'}",
                    "type": "loan_disbursal",
                    "member_name": _member_name(r.get("member")),
                    "debit": 0.0,
                    "credit": float(r.get("loan_amount") or 0),
                    "status": r.get("loan_status"),
                    "source_table": "loans",
                })
        except Exception:
            pass

    # ---- 4) Savings ledger — DEBIT for deposit, CREDIT for withdrawal
    if _include("savings_deposit") or _include("savings_withdrawal"):
        try:
            resp = (
                supabase.table("savings_ledger")
                .select("id, account_number, entry_type, amount, reference, posted_at")
                .gte("posted_at", start_ts)
                .lte("posted_at", end_ts)
                .order("posted_at", desc=True)
                .execute()
            )
            for r in (resp.data or []):
                entry_type = str(r.get("entry_type") or "").strip().lower()
                is_withdrawal = "withdraw" in entry_type
                tag = "savings_withdrawal" if is_withdrawal else "savings_deposit"
                if not _include(tag):
                    continue
                amt = float(r.get("amount") or 0)
                entries.append({
                    "date": r.get("posted_at"),
                    "reference": r.get("reference") or f"SAV-{r.get('id')}",
                    "description": f"{'Savings withdrawal' if is_withdrawal else 'Savings deposit'} · Acct {r.get('account_number') or '—'}",
                    "type": tag,
                    "member_name": "",
                    "debit": 0.0 if is_withdrawal else amt,
                    "credit": amt if is_withdrawal else 0.0,
                    "status": "posted",
                    "source_table": "savings_ledger",
                })
        except Exception:
            pass

    # ---- 5) CBU contributions — DEBIT
    if _include("cbu_contribution"):
        try:
            resp = (
                supabase.table("capital_build_up")
                .select(
                    "id, capital_added, transaction_date, "
                    "member:member_id(first_name, last_name)"
                )
                .gte("transaction_date", start_ts)
                .lte("transaction_date", end_ts)
                .order("transaction_date", desc=True)
                .execute()
            )
            for r in (resp.data or []):
                entries.append({
                    "date": r.get("transaction_date"),
                    "reference": f"CBU-{r.get('id')}",
                    "description": "CBU contribution",
                    "type": "cbu_contribution",
                    "member_name": _member_name(r.get("member")),
                    "debit": float(r.get("capital_added") or 0),
                    "credit": 0.0,
                    "status": "posted",
                    "source_table": "capital_build_up",
                })
        except Exception:
            pass

    # ---- 6) Membership payments — DEBIT
    if _include("membership_payment"):
        try:
            resp = (
                supabase.table("membership_payments")
                .select("id, application_id, payment_date, payment_status, payment_type, amount")
                .eq("payment_status", "paid")
                .gte("payment_date", start_ts)
                .lte("payment_date", end_ts)
                .order("payment_date", desc=True)
                .execute()
            )
            for r in (resp.data or []):
                entries.append({
                    "date": r.get("payment_date"),
                    "reference": f"MEM-{r.get('id')}",
                    "description": f"Membership {r.get('payment_type') or 'payment'} · App {r.get('application_id') or '—'}",
                    "type": "membership_payment",
                    "member_name": "",
                    "debit": float(r.get("amount") or 0),
                    "credit": 0.0,
                    "status": r.get("payment_status"),
                    "source_table": "membership_payments",
                })
        except Exception:
            pass

    # ---- 7) Vault entries — sign of `amount` decides debit vs credit
    if _include("vault_adjustment"):
        try:
            resp = (
                supabase.table("vault_entries")
                .select("id, amount, change_type, note, reference_id, created_at")
                .gte("created_at", start_ts)
                .lte("created_at", end_ts)
                .order("created_at", desc=True)
                .execute()
            )
            for r in (resp.data or []):
                amt = float(r.get("amount") or 0)
                change_type = str(r.get("change_type") or "adjustment")
                # Skip disbursements here — already captured as loan_disbursal
                # rows from the `loans` table above, would double-count.
                if change_type.lower() == "disbursement":
                    continue
                entries.append({
                    "date": r.get("created_at"),
                    "reference": f"VLT-{r.get('id')}",
                    "description": f"Vault {change_type}" + (f" · {r.get('note')}" if r.get("note") else ""),
                    "type": "vault_adjustment",
                    "member_name": "",
                    "debit": amt if amt > 0 else 0.0,
                    "credit": abs(amt) if amt < 0 else 0.0,
                    "status": None,
                    "source_table": "vault_entries",
                })
        except Exception:
            pass

    # Sort DESC by date (all sources produce ISO strings — lexicographic sort works).
    entries.sort(key=lambda e: str(e.get("date") or ""), reverse=True)

    # Totals across the full filtered window (pre-pagination) so the KPI cards
    # reflect the window, not just the visible page.
    total_debit = sum(e.get("debit") or 0 for e in entries)
    total_credit = sum(e.get("credit") or 0 for e in entries)

    # Pagination — applied AFTER totals so cards stay meaningful.
    paged = entries[offset : offset + limit]

    return {
        "success": True,
        "data": {
            "entries": paged,
            "total_count": len(entries),
            "total_debit": total_debit,
            "total_credit": total_credit,
            "net": total_debit - total_credit,
            "window": {"start": start_d.isoformat(), "end": end_d.isoformat()},
        },
    }


# ============================================================================
# SECTION: Cashier — CBU (Capital Build-Up)
# Endpoints for listing CBU members, viewing balances, listing deposit
# transactions, and recording CBU deposits.
# ============================================================================

@app.get("/api/cashier/cbu/members")
def get_cashier_cbu_members():
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        try:
            member_response = (
                supabase.table("member")
                .select("id,membership_id,first_name,middle_initial,last_name,created_at")
                .execute()
            )
        except Exception:
            try:
                member_response = (
                    supabase.table("member")
                    .select("id,membership_id,first_name,middle_initial,last_name")
                    .execute()
                )
            except Exception as err:
                raise HTTPException(status_code=500, detail=f"Unable to load members: {err}")

        member_rows = member_response.data or []

        # Paged, not a single .execute() -- PostgREST silently caps an
        # unbounded select at its default row limit (1000). This table is
        # past 1,700 rows, so a single-shot fetch would silently drop
        # whichever rows fall outside that first page and show stale
        # balances for any member whose latest row landed in the dropped
        # slice. Same fix as the legacy-payments/schedules pagination in
        # get_bookkeeper_manage_loans and the sequence scan in
        # create_cashier_cbu_deposit below.
        def _fetch_all_cbu_rows(columns: str) -> list[dict]:
            rows: list[dict] = []
            page = 1000
            offset = 0
            while True:
                batch = (
                    supabase.table("capital_build_up")
                    .select(columns)
                    .range(offset, offset + page - 1)
                    .execute()
                ).data or []
                rows.extend(batch)
                if len(batch) < page:
                    break
                offset += page
            return rows

        try:
            cbu_rows = _fetch_all_cbu_rows(
                "id,member_id,transaction_date,starting_share_capital,capital_added,ending_share_capital,cbu_deposit_id"
            )
        except Exception:
            cbu_rows = _fetch_all_cbu_rows(
                "id,member_id,transaction_date,starting_share_capital,capital_added,ending_share_capital"
            )

        # Pick the most recent CBU row per member. Same-day deposits can share
        # an identical `transaction_date` (legacy date-only rows), so we tie-
        # break on cbu_deposit_id's numeric suffix, not the row `id` -- `id`
        # is gen_random_uuid(), unrelated to insertion order, and comparing it
        # as text once let a stale row win the walk and broke the running-
        # balance chain (see the 2026-09-04 fix / cbu_backup_*.json). Same
        # ordering as create_cashier_cbu_deposit's _cbu_row_order below and
        # isc_v2_02_preview.sql.
        def _cbu_sort_key(row: dict) -> tuple:
            raw = str(row.get("cbu_deposit_id") or "")
            digits = "".join(ch for ch in raw if ch.isdigit())
            # Compare the date portion only. Most rows are date-only, but a few
            # (e.g. the initial-paid-up-capital import) carry a real
            # time-of-day, which otherwise sorts that row after a same-day
            # deposit with a much higher (truly later) sequence number and
            # makes the displayed balance regress. See the matching note on
            # _cbu_row_order below.
            return (
                str(row.get("transaction_date") or "")[:10],
                int(digits) if digits else -1,
                str(row.get("id") or ""),
            )

        # Exclude rows dated after today -- see the matching guard (and its
        # full explanation) in create_cashier_cbu_deposit's starting_balance
        # lookup below. The yearly import pre-creates a Dec-31 snapshot for
        # the CURRENT year before it's over, so without this guard the
        # displayed "current balance" freezes at that stale snapshot the
        # moment the import runs, for every real deposit made the rest of
        # the year.
        today_str = datetime.utcnow().date().isoformat()
        latest_cbu_by_member: dict[str, dict] = {}
        for row in cbu_rows:
            member_id = str(row.get("member_id") or "").strip()
            if not member_id:
                continue
            if str(row.get("transaction_date") or "")[:10] > today_str:
                continue
            previous = latest_cbu_by_member.get(member_id)
            if previous is None or _cbu_sort_key(row) > _cbu_sort_key(previous):
                latest_cbu_by_member[member_id] = row

        mapped_members = []
        for member in member_rows:
            member_uuid = str(member.get("id") or "").strip()
            if not member_uuid:
                continue

            latest = latest_cbu_by_member.get(member_uuid)
            is_new_member = latest is None
            current_balance = Decimal(str(latest.get("ending_share_capital") if latest else CBU_STARTING_CAPITAL))
            if current_balance < 0:
                current_balance = Decimal("0")

            mapped_members.append(
                {
                    "member_uuid": member_uuid,
                    "member_id": member.get("membership_id") or member_uuid,
                    "member_name": resolve_member_full_name(member),
                    "created_at": member.get("created_at"),
                    "current_balance": decimal_to_float(current_balance),
                    "current_shares": decimal_to_float(current_balance / CBU_SHARE_VALUE),
                    "is_new_member": is_new_member,
                    "starting_capital": decimal_to_float(CBU_STARTING_CAPITAL),
                }
            )

        # Show newest created members first so newly created accounts appear at the top.
        has_created_at = any(str(row.get("created_at") or "").strip() for row in mapped_members)
        if has_created_at:
            mapped_members.sort(
                key=lambda row: (
                    str(row.get("created_at") or ""),
                    str(row.get("member_name") or "").lower(),
                ),
                reverse=True,
            )
        else:
            mapped_members.sort(key=lambda row: str(row.get("member_name") or "").lower())
        return {"success": True, "data": mapped_members}
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load CBU members: {err}")


@app.get("/api/cashier/cbu/members/{member_ref}")
def get_cashier_cbu_member(member_ref: str):
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        clean_ref = str(member_ref or "").strip()
        if not clean_ref:
            raise HTTPException(status_code=400, detail="member_ref is required.")

        members_payload = get_cashier_cbu_members()
        members = members_payload.get("data") or []

        target = next(
            (
                row
                for row in members
                if str(row.get("member_uuid") or "") == clean_ref
                or str(row.get("member_id") or "") == clean_ref
            ),
            None,
        )

        if not target:
            raise HTTPException(status_code=404, detail="Member not found.")

        return {"success": True, "data": target}
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load CBU member: {err}")


@app.get("/api/cashier/cbu/members/{member_ref}/history")
def get_cashier_cbu_member_history(member_ref: str):
    """Full CBU ledger for one member, newest first, for the Capital Build-Up
    detail modal. The all-members transaction list is capped by PostgREST's
    row limit, so a member's history is read on its own here.

    `member_ref` is the member.id UUID or the membership_id. Rows dated after
    today (the yearly import's pre-created Dec-31 placeholder) are left out, as
    they are for the balance itself.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    clean_ref = str(member_ref or "").strip()
    if not clean_ref:
        raise HTTPException(status_code=400, detail="member_ref is required.")

    try:
        member_table = _resolve_member_table(supabase)
        lookup_field = "id" if len(clean_ref) == 36 and clean_ref.count("-") == 4 else "membership_id"
        member = (
            supabase.table(member_table)
            .select("id,membership_id,first_name,middle_initial,last_name")
            .eq(lookup_field, clean_ref)
            .limit(1)
            .execute()
        ).data or []
        if not member:
            raise HTTPException(status_code=404, detail="Member not found.")
        member = member[0]

        try:
            rows = (
                supabase.table("capital_build_up")
                .select("id,transaction_date,starting_share_capital,capital_added,ending_share_capital,deposit_account,cbu_deposit_id")
                .eq("member_id", member["id"])
                .execute()
            ).data or []
        except Exception:
            # Older databases without cbu_deposit_id / deposit_account.
            rows = (
                supabase.table("capital_build_up")
                .select("id,transaction_date,starting_share_capital,capital_added,ending_share_capital")
                .eq("member_id", member["id"])
                .execute()
            ).data or []

        today_iso = datetime.utcnow().date().isoformat()
        rows = [r for r in rows if str(r.get("transaction_date") or "")[:10] <= today_iso]

        # Same ordering as the balance walk: date, then the numeric suffix of
        # cbu_deposit_id (row ids are random UUIDs, not insertion order).
        def _sort_key(row: dict) -> tuple:
            digits = "".join(ch for ch in str(row.get("cbu_deposit_id") or "") if ch.isdigit())
            return (str(row.get("transaction_date") or ""), int(digits) if digits else -1, str(row.get("id") or ""))

        rows.sort(key=_sort_key, reverse=True)

        history = [
            {
                "cbu_deposit_id": r.get("cbu_deposit_id"),
                "transaction_date": r.get("transaction_date"),
                "deposit_account": r.get("deposit_account") or "Cash",
                "starting_balance": decimal_to_float(r.get("starting_share_capital") or 0),
                "capital_added": decimal_to_float(r.get("capital_added") or 0),
                "ending_balance": decimal_to_float(r.get("ending_share_capital") or 0),
            }
            for r in rows
        ]
        return {
            "success": True,
            "data": {
                "member_uuid": member["id"],
                "member_id": member.get("membership_id"),
                "member_name": resolve_member_full_name(member),
                "transactions": history,
            },
        }
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load CBU history: {err}")


@app.get("/api/cashier/cbu/transactions")
async def get_cashier_cbu_transactions():
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        try:
            response = (
                supabase.table("capital_build_up")
                .select("id,member_id,transaction_date,capital_added,deposit_account,cbu_deposit_id,member:member_id(first_name,middle_initial,last_name,membership_id)")
                .order("transaction_date", desc=True)
                .execute()
            )
        except Exception:
            response = (
                supabase.table("capital_build_up")
                .select("id,member_id,transaction_date,capital_added,deposit_account,member:member_id(first_name,middle_initial,last_name,membership_id)")
                .order("transaction_date", desc=True)
                .execute()
            )

        rows = response.data or []
        mapped = []
        for idx, row in enumerate(rows, start=1):
            member = row.get("member") or {}
            mapped.append(
                {
                    "cbu_deposit_id": row.get("cbu_deposit_id") or build_cbu_deposit_id(idx),
                    "member_id": member.get("membership_id") or row.get("member_id"),
                    "member_name": resolve_member_full_name(member),
                    "capital_added": decimal_to_float(row.get("capital_added") or 0),
                    "deposit_account": row.get("deposit_account") or "Cash",
                    "transaction_date": row.get("transaction_date"),
                    "status": "VERIFIED",
                }
            )

        return {"success": True, "data": mapped}
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load CBU transactions: {err}")


# The audit_log triggers on cashier-transaction tables (loan_payments,
# capital_build_up, savings_ledger, membership_payments,
# disbursement_confirmations) resolve the actor via Postgres's own
# auth.uid()/auth.role() session context (audit_resolve_actor() in
# audit_log_schema.sql). That context is always 'service_role' for a
# backend-initiated write, since this file's `supabase` client authenticates
# with the service role key regardless of which staff member is calling — so
# every one of those rows landed with actor_role='service_role' ("System" in
# the UI) no matter who actually pressed the button.
#
# Rather than threading a real user session through Supabase for every write
# (a much bigger change), this patches the actor fields on the row the
# trigger already wrote, right after the endpoint has verified who called it.
# Safe to call unconditionally: if the endpoint wasn't reached with a valid
# bearer token, current_user is never populated and this function isn't
# invoked at all (see call sites below).
def _correct_audit_actor(entity_type: str, entity_id: str, current_user: dict) -> None:
    if not supabase or not current_user or not current_user.get("id"):
        return
    try:
        role = None
        role_resp = (
            supabase.table("member_account")
            .select("role")
            .or_(f"auth_user_id.eq.{current_user['id']},email.eq.{current_user.get('email', '')}")
            .limit(1)
            .execute()
        )
        if role_resp.data:
            role = role_resp.data[0].get("role")

        latest = (
            supabase.table("audit_log")
            .select("id")
            .eq("entity_type", entity_type)
            .eq("entity_id", entity_id)
            .order("occurred_at", desc=True)
            .limit(1)
            .execute()
        )
        row_id = (latest.data or [None])[0]
        if not row_id:
            return
        supabase.table("audit_log").update({
            "actor_user_id": current_user["id"],
            "actor_role": role,
            "actor_email": current_user.get("email"),
        }).eq("id", row_id["id"]).execute()
    except Exception:
        # Best-effort correction — the underlying transaction already
        # succeeded, and a failure here should never surface as an error on
        # the action itself. The row simply keeps its service_role attribution.
        pass


@app.post("/api/cashier/cbu/deposits")
def create_cashier_cbu_deposit(
    payload: CashierCBUDepositRequest,
    current_user: dict | None = _Depends(_get_current_user_optional),
):
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        member_ref = str(payload.member_id or "").strip()
        if not member_ref:
            raise HTTPException(status_code=400, detail="member_id is required.")

        members_payload = get_cashier_cbu_members()
        members = members_payload.get("data") or []
        member_row = next(
            (
                row
                for row in members
                if str(row.get("member_uuid") or "") == member_ref
                or str(row.get("member_id") or "") == member_ref
            ),
            None,
        )
        if not member_row:
            raise HTTPException(status_code=404, detail="Member not found.")

        member_uuid = str(member_row.get("member_uuid") or "").strip()
        if not member_uuid:
            raise HTTPException(status_code=400, detail="Member UUID is missing.")

        # Reject a deposit for a terminated/inactive member. ISC eligibility and
        # other CBU-derived reporting assume only active members hold live
        # share capital; nothing upstream of this endpoint enforced that.
        try:
            status_response = (
                supabase.table("member")
                .select("member_status")
                .eq("id", member_uuid)
                .limit(1)
                .execute()
            )
            status_row = (status_response.data or [None])[0] or {}
            member_status = str(status_row.get("member_status") or "active").strip().lower()
            if member_status not in ("", "active"):
                raise HTTPException(
                    status_code=400,
                    detail=f"Cannot post a CBU deposit for a {member_status} member.",
                )
        except HTTPException:
            raise
        except Exception:
            # member_status column unavailable — do not block deposits over a
            # schema gap; the intent is to reject terminated members, not to
            # fail deposits when the column is missing.
            pass

        deposit_amount = Decimal(str(payload.deposit_amount or 0))
        if deposit_amount <= 0:
            raise HTTPException(status_code=400, detail="deposit_amount must be greater than zero.")

        # Most rows store `transaction_date` date-only (00:00:00), so two
        # same-day deposits tie on it and a tiebreaker decides which row is
        # "latest". `id` must NOT be used for that: it is gen_random_uuid(),
        # so ordering by it is random and unrelated to insertion order — that
        # bug let a stale balance win repeatedly and broke the running-balance
        # chain (see cbu_backup_*.json / the 2026-05-21 rows).
        #
        # `cbu_deposit_id` (CBUD_001, CBUD_002, ...) is assigned sequentially by
        # trg_set_cbu_deposit_id, so it does reflect insertion order. Sort on
        # its numeric suffix in Python rather than as text, so CBUD_100 sorts
        # after CBUD_099 rather than before it.
        latest_cbu_response = (
            supabase.table("capital_build_up")
            .select("ending_share_capital,transaction_date,id,cbu_deposit_id")
            .eq("member_id", member_uuid)
            .execute()
        )

        def _cbu_row_order(row: dict) -> tuple:
            raw = str(row.get("cbu_deposit_id") or "")
            digits = "".join(ch for ch in raw if ch.isdigit())
            # Date portion only -- see the matching note on _cbu_sort_key above.
            # A row with a real time-of-day (e.g. an import row) must not
            # outrank a same-day row with a higher sequence number.
            return (
                str(row.get("transaction_date") or "")[:10],
                int(digits) if digits else -1,
                str(row.get("id") or ""),
            )

        # Exclude rows dated AFTER today. The yearly historical import
        # pre-creates a Dec-31 snapshot for the current year before the year
        # is over (capital_added=0, ending_share_capital = whatever the
        # balance was at import time). Sorted purely by date, that
        # future-dated placeholder always outranks a real deposit made
        # earlier the same year, so every subsequent deposit would compute
        # its starting_balance from the STALE placeholder instead of the
        # true latest real entry -- silently dropping every prior real
        # deposit from the running-balance chain. Confirmed live: TTMPC-068's
        # second 2026 deposit ignored her first (see the 2026-09-17 incident
        # notes / conversation this fix came out of).
        today_str = datetime.utcnow().date().isoformat()
        eligible_cbu_rows = [
            row
            for row in (latest_cbu_response.data or [])
            if str(row.get("transaction_date") or "")[:10] <= today_str
        ]
        latest_cbu_row = max(
            eligible_cbu_rows,
            key=_cbu_row_order,
            default=None,
        )

        starting_balance = Decimal(str((latest_cbu_row or {}).get("ending_share_capital") or CBU_STARTING_CAPITAL))
        if starting_balance < 0:
            # A negative running balance means the chain is already broken
            # upstream of this deposit — clamping it to 0 would silently hide
            # that and let the deposit paper over a data-integrity problem.
            raise HTTPException(
                status_code=409,
                detail=(
                    "This member's running CBU balance is negative "
                    f"({decimal_to_float(starting_balance)}), which indicates a broken "
                    "capital_build_up chain. Fix the chain before posting a new deposit."
                ),
            )
        ending_balance = starting_balance + deposit_amount

        # Derive the next sequence from the HIGHEST existing CBUD_nnn suffix,
        # not from a row count. A count undercounts once any row has ever been
        # deleted and collides with an id already in use.
        #
        # Paged, not a single .execute() -- PostgREST silently caps an
        # unbounded select at its default row limit (1000). With this table
        # past 1,700 rows, a single-shot scan only sees an arbitrary subset,
        # so the computed "highest" sequence can be lower than the true max
        # and collide with a real row outside that slice (observed live:
        # scan settled on 1966 -> next id CBUD_1967 -> already existed,
        # insert failed with a 500 and the deposit was silently never
        # recorded). Same fix as the legacy-payments/schedules pagination
        # above in get_bookkeeper_manage_loans.
        highest_sequence = 0
        _seq_page = 1000
        _seq_offset = 0
        while True:
            _seq_batch = (
                supabase.table("capital_build_up")
                .select("cbu_deposit_id")
                .range(_seq_offset, _seq_offset + _seq_page - 1)
                .execute()
            ).data or []
            for row in _seq_batch:
                digits = "".join(ch for ch in str(row.get("cbu_deposit_id") or "") if ch.isdigit())
                if digits:
                    highest_sequence = max(highest_sequence, int(digits))
            if len(_seq_batch) < _seq_page:
                break
            _seq_offset += _seq_page
        next_sequence = highest_sequence + 1

        cbu_deposit_id = build_cbu_deposit_id(next_sequence)

        # Keep IDs unique even if the frontend sends a fixed placeholder (e.g., CBUD_001).
        try:
            existing_id_response = (
                supabase.table("capital_build_up")
                .select("id")
                .eq("cbu_deposit_id", cbu_deposit_id)
                .limit(1)
                .execute()
            )
            if existing_id_response.data:
                fallback_sequence = next_sequence
                while True:
                    candidate = build_cbu_deposit_id(fallback_sequence)
                    candidate_exists = (
                        supabase.table("capital_build_up")
                        .select("id")
                        .eq("cbu_deposit_id", candidate)
                        .limit(1)
                        .execute()
                    )
                    if not candidate_exists.data:
                        cbu_deposit_id = candidate
                        break
                    fallback_sequence += 1
        except Exception:
            # If cbu_deposit_id column does not exist yet, insertion fallback handles it.
            pass

        # Store date-only, matching every other CBU writer (the historical
        # import, the loan-disbursement trigger, membership payments). A full
        # timestamp here while other rows are date-only breaks same-day
        # tiebreaking and reproduces the running-balance chain bug already
        # fixed once (see cbu_backup_*.json).
        deposit_date = (payload.transaction_date or datetime.utcnow()).date()

        # Dedup guard: reject an identical deposit (same member, same date,
        # same amount) already on record. Cashier-entered rows carry no
        # source_* key the way loan/payment/ISC writers do, so a double-click
        # or retried request would otherwise credit share capital twice.
        duplicate_check = (
            supabase.table("capital_build_up")
            .select("id")
            .eq("member_id", member_uuid)
            .eq("transaction_date", deposit_date.isoformat())
            .eq("capital_added", decimal_to_float(deposit_amount))
            .limit(1)
            .execute()
        )
        if duplicate_check.data:
            raise HTTPException(
                status_code=409,
                detail="An identical CBU deposit for this member, date, and amount already exists.",
            )

        insert_payload = {
            "member_id": member_uuid,
            "transaction_date": deposit_date.isoformat(),
            "starting_share_capital": decimal_to_float(starting_balance),
            "capital_added": decimal_to_float(deposit_amount),
            "deposit_account": str(payload.deposit_account or "Cash").strip() or "Cash",
            "ending_share_capital": decimal_to_float(ending_balance),
            "cbu_deposit_id": cbu_deposit_id,
        }

        # Who recorded it, so the receipt can name them and they can open the
        # pop-up (receipts_04_cbu.sql adds the column).
        if current_user and current_user.get("id"):
            insert_payload["recorded_by"] = str(current_user["id"])

        # No silent fallback insert. A failure here means something real is
        # wrong with the payload/schema — surfacing it beats a stripped-down
        # retry that can drop fields (e.g. deposit_account) and make a broken
        # write look like a successful deposit. The one exception is
        # recorded_by, before receipts_04_cbu.sql is applied.
        try:
            insert_response = supabase.table("capital_build_up").insert(insert_payload).execute()
        except Exception as insert_err:
            if "recorded_by" not in insert_payload or "recorded_by" not in str(insert_err):
                raise
            insert_payload.pop("recorded_by")
            insert_response = supabase.table("capital_build_up").insert(insert_payload).execute()
        inserted_row = (insert_response.data or [None])[0]
        _correct_audit_actor("cbu", (inserted_row or {}).get("cbu_deposit_id") or cbu_deposit_id, current_user)

        # The receipt the trigger issued in the same insert (none for an
        # unrecognised "Paid by" value, or before receipts_04_cbu.sql).
        cbu_receipt_no = None
        if inserted_row and inserted_row.get("id"):
            try:
                cbu_receipt_no = ((
                    supabase.table("receipts").select("receipt_no")
                    .eq("source_type", "cbu").eq("source_id", str(inserted_row["id"]))
                    .limit(1).execute()
                ).data or [{}])[0].get("receipt_no")
            except Exception as receipt_err:
                logger.warning("CBU receipt lookup failed for %s: %s", inserted_row.get("id"), receipt_err)

        return {
            "success": True,
            "message": "CBU deposit recorded successfully.",
            "data": {
                "cbu_deposit_id": (inserted_row or {}).get("cbu_deposit_id") or cbu_deposit_id,
                "member_id": member_row.get("member_id"),
                "member_uuid": member_uuid,
                "member_name": member_row.get("member_name"),
                "starting_balance": decimal_to_float(starting_balance),
                "capital_added": decimal_to_float(deposit_amount),
                "ending_balance": decimal_to_float(ending_balance),
                "ending_shares": decimal_to_float(ending_balance / CBU_SHARE_VALUE),
                "transaction_date": (inserted_row or {}).get("transaction_date") or insert_payload["transaction_date"],
                "deposit_account": insert_payload["deposit_account"],
                "receipt_no": cbu_receipt_no,
            },
        }
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to create CBU deposit: {err}")


# ============================================================================
# SECTION: Disbursement net-cash-out — shared by the Cashier preview/disburse
# endpoints and the Treasurer vault/rescheduled endpoints below.
#
# "Net cash out" is what actually leaves the vault for a loan release, which is
# NOT the loan's principal (RESCHEDULED_LOANS_PLAN.md §4):
#   net_cash_out = principal − fee deductions − renewal payoff
# where the renewal payoff is the outstanding balance of the loan being
# renewed (application_type = 'renewal' offsets against the predecessor loan
# of the same member_id + loan_type — the loan is not disbursed twice; the new
# principal covers the old balance plus whatever the member actually receives).
# Using gross principal both over-deducts the vault on every renewal and
# wrongly reschedules renewals that are perfectly affordable.
# ============================================================================

VALIDATED_PAYMENT_STATUSES = ["validated", "confirmed", "bookkeeper_confirmed", "approved"]


def _resolve_loan_type_code_for_breakdown(loan_type_row: dict | None) -> str:
    type_code = str((loan_type_row or {}).get("code") or "").strip().upper()
    if type_code:
        return type_code
    type_name = str((loan_type_row or {}).get("name") or "").strip().lower()
    normalized = normalize_cashier_loan_type(type_name)
    if normalized == "bonus":
        return "NONMEMBER_BONUS" if "non" in type_name and "member" in type_name else "BONUS"
    return resolve_loan_type_code(normalized)


def _fee_breakdown_for_principal(type_code: str, principal: Decimal) -> dict:
    policy = resolve_fee_policy(type_code)
    service_fee = compute_service_fee(policy, principal)
    insurance_fee = money((principal * policy["insurance_per_thousand"]) / Decimal("1000"))
    cbu_deduction = money(principal * policy["cbu_rate"])
    notarial_fee = money(policy["notarial_fee"])
    return {
        "service_fee": service_fee,
        "cbu_deduction": cbu_deduction,
        "insurance_fee": insurance_fee,
        "notarial_fee": notarial_fee,
        "total_deductions": money(service_fee + cbu_deduction + insurance_fee + notarial_fee),
    }


def _resolve_renewal_predecessors(loan_rows: list[dict]) -> dict[str, dict]:
    """control_number (of a RENEWAL row) -> its immediate predecessor loan row.

    Predecessor = the loan most recently applied for by the same member_id,
    for the same loan_type name, strictly before this row's application_date,
    excluding rejected/cancelled — the same (member_id, loan_type) chain
    already used for prior_versions_by_loan / get_active_cashier_loan_ids.
    Rows that aren't renewals, have no member_id, or whose predecessor can't
    be resolved are simply absent from the result.
    """
    renewal_rows = [
        r for r in loan_rows
        if str(r.get("application_type") or "").strip().lower() == "renewal" and r.get("member_id")
    ]
    if not renewal_rows or not supabase:
        return {}

    member_ids = sorted({r["member_id"] for r in renewal_rows})
    try:
        candidates_resp = (
            supabase.table("loans")
            .select(
                "control_number,member_id,application_date,loan_status,principal_amount,loan_amount,"
                "total_interest,monthly_amortization,term,loan_type:loan_type_id(name)"
            )
            .in_("member_id", member_ids)
            .execute()
        )
    except Exception as err:
        logger.warning("renewal predecessor lookup failed: %s", err)
        return {}

    candidates = [
        r for r in (candidates_resp.data or [])
        if str(r.get("loan_status") or "").strip().lower() not in {"rejected", "cancelled"}
    ]

    chains: dict[tuple, list[dict]] = {}
    for row in candidates:
        mid = row.get("member_id")
        ltype = (row.get("loan_type") or {}).get("name") or ""
        if not mid or not ltype:
            continue
        chains.setdefault((mid, ltype), []).append(row)
    for items in chains.values():
        items.sort(key=lambda r: str(r.get("application_date") or ""))

    predecessor_by_control: dict[str, dict] = {}
    for r in renewal_rows:
        mid = r.get("member_id")
        ltype = (r.get("loan_type") or {}).get("name") or ""
        cn = str(r.get("control_number") or "")
        chain = chains.get((mid, ltype)) or []
        idx = next((i for i, c in enumerate(chain) if str(c.get("control_number")) == cn), None)
        if idx is not None and idx > 0:
            predecessor_by_control[cn] = chain[idx - 1]

    return predecessor_by_control


def _outstanding_balances(loan_rows: list[dict]) -> dict[str, Decimal]:
    """control_number -> outstanding balance (total payable − validated payments)."""
    if not loan_rows or not supabase:
        return {}
    control_numbers = sorted({str(r.get("control_number")) for r in loan_rows if r.get("control_number")})
    if not control_numbers:
        return {}
    try:
        payments_resp = (
            supabase.table("loan_payments")
            .select("loan_id,amount_paid,confirmation_status")
            .in_("loan_id", control_numbers)
            .in_("confirmation_status", VALIDATED_PAYMENT_STATUSES)
            .execute()
        )
        payment_rows = payments_resp.data or []
    except Exception as err:
        logger.warning("outstanding-balance payment lookup failed: %s", err)
        payment_rows = []

    paid_by_loan: dict[str, Decimal] = {}
    for p in payment_rows:
        key = str(p.get("loan_id") or "")
        paid_by_loan[key] = paid_by_loan.get(key, Decimal("0")) + Decimal(str(p.get("amount_paid") or 0))

    result: dict[str, Decimal] = {}
    for r in loan_rows:
        cn = str(r.get("control_number") or "")
        if not cn:
            continue
        payable = _loan_total_payable(r)
        result[cn] = max(payable - paid_by_loan.get(cn, Decimal("0")), Decimal("0"))
    return result


LOAN_FEE_SNAPSHOT_COLUMNS = "service_fee,cbu_deduction,insurance_fee,notarial_fee,net_proceeds"
_FEE_KEYS = ("service_fee", "cbu_deduction", "insurance_fee", "notarial_fee")


def _stored_fee_breakdown(loan_row: dict) -> dict | None:
    """Fees frozen on the loan at application time (trg_snapshot_loan_fees), or
    None for older loans that predate it — those fall back to the live policy."""
    if any(loan_row.get(k) is None for k in _FEE_KEYS):
        return None
    fees = {k: money(Decimal(str(loan_row.get(k)))) for k in _FEE_KEYS}
    fees["total_deductions"] = money(sum(fees.values(), Decimal("0")))
    return fees


def _estimate_bonus_upfront_interest(loan_row: dict) -> Decimal:
    """Estimate Saka upfront interest for a Bonus loan that hasn't been
    released yet (preview / vault-availability contexts), from whatever term
    and rate are currently stored on the row. This is only an estimate — the
    real figure is recomputed from the actual release date in
    disburse_cashier_loan, since the application-time term can be stale
    (BONUS_LOAN_PLAN.md as-built notes)."""
    loan_type_row = loan_row.get("loan_type") or {}
    if normalize_cashier_loan_type(loan_type_row.get("name")) != "bonus":
        return Decimal("0")
    principal = Decimal(str(loan_row.get("principal_amount") or loan_row.get("loan_amount") or 0))
    term_months = int(loan_row.get("term") or 0)
    if principal <= 0 or term_months <= 0:
        return Decimal("0")
    interest_rate_percent = (
        Decimal(str(loan_row.get("interest_rate"))) if loan_row.get("interest_rate") is not None else None
    )
    monthly_rate = resolve_monthly_rate_decimal(
        "bonus",
        interest_rate_percent,
        loan_type_code=resolve_loan_type_code("bonus"),
        loan_type_name=loan_type_row.get("name"),
    )
    if monthly_rate <= 0:
        return Decimal("0")
    return money(principal * monthly_rate * Decimal(term_months))


def _compute_net_cash_out(
    loan_row: dict,
    renewal_payoff: Decimal = Decimal("0"),
    bonus_upfront_interest: Decimal | None = None,
) -> dict:
    principal = Decimal(str(loan_row.get("principal_amount") or loan_row.get("loan_amount") or 0))
    type_code = _resolve_loan_type_code_for_breakdown(loan_row.get("loan_type") or {})
    fees = _stored_fee_breakdown(loan_row) or (
        _fee_breakdown_for_principal(type_code, principal)
        if principal > 0
        else {"service_fee": Decimal("0"), "cbu_deduction": Decimal("0"), "insurance_fee": Decimal("0"),
              "notarial_fee": Decimal("0"), "total_deductions": Decimal("0")}
    )
    payoff = money(max(renewal_payoff, Decimal("0")))
    # Saka upfront-deduction model (Bookkeeper-confirmed 2026-10-18): Bonus
    # deducts the whole term's interest from proceeds at release, same as a
    # fee. If the caller didn't supply the real release-date figure (only
    # disburse_cashier_loan can, since it knows the actual release date),
    # fall back to an estimate from the loan row's stored term/rate.
    if bonus_upfront_interest is None:
        bonus_upfront_interest = _estimate_bonus_upfront_interest(loan_row)
    upfront_interest = money(max(bonus_upfront_interest, Decimal("0")))
    total_deductions = money(fees["total_deductions"] + upfront_interest)
    net_cash_out = money(max(principal - total_deductions - payoff, Decimal("0")))
    return {
        "loan_type_code": type_code,
        "principal": money(principal),
        "deductions": {
            k: fees[k] for k in ("service_fee", "cbu_deduction", "insurance_fee", "notarial_fee")
        },
        "bonus_upfront_interest": upfront_interest,
        "total_deductions": total_deductions,
        "is_renewal": str(loan_row.get("application_type") or "").strip().lower() == "renewal",
        "renewal_payoff": payoff,
        "net_cash_out": net_cash_out,
    }


def _net_cash_out_for_rows(loan_rows: list[dict]) -> dict[str, Decimal]:
    """control_number -> net_cash_out, for a batch of `loans` rows in one pass."""
    predecessor_map = _resolve_renewal_predecessors(loan_rows)
    payoff_balances = _outstanding_balances(list(predecessor_map.values()))
    result = {}
    for row in loan_rows:
        cn = str(row.get("control_number") or "")
        predecessor = predecessor_map.get(cn)
        payoff = (
            payoff_balances.get(str(predecessor.get("control_number")), Decimal("0"))
            if predecessor else Decimal("0")
        )
        result[cn] = _compute_net_cash_out(row, payoff)["net_cash_out"]
    return result


def _compute_vault_available() -> dict:
    """{balance, committed, available} — committed = SUM(net_cash_out) over
    loans already 'ready for disbursement' (Treasurer-approved, awaiting the
    Cashier's physical release). Checking a loan against the raw balance alone
    allows two loans to each look affordable individually while together
    exceeding funds (RESCHEDULED_LOANS_PLAN.md §3.1)."""
    try:
        balance_resp = supabase.table("vault_balance_v").select("current_balance").limit(1).execute()
        balance = Decimal(str((balance_resp.data or [{}])[0].get("current_balance") or 0))
    except Exception as err:
        logger.warning("vault balance lookup failed: %s", err)
        balance = Decimal("0")

    try:
        # PostgREST caps an unbounded response at its max-rows setting, which
        # silently dropped newer loans off the end of an unordered 1000-row
        # page (the coop now has 1400+ loan rows). Page through the full
        # table, same as the decision-queue endpoint.
        all_loans = []
        page_size = 1000
        offset = 0
        while True:
            batch = (
                supabase.table("loans")
                .select(
                    "control_number,member_id,loan_amount,principal_amount,loan_status,application_type,"
                    f"application_date,term,interest_rate,{LOAN_FEE_SNAPSHOT_COLUMNS},loan_type:loan_type_id(name,code)"
                )
                .range(offset, offset + page_size - 1)
                .execute()
            ).data or []
            if not batch:
                break
            all_loans.extend(batch)
            if len(batch) < page_size:
                break
            offset += page_size
        ready_loans = [
            r for r in all_loans
            if str(r.get("loan_status") or "").strip().lower() == "ready for disbursement"
        ]
    except Exception as err:
        logger.warning("ready-for-disbursement lookup failed: %s", err)
        ready_loans = []

    net_cash_out_by_control = _net_cash_out_for_rows(ready_loans)
    committed = money(sum(net_cash_out_by_control.values(), Decimal("0")))
    available = money(balance - committed)
    return {"balance": balance, "committed": committed, "available": available}


@app.get("/api/cashier/disbursements/{loan_id}/preview")
async def preview_cashier_disbursement(loan_id: str):
    """Deduction (and, for a renewal, payoff) breakdown for releasing an
    EXISTING loan.

    The Review & Disburse dialog used to call /api/loans/compute for this. That
    endpoint validates a loan *application* (Bonus needs a member_category,
    Consolidated caps terms at 60 months, or 72 from ₱500,000, Emergency only 6/12), so the
    preview failed for Bonus loans and for 72-month Consolidated loans and the
    cashier could not release them. Fees depend only on the loan type and
    principal, so they are computed here straight from the stored loan.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    clean_loan_id = str(loan_id or "").strip()
    if not clean_loan_id:
        raise HTTPException(status_code=400, detail="loan_id is required.")

    try:
        loan_response = (
            supabase.table("loans")
            .select(
                "control_number,member_id,loan_amount,principal_amount,application_type,application_date,"
                f"term,interest_rate,{LOAN_FEE_SNAPSHOT_COLUMNS},loan_type:loan_type_id(name,code)"
            )
            .eq("control_number", clean_loan_id)
            .limit(1)
            .execute()
        )
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load loan for preview: {err}")
    loan_row = (loan_response.data or [None])[0]
    if not loan_row:
        raise HTTPException(status_code=404, detail="Loan not found.")

    principal = Decimal(str(loan_row.get("principal_amount") or loan_row.get("loan_amount") or 0))
    if principal <= 0:
        raise HTTPException(status_code=400, detail="Loan principal is missing or invalid.")

    predecessor_map = _resolve_renewal_predecessors([loan_row])
    predecessor = predecessor_map.get(clean_loan_id)
    renewal_payoff = Decimal("0")
    if predecessor:
        renewal_payoff = _outstanding_balances([predecessor]).get(
            str(predecessor.get("control_number")), Decimal("0")
        )

    breakdown = _compute_net_cash_out(loan_row, renewal_payoff)

    return {
        "success": True,
        "data": {
            "loan_type": breakdown["loan_type_code"],
            "principal": decimal_to_float(breakdown["principal"]),
            "deductions": {k: decimal_to_float(v) for k, v in breakdown["deductions"].items()},
            "total_deductions": decimal_to_float(breakdown["total_deductions"]),
            "is_renewal": breakdown["is_renewal"],
            "renewal_payoff": decimal_to_float(breakdown["renewal_payoff"]),
            "net_cash_out": decimal_to_float(breakdown["net_cash_out"]),
            # Back-compat alias: the Cashier's Review & Disburse dialog already
            # reads `net_proceeds` — this is now the renewal-aware true figure.
            "net_proceeds": decimal_to_float(breakdown["net_cash_out"]),
        },
    }


@app.post("/api/cashier/disbursements/{loan_id}/disburse")
async def disburse_cashier_loan(loan_id: str, payload: CashierDisbursementRequest, background_tasks: BackgroundTasks):
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        clean_loan_id = str(loan_id or "").strip()
        if not clean_loan_id:
            raise HTTPException(status_code=400, detail="loan_id is required.")

        loan_response = (
            supabase.table("loans")
            .select(
                "control_number,loan_amount,principal_amount,interest_rate,term,loan_status,total_interest,monthly_amortization,member_id," \
                "application_type,application_date,verified_bonus_amount," \
                f"{LOAN_FEE_SNAPSHOT_COLUMNS}," \
                "member:member_id(first_name,last_name)," \
                "loan_type:loan_type_id(name,code)"
            )
            .eq("control_number", clean_loan_id)
            .limit(1)
            .execute()
        )
        loan_row = (loan_response.data or [None])[0]
        if not loan_row:
            raise HTTPException(status_code=404, detail="Loan not found.")

        current_status = str(loan_row.get("loan_status") or "").strip().lower()
        if current_status != "ready for disbursement":
            raise HTTPException(status_code=400, detail="Loan is not in ready for disbursement status.")

        if normalize_cashier_loan_type((loan_row.get("loan_type") or {}).get("name")) == "bonus":
            # Q8: the cap for Bonus is the Bookkeeper-verified bonus amount,
            # not the MIGS CBU x3/5 cap other loan types use. The frontend
            # already requires this before the Bookkeeper can recommend
            # (BONUS_LOAN_PLAN.md Step 5); this is the server-side backstop
            # where money actually leaves the vault.
            verified_amount = loan_row.get("verified_bonus_amount")
            if verified_amount is None:
                raise HTTPException(
                    status_code=400,
                    detail="This Bonus loan has not had its bonus amount verified by the Bookkeeper yet.",
                )
            requested_amount = Decimal(str(loan_row.get("principal_amount") or loan_row.get("loan_amount") or 0))
            if requested_amount > Decimal(str(verified_amount)):
                raise HTTPException(
                    status_code=400,
                    detail=(
                        f"Loan amount ({requested_amount}) exceeds the Bookkeeper-verified "
                        f"bonus amount ({verified_amount})."
                    ),
                )

        disbursed_at = payload.disbursed_at or datetime.utcnow()
        first_due_date = add_months(disbursed_at.date(), 1)

        loan_type_name = (loan_row.get("loan_type") or {}).get("name")
        normalized_loan_type = normalize_cashier_loan_type(loan_type_name)

        if normalized_loan_type == "bonus":
            # The due date is the actual bonus month-end (nearest upcoming
            # May/Nov from the release date, Q13/D6), not +1 month like
            # other loan types, and the term is recomputed from the real
            # release date rather than whatever was stored at application
            # time (Q4/Q5: partial first month counts as a full month).
            first_due_date = next_bonus_month_end(disbursed_at.date())
            term_months = months_between_rounded_up(disbursed_at.date(), first_due_date)
        else:
            term_months = int(loan_row.get("term") or 0)
            if term_months <= 0:
                raise HTTPException(status_code=400, detail="Loan term is missing or invalid.")

        principal_amount = Decimal(str(loan_row.get("principal_amount") or loan_row.get("loan_amount") or 0))
        if principal_amount <= 0:
            raise HTTPException(status_code=400, detail="Loan principal is missing or invalid.")
        interest_rate_percent = Decimal(str(loan_row.get("interest_rate") or 0)) if loan_row.get("interest_rate") is not None else None
        monthly_rate_decimal = resolve_monthly_rate_decimal(
            normalized_loan_type,
            interest_rate_percent,
            loan_type_code=resolve_loan_type_code(normalized_loan_type),
            loan_type_name=loan_type_name,
        )
        if monthly_rate_decimal <= 0:
            raise HTTPException(status_code=400, detail="Loan interest rate is not configured in loan_types.")

        # Money leaves the vault HERE, atomically, before anything else is
        # written — a refusal (insufficient funds) leaves the loan completely
        # untouched. See vault_debit_for_disbursement() in
        # rescheduled_loans_and_vault_hardening.sql and §3/§8.1 of
        # RESCHEDULED_LOANS_PLAN.md: the vault never moved on disbursement
        # before this, and the deduction must be net cash out, not gross
        # principal, so a renewal's payoff against its old balance is honored.
        predecessor_map = _resolve_renewal_predecessors([loan_row])
        predecessor = predecessor_map.get(clean_loan_id)
        renewal_payoff = Decimal("0")
        if predecessor:
            renewal_payoff = _outstanding_balances([predecessor]).get(
                str(predecessor.get("control_number")), Decimal("0")
            )
        bonus_upfront_interest = None
        if normalized_loan_type == "bonus":
            bonus_upfront_interest = money(principal_amount * monthly_rate_decimal * Decimal(term_months))
        release_breakdown = _compute_net_cash_out(loan_row, renewal_payoff, bonus_upfront_interest)
        net_cash_out = release_breakdown["net_cash_out"]
        if normalized_loan_type == "bonus" and net_cash_out <= 0:
            raise HTTPException(
                status_code=400,
                detail="Net proceeds for this Bonus loan would be zero or negative after upfront interest and fees.",
            )

        vault_debited = False
        vault_new_balance = None
        if net_cash_out > 0:
            try:
                vault_rpc = supabase.rpc(
                    "vault_debit_for_disbursement",
                    {
                        "p_amount": decimal_to_float(net_cash_out),
                        "p_note": f"Disbursement — loan {clean_loan_id}",
                        "p_entered_by": payload.cashier_id,
                    },
                ).execute()
                vault_row = (vault_rpc.data or [None])[0] if isinstance(vault_rpc.data, list) else vault_rpc.data
                vault_new_balance = (vault_row or {}).get("new_balance") if isinstance(vault_row, dict) else None
                vault_debited = True
            except Exception as vault_err:
                msg = str(vault_err).lower()
                if "insufficient_funds" in msg or "insufficient funds" in msg:
                    raise HTTPException(
                        status_code=409,
                        detail=(
                            f"Insufficient vault funds. Releasing this loan requires "
                            f"{money(net_cash_out):,.2f} in cash on hand right now."
                        ),
                    )
                # Schema not migrated yet (rescheduled_loans_and_vault_hardening.sql
                # not applied): don't block a real release on a missing RPC — but
                # never silently: this is exactly what left the vault never moving
                # before (§8.1), so it must be visible in server logs.
                logger.warning("vault_debit_for_disbursement unavailable for loan %s: %s", clean_loan_id, vault_err)

        existing_schedule_response = (
            supabase.table("loan_schedules")
            .select("id,schedule_id")
            .eq("loan_id", clean_loan_id)
            .limit(1)
            .execute()
        )
        if not existing_schedule_response.data:
            existing_schedule_response = (
                supabase.table("loan_schedules")
                .select("id")
                .eq("loan_id", clean_loan_id)
                .limit(1)
                .execute()
            )
        has_existing_schedule = bool(existing_schedule_response.data)

        if has_existing_schedule:
            try:
                schedules_response = (
                    supabase.table("loan_schedules")
                    .select("id,due_date,schedule_status")
                    .eq("loan_id", clean_loan_id)
                    .order("due_date")
                    .execute()
                )
                schedules = schedules_response.data or []
                next_sched = None
                for sched in schedules:
                    status = str(sched.get("schedule_status") or "").strip().lower()
                    if status in {"unpaid", "pending", "overdue", ""}:
                        next_sched = sched
                        break
                if schedules and not next_sched:
                    next_sched = schedules[0]

                if next_sched:
                    current_due = parse_date_value(next_sched.get("due_date"))
                    if not current_due or current_due <= disbursed_at.date():
                        (
                            supabase.table("loan_schedules")
                            .update({"due_date": first_due_date.isoformat()})
                            .eq("id", next_sched.get("id"))
                            .execute()
                        )
            except Exception:
                pass

        created_schedules = []
        if not has_existing_schedule:
            schedule_count_response = supabase.table("loan_schedules").select("id").execute()
            start_sequence_number = len(schedule_count_response.data or []) + 1

            next_due_row = build_single_schedule_row(
                loan_type=normalized_loan_type,
                principal=principal_amount,
                term_months=term_months,
                monthly_rate_decimal=monthly_rate_decimal,
                due_date=first_due_date,
                loan_id=clean_loan_id,
                installment_no=1,
                remaining_principal_before=principal_amount,
                start_sequence_number=start_sequence_number,
            )
            next_due_row.pop("_leftover_credit", None)

            try:
                insert_schedule_response = supabase.table("loan_schedules").insert(next_due_row).execute()
                created_schedules = insert_schedule_response.data or []
            except Exception:
                legacy_schedule_row = {
                    "loan_id": next_due_row["loan_id"],
                    "installment_no": next_due_row["installment_no"],
                    "due_date": next_due_row["due_date"],
                    "expected_amount": next_due_row["expected_amount"],
                    "principal_component": next_due_row["principal_component"],
                    "interest_component": next_due_row["interest_component"],
                    "schedule_status": "Unpaid",
                }
                insert_schedule_response = supabase.table("loan_schedules").insert(legacy_schedule_row).execute()
                created_schedules = insert_schedule_response.data or []

        update_payload = {
            "loan_status": "released",
            "application_status": "released",
            "disbursal_date": disbursed_at.isoformat(),
        }
        if normalized_loan_type == "bonus":
            # The term stored at application time (old 5/11 picker) is
            # superseded by the real release-to-bonus-month count computed
            # above, so the payment-approval endpoint's "is this the last
            # installment" check (term_months, main.py ~12613) stays correct.
            update_payload["term"] = term_months

        (
            supabase.table("loans")
            .update(update_payload)
            .eq("control_number", clean_loan_id)
            .execute()
        )
        # cashier_id/cashier_email already flow through this payload (see
        # confirmation_record below) straight from the signed-in cashier's own
        # Supabase session — same identity _get_current_user would extract
        # from a bearer token, just already provided. Used only to correct
        # the audit_log rows the triggers above just wrote as service_role.
        _disbursement_actor = {"id": payload.cashier_id, "email": payload.cashier_email}
        _correct_audit_actor("loan", clean_loan_id, _disbursement_actor)

        updated_loan_response = (
            supabase.table("loans")
            .select("control_number,loan_status,application_status,disbursal_date")
            .eq("control_number", clean_loan_id)
            .limit(1)
            .execute()
        )
        updated_loan = (updated_loan_response.data or [None])[0]

        member_info = loan_row.get("member") or {}
        member_full_name = (
            f"{member_info.get('first_name') or ''} {member_info.get('last_name') or ''}".strip()
            or "Unknown Member"
        )
        loan_type_label = (loan_row.get("loan_type") or {}).get("name") or "N/A"

        reference_number = f"TTMPC-DSB-{disbursed_at.strftime('%Y%m%d%H%M%S')}-{clean_loan_id[-6:].upper()}"
        cashier_display = (payload.cashier_name or payload.cashier_email or "Cashier").strip()

        # Duplicate-submission guard. reference_number is UNIQUE, but the insert
        # below is intentionally non-fatal (legacy DBs may lack the table), so a
        # resubmit would otherwise be swallowed silently. Surface the existing
        # confirmation as a 409 instead of writing a second receipt.
        try:
            existing_confirmation = (
                supabase.table("disbursement_confirmations")
                .select("reference_number,loan_id,disbursed_at,cashier_name,loan_amount")
                .eq("reference_number", reference_number)
                .limit(1)
                .execute()
            )
            prior = (existing_confirmation.data or [None])[0]
        except Exception:
            prior = None

        if prior:
            # A plain string: the frontend renders `detail` directly, and an
            # object here surfaced as "[object Object]".
            raise HTTPException(
                status_code=409,
                detail=f"This disbursement has already been confirmed (reference {prior.get('reference_number')}).",
            )

        confirmation_record = {
            "reference_number": reference_number,
            "loan_id": clean_loan_id,
            "member_id": loan_row.get("member_id"),
            "member_name": member_full_name,
            "loan_type": loan_type_label,
            "loan_amount": float(principal_amount),
            "disbursed_at": disbursed_at.isoformat(),
            "first_due_date": first_due_date.isoformat(),
            "cashier_id": payload.cashier_id,
            "cashier_name": cashier_display,
            "loan_status": (updated_loan or {}).get("loan_status") or "released",
        }
        # What the member actually received, frozen here so the release receipt
        # shows it (loans has no fee snapshot for these releases —
        # RECEIPT_SYSTEM_PLAN.md §12.1, checks 08-10). Needs receipts_01_schema.sql.
        _release_deductions = release_breakdown["deductions"]
        release_columns = {
            "principal_amount": decimal_to_float(release_breakdown["principal"]),
            "service_fee": decimal_to_float(_release_deductions["service_fee"]),
            "cbu_deduction": decimal_to_float(_release_deductions["cbu_deduction"]),
            "insurance_fee": decimal_to_float(_release_deductions["insurance_fee"]),
            "notarial_fee": decimal_to_float(_release_deductions["notarial_fee"]),
            "renewal_payoff": decimal_to_float(release_breakdown["renewal_payoff"]),
            "net_proceeds": decimal_to_float(release_breakdown["net_cash_out"]),
            "term_months": term_months,
            "monthly_amortization": loan_row.get("monthly_amortization"),
        }
        try:
            release_columns["released_by_auth_id"] = str(UUID(str(payload.cashier_id)))
        except (TypeError, ValueError):
            pass
        confirmation_saved = False
        _confirmation_row = None
        try:
            try:
                _confirmation_insert = (
                    supabase.table("disbursement_confirmations")
                    .insert({**confirmation_record, **release_columns})
                    .execute()
                )
            except Exception as breakdown_err:
                # Before receipts_01_schema.sql is applied the breakdown columns
                # don't exist yet; save the confirmation without them.
                if not any(col in str(breakdown_err) for col in release_columns):
                    raise
                _confirmation_insert = (
                    supabase.table("disbursement_confirmations").insert(confirmation_record).execute()
                )
            _confirmation_row = (_confirmation_insert.data or [None])[0]
            confirmation_saved = bool(_confirmation_row)
            if _confirmation_row and _confirmation_row.get("id"):
                _correct_audit_actor("disbursement", str(_confirmation_row["id"]), _disbursement_actor)
        except Exception as confirm_err:
            err_text = str(confirm_err).lower()
            # A uniqueness violation means this disbursement was already confirmed
            # (racing double-submit that slipped past the pre-check above).
            if "duplicate key" in err_text or "unique constraint" in err_text:
                raise HTTPException(
                    status_code=409,
                    detail=f"This disbursement has already been confirmed (reference {reference_number}).",
                )
            # Non-fatal: the loan is already released and the receipt is still
            # returned to the client. But never silently -- the response's
            # `records.confirmation_saved` flag tells the cashier it was not stored.
            logger.warning(
                "disbursement_confirmations insert failed for loan %s: %s", clean_loan_id, confirm_err
            )

        # Member-facing email is sent earlier in the workflow, when the
        # Treasurer confirms disbursement (frontend → /api/loans/email/dispatch
        # with stage=treasurer action=disburse). The cashier confirm step does
        # not re-email, to avoid duplicates.
        #
        # However we DO fire an in-app member-bell notification so the member
        # sees the final "released" step in their portal.
        try:
            background_tasks.add_task(
                _fan_out_member_notification,
                notification_type="member_released",
                loan_id=clean_loan_id,
                member_id=str(loan_row.get("member_id") or "").strip() or None,
                member_name=member_full_name,
                loan_type=loan_type_label,
                actor_user_id=payload.cashier_id,
            )
        except Exception:
            pass

        # Read back what the release should have written, so the cashier is told
        # about a partial write instead of assuming everything landed.
        cbu_credit_row = None
        if loan_row.get("member_id"):
            try:
                _cbu_resp = (
                    supabase.table("capital_build_up")
                    .select("capital_added")
                    .eq("source_loan_id", clean_loan_id)
                    .limit(1)
                    .execute()
                )
                cbu_credit_row = (_cbu_resp.data or [None])[0]
            except Exception as cbu_err:
                logger.warning("CBU retention check failed for loan %s: %s", clean_loan_id, cbu_err)

        release_records = {
            "loan_released": (
                str((updated_loan or {}).get("loan_status") or "").strip().lower() == "released"
                and bool((updated_loan or {}).get("disbursal_date"))
            ),
            "schedule_ready": has_existing_schedule or bool(created_schedules),
            "confirmation_saved": confirmation_saved,
            "cbu_retention_credited": bool(cbu_credit_row),
            "cbu_retention_amount": (
                decimal_to_float(cbu_credit_row.get("capital_added")) if cbu_credit_row else None
            ),
            "vault_debited": vault_debited,
            "net_cash_out": decimal_to_float(net_cash_out),
            "renewal_payoff": decimal_to_float(renewal_payoff),
            "vault_balance_after": decimal_to_float(vault_new_balance) if vault_new_balance is not None else None,
        }
        if not all(
            release_records[k] for k in ("loan_released", "schedule_ready", "confirmation_saved")
        ):
            logger.warning("Incomplete disbursement records for loan %s: %s", clean_loan_id, release_records)

        # The receipt was issued by a trigger in the same insert; hand its number
        # to the cashier's pop-up. None when it couldn't be found (the pop-up then
        # falls back to the old confirmation panel).
        release_receipt_no = None
        if confirmation_saved and _confirmation_row and _confirmation_row.get("id"):
            try:
                _receipt_rows = (
                    supabase.table("receipts")
                    .select("receipt_no")
                    .eq("source_type", "loan_release")
                    .eq("source_id", str(_confirmation_row["id"]))
                    .limit(1)
                    .execute()
                ).data or []
                release_receipt_no = (_receipt_rows[0] if _receipt_rows else {}).get("receipt_no")
            except Exception as receipt_err:
                logger.warning("Could not read the release receipt for loan %s: %s", clean_loan_id, receipt_err)

        return {
            "success": True,
            "message": "Loan disbursed successfully. Only the next due schedule is created.",
            "data": {
                "receipt_no": release_receipt_no,
                "records": release_records,
                "loan": updated_loan,
                "schedule_created": not has_existing_schedule,
                "created_schedule_count": len(created_schedules),
                "first_due_date": first_due_date.isoformat(),
                "grace_period_days": 3,
                "delayed_flag_after_months": 1,
                "next_schedule_id": (
                    created_schedules[0].get("schedule_id")
                    if created_schedules and created_schedules[0].get("schedule_id")
                    else (created_schedules[0].get("id") if created_schedules else None)
                ),
                "confirmation": confirmation_record,
            },
        }
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to disburse loan: {err}")


class NonmemberLoanPaymentRequest(BaseModel):
    loan_id: str = Field(..., min_length=1)
    payment_amount: Decimal = Field(..., gt=0)
    or_no: str | None = None


@app.post("/api/cashier/nonmember-loan-payments")
async def create_nonmember_loan_payment(
    payload: NonmemberLoanPaymentRequest,
    current_user: dict = _Depends(_get_current_user),
):
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    loan_id = payload.loan_id.strip()
    loan = (
        supabase.table("non_member_loans")
        .select("control_number,loan_amount,loan_status,full_name")
        .eq("control_number", loan_id)
        .limit(1)
        .execute()
    ).data
    if not loan:
        raise HTTPException(status_code=404, detail="Non-member loan not found.")
    loan = loan[0]
    if str(loan.get("loan_status") or "").strip().lower() != "released":
        raise HTTPException(status_code=409, detail="This loan is not open for payment.")

    loan_amount = money(Decimal(str(loan.get("loan_amount") or 0)))
    paid_rows = _nonmember_payments_by_loan([loan_id]).get(loan_id, [])
    already_paid = sum(Decimal(str(r.get("amount_paid") or 0)) for r in paid_rows)
    outstanding = money(max(loan_amount - already_paid, Decimal("0")))
    amount = money(payload.payment_amount)
    if amount > outstanding:
        raise HTTPException(
            status_code=400,
            detail=f"Payment of {amount} exceeds the remaining balance of {outstanding}.",
        )

    try:
        inserted = (
            supabase.table("nonmember_loan_payments")
            .insert({
                "loan_id": loan_id,
                "amount_paid": str(amount),
                "or_no": (payload.or_no or "").strip() or None,
                "recorded_by": current_user.get("id"),
                "recorded_by_name": current_user.get("email"),
                "source": "cashier",
            })
            .execute()
        ).data or []
    except Exception as err:
        raise HTTPException(
            status_code=500,
            detail=f"Could not record the payment (is nonmember_bonus_payments_schema.sql applied?): {err}",
        )

    remaining = money(outstanding - amount)
    if remaining <= 0:
        supabase.table("non_member_loans").update(
            {"loan_status": "fully paid", "application_status": "fully paid"}
        ).eq("control_number", loan_id).execute()
    _MANAGE_LOANS_CACHE["expires_at"] = 0.0

    return {
        "success": True,
        "data": {
            "payment_id": (inserted[0] if inserted else {}).get("id"),
            "loan_id": loan_id,
            "amount_paid": decimal_to_float(amount),
            "remaining_balance": decimal_to_float(remaining),
            "loan_closed": remaining <= 0,
        },
    }


@app.post("/api/cashier/loans/{loan_id}/roll-forward")
async def roll_forward_cashier_loan(
    loan_id: str,
    current_user: dict | None = _Depends(_get_current_user_optional),
):
    """Carry missed installments forward before the cashier sees the loan, so
    the due date and amount shown are the CURRENT installment's."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    rolled = roll_forward_missed_installments(str(loan_id).strip())
    return {"loan_id": loan_id, "rolled": rolled}


@app.post("/api/cashier/loan-payments")
async def create_cashier_loan_payment(
    payload: CashierLoanPaymentCreateRequest,
    current_user: dict | None = _Depends(_get_current_user_optional),
):
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        loan_id = str(payload.loan_id).strip()
        if not loan_id:
            raise HTTPException(status_code=400, detail="loan_id is required.")

        # The loan_type join only feeds the penalty rate (bonus = 1%, else 2%).
        # It must never block recording money the member actually handed over,
        # so a join failure falls back to the plain columns.
        _loan_cols_base = (
            "control_number,loan_status,principal_amount,loan_amount,total_interest,"
            "monthly_amortization,term"
        )
        try:
            loan_response = (
                supabase.table("loans")
                .select(f"{_loan_cols_base},loan_type:loan_type_id(name)")
                .eq("control_number", loan_id)
                .limit(1)
                .execute()
            )
        except Exception:
            loan_response = (
                supabase.table("loans")
                .select(_loan_cols_base)
                .eq("control_number", loan_id)
                .limit(1)
                .execute()
            )
        if not loan_response.data:
            raise HTTPException(status_code=404, detail="Loan not found.")

        loan_row_for_status = loan_response.data[0]
        loan_status_lc = str(loan_row_for_status.get("loan_status") or "").strip().lower()
        if loan_status_lc in ("fully paid", "completed", "closed"):
            raise HTTPException(status_code=409, detail="This loan is already fully paid.")

        # Missed months are carried forward first, so the payment lands on the
        # CURRENT installment with every missed amount accumulated on it.
        roll_forward_missed_installments(loan_id)

        # The cashier now types the amount received, so it is checked here rather
        # than trusted: it can't exceed what is still owed. Balance = total
        # payable minus validated payments -- the same figure the approve step
        # uses. Skipped when the loan's totals aren't on record.
        entered_amount = money(Decimal(str(payload.payment_amount)))
        total_payable = _loan_total_payable(loan_row_for_status)
        if total_payable > 0:
            validated_rows = (
                supabase.table("loan_payments")
                .select("amount_paid")
                .eq("loan_id", loan_id)
                .in_("confirmation_status", ["validated", "confirmed", "bookkeeper_confirmed", "approved"])
                .execute()
            ).data or []
            already_paid = sum(Decimal(str(r.get("amount_paid") or 0)) for r in validated_rows)
            outstanding_balance = max(total_payable - already_paid, Decimal("0"))
            if entered_amount > money(outstanding_balance):
                raise HTTPException(
                    status_code=400,
                    detail=(
                        f"Payment amount {entered_amount:,.2f} exceeds the loan's outstanding balance "
                        f"of {money(outstanding_balance):,.2f}."
                    ),
                )

        try:
            schedules_response = (
                supabase.table("loan_schedules")
                .select("id,schedule_id,loan_id,due_date,schedule_status")
                .eq("loan_id", loan_id)
                .order("due_date")
                .execute()
            )
        except Exception:
            schedules_response = (
                supabase.table("loan_schedules")
                .select("id,loan_id,due_date,schedule_status")
                .eq("loan_id", loan_id)
                .order("due_date")
                .execute()
            )
        schedules = schedules_response.data or []
        if not schedules:
            raise HTTPException(status_code=400, detail="No loan schedule found for this loan.")

        selected_schedule = None
        if payload.schedule_id:
            selected_schedule = next(
                (
                    row
                    for row in schedules
                    if str(row.get("id")) == str(payload.schedule_id)
                    or str(row.get("schedule_id") or "") == str(payload.schedule_id)
                ),
                None,
            )
            if selected_schedule is None:
                raise HTTPException(status_code=400, detail="Provided schedule_id does not belong to this loan.")
            # The screen may have been opened before a roll-forward closed that
            # row; a payment always goes to the installment that is open now.
            if str(selected_schedule.get("schedule_status") or "").strip().lower() not in OPEN_SCHEDULE_STATUSES:
                selected_schedule = next(
                    (
                        row for row in schedules
                        if str(row.get("schedule_status") or "").strip().lower() in OPEN_SCHEDULE_STATUSES
                    ),
                    selected_schedule,
                )
        else:
            for sched in schedules:
                sched_status = str(sched.get("schedule_status") or "").strip().lower()
                if sched_status in {"unpaid", "pending", "overdue", ""}:
                    selected_schedule = sched
                    break
            if selected_schedule is None:
                selected_schedule = schedules[0]

        existing_payments_response = supabase.table("loan_payments").select("id").execute()
        next_sequence = len(existing_payments_response.data or []) + 1

        payment_reference = payload.payment_reference or build_sequence_id("TTMPCLP-", next_sequence)
        transaction_reference = payload.transaction_reference or build_sequence_id("TTMPCLP_TXN_", next_sequence)

        deficiency_value = payload.deficiency
        if deficiency_value is None:
            deficiency_value = compute_missed_due_dates(selected_schedule.get("due_date"))

        # Penalty is recomputed here and the client's figure is ignored. A
        # browser must not be able to decide what is chargeable, and the
        # cashier screen has no way to know whether the loan is legacy-exempt
        # or whether the zero-payment streak has actually been reached.
        server_penalty = _server_side_penalty_for_loan(
            loan_id=loan_id,
            loan_row=loan_row_for_status,
            schedules=schedules,
        )

        insert_payload = {
            "loan_id": loan_id,
            "schedule_id": selected_schedule.get("id"),
            "amount_paid": decimal_to_float(money(Decimal(str(payload.payment_amount)))),
            "payment_date": datetime.utcnow().isoformat(),
            # Penalty cash collected on top of the loan amount. The client's
            # figure is only trusted downward: it can never exceed what the
            # server says is owed.
            "penalties": decimal_to_float(money(min(
                max(Decimal(str(payload.penalties or 0)), Decimal("0")), server_penalty
            ))),
            "deficiency": decimal_to_float(money(Decimal(str(deficiency_value)))),
            "confirmation_status": "pending_bookkeeper",
            "entered_by_role": "cashier",
            "payment_reference": payment_reference,
            "transaction_reference": transaction_reference,
        }

        # Duplicate-submit guard: a double click, a retried request or a refresh
        # mid-submit must not debit the member twice. payment_reference is unique
        # per submission, so an existing row means this exact payment already
        # landed -- return it instead of inserting a second one.
        if payload.payment_reference:
            try:
                existing = (
                    supabase.table("loan_payments")
                    .select("*")
                    .eq("payment_reference", payment_reference)
                    .limit(1)
                    .execute()
                ).data or []
                if existing:
                    return {
                        "success": True,
                        "message": "This payment was already recorded.",
                        "data": {"payment": existing[0], "duplicate": True},
                    }
            except Exception:
                pass

        inserted_row = None
        try:
            inserted_response = supabase.table("loan_payments").insert(insert_payload).execute()
            inserted_row = (inserted_response.data or [{}])[0]
        except Exception as insert_err:
            message = str(insert_err).lower()
            # Unique violation on payment_reference -- a concurrent duplicate won
            # the race. Return that row rather than erroring or double-charging.
            if "duplicate" in message or "unique" in message:
                existing = (
                    supabase.table("loan_payments")
                    .select("*")
                    .eq("payment_reference", payment_reference)
                    .limit(1)
                    .execute()
                ).data or []
                if existing:
                    return {
                        "success": True,
                        "message": "This payment was already recorded.",
                        "data": {"payment": existing[0], "duplicate": True},
                    }
            # Fallback for environments where new optional columns are not migrated yet.
            if any(token in message for token in ["confirmation_status", "payment_reference", "transaction_reference"]):
                fallback_payload = {
                    "loan_id": loan_id,
                    "schedule_id": selected_schedule.get("id"),
                    "transaction_id": None,
                    "amount_paid": decimal_to_float(money(Decimal(str(payload.payment_amount)))),
                    "payment_date": datetime.utcnow().isoformat(),
                    "penalties": decimal_to_float(money(server_penalty)),
                    "deficiency": decimal_to_float(money(Decimal(str(deficiency_value)))),
                }
                inserted_response = supabase.table("loan_payments").insert(fallback_payload).execute()
                inserted_row = (inserted_response.data or [{}])[0]
            else:
                raise

        if inserted_row.get("id"):
            _correct_audit_actor("payment", str(inserted_row["id"]), current_user)

        return {
            "success": True,
            "message": "Payment logged and pending Bookkeeper confirmation. Loan balance is unchanged until confirmation.",
            "data": {
                "payment_id": payment_reference,
                "loan_id": loan_id,
                "schedule_id": selected_schedule.get("schedule_id") or selected_schedule.get("id"),
                "transaction_id": transaction_reference,
                "amount_paid": insert_payload["amount_paid"],
                "payment_date": insert_payload["payment_date"],
                "penalties": insert_payload["penalties"],
                "deficiency": insert_payload["deficiency"],
                "confirmation_status": inserted_row.get("confirmation_status") or "pending_bookkeeper",
            },
        }
    except HTTPException as err:
        raise err
    except Exception as err:
        # Full traceback to the server console: the cashier only ever sees a
        # sanitised message, so without this a failure here is undiagnosable.
        logging.exception("Cashier payment creation failed for loan %s", payload.loan_id)
        raise HTTPException(status_code=500, detail=f"Failed to create cashier payment: {err}")


def _loan_total_payable(loan_row: dict) -> Decimal:
    """Principal plus total interest for a loans row.

    total_interest is missing on some legacy rows; fall back to
    monthly_amortization * term - principal, as the payment approval does.
    Bonus is a single lump-sum payoff (BONUS_LOAN_PLAN.md Step 2):
    monthly_amortization there already holds principal + full interest, so
    it must not be multiplied by term again. Detected from a joined
    loan_type.name when the caller's select included one; a caller whose
    select omits that join falls back to the non-Bonus formula.
    """
    principal = Decimal(str(loan_row.get("principal_amount") or loan_row.get("loan_amount") or 0))
    total_interest = Decimal(str(loan_row.get("total_interest") or 0))
    if total_interest <= 0:
        monthly = Decimal(str(loan_row.get("monthly_amortization") or 0))
        term = int(loan_row.get("term") or 0)
        if monthly > 0 and term > 0:
            loan_type_name = (loan_row.get("loan_type") or {}).get("name") or loan_row.get("loan_type_code") or ""
            if "bonus" in str(loan_type_name).strip().lower():
                total_interest = max(monthly - principal, Decimal("0"))
            else:
                total_interest = max(monthly * term - principal, Decimal("0"))
    return principal + total_interest


def is_validated_payment_status(status_value: str | None) -> bool:
    normalized = str(status_value or "").strip().lower()
    return normalized in {"validated", "confirmed", "bookkeeper_confirmed", "approved"}


# ---------------------------------------------------------------------------
# Loan Eligibility — single source of truth for "can this member apply?"
# ---------------------------------------------------------------------------
# Rules (see WHAT_IFS_AND_CONSTRAINTS.txt):
#   - A member with NO active loan can apply for a New loan.
#   - A member with an active loan (loan_status in released/paid/partially paid)
#     cannot apply New; they may only Renew.
#   - Renewal requires >= 6 recorded loan_payments rows for that active loan.
#   - Frontend disables the radios based on this endpoint. Submit handlers also
#     re-check server-side (in submitUnifiedLoan) so a stale page can't bypass.
#
# Simulation: the frontend passes ?sim=clean|active_recent|active_renewable to
# fabricate one of three states without touching real data. This exists so the
# defense demo can flip states in one URL change. Never do this in production —
# the frontend also gates ?sim on a demo-account flag.
ACTIVE_LOAN_STATUSES = {"released", "paid", "partially paid"}
# A loan still moving through the approval pipeline (not yet disbursed, not
# rejected/cancelled). A member with one of these open shouldn't be able to
# start a second New application of the same type — ACTIVE_LOAN_STATUSES
# alone misses this because it only covers already-disbursed loans.
OPEN_APPLICATION_STATUSES = {
    "draft", "pending", "recommended for approval", "recommended for bod approval",
    "revision_requested", "revised_submitted", "approved", "ready for disbursement",
    "to be disbursed",
}
RENEWAL_MIN_PAYMENTS = 6
ELIGIBILITY_LOAN_TYPES = ("consolidated", "bonus", "emergency")

# Decision 3.3-1 (Simulation findings, confirmed 2026-10-23): Bonus loan
# applications are open all year -- a member may apply in any month,
# including May/November. The May/November restriction now applies only at
# the Bookkeeper->Manager handoff (recommending moves loan_status to
# 'recommended for approval'), since May/November are the Bonus's own
# repayment months, not application months. There is no override for this
# stage -- the Bookkeeper waits until the window reopens. Server time is the
# source of truth; the `enforce_bonus_loan_window` trigger (BEFORE UPDATE on
# loans/non_member_loans, bonus_loan_window_trigger.sql) is the real
# enforcement, since the recommend action writes via the Supabase client,
# not FastAPI. This constant/helper exist only so the Bookkeeper UI can show
# a clear error before hitting that trigger.
BONUS_RECOMMEND_BLOCKED_MONTHS = {5, 11}
BONUS_RECOMMEND_BLOCKED_REASON = (
    "A Bonus loan cannot be recommended for approval in May or November "
    "(its own repayment months). Please wait until the window reopens."
)

def _bonus_recommend_blocked(now: datetime | None = None) -> bool:
    return (now or datetime.now()).month in BONUS_RECOMMEND_BLOCKED_MONTHS


def _clean_bucket(loan_type: str, simulated: bool = False) -> dict:
    return {
        "loan_type": loan_type,
        "can_apply_new": True,
        "can_renew": False,
        "reason": ("SIMULATION: " if simulated else "") + f"No active {loan_type} loan on record.",
        "active_loan_id": None,
        "payments_made": 0,
        "simulation_active": simulated,
    }

def _open_application_bucket(loan_type: str, status: str, control_number: str | None) -> dict:
    status_label = status.replace('_', ' ').title()
    return {
        "loan_type": loan_type,
        "can_apply_new": False,
        "can_renew": False,
        "reason": f"You already have a {loan_type} application in progress ({status_label}).",
        "active_loan_id": control_number,
        "open_application_status": status,
        "payments_made": 0,
        "simulation_active": False,
    }


def _blocked_bucket(loan_type: str, payments_made: int, active_id: str | None, simulated: bool = False) -> dict:
    can_renew = payments_made >= RENEWAL_MIN_PAYMENTS
    return {
        "loan_type": loan_type,
        "can_apply_new": False,
        "can_renew": can_renew,
        "reason": (
            ("SIMULATION: " if simulated else "")
            + f"Active {loan_type} loan {active_id or ''} in repayment. "
            + ("Eligible for renewal." if can_renew
               else f"Needs {RENEWAL_MIN_PAYMENTS - payments_made} more monthly payment(s) before renewal.")
        ).strip(),
        "active_loan_id": active_id,
        "payments_made": payments_made,
        "simulation_active": simulated,
    }

def _fabricate_eligibility(sim_state: str, loan_type: str | None) -> dict | None:
    """Return a per-type map (or a single bucket if loan_type is specified)."""
    def build_for(lt: str) -> dict:
        if sim_state == "clean":
            return _clean_bucket(lt, simulated=True)
        if sim_state == "active_recent":
            return _blocked_bucket(lt, payments_made=2, active_id=f"SIM-{lt.upper()}-RECENT", simulated=True)
        if sim_state == "active_renewable":
            return _blocked_bucket(lt, payments_made=6, active_id=f"SIM-{lt.upper()}-RENEWABLE", simulated=True)
        return None

    if loan_type:
        result = build_for(loan_type.lower())
        return result
    per_type = {}
    for lt in ELIGIBILITY_LOAN_TYPES:
        bucket = build_for(lt)
        if bucket is None:
            return None
        per_type[lt] = bucket
    return {"per_type": per_type, "simulation_active": True}

def _resolve_loan_type_code(row: dict) -> str | None:
    """Map a loans row (with joined loan_types) to one of consolidated|bonus|emergency."""
    lt = row.get("loan_types") or {}
    code = str(lt.get("code") or "").strip().lower()
    name = str(lt.get("name") or "").strip().lower()
    if "consolidated" in code or "consolidated" in name:
        return "consolidated"
    if "emergency" in code or "emergency" in name:
        return "emergency"
    if "bonus" in code or "bonus" in name:
        return "bonus"
    return None

def _compute_bucket_for_type(member_id: str, loan_type: str) -> dict:
    """Single-type variant. Kept for the ?loan_type=X query-param path.

    For the per-type map (no filter), use _compute_all_buckets which batches
    all three loan types into 2 total queries instead of 6.
    """
    loans_response = (
        supabase.table("loans")
        .select("control_number,loan_status,application_date,disbursal_date,loan_type_id,loan_types:loan_type_id(code,name)")
        .eq("member_id", member_id)
        .execute()
    )
    loan_rows = loans_response.data or []
    return _bucket_from_loans(loan_rows, loan_type)


def _bucket_from_loans(
    loan_rows: list[dict],
    loan_type: str,
    payments_by_loan: dict[str, int] | None = None,
) -> dict:
    """Compute a bucket for one loan type from a pre-fetched loan list.

    If payments_by_loan is provided, skips the per-loan payment count query.
    Bonus has no application-time window (decision 3.3-1) -- the May/
    November restriction applies only when the Bookkeeper recommends it to
    the Manager, enforced by the DB trigger, not here.
    """
    # An application still in the pipeline (not yet disbursed, not
    # rejected/cancelled) blocks a second New application of the same type,
    # independent of whether an older, already-disbursed loan also exists.
    for row in loan_rows:
        if _resolve_loan_type_code(row) != loan_type:
            continue
        status = str(row.get("loan_status") or "").strip().lower()
        if status in OPEN_APPLICATION_STATUSES:
            return _open_application_bucket(loan_type, status, row.get("control_number"))

    active_loan = None
    for row in loan_rows:
        if _resolve_loan_type_code(row) != loan_type:
            continue
        status = str(row.get("loan_status") or "").strip().lower()
        if status not in ACTIVE_LOAN_STATUSES:
            continue
        candidate_ts = row.get("disbursal_date") or row.get("application_date") or ""
        current_ts = (
            (active_loan or {}).get("disbursal_date")
            or (active_loan or {}).get("application_date")
            or ""
        )
        if not active_loan or str(candidate_ts) > str(current_ts):
            active_loan = row

    if active_loan is None:
        return _clean_bucket(loan_type)

    active_id = active_loan.get("control_number")
    if payments_by_loan is not None:
        payments_made = payments_by_loan.get(str(active_id or ""), 0)
    else:
        # Fallback path used by _compute_bucket_for_type when caller didn't
        # pre-batch payments. One query per bucket in this case.
        payments_response = (
            supabase.table("loan_payments")
            .select("id")
            .eq("loan_id", active_id)
            .execute()
        )
        payments_made = len(payments_response.data or [])
    return _blocked_bucket(loan_type, payments_made, active_id)


def _compute_all_buckets(member_id: str) -> dict[str, dict]:
    """Batch path — computes all three type buckets from just 2 queries.

    Query 1: all loans for this member (classify by type in Python).
    Query 2: payment counts for any active loans, using .in_ to fetch all at once.

    Replaces the prior N calls where N = 3 loans queries + up to 3 payment queries.
    """
    loans_response = (
        supabase.table("loans")
        .select("control_number,loan_status,application_date,disbursal_date,loan_type_id,loan_types:loan_type_id(code,name)")
        .eq("member_id", member_id)
        .execute()
    )
    loan_rows = loans_response.data or []

    # Find every active loan across all types so we can count payments in one
    # .in_ query, not one per active loan.
    active_ids: list[str] = []
    for row in loan_rows:
        status = str(row.get("loan_status") or "").strip().lower()
        if status in ACTIVE_LOAN_STATUSES and row.get("control_number"):
            active_ids.append(str(row["control_number"]))

    payments_by_loan: dict[str, int] = {}
    if active_ids:
        try:
            payments_response = (
                supabase.table("loan_payments")
                .select("id,loan_id")
                .in_("loan_id", active_ids)
                .execute()
            )
            for p in payments_response.data or []:
                key = str(p.get("loan_id") or "")
                if key:
                    payments_by_loan[key] = payments_by_loan.get(key, 0) + 1
        except Exception:
            payments_by_loan = {}

    return {
        lt: _bucket_from_loans(loan_rows, lt, payments_by_loan)
        for lt in ELIGIBILITY_LOAN_TYPES
    }

# ============================================================================
# SECTION: Loan Eligibility
# Computes per-loan-type eligibility buckets (clean/blocked) for a member,
# including simulation helpers for QA scenarios.
# ============================================================================

@app.get("/api/loans/eligibility/{member_id}")
async def get_loan_eligibility(
    member_id: str,
    sim: str | None = None,
    loan_type: str | None = None,
):
    """Return per-loan-type eligibility for the member.

    - Without ?loan_type=: returns { per_type: { consolidated: {...}, bonus: {...}, emergency: {...} } }.
    - With ?loan_type=consolidated|bonus|emergency: returns just that bucket at top level.

    Rules apply within each loan type independently. Having an active Consolidated
    loan does NOT block Emergency or Bonus, and vice versa.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    normalized_type = (loan_type or "").strip().lower() or None
    if normalized_type and normalized_type not in ELIGIBILITY_LOAN_TYPES:
        raise HTTPException(status_code=400, detail=f"loan_type must be one of {ELIGIBILITY_LOAN_TYPES}.")

    if sim:
        fabricated = _fabricate_eligibility(sim.strip().lower(), normalized_type)
        if fabricated is not None:
            return fabricated

    # Member status gate — block inactive/suspended/terminated members before
    # computing any eligibility bucket.
    try:
        member_table = _resolve_member_table(supabase)
        lookup_field = "id" if len(member_id) == 36 and member_id.count("-") == 4 else "membership_id"
        member_row_resp = (
            supabase.table(member_table)
            .select("id,is_bona_fide,member_status,is_active,latest_net_pay,classification,employment_type")
            .eq(lookup_field, member_id)
            .limit(1)
            .execute()
        )
        member_row = (member_row_resp.data or [None])[0]
        if member_row:
            raw_status = str(member_row.get("member_status") or "").strip().lower()
            is_active = member_row.get("is_active")
            if raw_status in {"inactive", "suspended", "terminated", "exiting", "closed"} or is_active is False:
                raise HTTPException(
                    status_code=403,
                    detail=f"Member account is {raw_status or 'deactivated'} and is not eligible to apply for loans.",
                )

            # Non-bona-fide member requesting a member-only loan type → 403.
            if normalized_type in {"consolidated", "bonus"} and not member_row.get("is_bona_fide"):
                raise HTTPException(
                    status_code=403,
                    detail=f"{normalized_type.capitalize()} loans are available to bona fide (MIGS-classified) members only.",
                )

            # Missing required profile fields — return 400 with explicit field list.
            missing_fields = []
            if not member_row.get("latest_net_pay"):
                missing_fields.append("latest_net_pay")
            if not member_row.get("classification"):
                missing_fields.append("classification")
            if not member_row.get("employment_type"):
                missing_fields.append("employment_type")
            if missing_fields:
                raise HTTPException(
                    status_code=400,
                    detail={
                        "message": "Member profile is incomplete. The following required fields are missing.",
                        "missing_fields": missing_fields,
                    },
                )
    except HTTPException:
        raise
    except Exception:
        # Member table lookup failure is non-fatal — continue to eligibility compute.
        pass

    try:
        if normalized_type:
            return _compute_bucket_for_type(member_id, normalized_type)
        # Batched path: 2 queries total instead of up to 6. Big win for the
        # Member ApplyLoans page which fires this on every mount.
        per_type = _compute_all_buckets(member_id)
        return {"per_type": per_type, "simulation_active": False}
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Eligibility lookup failed: {exc}") from exc


# ============================================================================
# SECTION: 6-Month Renewal Rule Override
#
# A member with an active loan cannot renew until RENEWAL_MIN_PAYMENTS monthly
# payments are recorded. If they have an urgent need they file a request
# (member side); the Bookkeeper approves or rejects it (bookkeeper side). An
# approved request unlocks Renewal for that one active loan until it expires
# (RENEWAL_OVERRIDE_VALIDITY_DAYS) or is spent on a renewal application.
#
# Identity always comes from the verified JWT, never the request body. The
# loan_renewal_override_requests table is the history ledger (rows are never
# deleted); every state change is also mirrored into audit_log and the
# loan_notifications bell feed. Schema: loan_renewal_override_schema.sql.
# ============================================================================

RENEWAL_OVERRIDE_TABLE = "loan_renewal_override_requests"
RENEWAL_OVERRIDE_VALIDITY_DAYS = 30
RENEWAL_OVERRIDE_REASON_MIN = 20
RENEWAL_OVERRIDE_REASON_MAX = 1000
RENEWAL_OVERRIDE_STATUSES = {"pending", "approved", "rejected", "cancelled", "used"}
# Columns a member may see on their own requests (no reviewer/requester ids).
RENEWAL_OVERRIDE_MEMBER_COLUMNS = (
    "id,override_kind,loan_type,loan_id,payments_made,required_payments,reason,status,"
    "review_note,reviewed_at,expires_at,used_at,created_at"
)
# six_month: waive the 6-payment renewal rule for one active loan.
# bonus_window override REMOVED (decision 3.3-1, confirmed 2026-10-23): the
# Bonus May/November restriction now applies only at the Bookkeeper->Manager
# recommend step, and there is no override for it -- the Bookkeeper waits
# until the window reopens. bonus_window_override.sql's table rows (if any)
# are historical only.
OVERRIDE_KIND_SIX_MONTH = "six_month"


class _RenewalOverrideLoanTypeModel(BaseModel):
    loan_type: Literal["consolidated", "bonus", "emergency"]

    @field_validator("loan_type", mode="before")
    @classmethod
    def _normalize_loan_type(cls, value):
        return str(value or "").strip().lower()


# The "reason is long enough" / "rejection needs a note" rules are checked in
# the endpoints and raised as HTTPException(400) rather than as pydantic
# validators: the app's 422 handler returns exc.errors() verbatim, and a
# validator's ValueError lands in that payload as a non-serialisable object.
class RenewalOverrideCreate(_RenewalOverrideLoanTypeModel):
    reason: str = Field(..., max_length=RENEWAL_OVERRIDE_REASON_MAX)
    override_kind: Literal["six_month"] = "six_month"


class RenewalOverrideConsume(_RenewalOverrideLoanTypeModel):
    application_control_number: str = Field(..., min_length=1, max_length=100)


class RenewalOverrideReview(BaseModel):
    action: Literal["approved", "rejected"]
    note: str | None = Field(default=None, max_length=RENEWAL_OVERRIDE_REASON_MAX)


def _override_now() -> datetime:
    return datetime.utcnow()


def _override_iso(moment: datetime) -> str:
    # Explicit "Z" so timestamptz never depends on the session time zone.
    return moment.isoformat() + "Z"


def _override_account(current_user: dict) -> dict:
    """The calling member's account, resolved from the verified JWT."""
    try:
        resp = (
            supabase.table("member_account")
            .select("user_id, membership_id, email")
            .eq("auth_user_id", current_user["id"])
            .limit(1)
            .execute()
        )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not read account record: {exc}")
    account = (resp.data or [None])[0]
    member_id = str((account or {}).get("user_id") or "").strip()
    if not member_id:
        raise HTTPException(status_code=403, detail="No member profile is linked to this account.")
    return {
        "member_id": member_id,
        "membership_id": account.get("membership_id"),
    }


def _override_active_loan(member_id: str, loan_type: str) -> tuple[str | None, dict]:
    """(active loan control_number, eligibility bucket) for one loan type."""
    bucket = _compute_bucket_for_type(member_id, loan_type)
    return bucket.get("active_loan_id"), bucket


def _override_audit(
    action: str,
    row: dict,
    current_user: dict,
    *,
    before: dict | None = None,
    after: dict | None = None,
) -> None:
    """Mirror an override state change into audit_log. Best-effort: the request
    row already carries the full history, so a failure here must never undo or
    block the action itself."""
    if not supabase or not current_user or not current_user.get("id"):
        return
    try:
        role = _resolve_staff_role(current_user["id"], current_user.get("email") or "") or None
        supabase.table("audit_log").insert({
            "actor_user_id": current_user["id"],
            "actor_role": role,
            "actor_email": current_user.get("email") or None,
            "entity_type": "loan",
            "entity_id": str(row.get("loan_id") or ""),
            "action": action,
            "before": before,
            "after": after,
            "context": {
                "kind": "renewal_override",
                "override_kind": row.get("override_kind") or OVERRIDE_KIND_SIX_MONTH,
                "override_request_id": row.get("id"),
                "member_id": row.get("member_id"),
                "membership_id": row.get("membership_id"),
                "member_name": row.get("member_name"),
                "loan_type": row.get("loan_type"),
                "reason": row.get("reason"),
                "review_note": row.get("review_note"),
            },
        }).execute()
    except Exception as err:
        logger.warning("renewal override audit_log write failed: %s", err)


def _override_notify(
    *,
    recipient_role: str,
    notification_type: str,
    severity: str,
    title: str,
    message: str,
    loan_id: str | None,
    redirect_url: str,
    recipient_member_id: str | None = None,
    actor_user_id: str | None = None,
) -> None:
    """Drop a bell notification. Best-effort, never raises."""
    try:
        supabase.table("loan_notifications").insert({
            "recipient_role": recipient_role,
            "recipient_member_id": recipient_member_id,
            "title": title,
            "message": message,
            "notification_type": notification_type,
            "severity": severity,
            "loan_id": loan_id,
            "redirect_url": redirect_url,
            "is_read": False,
            "created_by": actor_user_id,
        }).execute()
    except Exception as err:
        logger.warning("renewal override notification failed: %s", err)


def _require_bookkeeper(current_user: dict) -> None:
    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role != "bookkeeper":
        raise HTTPException(status_code=403, detail="Only the Bookkeeper can review renewal override requests.")


# ============================================================================
# SECTION: Member loan revision resubmission
# Manager "Revise" sets loan_status='revision_requested' (see
# LoanApprovalDetails.jsx); the member edits the application themselves and
# resubmits it here, which moves it to 'revised_submitted' so the
# Bookkeeper's queue can tell a resubmission apart from a brand-new
# application. See REVISION flow notes in the implementation plan.
# ============================================================================

class LoanRevisionResubmit(BaseModel):
    fields: dict = Field(default_factory=dict)
    collateral_rows: list[dict] | None = None


def _revision_loan_table_and_row(control_number: str) -> tuple[str, dict]:
    """(table name, row) for a control_number across loans/koica_loans."""
    for table in ("loans", "koica_loans"):
        resp = (
            supabase.table(table)
            .select("*")
            .eq("control_number", control_number)
            .limit(1)
            .execute()
        )
        row = (resp.data or [None])[0]
        if row:
            return table, row
    raise HTTPException(status_code=404, detail="Loan application not found.")


def _sync_member_revision_collateral(control_number: str, rows: list[dict]) -> list[str]:
    """Sync member-declared collateral and return removed Storage object paths."""
    response = (
        supabase.table("loan_collateral")
        .select("*")
        .eq("loan_control_number", control_number)
        .execute()
    )
    existing_rows = response.data or []
    existing_by_id = {str(row.get("collateral_id")): row for row in existing_rows}
    allowed_types = {"co_maker", "cbu_shares", "chattel", "real_estate", "atm_hold", "other"}
    storage_prefix = f"loan_collateral/{control_number}/"
    desired_rows = []

    for item in rows:
        if not isinstance(item, dict):
            raise HTTPException(status_code=422, detail="Invalid collateral entry.")
        collateral_type = str(item.get("collateral_type") or "").strip()
        description = str(item.get("description") or "").strip()
        document_url = str(item.get("document_url") or "").strip() or None
        collateral_id = str(item.get("collateral_id") or "").strip()

        if collateral_type not in allowed_types or not description:
            raise HTTPException(status_code=422, detail="Each collateral entry needs a valid type and description.")
        if document_url and not document_url.startswith(storage_prefix):
            raise HTTPException(status_code=422, detail="Collateral photo path does not belong to this loan.")
        if collateral_id and collateral_id not in existing_by_id:
            raise HTTPException(status_code=403, detail="Collateral entry does not belong to this loan.")

        desired_rows.append({
            "collateral_id": collateral_id or f"col_{control_number}_{uuid4().hex[:12]}",
            "loan_control_number": control_number,
            "collateral_type": collateral_type,
            "description": description,
            "document_url": document_url,
        })

    desired_ids = {row["collateral_id"] for row in desired_rows}
    desired_paths = {row["document_url"] for row in desired_rows if row["document_url"]}
    removed_paths = {
        row["document_url"]
        for row in existing_rows
        if row.get("document_url") and row.get("document_url") not in desired_paths
    }

    if desired_rows:
        try:
            supabase.table("loan_collateral").upsert(desired_rows, on_conflict="collateral_id").execute()
        except Exception as exc:
            error_text = str(exc).lower()
            if "declared_value" not in error_text or "23502" not in error_text:
                raise
            legacy_rows = []
            for desired in desired_rows:
                legacy = {**desired}
                existing = existing_by_id.get(desired["collateral_id"], {})
                legacy["declared_value"] = existing.get("declared_value")
                if legacy["declared_value"] is None:
                    legacy["declared_value"] = 0
                legacy_rows.append(legacy)
            supabase.table("loan_collateral").upsert(legacy_rows, on_conflict="collateral_id").execute()
    for collateral_id in existing_by_id:
        if collateral_id not in desired_ids:
            supabase.table("loan_collateral").delete().eq("collateral_id", collateral_id).execute()

    return sorted(removed_paths)


@app.get("/api/member/loans/{control_number}")
def get_member_loan_for_edit(
    control_number: str,
    current_user: dict = _Depends(_get_current_user),
):
    """Fetch one of the member's own loan rows, for revision edit-mode prefill."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    account = _override_account(current_user)
    member_id = account["member_id"]

    table, row = _revision_loan_table_and_row(control_number)
    if str(row.get("member_id") or "").strip() != member_id:
        raise HTTPException(status_code=403, detail="This loan application does not belong to you.")

    return {"success": True, "data": {**row, "source_table": table}}


@app.post("/api/member/loans/{control_number}/resubmit")
def resubmit_member_loan_revision(
    control_number: str,
    body: LoanRevisionResubmit,
    current_user: dict = _Depends(_get_current_user),
):
    """Member resubmits a loan the Manager sent back for revision."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    account = _override_account(current_user)
    member_id = account["member_id"]

    table, row = _revision_loan_table_and_row(control_number)
    if str(row.get("member_id") or "").strip() != member_id:
        raise HTTPException(status_code=403, detail="This loan application does not belong to you.")

    current_status = str(row.get("loan_status") or row.get("application_status") or "").strip().lower()
    current_statuses = {
        str(row.get(field) or "").strip().lower()
        for field in ("loan_status", "application_status")
    }
    current_statuses.discard("")
    if "revision_requested" not in current_statuses:
        if "revised_submitted" in current_statuses:
            return {"success": True, "loan_status": "revised_submitted", "already_submitted": True}
        raise HTTPException(
            status_code=409,
            detail="This loan application is not currently awaiting your revision.",
        )

    # Identity/workflow fields are never client-editable via this endpoint.
    protected_fields = {
        "control_number", "member_id", "loan_id", "loan_status", "application_status",
        "bookkeeper_internal_remarks", "bookkeeper_reviewed_at", "manager_review_requested_at",
        "created_at", "updated_at",
    }
    edits = {k: v for k, v in (body.fields or {}).items() if k not in protected_fields}

    collateral_paths_to_remove = []
    if body.collateral_rows is not None:
        if table != "loans":
            raise HTTPException(status_code=422, detail="Collateral revisions are only supported for member loans.")
        collateral_paths_to_remove = _sync_member_revision_collateral(control_number, body.collateral_rows)

    update_payload = {
        **edits,
        "loan_status": "revised_submitted",
        "application_status": "revised_submitted",
    }

    try:
        updated = (
            supabase.table(table)
            .update(update_payload)
            .eq("control_number", control_number)
            .execute()
        )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not resubmit loan application: {exc}")

    if not (updated.data or []):
        raise HTTPException(status_code=500, detail="Loan application was not updated.")

    cleanup_warning = None
    if body.collateral_rows is not None:
        try:
            folder = f"loan_collateral/{control_number}"
            desired_paths = {
                str(item.get("document_url") or "").strip()
                for item in body.collateral_rows
                if isinstance(item, dict) and str(item.get("document_url") or "").strip()
            }
            storage = supabase.storage.from_("Supporting_Documents")
            stored_files = storage.list(folder) or []
            orphaned_paths = [
                f"{folder}/{item['name']}"
                for item in stored_files
                if item.get("name") and f"{folder}/{item['name']}" not in desired_paths
            ]
            stale_paths = sorted(set(collateral_paths_to_remove + orphaned_paths))
            if stale_paths:
                storage.remove(stale_paths)
        except Exception as err:
            cleanup_warning = "Some removed collateral photos could not be deleted from storage."
            logger.warning("revision collateral storage cleanup failed for %s: %s", control_number, err)

    try:
        role = _resolve_staff_role(current_user["id"], current_user.get("email") or "") or "member"
        supabase.table("audit_log").insert({
            "actor_user_id": current_user["id"],
            "actor_role": role,
            "actor_email": current_user.get("email") or None,
            "entity_type": "loan",
            "entity_id": control_number,
            "action": "update",
            "before": {"loan_status": current_status},
            "after": {"loan_status": "revised_submitted"},
            "context": {
                "kind": "revision_resubmission",
                "member_id": member_id,
                "loan_type": row.get("loan_type_id"),
            },
        }).execute()
    except Exception as err:
        logger.warning("revision resubmission audit_log write failed: %s", err)

    try:
        meta = _resolve_loan_member_meta(control_number)
        _create_loan_notification(
            supabase,
            recipient_role="bookkeeper",
            notification_type="resubmit",
            loan_id=control_number,
            member_name=meta.get("member_name") or None,
            loan_type=meta.get("loan_type") or None,
            status_label="resubmit",
            actor_user_id=current_user["id"],
        )
    except Exception as err:
        logger.warning("revision resubmission notification failed: %s", err)

    return {"success": True, "loan_status": "revised_submitted", "cleanup_warning": cleanup_warning}




@app.post("/api/member/renewal-override-requests")
def create_renewal_override_request(
    body: RenewalOverrideCreate,
    current_user: dict = _Depends(_get_current_user),
):
    """Member asks the Bookkeeper to waive the 6-month rule for one active loan."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    reason = body.reason.strip()
    if len(reason) < RENEWAL_OVERRIDE_REASON_MIN:
        raise HTTPException(
            status_code=400,
            detail=f"Please explain the urgent need in at least {RENEWAL_OVERRIDE_REASON_MIN} characters.",
        )

    account = _override_account(current_user)
    member_id = account["member_id"]

    member_row = resolve_member_by_ref(member_id) or {}
    raw_status = str(member_row.get("member_status") or "").strip().lower()
    if raw_status in {"inactive", "suspended", "terminated", "exiting", "closed"} or member_row.get("is_active") is False:
        raise HTTPException(
            status_code=403,
            detail=f"Member account is {raw_status or 'deactivated'} and is not eligible to apply for loans.",
        )

    try:
        active_loan_id, bucket = _override_active_loan(member_id, body.loan_type)
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not check loan eligibility: {exc}")

    if not active_loan_id:
        raise HTTPException(
            status_code=400,
            detail=f"You have no active {body.loan_type} loan, so there is nothing to override.",
        )
    if bucket.get("can_renew"):
        raise HTTPException(
            status_code=400,
            detail="You already meet the 6-month requirement for this loan. You can apply for Renewal directly.",
        )

    payments_made = int(bucket.get("payments_made") or 0)
    member_name = resolve_member_full_name(member_row) if member_row else ""
    record = {
        "member_id": member_id,
        "membership_id": account.get("membership_id") or member_row.get("membership_id"),
        "member_name": member_name,
        "requested_by_user_id": current_user["id"],
        "requested_by_email": current_user.get("email") or None,
        "loan_type": body.loan_type,
        "loan_id": active_loan_id,
        "payments_made": payments_made,
        "required_payments": RENEWAL_MIN_PAYMENTS,
        "reason": reason,
        "status": "pending",
    }

    try:
        inserted = supabase.table(RENEWAL_OVERRIDE_TABLE).insert(record).execute()
    except Exception as exc:
        message = str(exc).lower()
        if "uq_renewal_override_one_pending" in message or "duplicate key" in message:
            raise HTTPException(
                status_code=409,
                detail=f"You already have a pending {body.loan_type} override request. Please wait for the Bookkeeper's decision.",
            )
        raise HTTPException(status_code=500, detail=f"Could not save the request: {exc}")

    row = (inserted.data or [None])[0]
    if not row:
        raise HTTPException(status_code=500, detail="Could not save the request.")

    _override_audit("create", row, current_user, after={"status": "pending", "payments_made": payments_made})
    _override_notify(
        recipient_role="bookkeeper",
        notification_type="renewal_override_request",
        severity="warning",
        title="6-month rule override requested",
        message=(
            f"{member_name or 'A member'} is asking to renew their {body.loan_type} loan "
            f"{active_loan_id} early ({payments_made} of {RENEWAL_MIN_PAYMENTS} payments made). "
            f"Please review the request."
        ),
        loan_id=active_loan_id,
        redirect_url="/bookkeeper-renewal-overrides",
        actor_user_id=current_user["id"],
    )

    return {"success": True, "data": {k: row.get(k) for k in RENEWAL_OVERRIDE_MEMBER_COLUMNS.split(",")}}


@app.get("/api/member/renewal-override-requests")
def list_my_renewal_override_requests(current_user: dict = _Depends(_get_current_user)):
    """The calling member's own requests, newest first."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    account = _override_account(current_user)
    try:
        resp = (
            supabase.table(RENEWAL_OVERRIDE_TABLE)
            .select(RENEWAL_OVERRIDE_MEMBER_COLUMNS)
            .eq("member_id", account["member_id"])
            .order("created_at", desc=True)
            .limit(50)
            .execute()
        )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not load your requests: {exc}")
    return {"success": True, "data": resp.data or []}


@app.post("/api/member/renewal-override-requests/{request_id}/cancel")
def cancel_renewal_override_request(request_id: int, current_user: dict = _Depends(_get_current_user)):
    """Member withdraws their own pending request."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    account = _override_account(current_user)
    try:
        resp = (
            supabase.table(RENEWAL_OVERRIDE_TABLE)
            .update({"status": "cancelled"})
            .eq("id", request_id)
            .eq("member_id", account["member_id"])
            .eq("status", "pending")
            .execute()
        )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not cancel the request: {exc}")
    row = (resp.data or [None])[0]
    if not row:
        raise HTTPException(status_code=404, detail="No pending request found to cancel.")
    _override_audit("update", row, current_user, before={"status": "pending"}, after={"status": "cancelled"})
    return {"success": True}


@app.get("/api/member/renewal-overrides/active")
def get_active_renewal_overrides(current_user: dict = _Depends(_get_current_user)):
    """Approved, unexpired, unused overrides that still apply to the member's
    current active loan. The loan forms use this to unlock Renewal."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    account = _override_account(current_user)
    member_id = account["member_id"]
    try:
        resp = (
            supabase.table(RENEWAL_OVERRIDE_TABLE)
            .select("id,override_kind,loan_type,loan_id,expires_at,reviewed_at")
            .eq("member_id", member_id)
            .eq("status", "approved")
            .gt("expires_at", _override_iso(_override_now()))
            .execute()
        )
        rows = resp.data or []
        if not rows:
            return {"success": True, "data": []}
        # A 6-month override is tied to one specific loan; once that loan is no
        # longer the active one (renewed, paid off) it stops applying. (Any
        # lingering bonus_window rows from before decision 3.3-1 removed that
        # kind are historical only -- the loan_id check below simply excludes
        # them, since they were stored with loan_id=None.)
        buckets = _compute_all_buckets(member_id)
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not load active overrides: {exc}")

    active = [
        r for r in rows
        if (buckets.get(r["loan_type"]) or {}).get("active_loan_id") == r["loan_id"]
    ]
    return {"success": True, "data": active}


@app.post("/api/member/renewal-overrides/consume")
def consume_renewal_override(
    body: RenewalOverrideConsume,
    current_user: dict = _Depends(_get_current_user),
):
    """Spend the member's approved override on a submitted renewal application,
    so one approval cannot be reused for several renewals. Idempotent and
    harmless when no override applies (normal renewals call this too)."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    account = _override_account(current_user)
    member_id = account["member_id"]
    try:
        resp = (
            supabase.table(RENEWAL_OVERRIDE_TABLE)
            .select("*")
            .eq("member_id", member_id)
            .eq("loan_type", body.loan_type)
            .eq("override_kind", OVERRIDE_KIND_SIX_MONTH)
            .eq("status", "approved")
            .gt("expires_at", _override_iso(_override_now()))
            .order("reviewed_at", desc=True)
            .limit(1)
            .execute()
        )
        candidate = (resp.data or [None])[0]
        if not candidate:
            return {"success": True, "consumed": False}

        active_loan_id, _bucket = _override_active_loan(member_id, body.loan_type)
        if active_loan_id != candidate["loan_id"]:
            return {"success": True, "consumed": False}

        updated = (
            supabase.table(RENEWAL_OVERRIDE_TABLE)
            .update({
                "status": "used",
                "used_at": _override_iso(_override_now()),
                "used_application_id": body.application_control_number,
            })
            .eq("id", candidate["id"])
            .eq("status", "approved")
            .execute()
        )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not record override use: {exc}")

    row = (updated.data or [None])[0]
    if not row:
        return {"success": True, "consumed": False}
    _override_audit(
        "update",
        row,
        current_user,
        before={"status": "approved"},
        after={"status": "used", "used_application_id": body.application_control_number},
    )
    return {"success": True, "consumed": True}


@app.get("/api/bookkeeper/pending-counts")
def get_bookkeeper_pending_counts(current_user: dict = _Depends(_get_current_user)):
    """How many items are waiting on the Bookkeeper, for the sidebar badges.

    Each count mirrors the queue its page shows, so a badge never disagrees with
    the list behind it:
      - loan_approval:      loans + non-member loans still 'pending' or 'draft'
                            (the Loan Approval page's Pending tab)
      - loan_payments:      loan_payments awaiting Bookkeeper confirmation
      - savings_withdrawals: savings queue rows awaiting verification
      - override_requests:  renewal/bonus-window override requests still pending
      - profile_changes:    member profile change requests still pending
    Head-only count queries: no rows are transferred.
    """
    global supabase
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role != "bookkeeper":
        raise HTTPException(status_code=403, detail="Only the Bookkeeper can view these counts.")

    def head_count(table: str, apply_filter) -> int:
        query = supabase.table(table).select("*", count="exact", head=True)
        return int(getattr(apply_filter(query).execute(), "count", None) or 0)

    # ilike with no wildcard is a case-insensitive equality check, matching how
    # the pages lower-case these statuses before comparing.
    def pending_or_draft(q):
        return q.or_(
            "loan_status.ilike.pending,"
            "loan_status.ilike.draft,"
            "loan_status.ilike.revision_requested,"
            "loan_status.ilike.revised_submitted,"
            "application_status.ilike.pending,"
            "application_status.ilike.draft,"
            "application_status.ilike.revision_requested,"
            "application_status.ilike.revised_submitted"
        )

    try:
        loan_approval = head_count("loans", pending_or_draft) + head_count("non_member_loans", pending_or_draft)
        loan_payments = head_count(
            "loan_payments",
            lambda q: q.or_("confirmation_status.ilike.pending_bookkeeper,confirmation_status.is.null"),
        )
        savings_withdrawals = head_count(
            "savings_transaction_queue",
            lambda q: q.ilike("transaction_status", "pending_verification"),
        )
        override_requests = head_count(RENEWAL_OVERRIDE_TABLE, lambda q: q.eq("status", "pending"))
    except Exception as exc:
        if _is_stale_connection_error(exc) and url and key:
            supabase = create_client(url, key, options=_SUPABASE_CLIENT_OPTIONS)
            try:
                loan_approval = head_count("loans", pending_or_draft) + head_count("non_member_loans", pending_or_draft)
                loan_payments = head_count(
                    "loan_payments",
                    lambda q: q.or_("confirmation_status.ilike.pending_bookkeeper,confirmation_status.is.null"),
                )
                savings_withdrawals = head_count(
                    "savings_transaction_queue",
                    lambda q: q.ilike("transaction_status", "pending_verification"),
                )
                override_requests = head_count(RENEWAL_OVERRIDE_TABLE, lambda q: q.eq("status", "pending"))
            except Exception as retry_exc:
                raise HTTPException(status_code=500, detail=f"Could not load pending counts: {retry_exc}") from retry_exc
        else:
            raise HTTPException(status_code=500, detail=f"Could not load pending counts: {exc}") from exc

    return {
        "success": True,
        "data": {
            "loan_approval": loan_approval,
            "loan_payments": loan_payments,
            "savings_withdrawals": savings_withdrawals,
            "override_requests": override_requests,
            "profile_changes": _pc_pending_count(),
        },
    }


@app.get("/api/staff/pending-counts")
def get_staff_pending_counts(current_user: dict = _Depends(_get_current_user)):
    """Pending-work counts for the sidebar badges of the Manager, Treasurer,
    Cashier and BOD portals (the Bookkeeper has its own endpoint above).

    Each count mirrors the queue its page shows:
      - manager   loan_approval:   loans + non-member loans 'recommended for approval'
      - treasurer loan_approval:   loans + non-member loans 'to be disbursed'
      - cashier   loan_disbursement: loans 'ready for disbursement'
                  cbu_payouts:       terminated members still owed CBU
      - bod       loan_approvals:    loans 'recommended for bod approval'
                  member_approvals:  member applications still 'pending'
    Head-only count queries: no rows are transferred.
    """
    global supabase
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")

    def head_count(table: str, column: str, status: str) -> int:
        # ilike with no wildcard = case-insensitive equality, as the pages do.
        query = supabase.table(table).select("*", count="exact", head=True).ilike(column, status)
        return int(getattr(query.execute(), "count", None) or 0)

    def compute() -> dict:
        if role == "manager":
            return {"loan_approval": head_count("loans", "loan_status", "recommended for approval")
                    + head_count("non_member_loans", "loan_status", "recommended for approval")}
        if role == "treasurer":
            return {"loan_approval": head_count("loans", "loan_status", "to be disbursed")
                    + head_count("non_member_loans", "loan_status", "to be disbursed")}
        if role == "cashier":
            owed = [r for r in _settlement_rows(["terminated"]) if r["status"] == "terminated" and r["remaining"] > 0]
            return {
                "loan_disbursement": head_count("loans", "loan_status", "ready for disbursement"),
                "cbu_payouts": len(owed),
            }
        if role == "bod":
            return {
                "loan_approvals": head_count("loans", "loan_status", "recommended for bod approval"),
                "member_approvals": head_count("member_applications", "application_status", "pending"),
            }
        return {}

    try:
        data = compute()
    except HTTPException:
        raise
    except Exception as exc:
        if _is_stale_connection_error(exc) and url and key:
            supabase = create_client(url, key, options=_SUPABASE_CLIENT_OPTIONS)
            try:
                data = compute()
            except Exception as retry_exc:
                raise HTTPException(status_code=500, detail=f"Could not load pending counts: {retry_exc}") from retry_exc
        else:
            raise HTTPException(status_code=500, detail=f"Could not load pending counts: {exc}") from exc

    return {"success": True, "data": data}


@app.get("/api/bookkeeper/loan-approval-queue")
async def get_bookkeeper_loan_approval_queue(current_user: dict = _Depends(_get_current_user)):
    """Return the Bookkeeper queue through the authenticated server client."""
    global supabase
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role != "bookkeeper":
        raise HTTPException(status_code=403, detail="Only the Bookkeeper can view the loan approval queue.")

    queue_statuses = {"pending", "draft", "revision_requested", "revised_submitted"}
    # Filter in the query: the tables hold >1000 rows, which is PostgREST's
    # default row cap, so an unfiltered oldest-first read drops the newest
    # (i.e. the pending) loans. ilike with no wildcard = case-insensitive equals.
    queue_filter = ",".join(
        f"{col}.ilike.{st}" for col in ("loan_status", "application_status") for st in sorted(queue_statuses)
    )

    def fetch_rows() -> tuple[list, list]:
        loans = (
            supabase.table("loans")
            .select(
                "control_number,loan_amount,term,loan_status,application_status,application_type,application_date,"
                "applicant_full_name,"
                "member:member_id(first_name,last_name,is_bona_fide,membership_id),"
                "loan_types:loan_type_id(name)"
            )
            .or_(queue_filter)
            .order("application_date")
            .execute()
        ).data or []
        non_member = (
            supabase.table("non_member_loans")
            .select(
                "control_number,loan_amount,term,loan_status,application_status,"
                "application_date,full_name,loan_type_code"
            )
            .or_(queue_filter)
            .order("application_date")
            .execute()
        ).data or []
        return loans, non_member

    try:
        try:
            loans_rows, non_member_rows = fetch_rows()
        except Exception as exc:
            # A stale pooled connection surfaces as "server disconnected" or,
            # on Windows, WinError 10035. A fresh client usually succeeds.
            msg = str(exc).lower()
            transient = "server disconnected" in msg or "10035" in msg or "non-blocking socket" in msg
            if not (transient and url and key):
                raise
            supabase = create_client(url, key, options=_SUPABASE_CLIENT_OPTIONS)
            loans_rows, non_member_rows = fetch_rows()

        def is_queue_row(row: dict) -> bool:
            return bool({
                str(row.get("loan_status") or "").strip().lower(),
                str(row.get("application_status") or "").strip().lower(),
            } & queue_statuses)

        try:
            classification_payload = await list_migs_classifications()
            classifications = classification_payload.get("data") or {}
        except Exception:
            # Queue loading must remain available if the optional MIGS snapshot
            # tables have not been deployed yet.
            classifications = {}

        def attach_migs_status(row: dict) -> dict:
            member = row.get("member") or {}
            membership_id = str(member.get("membership_id") or "").strip()
            code = classifications.get(membership_id, "unscored")
            label = {"migs": "MIGS", "non_migs": "NON-MIGS", "unscored": "Unscored"}.get(code, "Unscored")
            return {**row, "source": "loans", "migs_status": label}

        rows = [attach_migs_status(row) for row in loans_rows if is_queue_row(row)]
        rows.extend({**row, "source": "non_member"} for row in non_member_rows if is_queue_row(row))
        rows.sort(key=lambda row: (
            str(row.get("application_date") or ""),
            str(row.get("control_number") or ""),
        ))
        return {"success": True, "data": rows}
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not load Bookkeeper loan approval queue: {exc}")


@app.get("/api/bookkeeper/renewal-override-requests")
def list_renewal_override_requests(
    status: str = "pending",
    current_user: dict = _Depends(_get_current_user),
):
    """Bookkeeper queue / history. status = pending|approved|rejected|cancelled|used|all."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_bookkeeper(current_user)

    wanted = (status or "pending").strip().lower()
    if wanted != "all" and wanted not in RENEWAL_OVERRIDE_STATUSES:
        raise HTTPException(status_code=400, detail="Invalid status filter.")

    try:
        query = supabase.table(RENEWAL_OVERRIDE_TABLE).select("*").order("created_at", desc=True).limit(200)
        if wanted != "all":
            query = query.eq("status", wanted)
        rows = query.execute().data or []
        pending = (
            supabase.table(RENEWAL_OVERRIDE_TABLE)
            .select("id", count="exact")
            .eq("status", "pending")
            .execute()
        )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not load override requests: {exc}")

    return {
        "success": True,
        "data": rows,
        "pending_count": getattr(pending, "count", None) or 0,
    }


@app.post("/api/bookkeeper/renewal-override-requests/{request_id}/review")
def review_renewal_override_request(
    request_id: int,
    body: RenewalOverrideReview,
    current_user: dict = _Depends(_get_current_user),
):
    """Bookkeeper approves (unlocks Renewal) or rejects a pending request."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_bookkeeper(current_user)

    note = (body.note or "").strip() or None
    if body.action == "rejected" and not note:
        raise HTTPException(status_code=400, detail="A note is required when rejecting a request.")

    try:
        found = (
            supabase.table(RENEWAL_OVERRIDE_TABLE)
            .select("*")
            .eq("id", request_id)
            .limit(1)
            .execute()
        )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not load the request: {exc}")
    req = (found.data or [None])[0]
    if not req:
        raise HTTPException(status_code=404, detail="Request not found.")
    if req.get("status") != "pending":
        raise HTTPException(status_code=409, detail=f"This request is already {req.get('status')}.")
    if str(req.get("requested_by_user_id") or "") == current_user["id"]:
        raise HTTPException(status_code=403, detail="You cannot review your own request.")

    now = _override_now()
    patch: dict[str, Any] = {
        "status": body.action,
        "reviewed_by_user_id": current_user["id"],
        "reviewed_by_email": current_user.get("email") or None,
        "reviewed_at": _override_iso(now),
        "review_note": note,
    }

    # bonus_window override kind REMOVED (decision 3.3-1) -- a pending row of
    # that kind can only be a leftover from before the removal; approving it
    # just grants the historical window-override behavior one last time
    # rather than erroring on a dangling reference.
    is_window = req.get("override_kind") == "bonus_window"
    if body.action == "approved" and is_window:
        patch["expires_at"] = _override_iso(now + timedelta(days=RENEWAL_OVERRIDE_VALIDITY_DAYS))
    elif body.action == "approved":
        try:
            active_loan_id, _bucket = _override_active_loan(req["member_id"], req["loan_type"])
        except Exception as exc:
            raise HTTPException(status_code=500, detail=f"Could not verify the member's active loan: {exc}")
        if active_loan_id != req["loan_id"]:
            raise HTTPException(
                status_code=409,
                detail="The loan this request was filed for is no longer the member's active loan. Reject it instead.",
            )
        patch["expires_at"] = _override_iso(now + timedelta(days=RENEWAL_OVERRIDE_VALIDITY_DAYS))

    try:
        updated = (
            supabase.table(RENEWAL_OVERRIDE_TABLE)
            .update(patch)
            .eq("id", request_id)
            .eq("status", "pending")
            .execute()
        )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not save the decision: {exc}")
    row = (updated.data or [None])[0]
    if not row:
        # Someone else decided it between our read and this write.
        raise HTTPException(status_code=409, detail="This request was already decided.")

    approved = body.action == "approved"
    _override_audit(
        "approve" if approved else "reject",
        row,
        current_user,
        before={"status": "pending"},
        after={"status": body.action, "expires_at": row.get("expires_at")},
    )
    loan_label = f"{req['loan_type']} loan {req['loan_id']}"
    if is_window:
        title = "Bonus window override approved" if approved else "Bonus window request declined"
        message = (
            f"The Bookkeeper approved your request. You can submit one Bonus loan application "
            f"in the next {RENEWAL_OVERRIDE_VALIDITY_DAYS} days."
            if approved else
            "The Bookkeeper declined your request to apply for a Bonus loan outside May/November."
            + (f" Reason: {note}" if note else "")
        )
    else:
        title = "Early renewal approved" if approved else "Early renewal request declined"
        message = (
            f"The Bookkeeper approved your request to renew your {loan_label} early. "
            f"You can apply for Renewal for the next {RENEWAL_OVERRIDE_VALIDITY_DAYS} days."
            if approved else
            f"The Bookkeeper declined your request to renew your {loan_label} early."
            + (f" Reason: {note}" if note else "")
        )
    _override_notify(
        recipient_role="member",
        recipient_member_id=str(req["member_id"]),
        notification_type="member_renewal_override_approved" if approved else "member_renewal_override_rejected",
        severity="success" if approved else "danger",
        title=title,
        message=message,
        loan_id=req["loan_id"],
        redirect_url="/member-apply-loans",
        actor_user_id=current_user["id"],
    )

    return {"success": True, "data": row}


# ============================================================================
# SECTION: Profile Change Requests (Bookkeeper approval)
# A member no longer edits a controlled Personal Data Sheet field directly:
# each changed field becomes a request row (one batch_id per save) that the
# Bookkeeper approves or rejects; approval writes the value to the profile.
# Net take-home pay (personal_data_sheet.salary, the figure the loan forms and
# the 40% debt-capacity rule read) additionally needs a payslip, stored in the
# private Supporting_Documents bucket under profile_payslips/ and only ever
# exposed as a short-lived signed link.
#
# Same shape as the renewal override above: identity comes from the verified
# JWT, never the body; a Bookkeeper can't review their own request; the table
# is the history ledger (rows are never deleted); decisions are mirrored into
# audit_log and the loan_notifications bell feed.
# Schema: member_profile_change_requests_schema.sql.
# ============================================================================

PROFILE_CHANGE_TABLE = "member_profile_change_requests"
PROFILE_CHANGE_STATUSES = {"pending", "approved", "rejected", "cancelled"}
PROFILE_CHANGE_BUCKET = "Supporting_Documents"
PROFILE_CHANGE_PAYSLIP_FOLDER = "profile_payslips"
PROFILE_CHANGE_NET_PAY_FIELD = "salary"
PROFILE_CHANGE_MAX_PAYSLIP_BYTES = 5 * 1024 * 1024
# A payslip must cover this month or one of the previous N months.
PROFILE_CHANGE_PAYSLIP_MAX_AGE_MONTHS = 2
PROFILE_CHANGE_SIGNED_URL_SECONDS = 300
PROFILE_CHANGE_NOTE_MAX = 1000
PROFILE_CHANGE_BLOCKED_MEMBER_STATUSES = {"terminated", "closed"}

_PROFILE_CHANGE_GENDERS = ("Male", "Female")
_PROFILE_CHANGE_CIVIL = ("Single", "Married", "Widowed", "Separated")
_PROFILE_CHANGE_BLOOD = ("A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-")

# Every field the member profile page can edit (Members_Profile.jsx), keyed by
# personal_data_sheet column. kind drives validation and how the value is
# written back; required fields can't be blanked.
PROFILE_CHANGE_FIELDS: dict[str, dict[str, Any]] = {
    "surname": {"label": "Surname", "kind": "text", "required": True},
    "first_name": {"label": "First Name", "kind": "text", "required": True},
    "middle_name": {"label": "Middle Name", "kind": "text"},
    "maiden_name": {"label": "Maiden Name", "kind": "text"},
    "date_of_birth": {"label": "Date of Birth", "kind": "date", "required": True},
    "place_of_birth": {"label": "Place of Birth", "kind": "text"},
    "gender": {"label": "Gender", "kind": "select", "options": _PROFILE_CHANGE_GENDERS},
    "civil_status": {"label": "Civil Status", "kind": "select", "options": _PROFILE_CHANGE_CIVIL},
    "citizenship": {"label": "Citizenship", "kind": "text"},
    "religion": {"label": "Religion", "kind": "text"},
    "blood_type": {"label": "Blood Type", "kind": "select", "options": _PROFILE_CHANGE_BLOOD},
    "height": {"label": "Height (cm)", "kind": "int"},
    "contact_number": {"label": "Mobile Number", "kind": "tel", "required": True},
    "email": {"label": "Email Address", "kind": "email", "required": True},
    "permanent_address": {"label": "Permanent Address", "kind": "text", "required": True, "max": 1000},
    "father_name": {"label": "Father's Name", "kind": "text"},
    "mother_name": {"label": "Mother's Maiden Name", "kind": "text"},
    "number_of_dependents": {"label": "Number of Dependents", "kind": "int", "required": True},
    "spouse_name": {"label": "Spouse Name", "kind": "text"},
    "spouse_occupation": {"label": "Spouse Occupation", "kind": "text"},
    "spouse_date_of_birth": {"label": "Spouse Date of Birth", "kind": "date"},
    "employer_name": {"label": "Employer Name", "kind": "text"},
    "position": {"label": "Position", "kind": "text"},
    "occupation": {"label": "Occupation", "kind": "text", "required": True},
    "educational_attainment": {"label": "Educational Attainment", "kind": "text"},
    "income_source": {"label": "Source of Income", "kind": "text"},
    PROFILE_CHANGE_NET_PAY_FIELD: {"label": "Net Take-Home Pay (Monthly)", "kind": "money", "proof": True},
    "annual_income": {"label": "Annual Income", "kind": "text"},
    "other_income": {"label": "Other Income", "kind": "text"},
    "tin_number": {"label": "TIN Number", "kind": "text"},
    "gsis_number": {"label": "GSIS Number", "kind": "text"},
}

# Columns a member may see on their own requests (no reviewer/requester ids,
# no storage path).
PROFILE_CHANGE_MEMBER_COLUMNS = (
    "id,batch_id,field_key,field_label,old_value,new_value,requires_proof,payslip_path,"
    "pay_period,status,review_note,reviewed_at,created_at"
)


class ProfileChangeItem(BaseModel):
    field_key: str = Field(..., min_length=1, max_length=64)
    new_value: str | None = Field(default=None, max_length=1000)


class ProfileChangePayslip(BaseModel):
    filename: str = Field(default="payslip", max_length=200)
    content_type: str = Field(default="", max_length=100)
    data_base64: str = Field(..., max_length=8_000_000)


class ProfileChangeCreate(BaseModel):
    changes: list[ProfileChangeItem] = Field(..., min_length=1, max_length=40)
    payslip: ProfileChangePayslip | None = None
    pay_period: str | None = Field(default=None, max_length=10)  # YYYY-MM


class ProfileChangeReview(BaseModel):
    action: Literal["approved", "rejected"]
    note: str | None = Field(default=None, max_length=PROFILE_CHANGE_NOTE_MAX)
    # A net-pay change moves what a loan in review is judged on; the Bookkeeper
    # has to acknowledge that explicitly when the member has one open.
    acknowledge_open_loan: bool = False


def _pc_retry(call):
    """Run a Supabase call; on a dead pooled connection (WinError 10035 /
    "server disconnected") rebuild the client and try once more, the same way the
    pending-counts endpoint does. `call` must look up the global `supabase` when
    it runs, so the retry uses the fresh client."""
    global supabase
    try:
        return call()
    except Exception as exc:
        if _is_stale_connection_error(exc) and url and key:
            supabase = create_client(url, key, options=_SUPABASE_CLIENT_OPTIONS)
            return call()
        raise


def _pc_normalize(key: str, raw: Any) -> str | None:
    """Validate a submitted value and return its canonical text (None = blank)."""
    spec = PROFILE_CHANGE_FIELDS[key]
    label = spec["label"]
    text = "" if raw is None else str(raw).strip()
    if not text:
        if spec.get("required"):
            raise HTTPException(status_code=400, detail=f"{label} is required.")
        return None

    kind = spec["kind"]
    if kind == "select":
        match = next((o for o in spec["options"] if o.lower() == text.lower()), None)
        if not match:
            raise HTTPException(status_code=400, detail=f"{label} must be one of: {', '.join(spec['options'])}.")
        return match
    if kind == "date":
        try:
            parsed = date.fromisoformat(text[:10])
        except ValueError:
            raise HTTPException(status_code=400, detail=f"{label} must be a valid date.")
        if parsed > date.today():
            raise HTTPException(status_code=400, detail=f"{label} can't be in the future.")
        return parsed.isoformat()
    if kind == "int":
        try:
            number = Decimal(text)
        except InvalidOperation:
            raise HTTPException(status_code=400, detail=f"{label} must be a number.")
        if number < 0 or number != number.to_integral_value():
            raise HTTPException(status_code=400, detail=f"{label} must be a whole number, zero or more.")
        return str(int(number))
    if kind == "money":
        try:
            amount = Decimal(text.replace(",", ""))
        except InvalidOperation:
            raise HTTPException(status_code=400, detail=f"{label} must be an amount.")
        if amount <= 0 or amount > Decimal("10000000"):
            raise HTTPException(status_code=400, detail=f"{label} must be greater than zero.")
        return str(amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    if kind == "email" and not re.fullmatch(r"[^\s@]+@[^\s@]+\.[^\s@]+", text):
        raise HTTPException(status_code=400, detail="Please enter a valid email address.")
    if kind == "tel" and not re.fullmatch(r"[0-9+\-\s()]{7,20}", text):
        raise HTTPException(status_code=400, detail="Please enter a valid contact number.")
    if len(text) > int(spec.get("max", 500)):
        raise HTTPException(status_code=400, detail=f"{label} is too long.")
    return text


def _pc_current_text(key: str, stored: Any) -> str | None:
    """A stored PDS value in the same canonical text _pc_normalize produces, so
    'unchanged' compares equal. Lenient: unparseable legacy values stay as-is."""
    if stored is None:
        return None
    text = str(stored).strip()
    if not text or text.lower() == "n/a":
        return None
    kind = PROFILE_CHANGE_FIELDS[key]["kind"]
    try:
        if kind == "date":
            return date.fromisoformat(text[:10]).isoformat()
        if kind == "int":
            number = Decimal(text)
            return str(int(number)) if number == number.to_integral_value() else text
        if kind == "money":
            return str(Decimal(text.replace(",", "")).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    except (ValueError, InvalidOperation):
        return text
    return text


def _pc_db_value(key: str, text: str | None) -> Any:
    """Canonical text -> what the PDS column should hold (matches what the
    profile page wrote before: numbers for number fields, text otherwise)."""
    if text is None:
        return None
    if PROFILE_CHANGE_FIELDS[key]["kind"] == "int":
        return int(text)
    return text


def _pc_member_status_gate(member_row: dict) -> None:
    raw_status = str(member_row.get("member_status") or "").strip().lower()
    if raw_status in PROFILE_CHANGE_BLOCKED_MEMBER_STATUSES:
        raise HTTPException(status_code=403, detail=f"Member account is {raw_status}; the profile can't be changed.")


def _pc_load_pds(membership_id: str) -> dict:
    try:
        resp = _pc_retry(lambda: (
            supabase.table("personal_data_sheet")
            .select("*")
            .eq("membership_number_id", membership_id)
            .order("created_at", desc=True)
            .limit(1)
            .execute()
        ))
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not read your Personal Data Sheet: {exc}")
    row = (resp.data or [None])[0]
    if not row:
        raise HTTPException(status_code=404, detail="No Personal Data Sheet is on file for this account.")
    return row


def _pc_public_row(row: dict, *, staff: bool = False) -> dict:
    """Strip internals: the storage path never leaves the server."""
    out = {k: v for k, v in row.items() if k != "payslip_path"}
    out["has_payslip"] = bool(row.get("payslip_path"))
    if not staff:
        for key in ("requested_by_user_id", "requested_by_email", "reviewed_by_user_id", "reviewed_by_email", "member_id"):
            out.pop(key, None)
    return out


def _pc_audit(action: str, row: dict, current_user: dict, *, before: dict | None = None, after: dict | None = None, extra: dict | None = None) -> None:
    """Mirror a profile-change event into audit_log. Best-effort: the request
    row already carries the history, so a failure here never blocks the action."""
    if not supabase or not current_user or not current_user.get("id"):
        return
    try:
        role = _resolve_staff_role(current_user["id"], current_user.get("email") or "") or "member"
        supabase.table("audit_log").insert({
            "actor_user_id": current_user["id"],
            "actor_role": role,
            "actor_email": current_user.get("email") or None,
            "entity_type": "member",
            "entity_id": str(row.get("membership_id") or row.get("member_id") or ""),
            "action": action,
            "before": before,
            "after": after,
            "context": {
                "kind": "profile_change",
                "request_id": row.get("id"),
                "batch_id": row.get("batch_id"),
                "member_id": row.get("member_id"),
                "membership_id": row.get("membership_id"),
                "member_name": row.get("member_name"),
                "field_key": row.get("field_key"),
                "field_label": row.get("field_label"),
                "review_note": row.get("review_note"),
                **(extra or {}),
            },
        }).execute()
    except Exception as err:
        logger.warning("profile change audit_log write failed: %s", err)


def _pc_apply(membership_id: str, member_id: str, field_key: str, text: str | None) -> None:
    """Write one approved value to the profile. Net pay also re-points the other
    places the system reads it so a stale copy can't drive a loan decision."""
    patch: dict[str, Any] = {field_key: _pc_db_value(field_key, text)}
    if field_key == "civil_status" and str(text or "").lower() == "single":
        patch.update({"spouse_name": None, "spouse_occupation": None, "spouse_date_of_birth": None})
    supabase.table("personal_data_sheet").update(patch).eq("membership_number_id", membership_id).execute()

    if field_key == PROFILE_CHANGE_NET_PAY_FIELD and text is not None:
        amount = float(Decimal(text))
        # member_profile.latest_net_pay feeds the DTI/stress index and its triggers
        # refresh loan_calculator; member.latest_net_pay is what the loan
        # eligibility gate reads. Best-effort: the PDS write above is the source
        # the loan forms prefill from.
        for table, column in (("member_profile", "membership_number_id"), ("member", "id")):
            try:
                supabase.table(table).update({"latest_net_pay": amount}).eq(column, member_id).execute()
            except Exception as err:
                logger.warning("profile change: could not sync latest_net_pay on %s: %s", table, err)


def _pc_pending_count() -> int:
    """Pending requests for the sidebar badge. Never raises: the badges endpoint
    must keep working before the migration has been applied."""
    try:
        resp = supabase.table(PROFILE_CHANGE_TABLE).select("*", count="exact", head=True).eq("status", "pending").execute()
        return int(getattr(resp, "count", None) or 0)
    except Exception as err:
        logger.warning("profile change pending count failed: %s", err)
        return 0


def _pc_open_loan_applications(member_id: str) -> int:
    """Loan applications of this member still in the Bookkeeper's hands."""
    try:
        resp = (
            supabase.table("loans")
            .select("*", count="exact", head=True)
            .eq("member_id", member_id)
            .or_(
                "loan_status.ilike.pending,loan_status.ilike.draft,loan_status.ilike.revision_requested,loan_status.ilike.revised_submitted,"
                "application_status.ilike.pending,application_status.ilike.draft,application_status.ilike.revision_requested,application_status.ilike.revised_submitted"
            )
            .execute()
        )
        return int(getattr(resp, "count", None) or 0)
    except Exception as err:
        logger.warning("profile change open-loan check failed: %s", err)
        return 0


def _pc_decode_payslip(payslip: ProfileChangePayslip) -> tuple[bytes, str, str]:
    """(bytes, content_type, extension) after checking size and real file type."""
    import base64
    import binascii

    encoded = payslip.data_base64.strip()
    if encoded.startswith("data:") and "," in encoded:
        encoded = encoded.split(",", 1)[1]
    try:
        data = base64.b64decode(encoded, validate=True)
    except (binascii.Error, ValueError):
        raise HTTPException(status_code=400, detail="The payslip file could not be read. Please attach it again.")
    if not data:
        raise HTTPException(status_code=400, detail="The payslip file is empty.")
    if len(data) > PROFILE_CHANGE_MAX_PAYSLIP_BYTES:
        raise HTTPException(
            status_code=400,
            detail=f"The payslip is larger than {PROFILE_CHANGE_MAX_PAYSLIP_BYTES // (1024 * 1024)} MB. Please attach a smaller file.",
        )
    # Trust the bytes, not the declared type or filename.
    if data.startswith(b"%PDF"):
        return data, "application/pdf", "pdf"
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        return data, "image/png", "png"
    if data.startswith(b"\xff\xd8\xff"):
        return data, "image/jpeg", "jpg"
    raise HTTPException(status_code=400, detail="The payslip must be a PDF, PNG or JPG file.")


def _pc_parse_pay_period(raw: str | None) -> date:
    text = (raw or "").strip()
    try:
        year, month = (int(part) for part in text.split("-", 1))
        period = date(year, month, 1)
    except (ValueError, TypeError):
        raise HTTPException(status_code=400, detail="Please enter the month your payslip covers.")
    today = date.today()
    this_month = today.replace(day=1)
    index = lambda d: d.year * 12 + d.month  # noqa: E731
    if index(period) > index(this_month):
        raise HTTPException(status_code=400, detail="The payslip month can't be in the future.")
    if index(this_month) - index(period) > PROFILE_CHANGE_PAYSLIP_MAX_AGE_MONTHS:
        raise HTTPException(
            status_code=400,
            detail=f"The payslip is too old. Please attach one from the last {PROFILE_CHANGE_PAYSLIP_MAX_AGE_MONTHS + 1} months.",
        )
    return period


def _pc_remove_payslip(path: str | None) -> None:
    if not path:
        return
    try:
        supabase.storage.from_(PROFILE_CHANGE_BUCKET).remove([path])
    except Exception as err:
        logger.warning("profile change: could not remove payslip %s: %s", path, err)


@app.get("/api/member/profile-change-requests")
def list_my_profile_change_requests(current_user: dict = _Depends(_get_current_user)):
    """The calling member's own requests, newest first."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    account = _override_account(current_user)
    try:
        resp = _pc_retry(lambda: (
            supabase.table(PROFILE_CHANGE_TABLE)
            .select(PROFILE_CHANGE_MEMBER_COLUMNS)
            .eq("member_id", account["member_id"])
            .order("created_at", desc=True)
            .limit(100)
            .execute()
        ))
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not load your requests: {exc}")
    return {"success": True, "data": [_pc_public_row(r) for r in (resp.data or [])]}


@app.post("/api/member/profile-change-requests")
def create_profile_change_requests(
    body: ProfileChangeCreate,
    current_user: dict = _Depends(_get_current_user),
):
    """Member submits profile edits. Each changed field becomes a pending request;
    a blank field being filled for the first time is applied straight away
    (nothing to protect yet, and it keeps first-time onboarding unblocked) —
    except net pay, which always needs a payslip and approval."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    account = _override_account(current_user)
    member_id = account["member_id"]
    membership_id = str(account.get("membership_id") or "").strip()
    if not membership_id:
        raise HTTPException(status_code=403, detail="No membership number is linked to this account.")

    member_row = resolve_member_by_ref(member_id) or {}
    _pc_member_status_gate(member_row)
    # Decision 3.3 (Simulation findings, confirmed 2026-10-23): a profile
    # change can't be submitted at all while a loan application of this
    # member's is still in the Bookkeeper's hands -- the figures those loans
    # are judged on (net pay and otherwise) must stay fixed for the duration
    # of that review. Net-pay approval already had its own open-loan
    # acknowledgement further down; this blocks submission outright for
    # every field, which is stricter and makes that acknowledgement
    # unreachable in practice (kept as-is; it's still correct, just moot now).
    if _pc_open_loan_applications(member_id):
        raise HTTPException(
            status_code=409,
            detail="You have a loan application still in review. Profile changes can't be submitted until it's decided.",
        )
    pds = _pc_load_pds(membership_id)
    member_name = resolve_member_full_name(member_row) if member_row else ""

    # Validate every submitted field and work out what actually changed.
    submitted: dict[str, str | None] = {}
    for item in body.changes:
        if item.field_key not in PROFILE_CHANGE_FIELDS:
            raise HTTPException(status_code=400, detail=f"'{item.field_key}' can't be changed from the profile page.")
        if item.field_key in submitted:
            raise HTTPException(status_code=400, detail="The same field was submitted twice.")
        submitted[item.field_key] = _pc_normalize(item.field_key, item.new_value)

    direct: list[tuple[str, str | None, str | None]] = []   # (key, old, new)
    to_request: list[tuple[str, str | None, str | None]] = []
    for key, new_text in submitted.items():
        old_text = _pc_current_text(key, pds.get(key))
        if new_text == old_text:
            continue
        spec = PROFILE_CHANGE_FIELDS[key]
        if old_text is None and not spec.get("proof"):
            direct.append((key, old_text, new_text))
        else:
            to_request.append((key, old_text, new_text))

    if not direct and not to_request:
        raise HTTPException(status_code=400, detail="There are no changes to save.")

    # Fields that already have a request waiting.
    if to_request:
        try:
            open_rows = _pc_retry(lambda: (
                supabase.table(PROFILE_CHANGE_TABLE)
                .select("field_key")
                .eq("member_id", member_id)
                .eq("status", "pending")
                .in_("field_key", [k for k, _, _ in to_request])
                .execute()
            )).data or []
        except Exception as exc:
            raise HTTPException(status_code=500, detail=f"Could not check your open requests: {exc}")
        if open_rows:
            labels = ", ".join(PROFILE_CHANGE_FIELDS[r["field_key"]]["label"] for r in open_rows)
            raise HTTPException(
                status_code=409,
                detail=f"You already have a request waiting for approval for: {labels}. Cancel it or wait for the Bookkeeper's decision.",
            )

    # Proof is only for net pay.
    needs_payslip = any(PROFILE_CHANGE_FIELDS[k].get("proof") for k, _, _ in to_request)
    payslip_bytes = payslip_type = payslip_ext = None
    pay_period: date | None = None
    if needs_payslip:
        if body.payslip is None:
            raise HTTPException(status_code=400, detail="Please attach a photo or PDF of your payslip to change your net take-home pay.")
        pay_period = _pc_parse_pay_period(body.pay_period)
        payslip_bytes, payslip_type, payslip_ext = _pc_decode_payslip(body.payslip)

    batch_id = str(uuid4())
    base = {
        "batch_id": batch_id,
        "member_id": member_id,
        "membership_id": membership_id,
        "member_name": member_name,
        "requested_by_user_id": current_user["id"],
        "requested_by_email": current_user.get("email") or None,
    }

    # Upload before inserting so a request never points at a missing file.
    payslip_path = None
    if needs_payslip:
        payslip_path = f"{PROFILE_CHANGE_PAYSLIP_FOLDER}/{member_id}/{batch_id}.{payslip_ext}"
        try:
            supabase.storage.from_(PROFILE_CHANGE_BUCKET).upload(
                payslip_path, payslip_bytes, {"content-type": payslip_type, "upsert": "false"}
            )
        except Exception as exc:
            raise HTTPException(status_code=500, detail=f"Could not upload the payslip: {exc}")

    records = []
    for key, old_text, new_text in to_request:
        spec = PROFILE_CHANGE_FIELDS[key]
        proof = bool(spec.get("proof"))
        records.append({
            **base,
            "field_key": key,
            "field_label": spec["label"],
            "old_value": old_text,
            "new_value": new_text,
            "requires_proof": proof,
            "payslip_path": payslip_path if proof else None,
            "payslip_content_type": payslip_type if proof else None,
            "pay_period": pay_period.isoformat() if proof and pay_period else None,
            "status": "pending",
        })

    inserted_rows: list[dict] = []
    if records:
        try:
            inserted_rows = _pc_retry(lambda: supabase.table(PROFILE_CHANGE_TABLE).insert(records).execute()).data or []
        except Exception as exc:
            _pc_remove_payslip(payslip_path)
            message = str(exc).lower()
            if "uq_profile_change_one_pending" in message or "duplicate key" in message:
                raise HTTPException(
                    status_code=409,
                    detail="You already have a request waiting for approval for one of these fields.",
                )
            raise HTTPException(status_code=500, detail=f"Could not save the request: {exc}")
        if not inserted_rows:
            _pc_remove_payslip(payslip_path)
            raise HTTPException(status_code=500, detail="Could not save the request.")

    # First-time fills go straight in, after the requests are safely stored.
    applied: list[str] = []
    for key, old_text, new_text in direct:
        try:
            _pc_apply(membership_id, member_id, key, new_text)
        except Exception as exc:
            raise HTTPException(status_code=500, detail=f"Could not save {PROFILE_CHANGE_FIELDS[key]['label']}: {exc}")
        applied.append(key)
        _pc_audit(
            "update",
            {**base, "field_key": key, "field_label": PROFILE_CHANGE_FIELDS[key]["label"]},
            current_user,
            before={key: old_text},
            after={key: new_text},
            extra={"applied": "direct_first_entry"},
        )

    for row in inserted_rows:
        _pc_audit(
            "create", row, current_user,
            before={row["field_key"]: row.get("old_value")},
            after={"status": "pending", row["field_key"]: row.get("new_value")},
        )
    if inserted_rows:
        labels = ", ".join(r["field_label"] for r in inserted_rows)
        _override_notify(
            recipient_role="bookkeeper",
            notification_type="profile_change_request",
            severity="warning",
            title="Profile change requested",
            message=f"{member_name or 'A member'} asked to change: {labels}. Please review the request.",
            loan_id=None,
            redirect_url="/bookkeeper-profile-changes",
            actor_user_id=current_user["id"],
        )

    return {
        "success": True,
        "data": {
            "requests": [_pc_public_row(r) for r in inserted_rows],
            "applied_directly": applied,
        },
    }


@app.post("/api/member/profile-change-requests/{request_id}/cancel")
def cancel_profile_change_request(request_id: int, current_user: dict = _Depends(_get_current_user)):
    """Member withdraws their own pending request. The payslip is deleted: a
    cancelled request has no use for it and it is sensitive."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    account = _override_account(current_user)
    try:
        found = (
            supabase.table(PROFILE_CHANGE_TABLE)
            .select("payslip_path")
            .eq("id", request_id)
            .eq("member_id", account["member_id"])
            .eq("status", "pending")
            .limit(1)
            .execute()
        ).data or []
        resp = (
            supabase.table(PROFILE_CHANGE_TABLE)
            .update({"status": "cancelled", "payslip_path": None, "payslip_content_type": None})
            .eq("id", request_id)
            .eq("member_id", account["member_id"])
            .eq("status", "pending")
            .execute()
        )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not cancel the request: {exc}")
    row = (resp.data or [None])[0]
    if not row:
        raise HTTPException(status_code=404, detail="No pending request found to cancel.")
    if found:
        _pc_remove_payslip(found[0].get("payslip_path"))
    _pc_audit("update", row, current_user, before={"status": "pending"}, after={"status": "cancelled"})
    return {"success": True}


@app.get("/api/profile-change-requests/{request_id}/payslip-url")
def get_profile_change_payslip_url(request_id: int, current_user: dict = _Depends(_get_current_user)):
    """Short-lived signed link to a request's payslip. Only the member who filed
    it and the Bookkeeper can get one."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    try:
        found = supabase.table(PROFILE_CHANGE_TABLE).select("member_id,payslip_path,payslip_content_type").eq("id", request_id).limit(1).execute()
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not load the request: {exc}")
    row = (found.data or [None])[0]
    if not row or not row.get("payslip_path"):
        raise HTTPException(status_code=404, detail="No payslip is attached to this request.")

    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role != "bookkeeper":
        account = _override_account(current_user)
        if str(row["member_id"]) != account["member_id"]:
            raise HTTPException(status_code=403, detail="You can't view this payslip.")

    try:
        signed = supabase.storage.from_(PROFILE_CHANGE_BUCKET).create_signed_url(
            row["payslip_path"], PROFILE_CHANGE_SIGNED_URL_SECONDS
        )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not open the payslip: {exc}")
    link = (signed or {}).get("signedURL") or (signed or {}).get("signedUrl") or ""
    if not link:
        raise HTTPException(status_code=500, detail="Could not open the payslip.")
    if not link.startswith("http"):
        link = f"{str(url).rstrip('/')}/storage/v1{link if link.startswith('/') else '/' + link}"
    return {
        "success": True,
        "data": {
            "url": link,
            "content_type": row.get("payslip_content_type"),
            "expires_in": PROFILE_CHANGE_SIGNED_URL_SECONDS,
        },
    }


def _require_bookkeeper_profile(current_user: dict) -> None:
    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role != "bookkeeper":
        raise HTTPException(status_code=403, detail="Only the Bookkeeper can review profile change requests.")


@app.get("/api/bookkeeper/profile-change-requests")
def list_profile_change_requests(
    status: str = "pending",
    current_user: dict = _Depends(_get_current_user),
):
    """Bookkeeper queue / history. status = pending|approved|rejected|cancelled|all."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_bookkeeper_profile(current_user)

    wanted = (status or "pending").strip().lower()
    if wanted != "all" and wanted not in PROFILE_CHANGE_STATUSES:
        raise HTTPException(status_code=400, detail="Invalid status filter.")

    try:
        def _fetch_rows():
            query = supabase.table(PROFILE_CHANGE_TABLE).select("*").order("created_at", desc=True).limit(300)
            if wanted != "all":
                query = query.eq("status", wanted)
            return query.execute().data or []

        rows = _pc_retry(_fetch_rows)
        pending_rows = _pc_retry(lambda: (
            supabase.table(PROFILE_CHANGE_TABLE)
            .select("membership_id")
            .eq("status", "pending")
            .limit(2000)
            .execute()
        )).data or []
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not load profile change requests: {exc}")

    # Warn on net-pay changes while the member has a loan in review.
    open_loans: dict[str, int] = {}
    for member in {str(r["member_id"]) for r in rows if r["status"] == "pending" and r["field_key"] == PROFILE_CHANGE_NET_PAY_FIELD}:
        open_loans[member] = _pc_open_loan_applications(member)

    data = []
    for row in rows:
        item = _pc_public_row(row, staff=True)
        item["open_loan_applications"] = open_loans.get(str(row["member_id"]), 0) if row["field_key"] == PROFILE_CHANGE_NET_PAY_FIELD else 0
        data.append(item)

    return {
        "success": True,
        "data": data,
        "pending_count": len(pending_rows),
        "pending_membership_ids": sorted({str(r["membership_id"]) for r in pending_rows if r.get("membership_id")}),
    }


@app.post("/api/bookkeeper/profile-change-requests/{request_id}/review")
def review_profile_change_request(
    request_id: int,
    body: ProfileChangeReview,
    current_user: dict = _Depends(_get_current_user),
):
    """Bookkeeper approves (writes the value to the profile) or rejects a request."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_bookkeeper_profile(current_user)

    note = (body.note or "").strip() or None
    if body.action == "rejected" and not note:
        raise HTTPException(status_code=400, detail="A reason is required when rejecting a request.")

    try:
        found = _pc_retry(lambda: supabase.table(PROFILE_CHANGE_TABLE).select("*").eq("id", request_id).limit(1).execute())
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not load the request: {exc}")
    req = (found.data or [None])[0]
    if not req:
        raise HTTPException(status_code=404, detail="Request not found.")
    if req.get("status") != "pending":
        raise HTTPException(status_code=409, detail=f"This request is already {req.get('status')}.")
    if str(req.get("requested_by_user_id") or "") == current_user["id"]:
        raise HTTPException(status_code=403, detail="You cannot review your own request.")

    key = req["field_key"]
    approved = body.action == "approved"
    open_loans = 0
    if approved:
        if key not in PROFILE_CHANGE_FIELDS:
            raise HTTPException(status_code=409, detail="This field can no longer be changed. Reject the request instead.")
        if PROFILE_CHANGE_FIELDS[key].get("proof") and not req.get("payslip_path"):
            raise HTTPException(status_code=409, detail="This request has no payslip attached. Reject it instead.")
        # The profile must still hold what the member saw when they asked.
        pds = _pc_load_pds(str(req["membership_id"]))
        if _pc_current_text(key, pds.get(key)) != req.get("old_value"):
            raise HTTPException(
                status_code=409,
                detail="The profile value has changed since this request was filed. Reject it and ask the member to submit it again.",
            )
        if key == PROFILE_CHANGE_NET_PAY_FIELD:
            open_loans = _pc_open_loan_applications(str(req["member_id"]))
            if open_loans and not body.acknowledge_open_loan:
                raise HTTPException(
                    status_code=409,
                    detail=(
                        f"This member has {open_loans} loan application{'s' if open_loans != 1 else ''} still in review. "
                        "Approving changes the net pay those are judged on. Confirm to proceed."
                    ),
                )

    patch: dict[str, Any] = {
        "status": body.action,
        "reviewed_by_user_id": current_user["id"],
        "reviewed_by_email": current_user.get("email") or None,
        "reviewed_at": _override_iso(_override_now()),
        "review_note": note,
    }
    try:
        updated = _pc_retry(lambda: (
            supabase.table(PROFILE_CHANGE_TABLE)
            .update(patch)
            .eq("id", request_id)
            .eq("status", "pending")
            .execute()
        ))
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not save the decision: {exc}")
    row = (updated.data or [None])[0]
    if not row:
        raise HTTPException(status_code=409, detail="This request was already decided.")

    if approved:
        try:
            _pc_apply(str(req["membership_id"]), str(req["member_id"]), key, req.get("new_value"))
            row = (
                supabase.table(PROFILE_CHANGE_TABLE)
                .update({"applied_at": _override_iso(_override_now())})
                .eq("id", request_id)
                .execute()
            ).data[0]
        except Exception as exc:
            # Nothing was applied: put the request back so it can be retried.
            try:
                supabase.table(PROFILE_CHANGE_TABLE).update({
                    "status": "pending", "reviewed_by_user_id": None, "reviewed_by_email": None,
                    "reviewed_at": None, "review_note": None,
                }).eq("id", request_id).execute()
            except Exception as revert_err:
                logger.error("profile change %s: could not revert after failed apply: %s", request_id, revert_err)
            raise HTTPException(status_code=500, detail=f"Could not apply the change to the profile: {exc}")

    _pc_audit(
        "approve" if approved else "reject",
        row,
        current_user,
        before={"status": "pending", key: req.get("old_value")},
        after={"status": body.action, key: req.get("new_value") if approved else req.get("old_value")},
        extra={"acknowledged_open_loan": bool(open_loans and body.acknowledge_open_loan)},
    )

    label = req.get("field_label") or key
    _override_notify(
        recipient_role="member",
        recipient_member_id=str(req["member_id"]),
        notification_type="member_profile_change_approved" if approved else "member_profile_change_rejected",
        severity="success" if approved else "danger",
        title="Profile change approved" if approved else "Profile change declined",
        message=(
            f"The Bookkeeper approved your change to {label}. Your profile is updated."
            if approved else
            f"The Bookkeeper declined your change to {label}." + (f" Reason: {note}" if note else "")
        ),
        loan_id=None,
        redirect_url="/members-profile",
        actor_user_id=current_user["id"],
    )
    return {"success": True, "data": _pc_public_row(row, staff=True)}


# ============================================================================
# SECTION: Member Notification Preferences
# Member Settings > Notifications. Only the optional loan status emails can be
# turned off; security codes always send and the in-app bell is unaffected.
# Enforced in services/notification_service.py. Schema:
# member_notification_preferences.sql. Identity comes from the verified JWT.
# ============================================================================

NOTIFICATION_PREFERENCE_FIELDS = ("loan_review_emails", "loan_release_emails")


class NotificationPreferencesUpdate(BaseModel):
    loan_review_emails: bool
    loan_release_emails: bool


@app.get("/api/member/notification-preferences")
def get_member_notification_preferences(current_user: dict = _Depends(_get_current_user)):
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    member_id = _override_account(current_user)["member_id"]
    try:
        resp = (
            supabase.table("member_notification_preferences")
            .select(",".join(NOTIFICATION_PREFERENCE_FIELDS))
            .eq("member_id", member_id)
            .limit(1)
            .execute()
        )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not load notification settings: {exc}")
    row = (resp.data or [None])[0] or {}
    # No row yet means every email is on.
    return {
        "success": True,
        "data": {field: row.get(field) is not False for field in NOTIFICATION_PREFERENCE_FIELDS},
    }


@app.put("/api/member/notification-preferences")
def update_member_notification_preferences(
    body: NotificationPreferencesUpdate,
    current_user: dict = _Depends(_get_current_user),
):
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    member_id = _override_account(current_user)["member_id"]
    record = {
        "member_id": member_id,
        "loan_review_emails": body.loan_review_emails,
        "loan_release_emails": body.loan_release_emails,
        "updated_at": datetime.utcnow().isoformat() + "Z",
    }
    try:
        supabase.table("member_notification_preferences").upsert(record, on_conflict="member_id").execute()
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not save notification settings: {exc}")
    return {"success": True, "data": {field: record[field] for field in NOTIFICATION_PREFERENCE_FIELDS}}


@app.get("/api/member/{member_key}/debt-capacity")
async def get_member_debt_capacity(member_key: str):
    """Compute maximum borrowable amount per loan type for a member.

    Consolidated: (Share Capital × multiplier) − outstanding Consolidated balances.
                  Multiplier = 5× for MIGS, 3× for Non-MIGS.
    Emergency:    Flat ₱20,000 cap − outstanding Emergency balance.
    Bonus:        Equal to member's bonus salary (null when unavailable).
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    key = str(member_key or "").strip()
    if not key:
        raise HTTPException(status_code=400, detail="member_key is required.")

    try:
        member_table = _resolve_member_table(supabase)
        lookup_field = "id" if len(key) == 36 and key.count("-") == 4 else "membership_id"
        member_response = (
            supabase.table(member_table)
            .select("id,membership_id,share_capital_amount,is_bona_fide")
            .eq(lookup_field, key)
            .limit(1)
            .execute()
        )
        member = (member_response.data or [None])[0]
        if not member:
            raise HTTPException(status_code=404, detail="Member not found.")
        member_uuid = member["id"]

        share_capital = Decimal(str(member.get("share_capital_amount") or 0))
        if share_capital <= 0:
            cbu_resp = (
                supabase.table("capital_build_up")
                .select("ending_share_capital,transaction_date")
                .eq("member_id", member_uuid)
                .order("transaction_date", desc=True)
                .limit(1)
                .execute()
            )
            latest = (cbu_resp.data or [None])[0]
            if latest:
                share_capital = Decimal(str(latest.get("ending_share_capital") or 0))

        multiplier = Decimal("3.0")
        migs_label = "Non-MIGS"
        try:
            snap_resp = (
                supabase.table("member_classification_temporal")
                .select("final_status,classification_level_id,accrual_date")
                .eq("membership_number_id", member_uuid)
                .order("accrual_date", desc=True)
                .limit(1)
                .execute()
            )
            snap = (snap_resp.data or [None])[0]
            if snap:
                label = snap.get("final_status")
                if not label and snap.get("classification_level_id"):
                    lvl_resp = (
                        supabase.table("classification_level")
                        .select("label")
                        .eq("classification_level_id", snap["classification_level_id"])
                        .limit(1)
                        .execute()
                    )
                    lvl = (lvl_resp.data or [None])[0]
                    if lvl:
                        label = lvl.get("label")
                if str(label or "").lower().startswith("migs"):
                    multiplier = Decimal("5.0")
                    migs_label = "MIGS"
        except Exception:
            pass

        loans_resp = (
            supabase.table("loans")
            .select(
                "control_number,principal_amount,loan_amount,total_interest,"
                "monthly_amortization,term,loan_status,application_date,disbursal_date,"
                "raw_payload,"
                "loan_types:loan_type_id(code,name)"
            )
            .eq("member_id", member_uuid)
            .execute()
        )
        loan_rows = loans_resp.data or []
        # Legacy marker is set at migration time on the loan itself
        # (raw_payload->>'legacy' = 'true'), not inferred from whether a row
        # happens to exist in loan_payments_legacy — a legacy loan with zero
        # recorded historical payments still has no rows there.
        legacy_control_numbers = {
            str(r.get("control_number"))
            for r in loan_rows
            if r.get("control_number") and str((r.get("raw_payload") or {}).get("legacy")).lower() == "true"
        }

        # Statuses whose outstanding balance counts toward debt-capacity ceilings.
        # (Fully paid / rejected / cancelled loans still show in the member's
        # loan history panel below, just with $0 contribution to the ceilings.)
        active_statuses = {"released", "partially paid", "unpaid", "paid"}
        active_by_type: dict[str, list[dict]] = {"consolidated": [], "emergency": [], "bonus": []}
        all_by_type: dict[str, list[dict]] = {"consolidated": [], "emergency": [], "bonus": []}
        for row in loan_rows:
            lt_code = _resolve_loan_type_code(row)
            if lt_code in all_by_type:
                all_by_type[lt_code].append(row)
            if str(row.get("loan_status") or "").strip().lower() not in active_statuses:
                continue
            if lt_code in active_by_type:
                active_by_type[lt_code].append(row)

        active_ids = [
            str(r.get("control_number"))
            for lst in active_by_type.values()
            for r in lst
            if r.get("control_number")
        ]
        all_ids = [
            str(r.get("control_number"))
            for lst in all_by_type.values()
            for r in lst
            if r.get("control_number")
        ]
        paid_by_loan: dict[str, Decimal] = {}
        legacy_loan_ids: set[str] = set(legacy_control_numbers)
        if all_ids:
            try:
                pay_resp = (
                    supabase.table("loan_payments")
                    .select("loan_id,amount_paid,confirmation_status")
                    .in_("loan_id", all_ids)
                    .execute()
                ).data or []
                for p in pay_resp:
                    if is_validated_payment_status(p.get("confirmation_status")):
                        lid = str(p.get("loan_id") or "")
                        paid_by_loan[lid] = paid_by_loan.get(lid, Decimal("0")) + Decimal(str(p.get("amount_paid") or 0))
            except Exception:
                pass
            try:
                leg_resp = (
                    supabase.table("loan_payments_legacy")
                    .select("loan_id,amount_paid")
                    .in_("loan_id", all_ids)
                    .execute()
                ).data or []
                for p in leg_resp:
                    lid = str(p.get("loan_id") or "")
                    paid_by_loan[lid] = paid_by_loan.get(lid, Decimal("0")) + Decimal(str(p.get("amount_paid") or 0))
                    legacy_loan_ids.add(lid)
            except Exception:
                pass

        # Earliest unpaid schedule per loan — used for penalty accrual.
        # Penalty applies only after the 3-month grace past the earliest missed due date.
        earliest_unpaid_due: dict[str, date] = {}
        if all_ids:
            try:
                sched_resp = (
                    supabase.table("loan_schedules")
                    .select("loan_id,due_date,schedule_status")
                    .in_("loan_id", all_ids)
                    .execute()
                ).data or []
                for s in sched_resp:
                    status = str(s.get("schedule_status") or "").strip().lower()
                    if status in {"paid", "completed", "closed"}:
                        continue
                    d = parse_date_value(s.get("due_date"))
                    if not d:
                        continue
                    lid = str(s.get("loan_id") or "")
                    if lid and (lid not in earliest_unpaid_due or d < earliest_unpaid_due[lid]):
                        earliest_unpaid_due[lid] = d
            except Exception:
                pass

        today = datetime.utcnow().date()

        def _accrued_penalty(loan_id: str, loan_type_code: str, remaining: Decimal, loan_row: dict, principal: Decimal) -> Decimal:
            # Same rule as compute_loan_penalty(): first charge on the 3rd missed
            # due date, rate x one installment per month. Legacy loans (any row in
            # loan_payments_legacy) are exempt -- historical delinquency on
            # migrated loans is not chargeable retroactively.
            if loan_id in legacy_loan_ids:
                return Decimal("0")
            return compute_loan_penalty(
                loan_type_code=loan_type_code,
                remaining_balance=remaining,
                earliest_unpaid_due=earliest_unpaid_due.get(loan_id),
                schedules=[],
                payment_dates=[],
                is_legacy=False,
                as_of=today,
                installment_amount=penalty_installment_base(loan_row, remaining),
                original_principal=principal,
            )

        def _remaining_for(loans: list[dict], type_code: str) -> Decimal:
            total = Decimal("0")
            for r in loans:
                principal = Decimal(str(r.get("principal_amount") or r.get("loan_amount") or 0))
                interest = Decimal(str(r.get("total_interest") or 0))
                if interest <= 0:
                    term = int(r.get("term") or 0)
                    amort = Decimal(str(r.get("monthly_amortization") or 0))
                    if term > 0 and amort > 0:
                        if "bonus" in str(type_code).strip().lower():
                            # monthly_amortization already holds the full
                            # lump-sum payoff for Bonus — don't multiply by
                            # term again (see Step 2/4 of BONUS_LOAN_PLAN.md).
                            interest = max(amort - principal, Decimal("0"))
                        else:
                            interest = max(amort * term - principal, Decimal("0"))
                total_payable = principal + interest
                loan_id = str(r.get("control_number") or "")
                paid = paid_by_loan.get(loan_id, Decimal("0"))
                remaining = max(total_payable - paid, Decimal("0"))
                penalty = _accrued_penalty(loan_id, type_code, remaining, r, principal)
                total += remaining + penalty
            return total

        outstanding_consolidated = _remaining_for(active_by_type["consolidated"], "consolidated")
        outstanding_emergency = _remaining_for(active_by_type["emergency"], "emergency")

        def _loan_summary(r: dict, type_label: str, type_code: str) -> dict:
            principal = Decimal(str(r.get("principal_amount") or r.get("loan_amount") or 0))
            interest = Decimal(str(r.get("total_interest") or 0))
            if interest <= 0:
                term = int(r.get("term") or 0)
                amort = Decimal(str(r.get("monthly_amortization") or 0))
                if term > 0 and amort > 0:
                    if "bonus" in str(type_code).strip().lower():
                        interest = max(amort - principal, Decimal("0"))
                    else:
                        interest = max(amort * term - principal, Decimal("0"))
            total_payable = principal + interest
            loan_id = str(r.get("control_number") or "")
            paid = paid_by_loan.get(loan_id, Decimal("0"))
            remaining = max(total_payable - paid, Decimal("0"))
            penalty = _accrued_penalty(loan_id, type_code, remaining, r, principal)
            is_legacy = loan_id in legacy_loan_ids
            return {
                "control_number": r.get("control_number"),
                "loan_type": type_label,
                "loan_status": r.get("loan_status"),
                "principal": decimal_to_float(principal),
                "total_payable": decimal_to_float(total_payable),
                "paid": decimal_to_float(paid),
                "remaining_balance": decimal_to_float(remaining),
                "accrued_penalty": decimal_to_float(penalty),
                "total_with_penalty": decimal_to_float(remaining + penalty),
                "is_legacy": is_legacy,
                "monthly_amortization": decimal_to_float(r.get("monthly_amortization") or 0),
                "term": int(r.get("term") or 0),
                "application_date": r.get("application_date"),
                "disbursal_date": r.get("disbursal_date"),
            }

        # All of the member's loans (any status), for the member-details history
        # panel. Ceilings above are computed from active_by_type only.
        active_loans_list: list[dict] = []
        for lt_code, rows in all_by_type.items():
            label = lt_code.capitalize()
            for row in rows:
                active_loans_list.append(_loan_summary(row, label, lt_code))
        active_loans_list.sort(key=lambda x: str(x.get("disbursal_date") or x.get("application_date") or ""), reverse=True)

        consolidated_ceiling = share_capital * multiplier
        consolidated_max = max(consolidated_ceiling - outstanding_consolidated, Decimal("0"))
        emergency_cap = Decimal("20000")
        emergency_max = max(emergency_cap - outstanding_emergency, Decimal("0"))

        return {
            "success": True,
            "data": {
                "member_id": member_uuid,
                "membership_id": member.get("membership_id"),
                "migs_status": migs_label,
                "multiplier": float(multiplier),
                "share_capital": decimal_to_float(share_capital),
                "consolidated": {
                    "ceiling": decimal_to_float(consolidated_ceiling),
                    "outstanding": decimal_to_float(outstanding_consolidated),
                    "max_available": decimal_to_float(consolidated_max),
                },
                "emergency": {
                    "ceiling": decimal_to_float(emergency_cap),
                    "outstanding": decimal_to_float(outstanding_emergency),
                    "max_available": decimal_to_float(emergency_max),
                },
                "bonus": {
                    "ceiling": None,
                    "outstanding": None,
                    "max_available": None,
                    "note": "Equal to member's Bonus Salary (not yet captured in schema).",
                },
                "active_loans": active_loans_list,
            },
        }
    except HTTPException:
        raise
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to compute debt capacity: {err}")


# ============================================================================
# SECTION: Bookkeeper — Loan Management & Ledger
# Endpoints for the bookkeeper's manage-loans queue and per-loan ledger view.
# ============================================================================

# 30-second in-memory cache for /api/bookkeeper/manage-loans. The endpoint
# takes 8-15s cold (fetches loans + payments + schedules with pagination
# loops), and is polled by the Bookkeeper Dashboard + reused by Manage-Loans
# and Delinquency pages — without caching, multiple tabs and the 60s poll
# stack up into request pile-up. TTL is short enough that new payments show
# up within half a minute; not worth wiring write-invalidation for a demo.
_MANAGE_LOANS_CACHE: dict = {"payload": None, "expires_at": 0.0}
_MANAGE_LOANS_CACHE_TTL_SECONDS = 120.0  # 2 min — payments show up within 2 min; avoids pile-up from multi-tab polling

@app.get("/api/bookkeeper/manage-loans")
async def get_bookkeeper_manage_loans():
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    import time as _time
    now = _time.monotonic()
    cached = _MANAGE_LOANS_CACHE
    if cached["payload"] is not None and cached["expires_at"] > now:
        return cached["payload"]

    try:
        # Narrow + paginated, same fix applied to /api/secretary/membership-records
        # for the narrowing (an unbounded select with nested foreign-table joins
        # over the full `loans` table can push supabase-py past the HTTP2 stream
        # limit) plus pagination like the loan_schedules/loan_payments_legacy
        # loops below: PostgREST enforces its own db-max-rows cap (commonly 1000)
        # regardless of any .limit() requested here, so a single request can
        # silently truncate the result below the real loan count.
        loan_rows: list[dict] = []
        page = 1000
        offset = 0
        while True:
            batch = (
                supabase.table("loans")
                .select(
                    "control_number,member_id,loan_amount,principal_amount,interest_rate,term,loan_status,application_status,monthly_amortization,total_interest,application_date,application_type," \
                    "member:member_id(membership_id,first_name,last_name,is_bona_fide),loan_type:loan_type_id(code,name,interest_rate)"
                )
                .order("application_date", desc=True)
                .range(offset, offset + page - 1)
                .execute()
            ).data or []
            if not batch:
                break
            loan_rows.extend(batch)
            if len(batch) < page:
                break
            offset += page

        # Prior-version count per loan. Same pattern as
        # /api/cashier/loan-payments/loans — chain = (member_id, loan_type_name)
        # sorted by application_date, index in the chain = number of prior
        # versions. Delinquency page uses this to exclude restructured
        # predecessors from the collection worklist (their balances are
        # bookkeeping artifacts, already rolled into the successor).
        prior_versions_by_loan: dict[str, int] = {}
        try:
            chains: dict[tuple, list[dict]] = {}
            for row in loan_rows:
                mid = row.get("member_id")
                ltype = ((row.get("loan_type") or {}).get("name")) or ""
                if not mid or not ltype:
                    continue
                chains.setdefault((mid, ltype), []).append(row)
            for items in chains.values():
                sorted_items = sorted(items, key=lambda r: str(r.get("application_date") or ""))
                for idx, r in enumerate(sorted_items):
                    cn = str(r.get("control_number") or "")
                    if cn:
                        prior_versions_by_loan[cn] = idx
        except Exception:
            prior_versions_by_loan = {}

        visible_statuses = {
            "approved",
            "ready for disbursement",
            "to be disbursed",
            "released",
            "partially paid",
            "fully paid",
        }
        loan_rows = [
            row
            for row in loan_rows
            if str(row.get("loan_status") or "").strip().lower() in visible_statuses
        ]

        loan_ids = [str(row.get("control_number") or "").strip() for row in loan_rows if row.get("control_number")]
        if not loan_ids:
            return {
                "success": True,
                "data": {
                    "server_time": datetime.utcnow().isoformat(),
                    "counts": {"active_loans": 0, "fully_paid_loans": 0},
                    "rows": [],
                },
            }

        # Chunk .in_() id lists: with 1,446 loans the full id list produces a
        # query string long enough (~27KB) that Cloudflare/PostgREST reject it
        # with a plain-text 400 "Bad Request" (not JSON, so postgrest-py's own
        # error parsing throws "JSON could not be generated"). 300 ids/chunk
        # keeps each request comfortably under that limit.
        _ID_CHUNK = 300

        def _id_chunks(ids: list[str]):
            for i in range(0, len(ids), _ID_CHUNK):
                yield ids[i : i + _ID_CHUNK]

        payment_rows: list[dict] = []
        for chunk in _id_chunks(loan_ids):
            batch = (
                supabase.table("loan_payments")
                .select("id,loan_id,amount_paid,penalties,payment_date,confirmation_status,payment_reference,transaction_reference")
                .in_("loan_id", chunk)
                .order("payment_date")
                .execute()
            ).data or []
            payment_rows.extend(batch)

        # Also pull legacy payments (historical, pre-migration). These live in
        # loan_payments_legacy and are keyed by the same control_number, but have
        # no confirmation workflow — they are always considered validated.
        # Supabase caps result sets at 1000 rows/page, so we page through until
        # done (legacy table can have 6k+ rows across all loans).
        legacy_payment_rows: list[dict] = []
        try:
            for chunk in _id_chunks(loan_ids):
                page = 1000
                offset = 0
                while True:
                    batch = (
                        supabase.table("loan_payments_legacy")
                        .select("id,loan_id,amount_paid,payment_date,payment_code,or_cdv_no,is_overpayment")
                        .in_("loan_id", chunk)
                        .order("payment_date")
                        .range(offset, offset + page - 1)
                        .execute()
                    ).data or []
                    if not batch:
                        break
                    legacy_payment_rows.extend(batch)
                    if len(batch) < page:
                        break
                    offset += page
        except Exception:
            legacy_payment_rows = []

        # Normalize legacy rows into the same shape as live loan_payments so the
        # downstream merge loop can treat them uniformly.
        for legacy in legacy_payment_rows:
            payment_rows.append({
                "id": legacy.get("id"),
                "loan_id": legacy.get("loan_id"),
                "amount_paid": legacy.get("amount_paid"),
                "penalties": 0,
                "payment_date": legacy.get("payment_date"),
                "confirmation_status": "validated",  # legacy = historical fact
                "payment_reference": legacy.get("payment_code") or legacy.get("or_cdv_no"),
                "transaction_reference": legacy.get("or_cdv_no") or legacy.get("payment_code"),
                "_is_legacy": True,
            })

        # Page through schedules — 6,080+ LEGACY rows silently truncate at
        # 1000 without pagination, starving most loans of their due dates and
        # leaving the Repayment Behavior chart empty for those loans.
        schedule_rows: list[dict] = []
        try:
            for chunk in _id_chunks(loan_ids):
                page = 1000
                offset = 0
                while True:
                    batch = (
                        supabase.table("loan_schedules")
                        .select("loan_id,schedule_id,due_date,schedule_status,expected_amount,installment_no")
                        .in_("loan_id", chunk)
                        .order("due_date")
                        .range(offset, offset + page - 1)
                        .execute()
                    ).data or []
                    if not batch:
                        break
                    schedule_rows.extend(batch)
                    if len(batch) < page:
                        break
                    offset += page
        except Exception:
            schedule_rows = []

        payments_by_loan: dict[str, list[dict]] = {}
        for payment in payment_rows:
            payments_by_loan.setdefault(str(payment.get("loan_id") or ""), []).append(payment)

        schedules_by_loan: dict[str, list[dict]] = {}
        for schedule in schedule_rows:
            schedules_by_loan.setdefault(str(schedule.get("loan_id") or ""), []).append(schedule)

        mapped_rows = []
        active_count = 0
        fully_paid_count = 0

        for row in loan_rows:
            loan_id = str(row.get("control_number") or "").strip()
            if not loan_id:
                continue

            member = row.get("member") or {}
            member_name = f"{member.get('first_name') or ''} {member.get('last_name') or ''}".strip() or "Unknown Member"
            member_type = "Member"
            membership_id = str(member.get("membership_id") or "").strip()

            loan_type = row.get("loan_type") or {}
            loan_type_name = loan_type.get("name") or "N/A"
            loan_type_code = str(loan_type.get("code") or normalize_cashier_loan_type(loan_type_name)).upper()

            principal_amount = Decimal(str(row.get("principal_amount") or row.get("loan_amount") or 0))
            total_interest_amount = Decimal(str(row.get("total_interest") or 0))
            if total_interest_amount <= 0:
                term_months_val = int(row.get("term") or 0)
                monthly_amort_val = Decimal(str(row.get("monthly_amortization") or 0))
                if term_months_val > 0 and monthly_amort_val > 0:
                    if "bonus" in loan_type_code.lower():
                        total_interest_amount = max(monthly_amort_val - principal_amount, Decimal("0"))
                    else:
                        total_interest_amount = max(monthly_amort_val * term_months_val - principal_amount, Decimal("0"))
            total_payable_amount = principal_amount + total_interest_amount

            loan_payments = sorted(
                payments_by_loan.get(loan_id, []),
                key=lambda item: str(item.get("payment_date") or ""),
            )

            # Repayment-speed pairing.
            #
            # Compare each payment to its NEAREST reconstructed due date and
            # report the signed offset. days_offset >0 = late, <0 = early.
            #
            # We do NOT roll due dates forward for renewals — doing so hides
            # the delinquency signal by inventing synthetic slots near every
            # renewal-era payment. If a loan's reconstructed schedule ends in
            # 2020 and the member is still paying in 2025, that's real
            # delinquency vs the original contract and should show as red
            # (offset ~1800 days). Bookkeepers reason about loans against the
            # contract's original term, not against a phantom extended one.
            _due_dates: list = []
            for _s in schedules_by_loan.get(loan_id, []):
                d = parse_date_value(_s.get("due_date"))
                if d:
                    _due_dates.append(d)
            _due_dates.sort()

            total_validated = Decimal("0")
            payment_history = []
            for payment in loan_payments:
                amount_paid = Decimal(str(payment.get("amount_paid") or 0))
                if is_validated_payment_status(payment.get("confirmation_status")):
                    total_validated += amount_paid
                running_remaining = max(total_payable_amount - total_validated, Decimal("0"))

                days_offset = None
                _paid_on = parse_date_value(payment.get("payment_date"))
                if _paid_on and _due_dates:
                    nearest = min(_due_dates, key=lambda d: abs((_paid_on - d).days))
                    days_offset = (_paid_on - nearest).days

                payment_history.append(
                    {
                        "payment_id": payment.get("payment_reference") or payment.get("id"),
                        "date_paid": payment.get("payment_date"),
                        "reference_no": payment.get("transaction_reference") or payment.get("payment_reference") or payment.get("id"),
                        "amount_paid": decimal_to_float(amount_paid),
                        "penalties": decimal_to_float(payment.get("penalties") or 0),
                        "remaining_after": decimal_to_float(running_remaining),
                        "confirmation_status": payment.get("confirmation_status") or "pending_bookkeeper",
                        "days_offset": days_offset,
                    }
                )

            remaining_balance = max(total_payable_amount - total_validated, Decimal("0"))
            if _ledger_says_fully_paid(row):
                remaining_balance = Decimal("0")
            if remaining_balance <= 0:
                repayment_status = "Fully Paid"
            elif total_validated > 0:
                repayment_status = "Partially Paid"
            else:
                repayment_status = "Unpaid"

            loan_schedules = schedules_by_loan.get(loan_id, [])
            active_due = None
            for schedule in loan_schedules:
                status = str(schedule.get("schedule_status") or "").strip().lower()
                if status not in {"paid", "validated", "cancelled"}:
                    active_due = schedule
                    break
            # Fallback: if every schedule is paid/validated, use the last one
            if not active_due and loan_schedules:
                active_due = loan_schedules[-1]

            due_date = active_due.get("due_date") if active_due else None

            # Inject the current-due schedule row as an "Upcoming" ledger entry only
            # for loans with no real payment history yet (e.g., legacy loans
            # reconstructed from CSV). Skip if real payments already exist.
            if active_due and not payment_history:
                payment_history.append(
                    {
                        "payment_id": f"SCHED-{loan_id}-{active_due.get('installment_no')}",
                        "date_paid": active_due.get("due_date"),
                        "reference_no": f"Installment #{active_due.get('installment_no')}",
                        "amount_paid": decimal_to_float(active_due.get("expected_amount") or 0),
                        "penalties": 0.0,
                        "remaining_after": decimal_to_float(remaining_balance),
                        "confirmation_status": "upcoming",
                    }
                )

            if repayment_status == "Fully Paid":
                fully_paid_count += 1
            else:
                active_count += 1

            mapped_rows.append(
                {
                    "loan_id": loan_id,
                    "membership_id": membership_id,
                    "member_name": member_name,
                    "member_type": member_type,
                    "loan_type": loan_type_name,
                    "loan_type_code": loan_type_code,
                    "loan_amount": decimal_to_float(principal_amount),
                    "interest_rate": BONUS_MONTHLY_RATE_MEMBER if loan_type_code == "BONUS" else sanitize_monthly_rate_percent(
                        row.get("interest_rate"),
                        (row.get("loan_type") or {}).get("interest_rate"),
                    ),
                    "term_months": int(row.get("term") or 0),
                    "amortization": decimal_to_float(row.get("monthly_amortization") or 0),
                    "remaining_balance": decimal_to_float(remaining_balance),
                    "total_payable": decimal_to_float(total_payable_amount),
                    "total_interest": decimal_to_float(total_interest_amount),
                    "due_date": due_date,
                    "status": repayment_status,
                    "source_loan_status": row.get("loan_status"),
                    "source_application_status": row.get("application_status"),
                    "application_date": row.get("application_date"),
                    "application_type": str(row.get("application_type") or "new").strip().lower(),
                    "payment_history": payment_history,
                    "prior_versions": prior_versions_by_loan.get(loan_id, 0),
                    # Legacy = loan whose schedule was reconstructed by the
                    # migration script (schedule_id prefixed "LEGACY_" per
                    # memory:project_legacy_loan_reconstruction.md). This
                    # marker is authoritative and survives later live
                    # payments, unlike a payment-based check which flips
                    # false as soon as a legacy loan takes its first live
                    # payment. Delinquency worklist defaults to Live so
                    # panelists see loans created through the running app.
                    "is_legacy": any(
                        str(s.get("schedule_id") or "").startswith("LEGACY_")
                        for s in schedules_by_loan.get(loan_id, [])
                    ),
                }
            )

        # Non-member Bonus loans live in non_member_loans and have no payment table;
        # their repayment evidence is on raw_payload.repayment.
        try:
            non_member_rows = (
                supabase.table("non_member_loans")
                .select("control_number,full_name,loan_amount,interest_rate,term,loan_status,application_status,application_date,application_type,raw_payload")
                .order("application_date", desc=True)
                .execute()
            ).data or []
        except Exception as e:
            logger.warning("non_member_loans lookup failed for manage-loans: %s", e)
            non_member_rows = []
        k_table_pays = _nonmember_payments_by_loan([str(k.get("control_number")) for k in non_member_rows])
        for k in non_member_rows:
            k_status = str(k.get("loan_status") or "").strip().lower()
            if k_status not in visible_statuses:
                continue
            k_amount = Decimal(str(k.get("loan_amount") or 0))
            k_src = k_table_pays.get(str(k.get("control_number"))) or [
                {"amount_paid": r.get("amount"), "payment_date": r.get("date"), "or_no": r.get("or_no")}
                for r in ((k.get("raw_payload") or {}).get("repayment") or [])
            ]
            k_history = []
            k_running = k_amount
            for i, r in enumerate(k_src, 1):
                amt = Decimal(str(r.get("amount_paid") or 0))
                k_running = max(k_running - amt, Decimal("0"))
                k_history.append({
                    "payment_id": r.get("id") or r.get("or_no") or f"{k.get('control_number')}-{i}",
                    "date_paid": r.get("payment_date"),
                    "reference_no": r.get("or_no") or "",
                    "amount_paid": decimal_to_float(amt),
                    "penalties": 0.0,
                    "remaining_after": decimal_to_float(k_running),
                    "confirmation_status": "validated",
                })
            k_paid = k_status == "fully paid" or k_running <= 0
            if k_paid:
                fully_paid_count += 1
            else:
                active_count += 1
            mapped_rows.append(
                {
                    "loan_id": k.get("control_number"),
                    "membership_id": None,
                    "member_name": k.get("full_name") or "Unknown Applicant",
                    "member_type": "Non-Member",
                    "loan_type": "Non-member Bonus Loan",
                    "loan_type_code": "NONMEMBER_BONUS",
                    "loan_amount": decimal_to_float(k_amount),
                    "interest_rate": BONUS_MONTHLY_RATE_NONMEMBER,
                    "term_months": int(k.get("term") or 0),
                    "amortization": 0.0,
                    "remaining_balance": 0.0 if k_paid else decimal_to_float(k_running),
                    "total_payable": decimal_to_float(k_amount),
                    "total_interest": 0.0,
                    "due_date": None,
                    "status": "Fully Paid" if k_paid else ("Partially Paid" if k_history else "Unpaid"),
                    "source_loan_status": k.get("loan_status"),
                    "source_application_status": k.get("application_status"),
                    "application_date": k.get("application_date"),
                    "application_type": str(k.get("application_type") or "new").strip().lower(),
                    "payment_history": k_history,
                    "prior_versions": 0,
                    "is_legacy": True,
                    "is_nonmember": True,
                }
            )

        payload = {
            "success": True,
            "data": {
                "server_time": datetime.utcnow().isoformat(),
                "counts": {"active_loans": active_count, "fully_paid_loans": fully_paid_count},
                "rows": mapped_rows,
            },
        }
        _MANAGE_LOANS_CACHE["payload"] = payload
        _MANAGE_LOANS_CACHE["expires_at"] = _time.monotonic() + _MANAGE_LOANS_CACHE_TTL_SECONDS
        return payload
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load manage loans data: {err}")


# 90-second in-memory cache for /api/bookkeeper/dashboard-summary. This
# endpoint exists so the Bookkeeper Dashboard (bookkeeperDashboard.jsx) never
# has to pull the full manage-loans / membership-records / credit-risk-queue
# payloads (loan-by-loan payment history, all schedules, all members, all
# CBU rows) just to render ~9 numbers and two chart aggregates. Every value
# below is scoped to reproduce EXACTLY what the dashboard already computes
# client-side today — this is a performance change, not a behavior change.
_DASHBOARD_SUMMARY_CACHE: dict = {"payload": None, "expires_at": 0.0}
_DASHBOARD_SUMMARY_CACHE_TTL_SECONDS = 90.0
_DASHBOARD_SUMMARY_RETRYING = False

# Same "visible" loan_status set as /api/bookkeeper/manage-loans — the
# dashboard's Total Loans stat must count the identical population. Keep this
# in sync with `visible_statuses` above if that set ever changes.
_DASHBOARD_VISIBLE_LOAN_STATUSES = {
    "approved",
    "ready for disbursement",
    "to be disbursed",
    "released",
    "partially paid",
    "fully paid",
}


@app.get("/api/bookkeeper/dashboard-summary")
async def get_bookkeeper_dashboard_summary():
    global supabase, _DASHBOARD_SUMMARY_RETRYING
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    import time as _time
    now = _time.monotonic()
    cached = _DASHBOARD_SUMMARY_CACHE
    if cached["payload"] is not None and cached["expires_at"] > now:
        return cached["payload"]

    try:
        # --- Total Loans ------------------------------------------------
        # Same population as manage-loans's `totalLoans = loans.length`, but
        # we only need control_number + loan_status here, not the full
        # member/loan_type join or payment/schedule fan-out.
        # PostgREST caps a single response (commonly 1000 rows), so page
        # through the table — a bare .execute() silently truncated this to 1000.
        def _count_visible_loans(table_name: str) -> int:
            count = 0
            page_size = 1000
            offset = 0
            while True:
                batch = (
                    supabase.table(table_name)
                    .select("control_number,loan_status")
                    .order("control_number")
                    .range(offset, offset + page_size - 1)
                    .execute()
                ).data or []
                count += sum(
                    1
                    for row in batch
                    if str(row.get("loan_status") or "").strip().lower() in _DASHBOARD_VISIBLE_LOAN_STATUSES
                )
                if len(batch) < page_size:
                    return count
                offset += page_size

        total_loans = _count_visible_loans("loans")
        # manage-loans also lists non-member loans (ABFF/KOICA, non-member Bonus).
        try:
            total_loans += _count_visible_loans("non_member_loans")
        except Exception as e:
            logger.warning("non_member_loans count failed for dashboard-summary: %s", e)

        # --- Payments this month / last month -----------------------------
        # Mirrors the dashboard's current `sumForKey`: it sums amount_paid for
        # ALL payments in the window, regardless of confirmation_status. That
        # is intentionally reproduced here as-is (not tightened to
        # "validated only") to keep the stat card's number unchanged.
        today = date.today()
        current_month_start = today.replace(day=1)
        if current_month_start.month == 1:
            prev_month_start = current_month_start.replace(year=current_month_start.year - 1, month=12)
        else:
            prev_month_start = current_month_start.replace(month=current_month_start.month - 1)
        next_month_start = (
            current_month_start.replace(year=current_month_start.year + 1, month=1)
            if current_month_start.month == 12
            else current_month_start.replace(month=current_month_start.month + 1)
        )

        def _sum_amount_paid_in_range(start: date, end: date) -> float:
            total = Decimal("0")
            # Live payments for the window.
            live_resp = (
                supabase.table("loan_payments")
                .select("amount_paid,payment_date")
                .gte("payment_date", start.isoformat())
                .lt("payment_date", end.isoformat())
                .execute()
            )
            for row in live_resp.data or []:
                total += Decimal(str(row.get("amount_paid") or 0))
            # Legacy payments for the same window (dashboard's allPayments
            # includes both live and legacy rows).
            legacy_resp = (
                supabase.table("loan_payments_legacy")
                .select("amount_paid,payment_date")
                .gte("payment_date", start.isoformat())
                .lt("payment_date", end.isoformat())
                .execute()
            )
            for row in legacy_resp.data or []:
                total += Decimal(str(row.get("amount_paid") or 0))
            return decimal_to_float(total)

        payments_this_month = _sum_amount_paid_in_range(current_month_start, next_month_start)
        payments_last_month = _sum_amount_paid_in_range(prev_month_start, current_month_start)

        # --- Total Share Capital ------------------------------------------
        # Same figure as fetchShareCapital(): sum of paid_up_capital across
        # membership-records. Recomputed narrowly here instead of reusing
        # /api/secretary/membership-records so the dashboard doesn't pull
        # personal_data_sheet/member rows it never displays.
        total_share_capital = _compute_total_share_capital()

        # --- Recent Activity (top 8, across every transaction type) --------
        # Pulling only the most recent handful from each source table
        # (ordered, limited) and merging avoids fetching full transaction
        # history just to keep a handful of rows.
        recent_activities = _fetch_recent_activity(limit=8)

        # --- Credit Risk Snapshot -------------------------------------------
        credit_risk_snapshot = _compute_credit_risk_snapshot()

        # --- Yearly Collections + Repayment Behavior ------------------------
        # Both charts need the full payment history (all years), so there is
        # no way to shrink this below "every payment" the way the stat cards
        # were shrunk. What IS avoidable is everything manage-loans also does
        # around payments: member/loan_type joins, remaining-balance running
        # totals, payment_history/is_legacy assembly. This helper fetches only
        # (loan_id, amount_paid, payment_date) from both payment tables and
        # (loan_id, due_date) from schedules — the minimum columns these two
        # charts need — instead of reusing the heavy manage-loans payload.
        yearly_collections, repayment_behavior_by_year = _compute_payment_charts()

        payload = {
            "success": True,
            "data": {
                "server_time": datetime.utcnow().isoformat(),
                "stats": {
                    "total_loans": total_loans,
                    "payments_this_month": payments_this_month,
                    "payments_last_month": payments_last_month,
                    "share_capital": total_share_capital,
                },
                "recent_activities": recent_activities,
                "credit_risk": credit_risk_snapshot,
                "yearly_collections": yearly_collections,
                "repayment_behavior_by_year": repayment_behavior_by_year,
            },
        }
        _DASHBOARD_SUMMARY_CACHE["payload"] = payload
        _DASHBOARD_SUMMARY_CACHE["expires_at"] = _time.monotonic() + _DASHBOARD_SUMMARY_CACHE_TTL_SECONDS
        return payload
    except Exception as err:
        # supabase-py's pooled HTTP client can retain a closed connection after
        # the local backend has been idle. Recreate the client once so the
        # dashboard does not turn a transient "Server disconnected" into a
        # persistent 500 for the staff portal.
        if (
            not _DASHBOARD_SUMMARY_RETRYING
            and _is_stale_connection_error(err)
            and url
            and key
        ):
            _DASHBOARD_SUMMARY_RETRYING = True
            try:
                supabase = create_client(url, key, options=_SUPABASE_CLIENT_OPTIONS)
                return await get_bookkeeper_dashboard_summary()
            finally:
                _DASHBOARD_SUMMARY_RETRYING = False
        raise HTTPException(status_code=500, detail=f"Failed to load dashboard summary: {err}")


def _compute_total_share_capital() -> float:
    """The cooperative's total CBU: every member's current running CBU
    balance (member.share_capital_amount, kept in sync with capital_build_up
    by recompute_member_shares() -- see cbu_share_sync_fix_future_dated.sql,
    which stops the year-end import placeholder from freezing it).

    Deposits add to it; loan CBU offsets and termination payouts subtract
    from it. (It used to sum initial_paid_up_capital -- each member's one-time
    joining amount -- which never moved.)
    """
    return decimal_to_float(_total_member_cbu())


def _total_member_cbu() -> Decimal:
    rows = (
        supabase.table("member")
        .select("share_capital_amount")
        .range(0, 9999)
        .execute()
    ).data or []
    return money(sum((Decimal(str(r.get("share_capital_amount") or 0)) for r in rows), Decimal("0")))


def _fetch_recent_activity(limit: int = 8) -> list[dict]:
    """Most recent activity across every transaction type the Bookkeeper
    actually deals with (item 4 of the dashboard rework) — not just loan
    payments: loan payments (live + legacy), loan applications, savings
    deposits/withdrawals, membership fee payments, and grocery sales.
    Deliberately excludes loan disbursement (that's a Treasurer action, not
    a Bookkeeper one), unlike BOD's own Recent Transactions.

    Each source is queried narrowly (only the columns needed, ordered,
    limited) before merging by date — never a full-table scan — then member
    names/details are resolved only for the rows that actually make the cut,
    same "resolve top rows only" shape as the original single-source version.
    """
    now_iso = datetime.utcnow().isoformat()
    candidates: list[dict] = []

    # --- Loan payments (live + legacy) --------------------------------
    live_resp = (
        supabase.table("loan_payments")
        .select("id,loan_id,amount_paid,penalties,payment_date,payment_reference,confirmation_status")
        .lte("payment_date", now_iso)
        .order("payment_date", desc=True)
        .limit(limit)
        .execute()
    )
    for row in live_resp.data or []:
        penalties = decimal_to_float(row.get("penalties") or 0)
        confirmation = str(row.get("confirmation_status") or "").strip().lower()
        candidates.append({
            "type": "loan_payment",
            "id": row.get("payment_reference") or f"PMT-{row.get('id')}",
            "loan_id": str(row.get("loan_id") or ""),
            "date": row.get("payment_date"),
            "amount": decimal_to_float(row.get("amount_paid") or 0),
            "status": "Pending" if "pending" in confirmation else ("Late" if penalties > 0 else "Approved"),
        })
    legacy_resp = (
        supabase.table("loan_payments_legacy")
        .select("id,loan_id,amount_paid,payment_date,payment_code,or_cdv_no")
        .lte("payment_date", now_iso)
        .order("payment_date", desc=True)
        .limit(limit)
        .execute()
    )
    for row in legacy_resp.data or []:
        candidates.append({
            "type": "loan_payment",
            "id": row.get("payment_code") or row.get("or_cdv_no") or f"PMT-{row.get('id')}",
            "loan_id": str(row.get("loan_id") or ""),
            "date": row.get("payment_date"),
            "amount": decimal_to_float(row.get("amount_paid") or 0),
            "status": "Approved",
        })

    # --- Loan applications ---------------------------------------------
    apps_resp = (
        supabase.table("loans")
        .select("control_number,loan_amount,application_date,loan_status")
        .not_.is_("application_date", "null")
        .lte("application_date", now_iso)
        .order("application_date", desc=True)
        .limit(limit)
        .execute()
    )
    for row in apps_resp.data or []:
        candidates.append({
            "type": "loan_application",
            "id": row.get("control_number"),
            "loan_id": str(row.get("control_number") or ""),
            "date": row.get("application_date"),
            "amount": decimal_to_float(row.get("loan_amount") or 0),
            "status": str(row.get("loan_status") or "pending"),
        })

    # --- Savings deposits / withdrawals ---------------------------------
    savings_resp = (
        supabase.table("savings_ledger")
        .select("id,account_number,entry_type,amount,posted_at")
        .lte("posted_at", now_iso)
        .order("posted_at", desc=True)
        .limit(limit)
        .execute()
    )
    for row in savings_resp.data or []:
        is_withdrawal = str(row.get("entry_type") or "").strip().lower() == "debit"
        candidates.append({
            "type": "withdrawal" if is_withdrawal else "deposit",
            "id": f"SAV-{row.get('id')}",
            "account_number": row.get("account_number"),
            "date": row.get("posted_at"),
            "amount": decimal_to_float(row.get("amount") or 0),
            "status": "Approved",
        })

    # --- Membership fee payments -----------------------------------------
    fees_resp = (
        supabase.table("membership_payments")
        .select("payment_id,membership_number_id,amount,payment_date,payment_status")
        .lte("payment_date", now_iso)
        .order("payment_date", desc=True)
        .limit(limit)
        .execute()
    )
    for row in fees_resp.data or []:
        candidates.append({
            "type": "fee",
            "id": row.get("payment_id"),
            "membership_id": row.get("membership_number_id"),
            "date": row.get("payment_date"),
            "amount": decimal_to_float(row.get("amount") or 0),
            "status": str(row.get("payment_status") or "pending"),
        })

    # --- Grocery transactions --------------------------------------------
    grocery_resp = (
        supabase.table("GROCERY_TRANSACTIONS")
        .select("GroceryID,membership_number_id,TransactionDate,GroceryAmount,Status")
        .lte("TransactionDate", now_iso)
        .order("TransactionDate", desc=True)
        .limit(limit)
        .execute()
    )
    for row in grocery_resp.data or []:
        candidates.append({
            "type": "grocery",
            "id": row.get("GroceryID"),
            "member_uuid": row.get("membership_number_id"),
            "date": row.get("TransactionDate"),
            "amount": decimal_to_float(row.get("GroceryAmount") or 0),
            "status": str(row.get("Status") or "pending"),
        })

    def _sort_key(item: dict):
        return parse_date_value(item.get("date")) or date.min

    candidates.sort(key=_sort_key, reverse=True)
    top = candidates[:limit]
    if not top:
        return []

    # --- Resolve member names + membership_id (for the modal's "View
    #     Member Profile" link) for the top rows only ------------------------
    loan_ids = sorted({item["loan_id"] for item in top if item.get("loan_id")})
    member_by_loan: dict[str, dict] = {}
    if loan_ids:
        loans_resp = (
            supabase.table("loans")
            .select("control_number,member:member_id(first_name,last_name,membership_id)")
            .in_("control_number", loan_ids)
            .execute()
        )
        for row in loans_resp.data or []:
            member_by_loan[str(row.get("control_number") or "")] = row.get("member") or {}

    account_numbers = sorted({item["account_number"] for item in top if item.get("account_number")})
    member_by_account: dict[str, dict] = {}
    if account_numbers:
        accounts_resp = (
            supabase.table("savings_accounts")
            .select("account_number,member:member_id(first_name,last_name,membership_id)")
            .in_("account_number", account_numbers)
            .execute()
        )
        for row in accounts_resp.data or []:
            member_by_account[str(row.get("account_number") or "")] = row.get("member") or {}

    membership_ids = sorted({item["membership_id"] for item in top if item.get("membership_id")})
    member_by_membership_id: dict[str, dict] = {}
    if membership_ids:
        member_resp = (
            supabase.table("member")
            .select("membership_id,first_name,last_name")
            .in_("membership_id", membership_ids)
            .execute()
        )
        for row in member_resp.data or []:
            member_by_membership_id[str(row.get("membership_id") or "")] = row

    member_uuids = sorted({item["member_uuid"] for item in top if item.get("member_uuid")})
    member_by_uuid: dict[str, dict] = {}
    if member_uuids:
        member_resp = (
            supabase.table("member")
            .select("id,first_name,last_name,membership_id")
            .in_("id", member_uuids)
            .execute()
        )
        for row in member_resp.data or []:
            member_by_uuid[str(row.get("id") or "")] = row

    def _full_name(row: dict | None) -> str:
        row = row or {}
        return f"{row.get('first_name') or ''} {row.get('last_name') or ''}".strip() or "Member"

    results = []
    for item in top:
        member_row = None
        if item.get("loan_id"):
            member_row = member_by_loan.get(item["loan_id"])
        elif item.get("account_number"):
            member_row = member_by_account.get(item["account_number"])
        elif item.get("membership_id"):
            member_row = member_by_membership_id.get(item["membership_id"])
        elif item.get("member_uuid"):
            member_row = member_by_uuid.get(item["member_uuid"])

        results.append({
            "type": item["type"],
            "id": item.get("id"),
            "loan_id": item.get("loan_id"),
            "member_name": _full_name(member_row),
            "membership_id": (member_row or {}).get("membership_id") or item.get("membership_id"),
            "amount": item.get("amount"),
            "date": item.get("date"),
            "status": item.get("status"),
        })
    return results


def _compute_credit_risk_snapshot() -> dict:
    """Band counts + top-3 high-risk applicants for the dashboard snippet.

    Reads from risk_assessments (already-scored loans) joined against the
    current in-review queue, instead of re-running feature assembly +
    prediction. The full-detail Credit Risk page has its own score cache-through;
    this snapshot only needs counts, not drivers or explanations.
    """
    try:
        loans_resp = (
            supabase.table("loans")
            .select(
                "control_number,member_id,loan_amount,principal_amount,application_status,loan_status,"
                "member:member_id(first_name,last_name),loan_type:loan_type_id(code,name)"
            )
            .in_("application_status", sorted(_CREDIT_RISK_QUEUE_STATUSES))
            .execute()
        )
        review_loans = loans_resp.data or []
        # application_status may be null on some rows with only loan_status
        # set — same fallback the full queue endpoint uses.
        fallback_resp = (
            supabase.table("loans")
            .select(
                "control_number,member_id,loan_amount,principal_amount,application_status,loan_status,"
                "member:member_id(first_name,last_name),loan_type:loan_type_id(code,name)"
            )
            .is_("application_status", "null")
            .in_("loan_status", sorted(_CREDIT_RISK_QUEUE_STATUSES))
            .execute()
        )
        seen = {str(r.get("control_number")) for r in review_loans}
        for row in fallback_resp.data or []:
            if str(row.get("control_number")) not in seen:
                review_loans.append(row)
    except Exception:
        return {"total": 0, "queue_total": 0, "high": 0, "watch": 0, "low": 0, "top_high": [], "model_version": None}

    control_numbers = [str(l.get("control_number")) for l in review_loans if l.get("control_number")]
    scored_by_loan: dict[str, dict] = {}
    if control_numbers:
        assessments_resp = (
            supabase.table("risk_assessments")
            .select("loan_control_number,risk_probability,model_version,scored_at")
            .in_("loan_control_number", control_numbers)
            .execute()
        )
        for row in assessments_resp.data or []:
            scored_by_loan[str(row.get("loan_control_number"))] = row

    try:
        thr = risk_thresholds()
        current_model_version = risk_model_version()
    except ModelNotAvailableError:
        thr = None
        current_model_version = None

    high, watch, low = [], [], []
    model_version_seen = None
    for loan in review_loans:
        cn = str(loan.get("control_number") or "")
        assessment = scored_by_loan.get(cn)
        if not assessment or thr is None:
            continue
        probability = float(assessment.get("risk_probability") or 0.0)
        current_band = risk_band(probability, thr)
        model_version_seen = model_version_seen or assessment.get("model_version") or current_model_version
        member = loan.get("member") or {}
        loan_type = (loan.get("loan_type") or {}).get("name") or (loan.get("loan_type") or {}).get("code") or "N/A"
        row_out = {
            "loan_id": cn,
            "member_name": f"{member.get('first_name') or ''} {member.get('last_name') or ''}".strip() or "Unknown",
            "loan_type": loan_type,
            "loan_amount": decimal_to_float(loan.get("loan_amount") or loan.get("principal_amount") or 0),
            "probability": probability,
        }
        if current_band == "RED":
            high.append(row_out)
        elif current_band == "AMBER":
            watch.append(row_out)
        else:
            low.append(row_out)

    top_high = sorted(high, key=lambda r: r["probability"], reverse=True)[:3]
    scored_total = len(high) + len(watch) + len(low)

    return {
        "total": scored_total,
        "queue_total": len(review_loans),
        "high": len(high),
        "watch": len(watch),
        "low": len(low),
        "top_high": top_high,
        "model_version": model_version_seen,
    }


def _fetch_all_paginated(table_name: str, columns: str, order_col: str) -> list[dict]:
    """Page through a whole table 1000 rows at a time (Supabase's page cap).
    Used only for the two narrow columns each of these tables needs — never
    the wide selects manage-loans does — but the underlying tables (6k+ rows)
    still require pagination to read in full.
    """
    rows: list[dict] = []
    page = 1000
    offset = 0
    while True:
        batch = (
            supabase.table(table_name)
            .select(columns)
            .order(order_col)
            .range(offset, offset + page - 1)
            .execute()
        ).data or []
        if not batch:
            break
        rows.extend(batch)
        if len(batch) < page:
            break
        offset += page
    return rows


def _compute_payment_charts() -> tuple[list[dict], dict[str, list[dict]]]:
    """Yearly Collections totals + Collection Performance (expected/collected/
    outstanding) buckets, for every year the cooperative has data — same
    population the dashboard's yearlyBarData/monthlyBehaviorData use today,
    but built from three narrow selects (payment amount/date, schedule due
    date/amount/status) instead of the full manage-loans response with its
    member/loan_type joins and payment_history assembly.
    """
    live_payments = _fetch_all_paginated(
        "loan_payments", "loan_id,amount_paid,payment_date", "payment_date"
    )
    legacy_payments = _fetch_all_paginated(
        "loan_payments_legacy", "loan_id,amount_paid,payment_date", "payment_date"
    )
    schedules = _fetch_all_paginated(
        "loan_schedules", "loan_id,due_date,expected_amount,schedule_status", "due_date"
    )

    # --- Yearly Collections ---------------------------------------------
    totals_by_year: dict[str, Decimal] = {}
    for row in live_payments:
        year = str(row.get("payment_date") or "")[:4]
        if len(year) == 4:
            totals_by_year[year] = totals_by_year.get(year, Decimal("0")) + Decimal(str(row.get("amount_paid") or 0))
    for row in legacy_payments:
        year = str(row.get("payment_date") or "")[:4]
        if len(year) == 4:
            totals_by_year[year] = totals_by_year.get(year, Decimal("0")) + Decimal(str(row.get("amount_paid") or 0))

    yearly_collections = [
        {"year": year, "total": decimal_to_float(total)}
        for year, total in sorted(totals_by_year.items(), key=lambda kv: int(kv[0]))
    ]

    # --- Collection Performance (expected vs. collected, by due month) --
    # What a bookkeeper actually needs: how much was DUE in a given month
    # (sum of loan_schedules.expected_amount for rows due that month) versus
    # how much of that is actually COLLECTED (schedule_status = 'paid') and
    # how much is still OUTSTANDING (unpaid/partially_paid/overdue rows whose
    # due date has already passed — not a future installment that simply
    # hasn't come due yet). This reuses the schedule rows' own status, the
    # same field the penalty engine and Cashier already treat as ground
    # truth, instead of re-deriving "late" by guessing which payment paired
    # with which due date. Months after today are never included, so an
    # incomplete or future period can't render as a real performance figure.
    today_for_charts = date.today()
    behavior_by_year: dict[str, list[dict]] = {}

    def _bucket_for(year: str) -> list[dict]:
        if year not in behavior_by_year:
            behavior_by_year[year] = [
                {"month": m, "expected": 0.0, "collected": 0.0, "outstanding": 0.0, "overdue_count": 0}
                for m in range(1, 13)
            ]
        return behavior_by_year[year]

    for row in schedules:
        due_on = parse_date_value(row.get("due_date"))
        if not due_on or due_on > today_for_charts:
            continue
        amount = float(row.get("expected_amount") or 0)
        status = str(row.get("schedule_status") or "").strip().lower()
        bucket = _bucket_for(str(due_on.year))[due_on.month - 1]
        bucket["expected"] += amount
        if status == "paid":
            bucket["collected"] += amount
        else:
            bucket["outstanding"] += amount
            if status in ("overdue", "unpaid", "partially_paid", "pending"):
                bucket["overdue_count"] += 1

    for year, months in behavior_by_year.items():
        for m in months:
            m["expected"] = round(m["expected"], 2)
            m["collected"] = round(m["collected"], 2)
            m["outstanding"] = round(m["outstanding"], 2)

    return yearly_collections, behavior_by_year


@app.get("/api/bod/member-loan-summary")
async def get_bod_member_loan_summary():
    """Per-member {activeCount, paidCount} only — for BOD Manage Member, which
    previously fetched the FULL manage-loans payload (payment_history,
    schedules, member/loan_type joins — ~15s cold) just to derive these two
    counts per row. Reuses get_bookkeeper_manage_loans()'s own cached payload
    (its repayment-status logic is the single source of truth for "active" vs
    "paid" — not reimplemented here) and returns only the narrow map the UI
    actually renders.
    """
    manage_loans_payload = await get_bookkeeper_manage_loans()
    loan_rows = (manage_loans_payload.get("data") or {}).get("rows") or []

    summary: dict[str, dict] = {}
    for loan in loan_rows:
        membership_id = str(loan.get("membership_id") or "").strip()
        if not membership_id:
            continue
        entry = summary.setdefault(membership_id, {"active_count": 0, "paid_count": 0})
        status = str(loan.get("status") or "").strip().lower()
        if status == "fully paid":
            entry["paid_count"] += 1
        else:
            entry["active_count"] += 1

    return {"success": True, "data": summary}


@app.get("/api/bod/terminated-members")
async def get_bod_terminated_members():
    """Per-membership_id termination info — for BOD Manage Member, which needs
    to know which personal_data_sheet rows belong to terminated members so it
    can split them into a separate table instead of mixing them into the
    active member list. member_status is the authoritative flag (see
    /api/admin/member/terminate and the staff-termination-decision flow),
    kept on the `member` table, not on personal_data_sheet.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        response = (
            supabase.table("member")
            .select("membership_id,termination_date,termination_resolution_number")
            .in_("member_status", ["terminated", "closed"])
            .execute()
        )
        rows = response.data or []
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load terminated members: {err}")

    summary: dict[str, dict] = {}
    for row in rows:
        membership_id = str(row.get("membership_id") or "").strip()
        if not membership_id:
            continue
        summary[membership_id] = {
            "termination_date": row.get("termination_date"),
            "termination_resolution_number": row.get("termination_resolution_number"),
        }

    return {"success": True, "data": summary}


@app.get("/api/bookkeeper/loan-ledger/{loan_id}")
async def get_bookkeeper_loan_ledger(loan_id: str):
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    clean_loan_id = str(loan_id or "").strip()
    if not clean_loan_id:
        raise HTTPException(status_code=400, detail="loan_id is required.")

    # Query only the single loan directly — avoids loading all 700+ loans.
    try:
        loan_resp = (
            supabase.table("loans")
            .select(
                "control_number,member_id,loan_amount,principal_amount,interest_rate,term,loan_status,application_status,monthly_amortization,total_interest,application_date,application_type,"
                "member:member_id(membership_id,first_name,last_name,is_bona_fide),loan_type:loan_type_id(code,name,interest_rate)"
            )
            .eq("control_number", clean_loan_id)
            .limit(1)
            .execute()
        )
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to fetch loan: {e}")

    row = (loan_resp.data or [None])[0]
    if not row:
        # Non-member Bonus loans (non_member_loans) are built by manage-loans.
        listing = await get_bookkeeper_manage_loans()
        for r in ((listing or {}).get("data") or {}).get("rows") or []:
            if r.get("is_nonmember") and r.get("loan_id") == clean_loan_id:
                return {"success": True, "data": r}
        raise HTTPException(status_code=404, detail="Loan ledger not found.")

    # Fetch live payments for this loan.
    try:
        pay_resp = (
            supabase.table("loan_payments")
            .select("id,loan_id,schedule_id,amount_paid,penalties,payment_date,confirmation_status,payment_reference,transaction_reference,applied_to_current,applied_to_credit")
            .eq("loan_id", clean_loan_id)
            .order("payment_date")
            .execute()
        )
        payment_rows = pay_resp.data or []
    except Exception:
        payment_rows = []

    # Fetch legacy payments for this loan.
    try:
        leg_resp = (
            supabase.table("loan_payments_legacy")
            .select("id,loan_id,amount_paid,payment_date,payment_code,or_cdv_no,is_overpayment")
            .eq("loan_id", clean_loan_id)
            .order("payment_date")
            .execute()
        )
        for legacy in (leg_resp.data or []):
            payment_rows.append({
                "id": legacy.get("id"),
                "loan_id": legacy.get("loan_id"),
                "amount_paid": legacy.get("amount_paid"),
                "penalties": 0,
                "payment_date": legacy.get("payment_date"),
                "confirmation_status": "validated",
                "payment_reference": legacy.get("payment_code") or legacy.get("or_cdv_no"),
                "transaction_reference": legacy.get("or_cdv_no") or legacy.get("payment_code"),
                "_is_legacy": True,
            })
        payment_rows.sort(key=lambda p: str(p.get("payment_date") or ""))
    except Exception:
        pass

    # Fetch schedules for this loan.
    try:
        sched_resp = (
            supabase.table("loan_schedules")
            .select("id,loan_id,schedule_id,due_date,schedule_status,expected_amount,expected_interest,interest_component,installment_no")
            .eq("loan_id", clean_loan_id)
            .order("due_date")
            .execute()
        )
        schedule_rows = sched_resp.data or []
    except Exception:
        schedule_rows = []

    # Map using same logic as manage-loans.
    member = row.get("member") or {}
    member_name = f"{member.get('first_name') or ''} {member.get('last_name') or ''}".strip() or "Unknown Member"
    member_type = "Member"
    membership_id = str(member.get("membership_id") or "").strip()

    loan_type = row.get("loan_type") or {}
    loan_type_name = loan_type.get("name") or "N/A"
    loan_type_code = str(loan_type.get("code") or normalize_cashier_loan_type(loan_type_name)).upper()

    principal_amount = Decimal(str(row.get("principal_amount") or row.get("loan_amount") or 0))
    total_interest_amount = Decimal(str(row.get("total_interest") or 0))
    if total_interest_amount <= 0:
        term_months_val = int(row.get("term") or 0)
        monthly_amort_val = Decimal(str(row.get("monthly_amortization") or 0))
        if term_months_val > 0 and monthly_amort_val > 0:
            if "bonus" in loan_type_code.lower():
                total_interest_amount = max(monthly_amort_val - principal_amount, Decimal("0"))
            else:
                total_interest_amount = max(monthly_amort_val * term_months_val - principal_amount, Decimal("0"))
    total_payable_amount = principal_amount + total_interest_amount

    _due_dates = []
    for _s in schedule_rows:
        d = parse_date_value(_s.get("due_date"))
        if d:
            _due_dates.append(d)
    _due_dates.sort()

    schedule_by_id = {s.get("id"): s for s in schedule_rows if s.get("id")}

    total_validated = Decimal("0")
    cumulative_principal_paid = Decimal("0")
    payment_history = []
    for payment in payment_rows:
        amount_paid = Decimal(str(payment.get("amount_paid") or 0))
        if is_validated_payment_status(payment.get("confirmation_status")):
            total_validated += amount_paid
            # Same rule as member_statement_of_account_view_v3: an overpayment
            # (applied_to_credit) is a straight principal prepayment, not
            # interest -- only applied_to_current (capped at the installment's
            # own due) carries that installment's interest share. Rows with no
            # allocation on file (legacy, or pre-migration) fall back to
            # treating the whole payment by the loan-wide interest ratio.
            applied_current = payment.get("applied_to_current")
            applied_credit = payment.get("applied_to_credit")
            has_allocation = applied_current is not None or applied_credit is not None
            if has_allocation:
                applied_current = Decimal(str(applied_current or 0))
                applied_credit = Decimal(str(applied_credit or 0))
                sched = schedule_by_id.get(payment.get("schedule_id")) or {}
                expected_amount = Decimal(str(sched.get("expected_amount") or 0))
                expected_interest = Decimal(str(sched.get("expected_interest") or sched.get("interest_component") or 0))
                interest_share = (expected_interest / expected_amount) if expected_amount > 0 else (
                    total_interest_amount / total_payable_amount if total_payable_amount > 0 else Decimal("0")
                )
                interest_part = money(applied_current * interest_share)
                principal_part = (applied_current - interest_part) + applied_credit
            else:
                interest_share = total_interest_amount / total_payable_amount if total_payable_amount > 0 else Decimal("0")
                interest_part = money(amount_paid * interest_share)
                principal_part = amount_paid - interest_part
            cumulative_principal_paid += principal_part
        running_remaining = max(total_payable_amount - total_validated, Decimal("0"))

        days_offset = None
        _paid_on = parse_date_value(payment.get("payment_date"))
        if _paid_on and _due_dates:
            nearest = min(_due_dates, key=lambda d: abs((_paid_on - d).days))
            days_offset = (_paid_on - nearest).days

        payment_history.append({
            "payment_id": payment.get("payment_reference") or payment.get("id"),
            "date_paid": payment.get("payment_date"),
            "reference_no": payment.get("transaction_reference") or payment.get("payment_reference") or payment.get("id"),
            "amount_paid": decimal_to_float(amount_paid),
            "penalties": decimal_to_float(payment.get("penalties") or 0),
            "remaining_after": decimal_to_float(running_remaining),
            "confirmation_status": payment.get("confirmation_status") or "pending_bookkeeper",
            "days_offset": days_offset,
            "schedule_id": payment.get("schedule_id"),
        })

    remaining_balance = max(total_payable_amount - total_validated, Decimal("0"))
    if _ledger_says_fully_paid(row):
        remaining_balance = Decimal("0")
    # remaining_balance stays principal+interest (same definition used by the
    # payment approval path), but the ledger also shows how much principal is
    # left so a payment larger than one installment doesn't read as if the
    # balance barely moved. Uses the actual per-payment allocation
    # (applied_to_current/applied_to_credit) computed above, not a naive
    # interest-first waterfall on the total payable -- an overpayment that
    # exceeds the loan's remaining lifetime interest would otherwise still
    # show zero principal paid.
    outstanding_principal = max(principal_amount - cumulative_principal_paid, Decimal("0"))
    if remaining_balance <= 0:
        repayment_status = "Fully Paid"
    elif total_validated > 0:
        repayment_status = "Partially Paid"
    else:
        repayment_status = "Unpaid"

    # The installment open now. Missed months closed by the roll-forward are
    # 'partially_paid' and must not be reported as the due date.
    active_due = next(
        (
            s for s in schedule_rows
            if str(s.get("schedule_status") or "").strip().lower() in OPEN_SCHEDULE_STATUSES
        ),
        None,
    )
    if not active_due:
        for schedule in schedule_rows:
            status = str(schedule.get("schedule_status") or "").strip().lower()
            if status not in {"paid", "validated", "cancelled"}:
                active_due = schedule
                break
    if not active_due and schedule_rows:
        active_due = schedule_rows[-1]

    due_date = active_due.get("due_date") if active_due else None

    if active_due and not payment_history:
        payment_history.append({
            "payment_id": f"SCHED-{clean_loan_id}-{active_due.get('installment_no')}",
            "date_paid": active_due.get("due_date"),
            "reference_no": f"Installment #{active_due.get('installment_no')}",
            "amount_paid": decimal_to_float(active_due.get("expected_amount") or 0),
            "penalties": 0.0,
            "remaining_after": decimal_to_float(remaining_balance),
            "confirmation_status": "upcoming",
        })

    is_legacy = any(
        str(s.get("schedule_id") or "").startswith("LEGACY_")
        for s in schedule_rows
    )

    result = {
        "loan_id": clean_loan_id,
        "membership_id": membership_id,
        "member_name": member_name,
        "member_type": member_type,
        "loan_type": loan_type_name,
        "loan_type_code": loan_type_code,
        "loan_amount": decimal_to_float(principal_amount),
        "interest_rate": BONUS_MONTHLY_RATE_MEMBER if loan_type_code == "BONUS" else sanitize_monthly_rate_percent(
            row.get("interest_rate"),
            (row.get("loan_type") or {}).get("interest_rate"),
        ),
        "term_months": int(row.get("term") or 0),
        "amortization": decimal_to_float(row.get("monthly_amortization") or 0),
        "remaining_balance": decimal_to_float(remaining_balance),
        "outstanding_principal": decimal_to_float(outstanding_principal),
        "total_payable": decimal_to_float(total_payable_amount),
        "total_interest": decimal_to_float(total_interest_amount),
        "due_date": due_date,
        "status": repayment_status,
        "source_loan_status": row.get("loan_status"),
        "source_application_status": row.get("application_status"),
        "application_date": row.get("application_date"),
        "application_type": str(row.get("application_type") or "new").strip().lower(),
        "payment_history": payment_history,
        "is_legacy": is_legacy,
    }

    return {"success": True, "data": result}


class LoanRestructureRequest(BaseModel):
    new_term_months: int = Field(..., gt=0, description="New repayment term in months")


class RestructureRequestSubmit(BaseModel):
    new_term_months: int = Field(..., gt=0)
    new_amortization: float = Field(..., gt=0)
    requested_by: str | None = None
    note: str | None = None


class RestructureRequestAction(BaseModel):
    action: str = Field(..., pattern="^(approved|rejected)$")
    reviewed_by: str | None = None


def _ensure_restructure_requests_table():
    """Create loan_restructure_requests table if it doesn't exist."""
    if not supabase:
        return
    try:
        supabase.table("loan_restructure_requests").select("id").limit(1).execute()
    except Exception:
        pass


@app.post("/api/bookkeeper/loan-ledger/{loan_id}/restructure-request")
async def submit_restructure_request(loan_id: str, body: RestructureRequestSubmit):
    """Bookkeeper submits a restructure request for Manager approval."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not initialized.")
    clean_id = str(loan_id or "").strip()
    if not clean_id:
        raise HTTPException(status_code=400, detail="loan_id is required.")

    # Cancel any existing pending request for this loan first
    supabase.table("loan_restructure_requests") \
        .update({"status": "cancelled"}) \
        .eq("loan_id", clean_id) \
        .eq("status", "pending") \
        .execute()

    insert_resp = supabase.table("loan_restructure_requests").insert({
        "loan_id": clean_id,
        "new_term_months": body.new_term_months,
        "new_amortization": body.new_amortization,
        "requested_by": body.requested_by or "Bookkeeper",
        "note": body.note or "",
        "status": "pending",
    }).execute()

    if not insert_resp.data:
        raise HTTPException(status_code=500, detail="Failed to save restructure request.")

    return {"success": True, "request_id": insert_resp.data[0].get("id")}


@app.get("/api/manager/restructure-requests")
async def get_restructure_requests(status: str = "pending"):
    """Manager fetches restructure requests filtered by status."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not initialized.")
    resp = supabase.table("loan_restructure_requests") \
        .select("*") \
        .eq("status", status) \
        .order("created_at", desc=True) \
        .execute()
    return {"success": True, "data": resp.data or []}


@app.get("/api/manager/restructure-requests/{loan_id}")
async def get_restructure_request_for_loan(loan_id: str):
    """Get the latest pending restructure request for a specific loan."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not initialized.")
    clean_id = str(loan_id or "").strip()
    resp = supabase.table("loan_restructure_requests") \
        .select("*") \
        .eq("loan_id", clean_id) \
        .eq("status", "pending") \
        .order("created_at", desc=True) \
        .limit(1) \
        .execute()
    data = (resp.data or [None])[0]
    return {"success": True, "data": data}


@app.patch("/api/manager/restructure-requests/{request_id}/review")
async def review_restructure_request(request_id: int, body: RestructureRequestAction):
    """Manager approves or rejects a restructure request."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not initialized.")

    req_resp = supabase.table("loan_restructure_requests") \
        .select("*") \
        .eq("id", request_id) \
        .eq("status", "pending") \
        .limit(1) \
        .execute()
    req = (req_resp.data or [None])[0]
    if not req:
        raise HTTPException(status_code=404, detail="Pending request not found.")

    # Mark the request as approved or rejected
    supabase.table("loan_restructure_requests") \
        .update({"status": body.action, "reviewed_by": body.reviewed_by or "Manager"}) \
        .eq("id", request_id) \
        .execute()

    if body.action == "approved":
        # Apply the restructure to the actual loan
        loan_id = req["loan_id"]
        new_term = req["new_term_months"]
        new_amort = req["new_amortization"]
        update_resp = supabase.table("loans").update({
            "term": new_term,
            "monthly_amortization": float(new_amort),
        }).eq("control_number", loan_id).execute()
        if not update_resp.data:
            raise HTTPException(status_code=500, detail="Failed to apply restructure to loan.")
        return {
            "success": True,
            "action": "approved",
            "loan_id": loan_id,
            "new_term_months": new_term,
            "new_amortization": new_amort,
        }

    return {"success": True, "action": "rejected"}


@app.patch("/api/bookkeeper/loan-ledger/{loan_id}/restructure")
async def restructure_loan_term(loan_id: str, body: LoanRestructureRequest):
    """
    Updates the loan's term and recomputes monthly_amortization from the
    current remaining_balance, interest_rate, and loan type.

    Consolidated — add-on interest:  amort = remaining × (1 + rate × new_term) / new_term
    Emergency    — diminishing:      amort = first-month total under equal-principal schedule
    Bonus / KOICA — add-on (same as consolidated formula)
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    clean_id = str(loan_id or "").strip()
    if not clean_id:
        raise HTTPException(status_code=400, detail="loan_id is required.")

    new_term = body.new_term_months

    # Fetch the live loan row directly.
    loan_resp = (
        supabase.table("loans")
        .select("control_number,principal_amount,loan_amount,interest_rate,term,loan_status,loan_type:loan_type_id(code,interest_rate)")
        .eq("control_number", clean_id)
        .limit(1)
        .execute()
    )
    loan_row = (loan_resp.data or [None])[0]
    if not loan_row:
        raise HTTPException(status_code=404, detail=f"Loan {clean_id} not found.")

    loan_status = str(loan_row.get("loan_status") or "").lower()
    if loan_status in ("fully paid", "completed", "closed"):
        raise HTTPException(status_code=400, detail="Cannot restructure a fully paid or closed loan.")

    # Renewal recomputes amortization on the original principal, not the remaining balance.
    principal = Decimal(str(loan_row.get("principal_amount") or loan_row.get("loan_amount") or 0))
    if principal <= 0:
        raise HTTPException(status_code=400, detail="Loan principal is missing or invalid.")

    loan_type_row = loan_row.get("loan_type") or {}
    # Use sanitize_monthly_rate_percent to handle legacy rows where interest_rate
    # was stored as a corrupted value (e.g. 83 instead of 0.83).
    rate_percent = Decimal(str(sanitize_monthly_rate_percent(
        loan_row.get("interest_rate"),
        loan_type_row.get("interest_rate"),
    )))
    monthly_rate = rate_percent / Decimal("100")

    loan_type_code = str(loan_type_row.get("code") or "").lower()

    if loan_type_code == "emergency":
        # Equal-principal, diminishing-interest schedule.
        principal_component = money(principal / Decimal(new_term))
        ending_balance = principal - principal_component
        first_month_interest = money(ending_balance * monthly_rate)
        new_amortization = money(principal_component + first_month_interest)
    else:
        # Add-on interest (consolidated, bonus, KOICA/ABF).
        total_payable = principal * (1 + monthly_rate * Decimal(new_term))
        new_amortization = money(total_payable / Decimal(new_term))

    update_resp = (
        supabase.table("loans")
        .update({
            "term": new_term,
            "monthly_amortization": float(new_amortization),
        })
        .eq("control_number", clean_id)
        .execute()
    )

    if not update_resp.data:
        raise HTTPException(status_code=500, detail="Database update failed — no rows affected.")

    return {
        "success": True,
        "loan_id": clean_id,
        "new_term_months": new_term,
        "new_amortization": float(new_amortization),
    }


# ============================================================================
# SECTION: Member Lifecycle
# Aggregated view of a member's full lifecycle (membership, loans, savings,
# CBU history) for member profile pages.
# ============================================================================

@app.get("/api/member/lifecycle/{member_id}")
async def get_member_lifecycle(member_id: str, request: Request):
    global supabase
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        clean_member_id = str(member_id or "").strip()
        if not clean_member_id:
            raise HTTPException(status_code=400, detail="member_id is required.")

        member_response = (
            supabase.table("member")
            .select("*")
            .eq("id", clean_member_id)
            .limit(1)
            .execute()
        )
        member_row = (member_response.data or [None])[0]
        if not member_row:
            raise HTTPException(status_code=404, detail="Member not found.")

        account_email = ""
        for account_table in ["member_account", "member_accounts"]:
            try:
                account_response = (
                    supabase.table(account_table)
                    .select("email")
                    .eq("user_id", clean_member_id)
                    .limit(1)
                    .execute()
                )
                account_row = (account_response.data or [None])[0]
                if account_row and account_row.get("email"):
                    account_email = str(account_row.get("email") or "").strip()
                    break
            except Exception:
                continue

        application_row = None
        membership_id = str(member_row.get("membership_id") or "").strip()
        if membership_id:
            try:
                app_by_membership = (
                    supabase.table("member_applications")
                    .select("*")
                    .eq("membership_id", membership_id)
                    .order("created_at", desc=True)
                    .limit(1)
                    .execute()
                )
                application_row = (app_by_membership.data or [None])[0]
            except Exception:
                application_row = None

        if not application_row and account_email:
            try:
                app_by_email = (
                    supabase.table("member_applications")
                    .select("*")
                    .ilike("email", account_email)
                    .order("created_at", desc=True)
                    .limit(1)
                    .execute()
                )
                application_row = (app_by_email.data or [None])[0]
            except Exception:
                application_row = None

        full_name = " ".join(
            part for part in [
                application_row.get("first_name") if application_row else None,
                application_row.get("middle_name") if application_row else None,
                (application_row.get("surname") if application_row else None)
                or (application_row.get("last_name") if application_row else None)
                or member_row.get("last_name"),
            ] if part
        ).strip()

        profile_payload = {
            "full_name": full_name or "N/A",
            "member_id": member_row.get("membership_id") or "N/A",
            "email": (application_row.get("email") if application_row else None) or account_email or "N/A",
            "mobile": (application_row.get("contact_number") if application_row else None) or "N/A",
            "civil_status": (application_row.get("civil_status") if application_row else None) or "N/A",
            "gender": (application_row.get("gender") if application_row else None) or "N/A",
            "employer": (application_row.get("employer_name") if application_row else None) or "N/A",
            "position": (application_row.get("position") if application_row else None) or (application_row.get("occupation") if application_row else None) or "N/A",
            "salary_grade": (application_row.get("salary_grade") if application_row else None) or "N/A",
            "address": (application_row.get("permanent_address") if application_row else None) or "N/A",
        }

        loans_response = (
            supabase.table("loans")
            .select(
                "control_number,loan_amount,principal_amount,interest_rate,monthly_amortization,total_interest,term,loan_status,application_status,application_type,application_date,disbursal_date," \
                f"{LOAN_FEE_SNAPSHOT_COLUMNS}," \
                "loan_type:loan_type_id(name,code,interest_rate)"
            )
            .eq("member_id", clean_member_id)
            .order("application_date", desc=True)
            .execute()
        )
        loan_rows = loans_response.data or []

        loan_ids = [str(row.get("control_number") or "").strip() for row in loan_rows if row.get("control_number")]

        schedules_by_loan: dict[str, list[dict]] = {}
        if loan_ids:
            try:
                schedules_response = (
                    supabase.table("loan_schedules")
                    .select("id,schedule_id,loan_id,installment_no,due_date,expected_amount,expected_principal,expected_interest,principal_component,interest_component,remaining_principal,schedule_status")
                    .in_("loan_id", loan_ids)
                    .order("due_date")
                    .execute()
                )
                for row in schedules_response.data or []:
                    schedules_by_loan.setdefault(str(row.get("loan_id") or ""), []).append(row)
            except Exception:
                schedules_by_loan = {}

        payment_rows = []
        if loan_ids:
            payments_response = (
                supabase.table("loan_payments")
                .select("id,payment_reference,loan_id,schedule_id,amount_paid,penalties,payment_date,confirmation_status,transaction_reference")
                .in_("loan_id", loan_ids)
                .order("payment_date", desc=True)
                .execute()
            )
            payment_rows = payments_response.data or []

            # Payments imported from the coop's pre-app records count as
            # validated, exactly as the Cashier's balance does.
            try:
                legacy_response = (
                    supabase.table("loan_payments_legacy")
                    .select("id,loan_id,amount_paid,payment_date,payment_code,or_cdv_no")
                    .in_("loan_id", loan_ids)
                    .execute()
                )
                for legacy in legacy_response.data or []:
                    payment_rows.append({
                        "id": legacy.get("id"),
                        "payment_reference": legacy.get("payment_code") or legacy.get("or_cdv_no"),
                        "transaction_reference": legacy.get("or_cdv_no") or legacy.get("payment_code"),
                        "loan_id": legacy.get("loan_id"),
                        "schedule_id": None,
                        "amount_paid": legacy.get("amount_paid"),
                        "penalties": 0,
                        "payment_date": legacy.get("payment_date"),
                        "confirmation_status": "validated",
                    })
            except Exception as legacy_err:
                logger.warning("member lifecycle legacy payment lookup failed: %s", legacy_err)
            payment_rows.sort(key=lambda p: str(p.get("payment_date") or ""), reverse=True)

        mapped_loans = []
        for row in loan_rows:
            loan_id = str(row.get("control_number") or "").strip()
            if not loan_id:
                continue

            ordered_schedules = sorted(
                schedules_by_loan.get(loan_id, []),
                key=lambda sched: str(sched.get("due_date") or ""),
            )

            mapped_schedules = [
                {
                    "schedule_id": sched.get("schedule_id") or sched.get("id"),
                    "installment_no": int(sched.get("installment_no") or 0),
                    "due_date": sched.get("due_date"),
                    "expected_amount": decimal_to_float(sched.get("expected_amount") or 0),
                    "expected_principal": decimal_to_float(sched.get("expected_principal") or sched.get("principal_component") or 0),
                    "expected_interest": decimal_to_float(sched.get("expected_interest") or sched.get("interest_component") or 0),
                    "remaining_principal": decimal_to_float(sched.get("remaining_principal") or 0),
                    "schedule_status": sched.get("schedule_status") or "unpaid",
                }
                for sched in ordered_schedules
            ]

            # Same figures the Cashier uses: _loan_total_payable for principal +
            # interest, validated live + legacy payments for the amount paid.
            principal_value = Decimal(str(row.get("principal_amount") or row.get("loan_amount") or 0))
            total_payable_value = _loan_total_payable(row)
            total_interest_value = total_payable_value - principal_value

            confirmed_paid_value = Decimal("0")
            for pay in payment_rows:
                if str(pay.get("loan_id") or "") != loan_id:
                    continue
                if is_validated_payment_status(pay.get("confirmation_status")):
                    confirmed_paid_value += Decimal(str(pay.get("amount_paid") or 0))
            remaining_balance_value = max(total_payable_value - confirmed_paid_value, Decimal("0"))

            is_fully_paid = str(row.get("loan_status") or "").strip().lower() == "fully paid" or (
                remaining_balance_value <= 0 and confirmed_paid_value > 0
            )
            next_due_schedule = None if is_fully_paid else next(
                (
                    sched
                    for sched in mapped_schedules
                    if str(sched.get("schedule_status") or "").strip().lower() in {"unpaid", "pending", "overdue", ""}
                ),
                None,
            )

            # Fees as the Cashier deducts them: saved on the loan at application,
            # else the current fee policy (older loans), via the same functions.
            stored_fees = _stored_fee_breakdown(row)
            fees = stored_fees or (
                _fee_breakdown_for_principal(
                    _resolve_loan_type_code_for_breakdown(row.get("loan_type") or {}), principal_value
                )
                if principal_value > 0 else None
            )
            fee_payload = None
            if fees:
                fee_payload = {k: decimal_to_float(fees[k]) for k in (*_FEE_KEYS, "total_deductions")}
                fee_payload["net_proceeds"] = decimal_to_float(money(principal_value - fees["total_deductions"]))
                fee_payload["saved_at_application"] = stored_fees is not None

            loan_type_row = row.get("loan_type") or {}
            interest_rate_percent = sanitize_monthly_rate_percent(
                row.get("interest_rate"), loan_type_row.get("interest_rate")
            )

            mapped_loans.append(
                {
                    "loan_id": loan_id,
                    "loan_type": (row.get("loan_type") or {}).get("name") or "N/A",
                    "principal": decimal_to_float(principal_value),
                    "total_interest": decimal_to_float(total_interest_value),
                    "total_payable": decimal_to_float(total_payable_value),
                    "amount_paid": decimal_to_float(confirmed_paid_value),
                    "remaining_balance": decimal_to_float(remaining_balance_value),
                    "monthly_amortization": decimal_to_float(row.get("monthly_amortization") or 0),
                    "interest_rate": interest_rate_percent or None,
                    "term": int(row.get("term") or 0),
                    "loan_status": row.get("loan_status") or "N/A",
                    "application_status": row.get("application_status") or "N/A",
                    "application_type": row.get("application_type"),
                    "application_date": row.get("application_date"),
                    "disbursal_date": row.get("disbursal_date"),
                    "fees": fee_payload,
                    "schedules": mapped_schedules,
                    "next_due_schedule": next_due_schedule,
                }
            )

        mapped_payments = [
            {
                "payment_id": row.get("payment_reference") or row.get("id"),
                "loan_id": row.get("loan_id"),
                "schedule_id": row.get("schedule_id"),
                "reference_no": row.get("transaction_reference") or row.get("payment_reference") or row.get("id"),
                "amount_paid": decimal_to_float(row.get("amount_paid") or 0),
                "penalties": decimal_to_float(row.get("penalties") or 0),
                "payment_date": row.get("payment_date"),
                "confirmation_status": row.get("confirmation_status") or "pending_bookkeeper",
            }
            for row in payment_rows
        ]

        return {
            "success": True,
            "data": {
                "server_time": datetime.utcnow().isoformat(),
                "profile": profile_payload,
                "loans": mapped_loans,
                "payments": mapped_payments,
            },
        }
    except HTTPException as err:
        raise err
    except Exception as err:
        error_text = str(err).lower()
        transient_socket_error = (
            "10035" in error_text
            or "non-blocking socket" in error_text
            or "server disconnected" in error_text
        )
        if transient_socket_error and url and key and not getattr(request.state, "lifecycle_retried", False):
            # Supabase's pooled HTTP client can retain a stale Windows socket.
            # Rebuild it once and retry the complete read-only lifecycle query.
            supabase = create_client(url, key, options=_SUPABASE_CLIENT_OPTIONS)
            request.state.lifecycle_retried = True
            return await get_member_lifecycle(member_id, request)
        raise HTTPException(status_code=500, detail=f"Failed to fetch member lifecycle: {err}")


# ============================================================================
# SECTION: Secretary — Membership Records & Personal Data Sheets
# Endpoints for listing/updating membership records and PDS entries used by the
# secretary/BOD portal.
# ============================================================================

@app.get("/api/secretary/membership-records")
async def get_secretary_membership_records():
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        # Narrow selects and bound the result count. Selecting * from member +
        # unbounded capital_build_up + * from personal_data_sheet can push
        # supabase-py past the HTTP2 stream limit, which surfaces as a client
        # `ConnectionTerminated` with no server-side traceback. Keeping the
        # payload small avoids that failure mode.
        members_response = (
            supabase.table("member")
            .select(
                "id,membership_id,first_name,middle_initial,last_name,"
                "membership_date,created_at,share_capital_amount,"
                "number_of_shares,initial_paid_up_capital,member_status"
            )
            .order("created_at", desc=True)
            .limit(2000)
            .execute()
        )
        member_rows = members_response.data or []

        cbu_response = (
            supabase.table("capital_build_up")
            .select("member_id,transaction_date,ending_share_capital")
            .order("transaction_date", desc=True)
            .limit(5000)
            .execute()
        )
        cbu_rows = cbu_response.data or []

        latest_cbu_by_member: dict[str, dict] = {}
        for cbu in cbu_rows:
            member_id = str(cbu.get("member_id") or "").strip()
            if member_id and member_id not in latest_cbu_by_member:
                latest_cbu_by_member[member_id] = cbu

        records = []
        seen_membership_numbers: set[str] = set()
        for row in member_rows:
            member_uuid = str(row.get("id") or "").strip()
            if not member_uuid:
                continue

            full_name = resolve_member_full_name(row)
            membership_number = row.get("membership_id") or member_uuid
            joined_value = row.get("membership_date") or row.get("created_at")

            cbu_row = latest_cbu_by_member.get(member_uuid)
            ending_capital = Decimal(str((cbu_row or {}).get("ending_share_capital") or 0))

            amount_value = row.get("share_capital_amount")
            if amount_value is None:
                amount_value = ending_capital

            shares_value = row.get("number_of_shares")
            if shares_value is None:
                shares_value = (Decimal(str(amount_value or 0)) / CBU_SHARE_VALUE) if amount_value else Decimal("0")

            paid_up_value = row.get("initial_paid_up_capital")
            if paid_up_value is None:
                paid_up_value = amount_value or Decimal("0")

            records.append(
                {
                    "member_uuid": member_uuid,
                    "applicant_id": membership_number,
                    "applicant_name": full_name,
                    "date_joined": joined_value,
                    "shares": decimal_to_float(shares_value),
                    "paid_up_capital": decimal_to_float(paid_up_value),
                    "member_status": str(row.get("member_status") or "active").strip().lower(),
                    "editable": False,
                    "edit_scope": "member",
                }
            )
            seen_membership_numbers.add(str(membership_number or "").strip())

        # Include personal_data_sheet records not yet present in member table.
        pds_columns = (
            "membership_number_id,first_name,middle_name,surname,"
            "date_of_membership,created_at,number_of_shares,"
            "initial_paid_up_capital,amount"
        )
        try:
            pds_rows = (
                supabase.table("personal_data_sheet")
                .select(pds_columns)
                .order("created_at", desc=True)
                .limit(2000)
                .execute()
            ).data or []
        except Exception:
            pds_rows = (
                supabase.table("personal_data_sheet")
                .select(pds_columns)
                .limit(2000)
                .execute()
            ).data or []

        for pds in pds_rows:
            membership_number = str(pds.get("membership_number_id") or "").strip()
            if not membership_number or membership_number in seen_membership_numbers:
                continue

            full_name = " ".join(
                part
                for part in [
                    str(pds.get("first_name") or "").strip(),
                    str(pds.get("middle_name") or "").strip(),
                    str(pds.get("surname") or "").strip(),
                ]
                if part
            ) or "Unknown Member"

            records.append(
                {
                    "member_uuid": membership_number,
                    "applicant_id": membership_number,
                    "applicant_name": full_name,
                    "date_joined": pds.get("date_of_membership") or pds.get("created_at") or "",
                    "shares": decimal_to_float(pds.get("number_of_shares") or 0),
                    "paid_up_capital": decimal_to_float(pds.get("initial_paid_up_capital") or pds.get("amount") or 0),
                    "editable": True,
                    "edit_scope": "personal_data_sheet",
                }
            )

        return {"success": True, "data": records}
    except Exception as err:
        import traceback
        traceback.print_exc()
        raise HTTPException(status_code=500, detail=f"Failed to load secretary membership records: {err}")


# =============================================================================
# Member clustering (Manage Members)
# =============================================================================
# Supabase holds more member records than the coop's current roster, for good
# reasons that are invisible from the row itself. Rather than hide the extras,
# Manage Members shows every record with a badge saying which group it belongs
# to. The groups are derived from evidence, not hand-maintained:
#
#   legacy_member       in Cleaned_Members.csv -- the migrated current roster.
#   recovered_borrower  owns loans imported from the coop's historical records
#                       but is absent from that CSV. Real members the source
#                       member list had lost; they must stay visible.
#   imported_member     provisioned by the bulk import (synthetic
#                       `ttmpc-NNN@ttmpc.local` address) with no legacy loan yet.
#   simulation_account  created through the app's own signup flow while building
#                       and demonstrating the system, not a real member.
#   system_placeholder  deliberate bucket for legacy loans whose borrower cannot
#                       be identified (e.g. "WITHDRAWN 11.26.2015").
#   orphan_pds          a personal_data_sheet row with no member record behind
#                       it -- left over from duplicate test applications.

MEMBER_CLUSTER_LEGACY = "legacy_member"
MEMBER_CLUSTER_RECOVERED = "recovered_borrower"
MEMBER_CLUSTER_IMPORTED = "imported_member"
MEMBER_CLUSTER_SIMULATION = "simulation_account"
MEMBER_CLUSTER_PLACEHOLDER = "system_placeholder"
MEMBER_CLUSTER_ORPHAN_PDS = "orphan_pds"

MEMBER_CLUSTER_LABELS = {
    MEMBER_CLUSTER_LEGACY: "Current member",
    MEMBER_CLUSTER_RECOVERED: "Recovered borrower",
    MEMBER_CLUSTER_IMPORTED: "Imported member",
    MEMBER_CLUSTER_SIMULATION: "Simulation account",
    MEMBER_CLUSTER_PLACEHOLDER: "System placeholder",
    MEMBER_CLUSTER_ORPHAN_PDS: "Orphan record",
}

# Members created through the app's membership-application flow while building
# and demoing the system. Held as a literal set so this never has to read
# member_applications, which carries staff email addresses.
_SIMULATION_MEMBERSHIP_IDS = {
    "TTMPC-265", "TTMPC-266", "TTMPC-267", "TTMPC-268", "TTMPC-269",
    "TTMPC-270", "TTMPC-271", "TTMPC-295", "TTMPC-296",
}

# Names that mark a bookkeeping placeholder rather than a person.
_PLACEHOLDER_NAME_MARKERS = ("HISTORICAL BORROWER", "UNKNOWN")

# Every bulk-imported member was provisioned an address on this domain.
_SYNTHETIC_EMAIL_DOMAIN = "@ttmpc.local"


# Inputs to _load_member_clusters (CSV roster, member names, legacy-loan
# borrower set) change only when membership/loans data changes, not on every
# page view — but the function was re-reading the CSV from disk and paging
# through the ENTIRE loans table's raw_payload on every single call to
# /api/personal_data_sheet, regardless of which membership_ids were asked
# for. That work is identical across requests (it always ends up scanning
# every loan), so it's cached here rather than parameterized per-request.
_MEMBER_CLUSTER_INPUTS_CACHE: dict = {"payload": None, "expires_at": 0.0}
_MEMBER_CLUSTER_INPUTS_CACHE_TTL_SECONDS = 300.0  # 5 min — clustering is a display label, not live data


def _load_member_cluster_inputs() -> tuple[set[str], dict[str, str], set[str]]:
    """(legacy_roster, member_names, borrowers_with_legacy_loans) — cached.

    Falls back to a usable answer rather than raising: clustering is a display
    aid, and a failure here must not take down the member list.
    """
    import time as _time
    now = _time.monotonic()
    cached = _MEMBER_CLUSTER_INPUTS_CACHE
    if cached["payload"] is not None and cached["expires_at"] > now:
        return cached["payload"]

    legacy_roster = {
        (row.get("MemberID") or "").strip()
        for row in _read_csv_resilient(_CLEANED_MEMBERS)
        if (row.get("MemberID") or "").strip()
    }

    # Members carrying at least one loan imported from the historical records.
    borrowers_with_legacy_loans: set[str] = set()
    member_names: dict[str, str] = {}
    try:
        member_rows = (
            supabase.table("member")
            .select("id, membership_id, last_name, first_name")
            .execute()
        ).data or []
        membership_by_uuid = {}
        for row in member_rows:
            mid = str(row.get("membership_id") or "").strip()
            membership_by_uuid[row.get("id")] = mid
            member_names[mid] = (
                f"{row.get('last_name') or ''} {row.get('first_name') or ''}".upper()
            )

        # Only member_id + a boolean flag inside raw_payload are needed here —
        # raw_payload can't be narrowed further in a Postgrest select (it's a
        # single jsonb column), so this still pulls the whole column, but at
        # least it's paid once per TTL window instead of once per page view.
        offset = 0
        while True:
            batch = (
                supabase.table("loans")
                .select("member_id, raw_payload")
                .range(offset, offset + 999)
                .execute()
            ).data or []
            for loan in batch:
                payload = loan.get("raw_payload") or {}
                if isinstance(payload, dict) and str(payload.get("legacy", "")).lower() == "true":
                    mid = membership_by_uuid.get(loan.get("member_id"))
                    if mid:
                        borrowers_with_legacy_loans.add(mid)
            if len(batch) < 1000:
                break
            offset += 1000
    except Exception:
        # Without loan data we can still separate roster from non-roster.
        pass

    result = (legacy_roster, member_names, borrowers_with_legacy_loans)
    _MEMBER_CLUSTER_INPUTS_CACHE["payload"] = result
    _MEMBER_CLUSTER_INPUTS_CACHE["expires_at"] = _time.monotonic() + _MEMBER_CLUSTER_INPUTS_CACHE_TTL_SECONDS
    return result


def _load_member_clusters(membership_ids: list[str]) -> dict[str, str]:
    """Map membership_id -> cluster key for the given ids."""
    if not membership_ids:
        return {}

    legacy_roster, member_names, borrowers_with_legacy_loans = _load_member_cluster_inputs()

    clusters: dict[str, str] = {}
    for membership_id in membership_ids:
        name = member_names.get(membership_id, "")
        if member_names and membership_id not in member_names:
            # A datasheet with no member record behind it. Checked first: some
            # of these are also test applications, but "no member record" is
            # the more useful thing to show.
            clusters[membership_id] = MEMBER_CLUSTER_ORPHAN_PDS
        elif membership_id in _SIMULATION_MEMBERSHIP_IDS:
            clusters[membership_id] = MEMBER_CLUSTER_SIMULATION
        elif any(marker in name for marker in _PLACEHOLDER_NAME_MARKERS):
            clusters[membership_id] = MEMBER_CLUSTER_PLACEHOLDER
        elif membership_id in legacy_roster:
            clusters[membership_id] = MEMBER_CLUSTER_LEGACY
        elif membership_id in borrowers_with_legacy_loans:
            clusters[membership_id] = MEMBER_CLUSTER_RECOVERED
        else:
            clusters[membership_id] = MEMBER_CLUSTER_IMPORTED

    return clusters


# 90s cache — same rationale as manage-loans/dashboard-summary. This endpoint
# previously took 1.8-3.2s on EVERY call (uncached CSV read + full loans-table
# scan inside _load_member_clusters, run fresh per request); caching the
# response itself means only the first viewer in a 90s window pays that cost.
_PERSONAL_DATA_SHEET_CACHE: dict = {"payload": None, "expires_at": 0.0}
_PERSONAL_DATA_SHEET_CACHE_TTL_SECONDS = 90.0


@app.get("/api/personal_data_sheet")
async def get_personal_datasheet_records():
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    import time as _time
    now = _time.monotonic()
    cached = _PERSONAL_DATA_SHEET_CACHE
    if cached["payload"] is not None and cached["expires_at"] > now:
        return cached["payload"]

    try:
        rows = []
        try:
            response = (
                supabase.table("personal_data_sheet")
                .select("*")
                .order("created_at", desc=True)
                .execute()
            )
            rows = response.data or []
        except Exception:
            response = (
                supabase.table("personal_data_sheet")
                .select("*")
                .execute()
            )
            rows = response.data or []

        membership_ids = sorted(
            {
                str(row.get("membership_number_id") or "").strip()
                for row in rows
                if str(row.get("membership_number_id") or "").strip()
            }
        )

        email_by_membership: dict[str, str] = {}
        if membership_ids:
            try:
                apps_response = (
                    supabase.table("member_applications")
                    .select("membership_id,email,created_at")
                    .in_("membership_id", membership_ids)
                    .order("created_at", desc=True)
                    .execute()
                )
                for app_row in apps_response.data or []:
                    membership_id = str(app_row.get("membership_id") or "").strip()
                    email_value = str(app_row.get("email") or "").strip()
                    if membership_id and email_value and membership_id not in email_by_membership:
                        email_by_membership[membership_id] = email_value
            except Exception:
                email_by_membership = {}

        # Final fallback: member_account.email. For migrated members who never
        # had a PDS email or an application row (the 22 TTMPC-272..293 batch),
        # the placeholder `ttmpc-XXX@ttmpc.local` lives only in member_account.
        if membership_ids:
            try:
                account_response = (
                    supabase.table("member_account")
                    .select("membership_id,email")
                    .in_("membership_id", membership_ids)
                    .execute()
                )
                for acc_row in account_response.data or []:
                    membership_id = str(acc_row.get("membership_id") or "").strip()
                    email_value = str(acc_row.get("email") or "").strip()
                    if membership_id and email_value and membership_id not in email_by_membership:
                        email_by_membership[membership_id] = email_value
            except Exception:
                pass

        cluster_by_membership = _load_member_clusters(membership_ids)

        normalized = []
        for idx, row in enumerate(rows, start=1):
            first = row.get("first_name") or ""
            middle = row.get("middle_name") or row.get("middle_initial") or ""
            last = row.get("last_name") or row.get("surname") or ""
            full_name = " ".join(part for part in [str(first).strip(), str(middle).strip(), str(last).strip()] if part)

            membership_id = str(row.get("membership_number_id") or "").strip()
            email_value = str(row.get("email") or "").strip() or email_by_membership.get(membership_id, "")
            contact_number = row.get("contact_number") or row.get("mobile_number") or ""
            address_value = row.get("permanent_address") or row.get("address") or ""

            cluster = cluster_by_membership.get(membership_id, MEMBER_CLUSTER_ORPHAN_PDS)

            normalized.append(
                {
                    "id": row.get("personal_data_sheet_id") or row.get("id") or idx,
                    "member_id": membership_id,
                    "full_name": full_name,
                    "email": email_value,
                    "contact_number": contact_number,
                    "address": address_value,
                    "permanent_address": row.get("permanent_address") or "",
                    # Net take-home pay -- shown only to Bookkeeper/BOD roster
                    # pages (Simulation findings #30); frontend decides who
                    # actually renders the column.
                    "net_take_home_pay": row.get("salary"),
                    "created_at": row.get("created_at"),
                    "cluster": cluster,
                    "cluster_label": MEMBER_CLUSTER_LABELS.get(cluster, cluster),
                    "raw": row,
                }
            )

        payload = {"success": True, "data": normalized}
        _PERSONAL_DATA_SHEET_CACHE["payload"] = payload
        _PERSONAL_DATA_SHEET_CACHE["expires_at"] = _time.monotonic() + _PERSONAL_DATA_SHEET_CACHE_TTL_SECONDS
        return payload
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load personal datasheet records: {err}")


@app.get("/api/personal_data_sheet/{membership_number_id}")
async def get_personal_datasheet_record_by_membership(membership_number_id: str):
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        clean_membership_id = str(membership_number_id or "").strip()
        if not clean_membership_id:
            raise HTTPException(status_code=400, detail="membership_number_id is required.")

        response = (
            supabase.table("personal_data_sheet")
            .select("*")
            .eq("membership_number_id", clean_membership_id)
            .limit(1)
            .execute()
        )

        row = (response.data or [None])[0]
        if not row:
            raise HTTPException(
                status_code=404,
                detail={
                    "message": "Personal data sheet record not found.",
                    "next_action": "Create a PDS for this member via the BOD membership confirmation flow, or manually insert a record with membership_number_id matching the member's membership_id.",
                    "membership_number_id": clean_membership_id,
                },
            )

        try:
            app_response = (
                supabase.table("member_applications")
                .select("membership_id,email")
                .eq("membership_id", clean_membership_id)
                .order("created_at", desc=True)
                .limit(1)
                .execute()
            )
            app_row = (app_response.data or [None])[0]
            if app_row and not str(row.get("email") or "").strip():
                row["email"] = str(app_row.get("email") or "").strip()
        except Exception:
            pass

        # Flag missing email so the frontend can prompt for follow-up.
        email_value = str(row.get("email") or "").strip()
        row["email_incomplete"] = not email_value

        # Flag membership_id mismatch between PDS record and the member table.
        membership_id_mismatch = False
        try:
            member_check = (
                supabase.table("member")
                .select("membership_id")
                .eq("membership_id", clean_membership_id)
                .limit(1)
                .execute()
            )
            if not member_check.data:
                membership_id_mismatch = True
        except Exception:
            pass
        row["membership_id_mismatch"] = membership_id_mismatch

        return {"success": True, "data": row}
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load personal data sheet details: {err}")


def _require_member_record_viewer(current_user: dict) -> None:
    """Manager, Bookkeeper and BOD all open the shared member record page
    (member_details.jsx). Role comes from the verified JWT via
    _resolve_staff_role, never from the URL."""
    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role not in ("manager", "bookkeeper", "bod"):
        raise HTTPException(status_code=403, detail="Only the Manager, Bookkeeper or BOD can view this member record.")


# ---------------------------------------------------------------------------
# Member record: financial summary (read-only)
#
# Feeds the tabs on the shared member record page (Bookkeeper, Manager and BOD
# open the same page). One call returns share capital, savings, time deposits,
# grocery, income and classification points for one member. Staff only: the
# caller's role comes from the verified JWT via _require_member_record_viewer,
# never from the URL. Each section is fetched on its own so one failing table
# leaves the rest of the page intact; failures are listed in "errors".
# ---------------------------------------------------------------------------
@app.get("/api/members/{membership_id}/financial-summary")
def get_member_financial_summary(membership_id: str, current_user: dict = _Depends(_get_current_user)):
    _require_member_record_viewer(current_user)
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    key = str(membership_id or "").strip()
    if not key:
        raise HTTPException(status_code=400, detail="membership_id is required.")

    member_rows = (
        supabase.table("member")
        .select("id,membership_id,member_status,membership_date,share_capital_amount,number_of_shares")
        .eq("membership_id", key)
        .limit(1)
        .execute()
        .data
        or []
    )
    if not member_rows:
        raise HTTPException(status_code=404, detail="Member not found.")
    member = member_rows[0]
    mid = member["id"]

    errors: list[str] = []

    def section(name: str, fn, default):
        try:
            return fn()
        except Exception as exc:  # noqa: BLE001
            logger.warning("[member financial summary] %s failed: %s", name, exc)
            errors.append(name)
            return default

    def _capital():
        rows = (
            supabase.table("capital_build_up")
            .select("transaction_date,capital_added,ending_share_capital,deposit_account,cbu_deposit_id")
            .eq("member_id", mid)
            .lte("transaction_date", _cooperative_today().isoformat())
            .order("transaction_date", desc=True)
            .limit(25)
            .execute()
            .data
            or []
        )
        return rows

    def _savings():
        accounts = (
            supabase.table("savings_accounts")
            .select("account_number,account_name,account_kind,balance,status")
            .eq("member_id", mid)
            .order("account_number")
            .execute()
            .data
            or []
        )
        numbers = [a["account_number"] for a in accounts if a.get("account_number")]
        ledger: list[dict] = []
        if numbers:
            ledger = (
                supabase.table("savings_ledger")
                .select("account_number,entry_type,amount,running_balance,posted_at,remarks")
                .in_("account_number", numbers)
                .order("posted_at", desc=True)
                .limit(25)
                .execute()
                .data
                or []
            )
        return {"accounts": accounts, "ledger": ledger}

    def _time_deposits():
        return (
            supabase.table("time_deposits")
            .select("certificate_number,placement_date,maturity_date,principal,term_days,annual_rate,expected_interest,expected_maturity_value,status")
            .eq("member_id", mid)
            .order("placement_date", desc=True)
            .limit(25)
            .execute()
            .data
            or []
        )

    def _grocery():
        now_iso = datetime.now(timezone.utc).isoformat()
        rows = (
            supabase.table("GROCERY_TRANSACTIONS")
            .select("TransactionDate,GroceryAmount,Status,balance_due")
            .eq("membership_number_id", mid)
            .lte("TransactionDate", now_iso)
            .order("TransactionDate", desc=True)
            .limit(25)
            .execute()
            .data
            or []
        )
        totals = (
            supabase.table("member_grocery_totals")
            .select("total_grocery_amount,transaction_count,last_transaction_at")
            .eq("membership_number_id", mid)
            .limit(1)
            .execute()
            .data
            or [None]
        )[0]
        return {"totals": totals, "recent": rows}

    def _income():
        profile = (
            supabase.table("member_profile")
            .select("latest_net_pay,net_income,employment_status,years_in_service,housing_status,civil_status")
            .eq("membership_number_id", mid)
            .limit(1)
            .execute()
            .data
            or [None]
        )[0]
        pds = (
            supabase.table("personal_data_sheet")
            .select("employer_name,salary,annual_income,other_income,income_source,number_of_dependents,DependentCount,spouse_name,spouse_occupation,gsis_number")
            .eq("membership_number_id", key)
            .limit(1)
            .execute()
            .data
            or [None]
        )[0]
        return {"profile": profile, "pds": pds}

    def _classification():
        return (
            supabase.table("member_classification_temporal")
            .select("accrual_date,cbu_points,loan_points,savings_points,payment_points,grocery_points,pli_points,attendance_points,total_score,final_status")
            .eq("membership_number_id", mid)
            .order("accrual_date", desc=True)
            .limit(1)
            .execute()
            .data
            or [None]
        )[0]

    return {
        "success": True,
        "data": {
            "member": member,
            "capital": section("capital", _capital, []),
            "savings": section("savings", _savings, {"accounts": [], "ledger": []}),
            "time_deposits": section("time_deposits", _time_deposits, []),
            "grocery": section("grocery", _grocery, {"totals": None, "recent": []}),
            "income": section("income", _income, {"profile": None, "pds": None}),
            "classification": section("classification", _classification, None),
            "errors": errors,
        },
    }


# ============================================================================
# SECTION: Savings — Transactions, Accounts, Deposits & Withdrawals
# General savings endpoints plus cashier-specific savings deposit/withdraw
# operations, account listing, and ledger retrieval.
