@app.get("/api/member/time-deposits")
def list_member_time_deposits(current_user: dict = _Depends(_get_current_user)):
    """Return only the authenticated member's TD contracts and placement ledger."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    account = _get_member_account_by_auth_user(current_user["id"])
    member_id = str((account or {}).get("user_id") or "").strip()
    if not member_id:
        raise HTTPException(status_code=403, detail="No member profile is linked to this account.")
    _sync_time_deposit_maturities()
    try:
        placements = (
            supabase.table("time_deposits")
            .select(
                "id,certificate_number,placement_date,maturity_date,principal,term_days,"
                "annual_rate,rate_bracket_min,rate_bracket_max,rate_bracket_label,"
                "expected_interest,expected_maturity_value,status,created_at,settled_at"
            )
            .eq("member_id", member_id)
            .order("maturity_date")
            .execute()
            .data or []
        )
        ids = [row["id"] for row in placements]
        ledger = []
        if ids:
            ledger = (
                supabase.table("time_deposit_ledger")
                .select("id,time_deposit_id,entry_type,amount,reference,posted_at")
                .in_("time_deposit_id", ids)
                .order("posted_at", desc=True)
                .execute()
                .data or []
            )
        return {"success": True, "data": {"placements": placements, "ledger": ledger}}
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load member Time Deposits: {err}")


@app.get("/api/savings/accounts")
async def list_savings_accounts(
    kind: str | None = None,
    status: str | None = None,
    search: str | None = None,
):
    """List all savings accounts from the new canonical table.

    Query params:
      - kind:   'member' | 'standalone'
      - status: 'active' | 'closed' | 'frozen'
      - search: matches account_number, account_name (case-insensitive)
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        query = (
            supabase.table("savings_accounts")
            .select("account_number,account_name,member_id,account_kind,balance,status,legacy_savings_id,created_at,updated_at")
            .order("account_name")
        )
        if kind:
            query = query.eq("account_kind", kind)
        if status:
            query = query.eq("status", status)
        rows = (query.execute().data or [])

        if search:
            term = search.strip().lower()
            rows = [
                r for r in rows
                if term in str(r.get("account_number", "")).lower()
                or term in str(r.get("account_name", "")).lower()
            ]

        # Enrich with membership_id when account is linked to a member.
        member_ids = sorted({r["member_id"] for r in rows if r.get("member_id")})
        member_lookup: dict[str, dict] = {}
        if member_ids:
            try:
                member_rows = (
                    supabase.table("member")
                    .select("id,membership_id,first_name,last_name")
                    .in_("id", member_ids)
                    .execute()
                ).data or []
                for m in member_rows:
                    member_lookup[m["id"]] = m
            except Exception:
                pass

        for r in rows:
            m = member_lookup.get(r.get("member_id"))
            r["membership_id"] = m.get("membership_id") if m else None

        return {"success": True, "data": rows, "count": len(rows)}
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to list savings accounts: {err}")


@app.get("/api/savings/accounts/{account_param}")
async def get_savings_account(account_param: str):
    """Fetch one savings account with the most recent ledger entries.

    `account_param` may be a SA-NNNNNN number OR a legacy Savings_ID.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    account_number = _resolve_account_number_from_param(account_param)
    if not account_number:
        raise HTTPException(status_code=404, detail="Savings account not found.")

    try:
        acc_response = (
            supabase.table("savings_accounts")
            .select("*")
            .eq("account_number", account_number)
            .limit(1)
            .execute()
        )
        account = (acc_response.data or [None])[0]
        if not account:
            raise HTTPException(status_code=404, detail="Savings account not found.")

        ledger_response = (
            supabase.table("savings_ledger")
            .select("*")
            .eq("account_number", account_number)
            .order("posted_at", desc=True)
            .limit(10)
            .execute()
        )
        ledger = ledger_response.data or []

        member: dict | None = None
        if account.get("member_id"):
            try:
                member_response = (
                    supabase.table("member")
                    .select("id,membership_id,first_name,last_name,middle_name,is_bona_fide")
                    .eq("id", account["member_id"])
                    .limit(1)
                    .execute()
                )
                member = (member_response.data or [None])[0]
            except Exception:
                member = None

        return {
            "success": True,
            "data": {
                "account": account,
                "member": member,
                "recent_ledger": ledger,
            },
        }
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to fetch savings account: {err}")


@app.get("/api/savings/accounts/{account_param}/ledger")
async def get_savings_account_ledger(
    account_param: str,
    limit: int = 100,
    offset: int = 0,
):
    """Paginated debit/credit history for one account, newest first."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    account_number = _resolve_account_number_from_param(account_param)
    if not account_number:
        raise HTTPException(status_code=404, detail="Savings account not found.")

    safe_limit = max(1, min(int(limit or 100), 500))
    safe_offset = max(0, int(offset or 0))

    try:
        response = (
            supabase.table("savings_ledger")
            .select("*")
            .eq("account_number", account_number)
            .order("posted_at", desc=True)
            .range(safe_offset, safe_offset + safe_limit - 1)
            .execute()
        )
        return {
            "success": True,
            "data": response.data or [],
            "limit": safe_limit,
            "offset": safe_offset,
        }
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to fetch ledger: {err}")


def _require_savings_cashier(current_user: dict | None) -> None:
    """Deposits and withdrawal requests on a savings account are the Cashier's.
    The Bookkeeper verifies withdrawals, so letting the same person request one
    would remove the second pair of eyes."""
    if not current_user or not current_user.get("id"):
        raise HTTPException(status_code=401, detail="Sign in to record savings transactions.")
    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role != "cashier":
        raise HTTPException(status_code=403, detail="Only the Cashier can record savings deposits and withdrawal requests.")


@app.post("/api/savings/accounts/{account_number}/deposit")
async def post_savings_account_deposit(
    account_number: str,
    payload: CashierSavingsDepositRequest,
    current_user: dict | None = _Depends(_get_current_user_optional),
):
    """New-table-native deposit. Writes savings_ledger credit (trigger updates
    savings_accounts.balance) and mirrors to legacy Savings_Transactions when
    a legacy_savings_id bridge exists."""
    _require_savings_cashier(current_user)
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    account_number = str(account_number or "").strip()
    if not account_number:
        raise HTTPException(status_code=400, detail="account_number is required.")

    try:
        account_response = (
            supabase.table("savings_accounts")
            .select("account_number,account_name,member_id,balance,status,legacy_savings_id")
            .eq("account_number", account_number)
            .limit(1)
            .execute()
        )
        account = (account_response.data or [None])[0]
        if not account:
            raise HTTPException(status_code=404, detail="Savings account not found.")
        if account.get("status") != "active":
            raise HTTPException(status_code=400, detail=f"Account is {account.get('status')}; deposits not allowed.")

        if account.get("member_id"):
            try:
                member_response = (
                    supabase.table("member")
                    .select("id,is_bona_fide")
                    .eq("id", account["member_id"])
                    .limit(1)
                    .execute()
                )
                member_row = (member_response.data or [None])[0]
                if member_row and member_row.get("is_bona_fide") is False:
                    raise HTTPException(status_code=400, detail="Member is not bonafide and cannot transact.")
            except HTTPException as err:
                raise err
            except Exception:
                pass

        amount = money(Decimal(str(payload.amount or 0)))
        if amount <= 0:
            raise HTTPException(status_code=400, detail="Deposit amount must be greater than zero.")

        transaction_id = get_next_savings_cashier_transaction_id()
        posted_at_value = datetime.utcnow().isoformat()

        # Queue row (validated immediately since cashier-posted deposit).
        try:
            supabase.table("savings_transaction_queue").insert({
                "transaction_id": transaction_id,
                "savings_id": account.get("legacy_savings_id") or account_number,
                "account_number": account_number,
                "member_name": account.get("account_name"),
                "account_type": "Savings Deposit",
                "transaction_type": "deposit",
                "amount": decimal_to_float(amount),
                "transaction_status": "validated",
                "entered_by_role": "cashier",
                "requested_at": posted_at_value,
                "verified_at": posted_at_value,
                "verified_by": "system",
                "posted_at": posted_at_value,
                "notes": "Cashier deposit (auto-posted)",
            }).execute()
        except Exception as exc:  # noqa: BLE001
            print(f"[deposit] queue insert failed: {exc}")

        # Canonical write: ledger credit. Trigger updates savings_accounts.balance.
        try:
            _ledger_insert = _insert_with_optional("savings_ledger", {
                "account_number": account_number,
                "entry_type": "credit",
                "amount": decimal_to_float(amount),
                "reference": transaction_id,
                "source": "cashier_deposit",
                "remarks": "Cashier deposit",
                "posted_by": "cashier",
            }, {"recorded_by": (current_user or {}).get("id")})
            _ledger_row = (_ledger_insert.data or [None])[0]
            if _ledger_row and _ledger_row.get("id"):
                _correct_audit_actor("savings", str(_ledger_row["id"]), current_user)
        except Exception as exc:  # noqa: BLE001
            raise HTTPException(status_code=500, detail=f"Failed to post ledger credit: {exc}")

        # Mirror to legacy Savings_Transactions if bridge exists.
        legacy_id = account.get("legacy_savings_id")
        if legacy_id:
            try:
                legacy_response = (
                    supabase.table("Savings_Transactions")
                    .select("Balance,Savings_Amount,Amount")
                    .eq("Savings_ID", legacy_id)
                    .limit(1)
                    .execute()
                )
                legacy_row = (legacy_response.data or [None])[0]
                if legacy_row:
                    current = Decimal(str(
                        legacy_row.get("Balance")
                        if legacy_row.get("Balance") is not None
                        else (legacy_row.get("Savings_Amount") or legacy_row.get("Amount") or 0)
                    ))
                    new_legacy = int(money(current + amount).to_integral_value(rounding=ROUND_HALF_UP))
                    supabase.table("Savings_Transactions").update({
                        "Balance": new_legacy,
                        "Amount": new_legacy,
                    }).eq("Savings_ID", legacy_id).execute()
            except Exception as exc:  # noqa: BLE001
                print(f"[deposit] legacy mirror skipped: {exc}")

        # Re-read account to return the trigger-updated balance.
        try:
            refreshed = (
                supabase.table("savings_accounts")
                .select("balance")
                .eq("account_number", account_number)
                .limit(1)
                .execute()
            )
            new_balance = (refreshed.data or [{"balance": 0}])[0].get("balance") or 0
        except Exception:
            new_balance = decimal_to_float(Decimal(str(account.get("balance") or 0)) + amount)

        return {
            "success": True,
            "message": "Deposit posted successfully.",
            "data": {
                "transaction_id": transaction_id,
                "account_number": account_number,
                "amount_deposited": decimal_to_float(amount),
                "new_balance": float(new_balance),
                "receipt_no": _receipt_no_for("savings", transaction_id),
            },
        }
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to post deposit: {err}")


@app.post("/api/savings/accounts/{account_number}/withdraw")
async def post_savings_account_withdraw(
    account_number: str,
    payload: CashierSavingsWithdrawRequest,
    current_user: dict | None = _Depends(_get_current_user_optional),
):
    """New-table-native withdrawal request. Inserts a pending_verification queue
    row only; no balance change until Bookkeeper confirms."""
    _require_savings_cashier(current_user)
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    account_number = str(account_number or "").strip()
    if not account_number:
        raise HTTPException(status_code=400, detail="account_number is required.")

    try:
        account_response = (
            supabase.table("savings_accounts")
            .select("account_number,account_name,member_id,balance,status,legacy_savings_id")
            .eq("account_number", account_number)
            .limit(1)
            .execute()
        )
        account = (account_response.data or [None])[0]
        if not account:
            raise HTTPException(status_code=404, detail="Savings account not found.")
        if account.get("status") != "active":
            raise HTTPException(status_code=400, detail=f"Account is {account.get('status')}; withdrawals not allowed.")

        if account.get("member_id"):
            try:
                member_response = (
                    supabase.table("member")
                    .select("id,is_bona_fide")
                    .eq("id", account["member_id"])
                    .limit(1)
                    .execute()
                )
                member_row = (member_response.data or [None])[0]
                if member_row and member_row.get("is_bona_fide") is False:
                    raise HTTPException(status_code=400, detail="Member is not bonafide and cannot transact.")
            except HTTPException as err:
                raise err
            except Exception:
                pass

        amount = money(Decimal(str(payload.amount or 0)))
        if amount <= 0:
            raise HTTPException(status_code=400, detail="Withdrawal amount must be greater than zero.")

        current_balance = Decimal(str(account.get("balance") or 0))
        if amount > current_balance:
            raise HTTPException(status_code=400, detail="Withdrawal exceeds available balance.")

        transaction_id = get_next_savings_cashier_transaction_id()
        try:
            queue_response = supabase.table("savings_transaction_queue").insert({
                "transaction_id": transaction_id,
                "savings_id": account.get("legacy_savings_id") or account_number,
                "account_number": account_number,
                "member_name": account.get("account_name"),
                "account_type": "Savings Withdrawal",
                "transaction_type": "withdraw",
                "amount": decimal_to_float(amount),
                "transaction_status": "pending_verification",
                "entered_by_role": "cashier",
                "requested_at": datetime.utcnow().isoformat(),
            }).execute()
            queued = (queue_response.data or [None])[0]
        except Exception as exc:  # noqa: BLE001
            raise HTTPException(status_code=500, detail=f"Failed to queue withdrawal: {exc}")

        _correct_audit_actor("withdrawal", transaction_id, current_user)

        return {
            "success": True,
            "message": "Withdrawal submitted; pending Bookkeeper verification.",
            "data": {
                "transaction_id": transaction_id,
                "account_number": account_number,
                "amount_requested": decimal_to_float(amount),
                "transaction_status": "pending_verification",
                "record": queued,
            },
        }
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to post withdrawal: {err}")


# ---------------------------------------------------------------------------
# Savings Interest v2 — quarterly, Actual/365, running-balance accrual.
# Confirmed cooperative rule (SAVINGS_INTEREST_V2_PLAN.md). Authoritative math
# lives in savings_interest_v2/ledger_engine.py (Decimal/ROUND_HALF_UP,
# unit-tested against the cooperative's reference dataset); this section only
# feeds it savings_ledger rows per account and persists results.
#
# Segregation of duties mirrors loan_renewal_override_requests: Bookkeeper
# posts, Manager reverses, never their own posting. Table is RLS-on with no
# client policies, so this goes through the service-role Supabase client only
# (schema: savings_interest_v2_schema.sql).
# ---------------------------------------------------------------------------
from savings_interest_v2.ledger_engine import (  # noqa: E402
    SavingsLedgerEngine,
    Transaction as _SavingsTxn,
    money as _savings_money,
    QUARTER_END_MONTHS_DAYS as _SAVINGS_QUARTER_END_MONTHS_DAYS,
)


def _require_manager(current_user: dict) -> None:
    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role != "manager":
        raise HTTPException(status_code=403, detail="Only the Manager can reverse a savings interest posting.")


def _require_savings_interest_viewer(current_user: dict, account_number: str | None = None) -> None:
    """Cashier sees the accrued-interest preview on their Savings Detail page
    (read-only); Bookkeeper sees it too, since they're the one who posts.
    A member may also preview the account's own interest — their Statement
    of Account's "Next Interest Posting" card calls this for their own
    account_number; previously it 403'd for every member (Simulation
    findings #23)."""
    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role in ("cashier", "bookkeeper"):
        return
    if account_number:
        try:
            owner_resp = (
                supabase.table("savings_accounts")
                .select("member_id")
                .eq("account_number", account_number)
                .limit(1)
                .execute()
            )
            owner_member_id = (owner_resp.data or [{}])[0].get("member_id")
            member_resp = (
                supabase.table("member_account")
                .select("user_id")
                .eq("auth_user_id", current_user["id"])
                .limit(1)
                .execute()
            )
            own_member_id = (member_resp.data or [{}])[0].get("user_id")
            if owner_member_id and own_member_id and str(owner_member_id) == str(own_member_id):
                return
        except Exception:
            pass
    raise HTTPException(status_code=403, detail="Only the Cashier, Bookkeeper, or the account's own member can view savings interest.")


def _savings_quarter_candidates(opening_date: date, limit: int = 8) -> list[date]:
    """Quarter-end dates strictly after opening_date, up to today, oldest first."""
    today = date.today()
    out: list[date] = []
    year = opening_date.year
    while len(out) < limit:
        for month, day in _SAVINGS_QUARTER_END_MONTHS_DAYS:
            candidate = date(year, month, day)
            if candidate > opening_date and candidate <= today:
                out.append(candidate)
        year += 1
        if year > today.year + 1:
            break
    out.sort()
    return out[:limit]


def _run_savings_ledger_engine(account_number: str, upto: date | None = None) -> tuple[SavingsLedgerEngine, list, date | None]:
    """Replays an account's savings_ledger (deposits/withdrawals only — prior
    'Int.' rows are skipped, since those are what this engine itself posted
    last time and replaying them would double-count) through the engine from
    account opening, posting every quarter-close up to `upto` (default: the
    latest quarter-end not already posted). Returns (engine, pending_quarters, last_posted_quarter).
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    account_resp = (
        supabase.table("savings_accounts")
        .select("account_number,balance,created_at,status")
        .eq("account_number", account_number)
        .limit(1)
        .execute()
    )
    account = (account_resp.data or [None])[0]
    if not account:
        raise HTTPException(status_code=404, detail="Savings account not found.")

    policy_resp = (
        supabase.table("deposit_interest_policies")
        .select("annual_rate,minimum_balance,crediting_frequency")
        .eq("product_code", "SAVINGS")
        .limit(1)
        .execute()
    )
    policy = (policy_resp.data or [None])[0] or {}
    annual_rate_pct = Decimal(str(policy.get("annual_rate") or "1.0"))
    minimum_balance = Decimal(str(policy["minimum_balance"])) if policy.get("minimum_balance") is not None else None

    last_batch_resp = (
        supabase.table("savings_interest_batches")
        .select("period_quarter,closing_balance")
        .eq("account_number", account_number)
        .eq("status", "posted")
        .order("period_quarter", desc=True)
        .limit(1)
        .execute()
    )
    last_batch = (last_batch_resp.data or [None])[0]

    created_at_raw = account.get("created_at")
    opening_date = (
        date.fromisoformat(str(last_batch["period_quarter"]))
        if last_batch
        else (date.fromisoformat(str(created_at_raw)[:10]) if created_at_raw else date.today())
    )
    opening_balance = _savings_money(Decimal(str(last_batch["closing_balance"]))) if last_batch else Decimal("0")

    ledger_resp = (
        supabase.table("savings_ledger")
        .select("entry_type,amount,posted_at,source")
        .eq("account_number", account_number)
        .neq("source", "savings_interest")
        .gt("posted_at", opening_date.isoformat())
        .order("posted_at")
        .execute()
    )
    ledger_rows = ledger_resp.data or []

    engine = SavingsLedgerEngine(
        opening_date=opening_date,
        opening_balance=opening_balance,
        minimum_balance=minimum_balance,
    )
    # Patch the module-level annual rate for this run — BOD-edited, not the
    # engine's hardcoded 1.00% default — without forking the tested engine.
    import savings_interest_v2.ledger_engine as _engine_mod
    _original_rate = _engine_mod.ANNUAL_RATE
    _engine_mod.ANNUAL_RATE = annual_rate_pct / Decimal("100")
    try:
        transactions = [
            _SavingsTxn(
                txn_date=date.fromisoformat(str(row["posted_at"])[:10]),
                code="CD" if row["entry_type"] == "credit" else "WD",
                amount=_savings_money(Decimal(str(row["amount"]))),
            )
            for row in ledger_rows
        ]

        all_quarters = _savings_quarter_candidates(opening_date)
        pending_quarters = [q for q in all_quarters if q <= (upto or date.today())]
        # run() interleaves transactions and quarter-closes in date order —
        # posting all transactions first (as a naive loop would) makes a
        # quarter-close whose date falls before a later transaction look like
        # it "precedes" the ledger, since the engine enforces date order.
        engine.run(transactions, pending_quarters)
    finally:
        _engine_mod.ANNUAL_RATE = _original_rate

    last_posted = date.fromisoformat(str(last_batch["period_quarter"])) if last_batch else None
    return engine, pending_quarters, last_posted


@app.get("/api/savings-interest/ledger/{account_number}")
async def get_savings_interest_passbook(
    account_number: str,
    current_user: dict | None = _Depends(_get_current_user_optional),
):
    """Full passbook breakdown (deposits/withdrawals/interest, running balance,
    accrued line interest) for the Cashier and Member passbook tables' Accrued
    Int. column + formula tooltip. Replays from account opening, not just the
    last posted quarter, so every historical row's accrued interest is shown."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    account_resp = (
        supabase.table("savings_accounts")
        .select("account_number,created_at")
        .eq("account_number", account_number)
        .limit(1)
        .execute()
    )
    account = (account_resp.data or [None])[0]
    if not account:
        raise HTTPException(status_code=404, detail="Savings account not found.")

    policy_resp = (
        supabase.table("deposit_interest_policies")
        .select("annual_rate,minimum_balance")
        .eq("product_code", "SAVINGS")
        .limit(1)
        .execute()
    )
    policy = (policy_resp.data or [None])[0] or {}
    annual_rate_pct = Decimal(str(policy.get("annual_rate") or "1.0"))
    minimum_balance = Decimal(str(policy["minimum_balance"])) if policy.get("minimum_balance") is not None else None

    created_at_raw = account.get("created_at")
    opening_date = date.fromisoformat(str(created_at_raw)[:10]) if created_at_raw else date.today()

    ledger_resp = (
        supabase.table("savings_ledger")
        .select("id,entry_type,amount,posted_at,source")
        .eq("account_number", account_number)
        .neq("source", "savings_interest")
        .order("posted_at")
        .execute()
    )
    ledger_rows = ledger_resp.data or []

    engine = SavingsLedgerEngine(
        opening_date=opening_date,
        opening_balance=Decimal("0"),
        minimum_balance=minimum_balance,
    )
    import savings_interest_v2.ledger_engine as _engine_mod
    _original_rate = _engine_mod.ANNUAL_RATE
    _engine_mod.ANNUAL_RATE = annual_rate_pct / Decimal("100")
    row_ids: list[str | None] = []
    try:
        all_quarters = _savings_quarter_candidates(opening_date)
        pending_quarters = [q for q in all_quarters if q <= date.today()]

        # Interleave transactions and quarter-closes in date order (same rule
        # as SavingsLedgerEngine.run()) while tracking each posted row's
        # savings_ledger id (quarter-closes have none — they're synthesized).
        events: list[tuple[date, int, dict | date]] = []
        for row in ledger_rows:
            events.append((date.fromisoformat(str(row["posted_at"])[:10]), 0, row))
        for q in pending_quarters:
            events.append((q, 1, q))  # quarter-close sorts after same-day transactions
        events.sort(key=lambda e: (e[0], e[1]))

        for txn_date, kind, payload in events:
            if kind == 0:
                code = "CD" if payload["entry_type"] == "credit" else "WD"
                engine.post_transaction(_SavingsTxn(txn_date=txn_date, code=code, amount=_savings_money(Decimal(str(payload["amount"])))))
                row_ids.append(payload.get("id"))
            else:
                engine.post_quarter_close(payload)
                row_ids.append(None)  # quarter-close rows have no savings_ledger id of their own yet
    finally:
        _engine_mod.ANNUAL_RATE = _original_rate

    passbook = []
    for ledger_entry_id, row in zip(row_ids, engine.rows):
        passbook.append({
            "id": ledger_entry_id,
            "date": row.date.isoformat(),
            "code": row.code,
            "withdrawal": decimal_to_float(row.withdrawal) if row.withdrawal is not None else None,
            "interest_posted": decimal_to_float(row.interest_posted) if row.interest_posted is not None else None,
            "deposit": decimal_to_float(row.deposit) if row.deposit is not None else None,
            "running_balance": decimal_to_float(row.total_balance),
            "accrued_line_interest": decimal_to_float(row.accrued_line_interest),
        })

    return {
        "success": True,
        "data": passbook,
        "interest_rate": decimal_to_float(annual_rate_pct) / 100,
    }


@app.get("/api/savings-interest/preview/{account_number}")
async def preview_savings_interest(
    account_number: str,
    current_user: dict = _Depends(_get_current_user),
):
    """Computes (without posting) the interest due for the next unposted
    quarter-close on this account. Used by the Bookkeeper's 'Post Quarterly
    Interest' confirmation modal, and by a member's own Statement of Account.
    Cashier and Bookkeeper can view any account (read-only) — only the
    Bookkeeper can actually post (see below); a member may view only their
    own account."""
    _require_savings_interest_viewer(current_user, account_number)

    engine, pending_quarters, _last_posted = _run_savings_ledger_engine(account_number)
    if not pending_quarters:
        return {"success": True, "data": None, "message": "No quarter-close is due for this account yet."}

    target_quarter = pending_quarters[-1]
    quarter_row = next((r for r in engine.rows if r.code == "Int." and r.date == target_quarter), None)
    if not quarter_row:
        raise HTTPException(status_code=500, detail="Interest engine did not produce a posting row for the target quarter.")

    return {
        "success": True,
        "data": {
            "account_number": account_number,
            "period_quarter": target_quarter.isoformat(),
            "interest_to_credit": decimal_to_float(quarter_row.interest_posted),
            "current_balance": decimal_to_float(engine.balance - quarter_row.interest_posted),
            "post_credit_balance": decimal_to_float(engine.balance),
        },
    }


@app.post("/api/savings-interest/post/{account_number}")
async def post_savings_interest(
    account_number: str,
    current_user: dict = _Depends(_get_current_user),
):
    """Posts the next unposted quarter-close's accrued interest as a
    savings_ledger credit (source='savings_interest') and records the batch.
    Bookkeeper-only, matching the actor restriction on every savings posting
    action."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_bookkeeper(current_user)

    engine, pending_quarters, _last_posted = _run_savings_ledger_engine(account_number)
    if not pending_quarters:
        raise HTTPException(status_code=409, detail="No quarter-close is due for this account yet.")

    target_quarter = pending_quarters[-1]
    quarter_row = next((r for r in engine.rows if r.code == "Int." and r.date == target_quarter), None)
    if not quarter_row or quarter_row.interest_posted <= 0:
        raise HTTPException(status_code=409, detail="Computed interest for this quarter is zero; nothing to post.")

    policy_resp = (
        supabase.table("deposit_interest_policies")
        .select("annual_rate")
        .eq("product_code", "SAVINGS")
        .limit(1)
        .execute()
    )
    annual_rate = (policy_resp.data or [{"annual_rate": 1.0}])[0].get("annual_rate") or 1.0

    try:
        ledger_insert = supabase.table("savings_ledger").insert({
            "account_number": account_number,
            "entry_type": "credit",
            "amount": decimal_to_float(quarter_row.interest_posted),
            "source": "savings_interest",
            "remarks": f"Quarterly interest — {target_quarter.isoformat()}",
            "posted_by": "bookkeeper",
            "posted_at": target_quarter.isoformat(),
        }).execute()
        ledger_row = (ledger_insert.data or [None])[0]
        if not ledger_row:
            raise HTTPException(status_code=500, detail="Ledger insert returned no row.")
    except HTTPException:
        raise
    except Exception as exc:  # noqa: BLE001
        raise HTTPException(status_code=500, detail=f"Failed to post interest credit: {exc}")

    try:
        batch_insert = supabase.table("savings_interest_batches").insert({
            "account_number": account_number,
            "period_quarter": target_quarter.isoformat(),
            "annual_rate": annual_rate,
            "opening_balance": decimal_to_float(engine.balance - quarter_row.interest_posted),
            "closing_balance": decimal_to_float(ledger_row.get("running_balance") or engine.balance),
            "interest_posted": decimal_to_float(quarter_row.interest_posted),
            "ledger_entry_id": ledger_row.get("id"),
            "posted_by_user_id": current_user["id"],
            "posted_by_email": current_user.get("email") or None,
        }).execute()
        batch_row = (batch_insert.data or [None])[0]
    except Exception as exc:  # noqa: BLE001
        # Ledger credit already landed (source of truth for the balance);
        # the batch row is bookkeeping on top, so surface but don't roll back.
        raise HTTPException(status_code=500, detail=f"Interest credited, but failed to record the batch: {exc}")

    return {
        "success": True,
        "message": f"Posted {decimal_to_float(quarter_row.interest_posted)} interest for {target_quarter.isoformat()}.",
        "data": batch_row,
    }


@app.get("/api/savings-interest/batches/{account_number}")
async def list_savings_interest_batches(
    account_number: str,
    current_user: dict = _Depends(_get_current_user),
):
    """Posting history for one account, newest first."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_bookkeeper(current_user)

    rows = (
        supabase.table("savings_interest_batches")
        .select("*")
        .eq("account_number", account_number)
        .order("period_quarter", desc=True)
        .execute()
    ).data or []
    return {"success": True, "data": rows}


@app.post("/api/savings-interest/batches/{batch_id}/reverse")
async def reverse_savings_interest_batch(
    batch_id: int,
    current_user: dict = _Depends(_get_current_user),
):
    """Manager-only reversal: debits the posted interest back out and marks
    the batch reversed. A Manager cannot reverse their own posting — but
    batches are always posted by the Bookkeeper, so this check also catches
    the case where a Bookkeeper account was later promoted to Manager."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_manager(current_user)

    found = (
        supabase.table("savings_interest_batches")
        .select("*")
        .eq("id", batch_id)
        .limit(1)
        .execute()
    )
    batch = (found.data or [None])[0]
    if not batch:
        raise HTTPException(status_code=404, detail="Batch not found.")
    if batch.get("status") != "posted":
        raise HTTPException(status_code=409, detail=f"This batch is already {batch.get('status')}.")
    if str(batch.get("posted_by_user_id") or "") == current_user["id"]:
        raise HTTPException(status_code=403, detail="You cannot reverse your own posting.")

    try:
        reversal_insert = supabase.table("savings_ledger").insert({
            "account_number": batch["account_number"],
            "entry_type": "debit",
            "amount": batch["interest_posted"],
            "source": "savings_interest_reversal",
            "remarks": f"Reversal of {batch['period_quarter']} interest posting (batch {batch_id})",
            "posted_by": "manager",
        }).execute()
        reversal_row = (reversal_insert.data or [None])[0]
    except Exception as exc:  # noqa: BLE001
        raise HTTPException(status_code=500, detail=f"Failed to post reversal debit: {exc}")

    updated = (
        supabase.table("savings_interest_batches")
        .update({
            "status": "reversed",
            "reversed_by_user_id": current_user["id"],
            "reversed_by_email": current_user.get("email") or None,
            "reversed_at": datetime.utcnow().isoformat(),
            "reversal_ledger_entry_id": reversal_row.get("id") if reversal_row else None,
        })
        .eq("id", batch_id)
        .eq("status", "posted")
        .execute()
    )
    updated_row = (updated.data or [None])[0]
    if not updated_row:
        raise HTTPException(status_code=409, detail="This batch was already reversed by someone else.")

    return {"success": True, "data": updated_row}


# ---------------------------------------------------------------------------
# MIGS scoring — read-only roster + per-member detail for the bookkeeper.
# Live values: capital, loan availed YTD, savings balance, late-payment count.
# Defaulted values (until those modules are wired): groceries=0, PLI=no
# outside loan (10 pts), attendance=absent (0 pts). Scoring engine in
# migs_engine.py awards points and classifies MIGS vs Non-MIGS.
# ---------------------------------------------------------------------------
from migs_engine import compute_migs_score, result_to_dict  # noqa: E402


class MigsOutsideLoanRequest(BaseModel):
    """Bookkeeper's declaration for the 'Loans from Other PLIs' criterion."""

    has_outside_loan: bool
    year: int | None = None
    note: str | None = None
    declared_by: str | None = None
    declared_by_email: str | None = None


def _load_outside_loan_declarations(year: int) -> dict[str, bool]:
    """member_id -> declared has_outside_loan for `year`.

    "Loans from Other PLIs" is the one MIGS criterion with no system source --
    every other one is derived from a ledger. It is entered by the bookkeeper
    and stored in migs_outside_loan_declaration (see
    migs_outside_loan_schema.sql for why it is NOT a column on the snapshot
    table: recompute-all delete+inserts that table and would wipe it).

    A member absent from this map has not been asked. Callers pass None for
    them, and score_outside_loan() applies its documented default of 10/10 --
    identical to the behaviour before this was wired, so no score moves until
    a bookkeeper actually answers.

    Never raises: a missing table (migration not yet applied) degrades to "no
    declarations", which is exactly the old hardcoded-None behaviour.
    """
    if not supabase:
        return {}
    try:
        response = (
            supabase.table("migs_outside_loan_declaration")
            .select("member_id,has_outside_loan")
            .eq("year", year)
            .execute()
        )
    except Exception as exc:  # noqa: BLE001
        print(f"[migs] outside-loan declarations unavailable for {year}: {exc}")
        return {}

    declarations: dict[str, bool] = {}
    for row in response.data or []:
        member_id = row.get("member_id")
        if member_id is not None:
            declarations[str(member_id)] = bool(row.get("has_outside_loan"))
    return declarations


# ============================================================================
# SECTION: MIGS Scoring (Member In Good Standing)
# Endpoints wrapping migs_engine.py: list members with MIGS scores, recompute
# all scores for a year, and fetch individual member score details/labels.
# ============================================================================

@app.get("/api/migs/classifications")
async def list_migs_classifications():
    """Bulk, view-only MIGS/Non-MIGS label per member, keyed by membership_id.

    For table columns elsewhere (e.g. Manager's Manage Member) that just need
    to show the badge, not re-run scoring. Reads the latest persisted
    member_classification_temporal snapshot per member — same source and
    "most recent row wins" rule as the MIGS distribution stat on BOD Reports.
    Members never scored come back as "unscored" rather than being omitted.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        member_table = _resolve_member_table(supabase)
        members_resp = (
            supabase.table(member_table).select("id,membership_id").execute()
        )
        members = members_resp.data or []
        membership_by_id = {m["id"]: m.get("membership_id") for m in members if m.get("id")}

        snap_resp = (
            supabase.table("member_classification_temporal")
            .select("membership_number_id,classification_level_id,accrual_date")
            .order("accrual_date", desc=True)
            .execute()
        )
        level_resp = (
            supabase.table("classification_level")
            .select("classification_level_id,code")
            .execute()
        )
        level_code_by_id = {
            str(r["classification_level_id"]): str(r.get("code") or "").lower()
            for r in (level_resp.data or [])
        }

        labels: dict[str, str] = {}
        seen: set[str] = set()
        for row in snap_resp.data or []:
            member_uuid = str(row.get("membership_number_id") or "").strip()
            if not member_uuid or member_uuid in seen:
                continue
            seen.add(member_uuid)
            membership_id = membership_by_id.get(member_uuid)
            if not membership_id:
                continue
            code = level_code_by_id.get(str(row.get("classification_level_id") or ""), "")
            labels[membership_id] = "migs" if code == "migs" else "non_migs"

        # Members with no snapshot yet are explicitly "unscored" rather than
        # left out, so the UI can tell "not MIGS" from "never scored".
        for membership_id in membership_by_id.values():
            if membership_id and membership_id not in labels:
                labels[membership_id] = "unscored"

        return {"success": True, "data": labels}
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to load MIGS classifications: {exc}")


@app.get("/api/migs/members")
async def list_migs_members(year: int | None = None):
    """MIGS member list. Retries once on a fresh Supabase client when the pooled
    connection has gone stale (WinError 10035 / "server disconnected"); this is a
    read-only lookup of roughly twenty queries, so one dropped connection used to
    fail the whole page. The all-members save reuses it too."""
    global supabase
    try:
        return await _list_migs_members(year)
    except HTTPException as err:
        if not (_is_stale_connection_error(Exception(str(err.detail))) and url and key):
            raise
        supabase = create_client(url, key, options=_SUPABASE_CLIENT_OPTIONS)
        return await _list_migs_members(year)


async def _list_migs_members(year: int | None = None):
    """List all members with the raw inputs needed for MIGS scoring.

    Query params:
      - year: filter loan-availed and late-payment counts to this calendar year.
              Defaults to the current UTC year. Capital and savings are
              point-in-time balances and ignore the year filter.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    target_year = int(year) if year else datetime.utcnow().year

    try:
        # --- Member roster ------------------------------------------------
        member_table = _resolve_member_table(supabase)
        members_response = (
            supabase.table(member_table)
            .select("id,membership_id,first_name,last_name,is_bona_fide")
            .order("last_name")
            .execute()
        )
        members = members_response.data or []
        member_ids = [m["id"] for m in members if m.get("id")]
        if not member_ids:
            return {"success": True, "data": [], "year": target_year, "count": 0}

        # --- Middle name from personal_data_sheet (latest row per member) -
        # member table only stores first/last; PDS has middle/surname split.
        membership_keys = [m.get("membership_id") for m in members if m.get("membership_id")]
        pds_by_membership: dict[str, dict] = {}
        if membership_keys:
            try:
                pds_response = (
                    supabase.table("personal_data_sheet")
                    .select("membership_number_id,first_name,middle_name,surname,created_at")
                    .in_("membership_number_id", membership_keys)
                    .order("created_at", desc=True)
                    .execute()
                )
                for row in pds_response.data or []:
                    key = row.get("membership_number_id")
                    if key and key not in pds_by_membership:
                        pds_by_membership[key] = row
            except Exception as exc:  # noqa: BLE001
                print(f"[migs] PDS lookup failed: {exc}")

        # --- Capital Build-Up (latest ending_share_capital per member) ----
        # We need the most recent row per member, so pull all rows ordered
        # by transaction_date DESC and pick the first occurrence of each id.
        cbu_by_member: dict[str, float] = {}
        try:
            cbu_response = (
                supabase.table("capital_build_up")
                .select("member_id,ending_share_capital,transaction_date")
                .in_("member_id", member_ids)
                .order("transaction_date", desc=True)
                .execute()
            )
            for row in cbu_response.data or []:
                mid = row.get("member_id")
                if mid and mid not in cbu_by_member:
                    cbu_by_member[mid] = float(row.get("ending_share_capital") or 0)
        except Exception as exc:  # noqa: BLE001
            print(f"[migs] cbu lookup failed: {exc}")

        # --- Loan availed YTD (sum of principal_amount this year)
        # AND current outstanding loan balance across all years.
        # `loan_availed` feeds the MIGS score's 5th criterion (loans this year).
        # `loan_balance` is what the UI displays in the "Loan" column so the
        # bookkeeper can see the member's actual outstanding debt at a glance
        # — 90+% of TTMPC's legacy portfolio was disbursed pre-2026, so
        # limiting to YTD principal shows ₱0 for essentially everyone.
        loans_by_member: dict[str, float] = {m: 0.0 for m in member_ids}
        loan_balance_by_member: dict[str, float] = {m: 0.0 for m in member_ids}
        try:
            # Pull all non-rejected loans in a paginated loop (portfolio may
            # exceed the 1000-row default cap once legacy is included).
            _page = 1000
            _offset = 0
            all_loans: list[dict] = []
            while True:
                _batch = (
                    supabase.table("loans")
                    .select("control_number,member_id,principal_amount,application_date,loan_status,total_interest,monthly_amortization,term,loan_type:loan_type_id(name)")
                    .in_("member_id", member_ids)
                    .range(_offset, _offset + _page - 1)
                    .execute()
                ).data or []
                if not _batch:
                    break
                all_loans.extend(_batch)
                if len(_batch) < _page:
                    break
                _offset += _page

            # Payments summed per loan to compute outstanding balance.
            loan_ids_all = [l.get("control_number") for l in all_loans if l.get("control_number")]
            paid_by_loan: dict[str, float] = {}
            try:
                _offset = 0
                while True:
                    _batch = (
                        supabase.table("loan_payments")
                        .select("loan_id,amount_paid,confirmation_status")
                        .range(_offset, _offset + 999)
                        .execute()
                    ).data or []
                    if not _batch:
                        break
                    for _p in _batch:
                        if str(_p.get("confirmation_status") or "").lower() not in {"validated","confirmed","approved","bookkeeper_confirmed"}:
                            continue
                        _lid = str(_p.get("loan_id") or "")
                        if _lid:
                            paid_by_loan[_lid] = paid_by_loan.get(_lid, 0.0) + float(_p.get("amount_paid") or 0)
                    if len(_batch) < 1000:
                        break
                    _offset += 1000
                # Legacy payments (always validated)
                _offset = 0
                while True:
                    _batch = (
                        supabase.table("loan_payments_legacy")
                        .select("loan_id,amount_paid")
                        .range(_offset, _offset + 999)
                        .execute()
                    ).data or []
                    if not _batch:
                        break
                    for _p in _batch:
                        _lid = str(_p.get("loan_id") or "")
                        if _lid:
                            paid_by_loan[_lid] = paid_by_loan.get(_lid, 0.0) + float(_p.get("amount_paid") or 0)
                    if len(_batch) < 1000:
                        break
                    _offset += 1000
            except Exception as exc:  # noqa: BLE001
                print(f"[migs] payments-for-balance lookup failed: {exc}")

            for row in all_loans:
                status_lc = str(row.get("loan_status") or "").lower()
                if status_lc in {"rejected", "cancelled", "canceled", "bod rejected"}:
                    continue
                mid = row.get("member_id")
                if not mid:
                    continue
                principal = float(row.get("principal_amount") or 0)

                # MIGS "Loan Availed" counts loans whose repayment period is
                # still active during target_year — i.e., a loan opened in
                # 2023 with a 60-month term runs until 2028 so it counts for
                # FY 2026. Fully-paid or expired loans are excluded.
                app_date_str = str(row.get("application_date") or "")
                term_months = int(row.get("term") or 0)
                _app_year = None
                _app_month = None
                if len(app_date_str) >= 7:
                    try:
                        _app_year = int(app_date_str[:4])
                        _app_month = int(app_date_str[5:7])
                    except Exception:
                        _app_year = None
                _row_is_bonus = "bonus" in str((row.get("loan_type") or {}).get("name") or "").strip().lower()
                # TODO(BONUS_LOAN_PLAN.md Step 4): for Bonus, term_months now
                # means "months from release to the bonus date" (not an
                # installment count from application_date), so this maturity-
                # window math is unreviewed for Bonus and may mis-time when a
                # Bonus loan drops out of MIGS "Loan Availed". Needs a
                # dedicated look, not folded into this pass.
                if _app_year and _app_month and term_months > 0:
                    # Loan is active in target_year if app_year <= target_year
                    # AND the maturity month is >= January of target_year.
                    _maturity_total_months = _app_year * 12 + (_app_month - 1) + term_months
                    _target_start_months = target_year * 12
                    if _app_year <= target_year and _maturity_total_months >= _target_start_months:
                        # Also skip if already fully paid.
                        if status_lc != "fully paid":
                            loans_by_member[mid] = loans_by_member.get(mid, 0.0) + principal

                # Outstanding balance (informational column, all non-rejected).
                total_interest = float(row.get("total_interest") or 0)
                if total_interest <= 0 and term_months > 0:
                    monthly = float(row.get("monthly_amortization") or 0)
                    if monthly > 0:
                        if _row_is_bonus:
                            # monthly_amortization already holds the full
                            # lump-sum payoff for Bonus (Step 2) — don't
                            # multiply by term again.
                            total_interest = max(monthly - principal, 0.0)
                        else:
                            total_interest = max(monthly * term_months - principal, 0.0)
                total_payable = principal + total_interest
                paid = paid_by_loan.get(str(row.get("control_number") or ""), 0.0)
                loan_balance_by_member[mid] = loan_balance_by_member.get(mid, 0.0) + max(total_payable - paid, 0.0)
        except Exception as exc:  # noqa: BLE001
            print(f"[migs] loans lookup failed: {exc}")

        # --- Groceries availed YTD (sum of GroceryAmount this year) --------
        grocery_by_member: dict[str, float] = {m: 0.0 for m in member_ids}
        try:
            grocery_response = (
                supabase.table("GROCERY_TRANSACTIONS")
                .select("membership_number_id,GroceryAmount,TransactionDate,Status")
                .in_("membership_number_id", member_ids)
                .gte("TransactionDate", f"{target_year}-01-01")
                .lte("TransactionDate", f"{target_year}-12-31T23:59:59")
                .execute()
            )
            for row in grocery_response.data or []:
                if str(row.get("Status") or "") not in {"Completed", "On Credit"}:
                    continue
                mid = row.get("membership_number_id")
                if mid:
                    grocery_by_member[mid] = grocery_by_member.get(mid, 0.0) + float(
                        row.get("GroceryAmount") or 0
                    )
        except Exception as exc:  # noqa: BLE001
            print(f"[migs] grocery lookup failed: {exc}")

        # --- Savings balance (sum of savings_accounts.balance, kind=member, active)
        savings_by_member: dict[str, float] = {m: 0.0 for m in member_ids}
        try:
            savings_response = (
                supabase.table("savings_accounts")
                .select("member_id,balance,account_kind,status")
                .in_("member_id", member_ids)
                .eq("account_kind", "member")
                .eq("status", "active")
                .execute()
            )
            for row in savings_response.data or []:
                mid = row.get("member_id")
                if mid:
                    savings_by_member[mid] = savings_by_member.get(mid, 0.0) + float(
                        row.get("balance") or 0
                    )
        except Exception as exc:  # noqa: BLE001
            print(f"[migs] savings lookup failed: {exc}")

        # Open Time Deposit principal counts toward MIGS "Savings / Time
        # Deposit" too (score_savings_balance()'s own docstring says so) --
        # settled_at IS NULL means the principal is still held regardless of
        # whether the certificate is locked or matured-awaiting-instruction.
        try:
            td_response = (
                supabase.table("time_deposits")
                .select("member_id,principal,settled_at")
                .in_("member_id", member_ids)
                .is_("settled_at", "null")
                .execute()
            )
            for row in td_response.data or []:
                mid = row.get("member_id")
                if mid:
                    savings_by_member[mid] = savings_by_member.get(mid, 0.0) + float(
                        row.get("principal") or 0
                    )
        except Exception as exc:  # noqa: BLE001
            print(f"[migs] time deposit lookup failed: {exc}")

        # --- Late payment count YTD ---------------------------------------
        # Pull validated payments for this year, join in-memory to schedules
        # so we can compare payment_date > due_date.
        late_count_by_member: dict[str, int] = {m: 0 for m in member_ids}
        try:
            payments_response = (
                supabase.table("loan_payments")
                .select("loan_id,schedule_id,payment_date,confirmation_status")
                .gte("payment_date", f"{target_year}-01-01")
                .lte("payment_date", f"{target_year}-12-31")
                .eq("confirmation_status", "validated")
                .execute()
            )
            payments = payments_response.data or []

            schedule_ids = sorted({p["schedule_id"] for p in payments if p.get("schedule_id")})
            loan_ids = sorted({p["loan_id"] for p in payments if p.get("loan_id")})

            def _id_chunks(values, size=200):
                values = list(values)
                for i in range(0, len(values), size):
                    yield values[i:i + size]

            schedule_due: dict[str, str] = {}
            for chunk in _id_chunks(schedule_ids):
                sched_response = (
                    supabase.table("loan_schedules")
                    .select("id,due_date")
                    .in_("id", chunk)
                    .execute()
                )
                for s in sched_response.data or []:
                    if s.get("id") and s.get("due_date"):
                        schedule_due[s["id"]] = s["due_date"]

            loan_to_member: dict[str, str] = {}
            for chunk in _id_chunks(loan_ids):
                loan_member_response = (
                    supabase.table("loans")
                    .select("control_number,member_id")
                    .in_("control_number", chunk)
                    .execute()
                )
                for l in loan_member_response.data or []:
                    if l.get("control_number") and l.get("member_id"):
                        loan_to_member[l["control_number"]] = l["member_id"]

            for p in payments:
                due_str = schedule_due.get(p.get("schedule_id"))
                paid_str = p.get("payment_date")
                if not due_str or not paid_str:
                    continue
                try:
                    paid_dt = datetime.fromisoformat(str(paid_str).replace("Z", "+00:00")).date()
                    due_dt = datetime.fromisoformat(str(due_str)).date() if "T" in str(due_str) else datetime.strptime(str(due_str), "%Y-%m-%d").date()
                except Exception:
                    continue
                if paid_dt > due_dt:
                    mid = loan_to_member.get(p.get("loan_id"))
                    if mid:
                        late_count_by_member[mid] = late_count_by_member.get(mid, 0) + 1
        except Exception as exc:  # noqa: BLE001
            print(f"[migs] late-payment lookup failed: {exc}")

        # --- General Assembly attendance (this year) ----------------------
        # Member is "Present" if general_assembly_attendance has any row with
        # status='Present' within the target year.
        ga_present_by_member: dict[str, bool] = {}
        try:
            ga_response = (
                supabase.table("general_assembly_attendance")
                .select("member_id,status,meeting_date")
                .eq("status", "Present")
                .gte("meeting_date", f"{target_year}-01-01")
                .lte("meeting_date", f"{target_year}-12-31")
                .execute()
            )
            for row in ga_response.data or []:
                mid = row.get("member_id")
                if mid:
                    ga_present_by_member[mid] = True
        except Exception as exc:  # noqa: BLE001
            print(f"[migs] GA attendance lookup failed: {exc}")

        # --- Compose response --------------------------------------------
        # One query for the whole page rather than one per member.
        outside_loan_by_member = _load_outside_loan_declarations(target_year)

        rows = []
        for m in members:
            mid = m.get("id")
            pds = pds_by_membership.get(m.get("membership_id")) or {}
            first = pds.get("first_name") or m.get("first_name")
            middle = pds.get("middle_name")
            last = pds.get("surname") or pds.get("last_name") or m.get("last_name")
            full_name = " ".join(
                str(part).strip()
                for part in (first, middle, last)
                if str(part or "").strip()
            ).strip() or "Unknown Member"

            capital_v = cbu_by_member.get(mid, 0.0)
            loan_v = loans_by_member.get(mid, 0.0)
            loan_balance_v = loan_balance_by_member.get(mid, 0.0)
            savings_v = savings_by_member.get(mid, 0.0)
            late_v = late_count_by_member.get(mid, 0)
            grocery_v = grocery_by_member.get(mid, 0.0)

            attendance_v = ga_present_by_member.get(mid, False)
            # None when no declaration exists -- score_outside_loan() then
            # applies its 10/10 default, unchanged from before this was wired.
            outside_loan_v = outside_loan_by_member.get(str(mid))
            result = compute_migs_score(
                cbu_added=capital_v,
                loan_availed=loan_v,
                savings_balance=savings_v,
                late_payment_count=late_v,
                groceries_availed=grocery_v,
                has_outside_loan=outside_loan_v,
                assembly_present=attendance_v,
            )

            rows.append({
                "id": mid,
                "member_id": m.get("membership_id"),
                "full_name": full_name,
                "is_bona_fide": bool(m.get("is_bona_fide")),
                "capital": capital_v,
                "loan_balance": loan_balance_v,
                "loan_availed_ytd": loan_v,
                "savings_balance": savings_v,
                "late_payment_count": late_v,
                "groceries_availed": grocery_v,
                "has_outside_loan": outside_loan_v,
                "assembly_attendance": "Present" if attendance_v else "Absent",
                # Live score + classification.
                "migs_score": result.total_score,
                "migs_status": result.status,
                "loan_multiplier": result.loan_multiplier,
                "can_vote": result.can_vote,
            })

        return {
            "success": True,
            "data": rows,
            "year": target_year,
            "count": len(rows),
        }
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load MIGS members: {err}")


@app.post("/api/migs/recompute-all")
async def recompute_all_migs(year: int | None = None):
    """Run the MIGS engine for every member and persist a snapshot row into
    public.member_classification_temporal.

    Snapshot keying:
      - accrual_date = current week's Saturday (table constraint requires it)
      - one row per (member_id, accrual_date); re-running the same week
        updates the existing row instead of creating duplicates.

    Other modules can then read the latest snapshot via /api/migs/label/{id}.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    target_year = int(year) if year else datetime.utcnow().year

    # Resolve the upcoming/current Saturday (ISO weekday 6).
    today = datetime.utcnow().date()
    days_until_sat = (5 - today.weekday()) % 7  # weekday(): Mon=0..Sun=6, Sat=5
    accrual_date = (today if days_until_sat == 0 else today.replace()) if days_until_sat == 0 else today
    if days_until_sat != 0:
        from datetime import timedelta
        # Snap to the most recent past Saturday so the snapshot covers a complete week.
        days_since_sat = (today.weekday() - 5) % 7
        accrual_date = today - timedelta(days=days_since_sat)
    accrual_iso = accrual_date.isoformat()

    # Resolve classification_level FK ids once.
    try:
        levels_response = (
            supabase.table("classification_level")
            .select("classification_level_id,code")
            .in_("code", ["migs", "non_migs"])
            .execute()
        )
        levels = {row["code"]: row["classification_level_id"] for row in levels_response.data or []}
        if "migs" not in levels or "non_migs" not in levels:
            raise HTTPException(
                status_code=500,
                detail="classification_level rows missing. Apply migs_classification_levels.sql.",
            )
    except HTTPException as err:
        raise err
    except Exception as exc:  # noqa: BLE001
        raise HTTPException(status_code=500, detail=f"Failed to resolve classification levels: {exc}")

    # Reuse the same data-gathering as /api/migs/members.
    try:
        members_payload = await list_migs_members(year=target_year)  # type: ignore[arg-type]
    except HTTPException as err:
        raise err
    members = members_payload.get("data", [])

    # Compute all rows in-memory first, then write in two bulk calls.
    from migs_engine import compute_migs_score
    payloads = []
    errors = []
    for m in members:
        mid = m.get("id")
        if not mid:
            continue
        result = compute_migs_score(
            cbu_added=m.get("capital") or 0,
            loan_availed=m.get("loan_balance") or 0,
            savings_balance=m.get("savings_balance") or 0,
            late_payment_count=m.get("late_payment_count") or 0,
            groceries_availed=m.get("groceries_availed") or 0,
            # list_migs_members already resolved the declaration for this year
            # (and left it None where nobody has answered), so the snapshot
            # scores the same value the screen showed.
            has_outside_loan=m.get("has_outside_loan"),
            assembly_present=(m.get("assembly_attendance") == "Present"),
        )
        bp = {c.criterion: c.score for c in result.breakdown}
        # Schema constraint allows `final_status` only on first-week snapshots
        # (accrual day <= 7). Outside that window, leave it NULL — the label is
        # still resolvable via classification_level_id.
        in_first_week = accrual_date.day <= 7
        payloads.append({
            "membership_number_id": mid,
            "classification_level_id": levels["migs"] if result.status == "MIGS Qualified" else levels["non_migs"],
            "accrual_date": accrual_iso,
            "cbu_points":        bp.get("Capital Build-Up", 0),
            "loan_points":       bp.get("Loan Availed", 0),
            "savings_points":    bp.get("Savings / Time Deposit", 0),
            "payment_points":    bp.get("Payment Record (late count)", 0),
            "grocery_points":    bp.get("Groceries Availed", 0),
            "pli_points":        bp.get("Loans from Other PLIs", 0),
            "attendance_points": bp.get("Assembly Attendance", 0),
            "final_status": result.status if in_first_week else None,
        })

    # Bulk wipe + insert for this snapshot date. Two network calls instead of 2N.
    inserted = 0
    updated = 0
    if payloads:
        try:
            # Count how many existed before (for reporting; not strictly needed).
            pre = (
                supabase.table("member_classification_temporal")
                .select("classification_id", count="exact")
                .eq("accrual_date", accrual_iso)
                .execute()
            )
            pre_count = pre.count or 0

            supabase.table("member_classification_temporal").delete().eq(
                "accrual_date", accrual_iso
            ).execute()

            # Supabase Python client batch-inserts in one network round-trip.
            supabase.table("member_classification_temporal").insert(payloads).execute()

            # Treat overlap as "updated", new ones as "inserted".
            updated = min(pre_count, len(payloads))
            inserted = max(0, len(payloads) - pre_count)
        except Exception as exc:  # noqa: BLE001
            errors.append({"member": "BULK", "error": str(exc)[:400]})

    return {
        "success": True if not errors else False,
        "accrual_date": accrual_iso,
        "year": target_year,
        "members_processed": len(members),
        "inserted": inserted,
        "updated": updated,
        "errors": errors,
    }


@app.get("/api/migs/label/{member_key}")
async def get_migs_label(member_key: str):
    """Cheap MIGS classification lookup for other modules.

    Returns the most recent snapshot row from member_classification_temporal.
    Used by loan-approval, member-dashboard, etc. to know if a member is MIGS
    without re-running the scoring engine.

    `member_key` accepts either member.id (UUID) or member.membership_id.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    key = str(member_key or "").strip()
    if not key:
        raise HTTPException(status_code=400, detail="member_key is required.")

    try:
        member_table = _resolve_member_table(supabase)
        lookup_field = "id" if len(key) == 36 and key.count("-") == 4 else "membership_id"
        member_response = (
            supabase.table(member_table)
            .select("id,membership_id,first_name,last_name")
            .eq(lookup_field, key)
            .limit(1)
            .execute()
        )
        member = (member_response.data or [None])[0]
        if not member:
            raise HTTPException(status_code=404, detail="Member not found.")

        snapshot_response = (
            supabase.table("member_classification_temporal")
            .select("accrual_date,total_score,final_status,classification_level_id,cbu_points,loan_points,savings_points,payment_points,grocery_points,pli_points,attendance_points")
            .eq("membership_number_id", member["id"])
            .order("accrual_date", desc=True)
            .limit(1)
            .execute()
        )
        snapshot = (snapshot_response.data or [None])[0]

        if not snapshot:
            return {
                "success": True,
                "data": {
                    "member_id": member["id"],
                    "membership_id": member.get("membership_id"),
                    "label": "Unscored",
                    "score": None,
                    "as_of": None,
                    "loan_multiplier": 3.0,
                    "can_vote": False,
                },
            }

        # final_status is only populated on first-week snapshots (schema constraint).
        # Fall back to the classification_level lookup for mid-month snapshots.
        label = snapshot.get("final_status")
        if not label and snapshot.get("classification_level_id"):
            try:
                level_response = (
                    supabase.table("classification_level")
                    .select("label")
                    .eq("classification_level_id", snapshot["classification_level_id"])
                    .limit(1)
                    .execute()
                )
                lvl = (level_response.data or [None])[0]
                if lvl:
                    label = lvl.get("label")
            except Exception:
                pass
        snapshot["final_status"] = label
        is_migs = str(label or "").lower().startswith("migs")
        return {
            "success": True,
            "data": {
                "member_id": member["id"],
                "membership_id": member.get("membership_id"),
                "label": snapshot.get("final_status"),
                "score": snapshot.get("total_score"),
                "as_of": snapshot.get("accrual_date"),
                "loan_multiplier": 5.0 if is_migs else 3.0,
                "can_vote": is_migs,
                "breakdown": {
                    "cbu":        snapshot.get("cbu_points"),
                    "loan":       snapshot.get("loan_points"),
                    "savings":    snapshot.get("savings_points"),
                    "payment":    snapshot.get("payment_points"),
                    "grocery":    snapshot.get("grocery_points"),
                    "pli":        snapshot.get("pli_points"),
                    "attendance": snapshot.get("attendance_points"),
                },
            },
        }
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to fetch MIGS label: {err}")


@app.get("/api/migs/members/{member_key}")
async def get_migs_member_detail(member_key: str, year: int | None = None):
    """Retries once on a fresh Supabase client when the pooled connection has gone
    stale. On Windows that surfaces as WinError 10035 ("non-blocking socket
    operation could not be completed") or "server disconnected"; the read-only
    detail lookup is safe to repeat."""
    global supabase
    try:
        return await _get_migs_member_detail(member_key, year)
    except HTTPException as err:
        message = str(err.detail).lower()
        transient = "10035" in message or "non-blocking socket" in message or "server disconnected" in message
        if not (transient and url and key):
            raise
        supabase = create_client(url, key, options=_SUPABASE_CLIENT_OPTIONS)
        return await _get_migs_member_detail(member_key, year)


async def _get_migs_member_detail(member_key: str, year: int | None = None):
    """Single-member MIGS detail for the Evaluate page.

    `member_key` may be either the member.id UUID or the membership_id (e.g. TTMPC-123).
    Returns the same raw fields as the list endpoint plus a scoring_breakdown stub
    so the existing UI can render. Score/status remain null until the engine ships.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    target_year = int(year) if year else datetime.utcnow().year
    key = str(member_key or "").strip()
    if not key:
        raise HTTPException(status_code=400, detail="member_key is required.")

    try:
        member_table = _resolve_member_table(supabase)
        lookup_field = "id" if len(key) == 36 and key.count("-") == 4 else "membership_id"
        member_response = (
            supabase.table(member_table)
            .select("id,membership_id,first_name,last_name,is_bona_fide")
            .eq(lookup_field, key)
            .limit(1)
            .execute()
        )
        member = (member_response.data or [None])[0]
        if not member:
            raise HTTPException(status_code=404, detail="Member not found.")

        mid = member["id"]
        membership_id = member.get("membership_id")

        # --- Middle name from PDS -----------------------------------------
        pds = None
        if membership_id:
            try:
                pds_response = (
                    supabase.table("personal_data_sheet")
                    .select("first_name,middle_name,surname,last_name")
                    .eq("membership_number_id", membership_id)
                    .order("created_at", desc=True)
                    .limit(1)
                    .execute()
                )
                pds = (pds_response.data or [None])[0]
            except Exception:
                pds = None
        pds = pds or {}
        first = pds.get("first_name") or member.get("first_name")
        middle = pds.get("middle_name")
        last = pds.get("surname") or pds.get("last_name") or member.get("last_name")
        full_name = " ".join(
            str(part).strip() for part in (first, middle, last) if str(part or "").strip()
        ).strip() or "Unknown Member"

        # --- Capital ------------------------------------------------------
        capital = 0.0
        try:
            cbu_response = (
                supabase.table("capital_build_up")
                .select("ending_share_capital,transaction_date")
                .eq("member_id", mid)
                .order("transaction_date", desc=True)
                .limit(1)
                .execute()
            )
            cbu_row = (cbu_response.data or [None])[0]
            if cbu_row:
                capital = float(cbu_row.get("ending_share_capital") or 0)
        except Exception as exc:  # noqa: BLE001
            print(f"[migs detail] cbu lookup failed: {exc}")

        # --- Loan availed (this year) + Outstanding balance (all years) ---
        # `loan_availed` feeds the MIGS engine's Loan-Availed criterion which
        # scores loans taken during the target year.
        # `loan_balance` is the member's total outstanding debt across all
        # their loans (legacy + live) and is what the UI's Loan column shows
        # in the Scoring Breakdown row.
        loan_availed = 0.0
        loan_balance = 0.0
        try:
            loans_response = (
                supabase.table("loans")
                .select("control_number,principal_amount,application_date,loan_status,total_interest,monthly_amortization,term,loan_type:loan_type_id(name)")
                .eq("member_id", mid)
                .execute()
            )
            _member_loans = loans_response.data or []

            # Sum validated payments per loan (live + legacy) to compute
            # outstanding balance = principal + interest − paid.
            _loan_ids = [l.get("control_number") for l in _member_loans if l.get("control_number")]
            _paid_by_loan: dict[str, float] = {}
            if _loan_ids:
                try:
                    live_p = supabase.table("loan_payments").select("loan_id,amount_paid,confirmation_status").in_("loan_id", _loan_ids).execute().data or []
                    for _p in live_p:
                        if str(_p.get("confirmation_status") or "").lower() not in {"validated","confirmed","approved","bookkeeper_confirmed"}:
                            continue
                        _lid = str(_p.get("loan_id") or "")
                        if _lid:
                            _paid_by_loan[_lid] = _paid_by_loan.get(_lid, 0.0) + float(_p.get("amount_paid") or 0)
                    legacy_p = supabase.table("loan_payments_legacy").select("loan_id,amount_paid").in_("loan_id", _loan_ids).execute().data or []
                    for _p in legacy_p:
                        _lid = str(_p.get("loan_id") or "")
                        if _lid:
                            _paid_by_loan[_lid] = _paid_by_loan.get(_lid, 0.0) + float(_p.get("amount_paid") or 0)
                except Exception as exc:  # noqa: BLE001
                    print(f"[migs detail] payments-for-balance lookup failed: {exc}")

            for row in _member_loans:
                status_lc = str(row.get("loan_status") or "").lower()
                if status_lc in {"rejected", "cancelled", "canceled", "bod rejected"}:
                    continue
                principal = float(row.get("principal_amount") or 0)
                term_months = int(row.get("term") or 0)
                app_date_str = str(row.get("application_date") or "")
                _row_is_bonus = "bonus" in str((row.get("loan_type") or {}).get("name") or "").strip().lower()

                # Active-window check: loan opened in app_year with term_months
                # is "still running" during target_year if maturity month >=
                # January of target_year. Excludes fully-paid loans.
                # TODO(BONUS_LOAN_PLAN.md Step 4): for Bonus, term_months now
                # means "months from release to the bonus date" (not an
                # installment count from application_date) — this maturity-
                # window math is unreviewed for Bonus; needs a dedicated look.
                _app_year = None
                _app_month = None
                if len(app_date_str) >= 7:
                    try:
                        _app_year = int(app_date_str[:4])
                        _app_month = int(app_date_str[5:7])
                    except Exception:
                        _app_year = None
                if _app_year and _app_month and term_months > 0:
                    _maturity_total_months = _app_year * 12 + (_app_month - 1) + term_months
                    _target_start_months = target_year * 12
                    if _app_year <= target_year and _maturity_total_months >= _target_start_months:
                        if status_lc != "fully paid":
                            loan_availed += principal

                # Outstanding balance (informational, all non-rejected).
                total_interest = float(row.get("total_interest") or 0)
                if total_interest <= 0 and term_months > 0:
                    monthly = float(row.get("monthly_amortization") or 0)
                    if monthly > 0:
                        if _row_is_bonus:
                            total_interest = max(monthly - principal, 0.0)
                        else:
                            total_interest = max(monthly * term_months - principal, 0.0)
                total_payable = principal + total_interest
                paid = _paid_by_loan.get(str(row.get("control_number") or ""), 0.0)
                loan_balance += max(total_payable - paid, 0.0)
        except Exception as exc:  # noqa: BLE001
            print(f"[migs detail] loans lookup failed: {exc}")

        # --- Savings ------------------------------------------------------
        savings = 0.0
        try:
            savings_response = (
                supabase.table("savings_accounts")
                .select("balance")
                .eq("member_id", mid)
                .eq("account_kind", "member")
                .eq("status", "active")
                .execute()
            )
            for row in savings_response.data or []:
                savings += float(row.get("balance") or 0)
        except Exception as exc:  # noqa: BLE001
            print(f"[migs detail] savings lookup failed: {exc}")

        # Open Time Deposit principal counts toward "Savings / Time Deposit"
        # too — settled_at IS NULL means the principal is still held.
        try:
            td_response = (
                supabase.table("time_deposits")
                .select("principal,settled_at")
                .eq("member_id", mid)
                .is_("settled_at", "null")
                .execute()
            )
            for row in td_response.data or []:
                savings += float(row.get("principal") or 0)
        except Exception as exc:  # noqa: BLE001
            print(f"[migs detail] time deposit lookup failed: {exc}")

        # --- Late payments (this year) -----------------------------------
        late_count = 0
        try:
            loans_for_member = (
                supabase.table("loans")
                .select("control_number")
                .eq("member_id", mid)
                .execute()
            ).data or []
            control_numbers = [l["control_number"] for l in loans_for_member if l.get("control_number")]
            if control_numbers:
                payments_response = (
                    supabase.table("loan_payments")
                    .select("schedule_id,payment_date,confirmation_status,loan_id")
                    .in_("loan_id", control_numbers)
                    .gte("payment_date", f"{target_year}-01-01")
                    .lte("payment_date", f"{target_year}-12-31")
                    .eq("confirmation_status", "validated")
                    .execute()
                )
                payments = payments_response.data or []
                schedule_ids = sorted({p["schedule_id"] for p in payments if p.get("schedule_id")})
                schedule_due: dict[str, str] = {}
                if schedule_ids:
                    sched_response = (
                        supabase.table("loan_schedules")
                        .select("id,due_date")
                        .in_("id", schedule_ids)
                        .execute()
                    )
                    for s in sched_response.data or []:
                        if s.get("id") and s.get("due_date"):
                            schedule_due[s["id"]] = s["due_date"]
                for p in payments:
                    due_str = schedule_due.get(p.get("schedule_id"))
                    paid_str = p.get("payment_date")
                    if not due_str or not paid_str:
                        continue
                    try:
                        paid_dt = datetime.fromisoformat(str(paid_str).replace("Z", "+00:00")).date()
                        due_dt = (
                            datetime.fromisoformat(str(due_str)).date()
                            if "T" in str(due_str)
                            else datetime.strptime(str(due_str), "%Y-%m-%d").date()
                        )
                    except Exception:
                        continue
                    if paid_dt > due_dt:
                        late_count += 1
        except Exception as exc:  # noqa: BLE001
            print(f"[migs detail] late-payment lookup failed: {exc}")

        # --- General Assembly attendance (this year) ----------------------
        attendance_present = False
        try:
            ga_response = (
                supabase.table("general_assembly_attendance")
                .select("status,meeting_date")
                .eq("member_id", mid)
                .eq("status", "Present")
                .gte("meeting_date", f"{target_year}-01-01")
                .lte("meeting_date", f"{target_year}-12-31")
                .limit(1)
                .execute()
            )
            attendance_present = bool(ga_response.data)
        except Exception as exc:  # noqa: BLE001
            print(f"[migs detail] GA lookup failed: {exc}")

        # --- Groceries availed YTD ---------------------------------------
        groceries = 0.0
        try:
            grocery_response = (
                supabase.table("GROCERY_TRANSACTIONS")
                .select("GroceryAmount,Status,TransactionDate")
                .eq("membership_number_id", mid)
                .gte("TransactionDate", f"{target_year}-01-01")
                .lte("TransactionDate", f"{target_year}-12-31T23:59:59")
                .execute()
            )
            for row in grocery_response.data or []:
                if str(row.get("Status") or "") in {"Completed", "On Credit"}:
                    groceries += float(row.get("GroceryAmount") or 0)
        except Exception as exc:  # noqa: BLE001
            print(f"[migs detail] grocery lookup failed: {exc}")

        # --- Loans from other PLIs (bookkeeper-declared) ------------------
        # None when unanswered; score_outside_loan() then defaults to 10/10.
        outside_loan_declared = _load_outside_loan_declarations(target_year).get(str(mid))

        # --- Score using the engine (safe defaults for unwired modules) ---
        result = compute_migs_score(
            cbu_added=capital,
            loan_availed=loan_availed,
            savings_balance=savings,
            late_payment_count=late_count,
            groceries_availed=groceries,
            has_outside_loan=outside_loan_declared,
            assembly_present=attendance_present,
        )
        scored = result_to_dict(result)

        # --- Persist snapshot into member_classification_temporal --------
        # Snap to the most recent Saturday (same keying as recompute-all).
        _snap_today = datetime.utcnow().date()
        _days_since_sat = (_snap_today.weekday() - 5) % 7
        _accrual_date = (_snap_today - timedelta(days=_days_since_sat)).isoformat()

        try:
            levels_resp = (
                supabase.table("classification_level")
                .select("classification_level_id,code")
                .in_("code", ["migs", "non_migs"])
                .execute()
            )
            levels = {row["code"]: row["classification_level_id"] for row in levels_resp.data or []}
            if levels:
                bp = {c["criterion"]: c["score"] for c in (scored.get("breakdown") or [])}
                _in_first_week = _snap_today.day <= 7
                _payload = {
                    "membership_number_id": mid,
                    "classification_level_id": levels.get("migs" if result.status == "MIGS Qualified" else "non_migs"),
                    "accrual_date": _accrual_date,
                    "cbu_points":        bp.get("Capital Build-Up", 0),
                    "loan_points":       bp.get("Loan Availed", 0),
                    "savings_points":    bp.get("Savings / Time Deposit", 0),
                    "payment_points":    bp.get("Payment Record (late count)", 0),
                    "grocery_points":    bp.get("Groceries Availed", 0),
                    "pli_points":        bp.get("Loans from Other PLIs", 0),
                    "attendance_points": bp.get("Assembly Attendance", 0),
                    "final_status": result.status if _in_first_week else None,
                }
                # One row per member per week, saved as a single atomic upsert: the old
                # delete-then-insert raced when the page loaded twice at once (initial load
                # + realtime refetch) and tripped the unique key.
                supabase.table("member_classification_temporal").upsert(
                    _payload, on_conflict="membership_number_id,accrual_date"
                ).execute()
        except Exception as _persist_err:
            print(f"[migs detail] snapshot persist failed (non-fatal): {_persist_err}")

        return {
            "success": True,
            "data": {
                "id": mid,
                "member_id": membership_id,
                "full_name": full_name,
                "is_bona_fide": bool(member.get("is_bona_fide")),
                "year": target_year,
                "capital": capital,
                "loan_availed": loan_availed,
                "loan_balance": loan_balance,
                "savings_balance": savings,
                "late_payment_count": late_count,
                "groceries_availed": groceries,
                # null = the bookkeeper has not been asked yet. The UI must
                # show that differently from an explicit false, even though
                # both score 10/10.
                "has_outside_loan": outside_loan_declared,
                "migs_score": scored["total_score"],
                "migs_status": scored["status"],
                "loan_multiplier": scored["loan_multiplier"],
                "can_vote": scored["can_vote"],
                "scoring_breakdown": scored["breakdown"],
                "snapshot_recorded": _accrual_date,
            },
        }
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load MIGS member detail: {err}")


@app.post("/api/migs/members/{member_key}/outside-loan")
async def declare_migs_outside_loan(member_key: str, payload: MigsOutsideLoanRequest):
    """Record the bookkeeper's 'Loans from Other PLIs' answer for a member.

    The only MIGS criterion a person supplies -- everything else is derived
    from a ledger. Stored in migs_outside_loan_declaration, one row per member
    per year, deliberately apart from the snapshot table that recompute-all
    rebuilds (see migs_outside_loan_schema.sql).

    Scoring is untouched and still lives in migs_engine.score_outside_loan():
    true -> 0 of 10, false -> 10 of 10.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    clean_key = str(member_key or "").strip()
    if not clean_key:
        raise HTTPException(status_code=400, detail="member_key is required.")

    target_year = payload.year or datetime.utcnow().year

    # member_key arrives as either the membership_id text (TTMPC-266, what the
    # UI has in the URL) or the member.id uuid. Resolve to the uuid the table
    # is keyed on -- these are two different keys that look interchangeable
    # and are not.
    try:
        member_response = (
            supabase.table("member")
            .select("id,membership_id")
            .or_(f"membership_id.eq.{clean_key},id.eq.{clean_key}")
            .limit(1)
            .execute()
        )
    except Exception:
        # `id.eq.<non-uuid>` is a cast error in Postgres, so fall back to
        # matching on membership_id alone.
        member_response = (
            supabase.table("member")
            .select("id,membership_id")
            .eq("membership_id", clean_key)
            .limit(1)
            .execute()
        )

    member_row = (member_response.data or [None])[0]
    if not member_row:
        raise HTTPException(status_code=404, detail=f"Member '{clean_key}' not found.")

    record = {
        "member_id": member_row["id"],
        "year": target_year,
        "has_outside_loan": bool(payload.has_outside_loan),
        "declared_by_email": (payload.declared_by_email or "").strip() or None,
        "note": (payload.note or "").strip() or None,
    }
    if payload.declared_by:
        record["declared_by"] = payload.declared_by

    try:
        supabase.table("migs_outside_loan_declaration").upsert(
            record, on_conflict="member_id,year"
        ).execute()
    except Exception as err:
        raise HTTPException(
            status_code=500,
            detail=(
                f"Failed to save the outside-loan declaration: {err}. "
                "If the table is missing, apply migs_outside_loan_schema.sql."
            ),
        )

    return {
        "success": True,
        "data": {
            "member_id": member_row["id"],
            "membership_id": member_row.get("membership_id"),
            "year": target_year,
            "has_outside_loan": bool(payload.has_outside_loan),
            # Mirrors score_outside_loan(); shown so the caller can confirm the
            # points moved the way they expected.
            "pli_points": 0 if payload.has_outside_loan else 10,
        },
    }


# ---------------------------------------------------------------------------
# General Assembly attendance — Secretary portal.
# Stores Present/Absent + remarks per member into attendance_logs with
# meeting_type='GA'. Each GA day is identified by (meeting_date, membership_number_id).
# The MIGS scoring engine reads from this table to award the 5pt attendance criterion.
# ---------------------------------------------------------------------------

# ============================================================================
# SECTION: Secretary — General Assembly Attendance
# Endpoints for GA roster retrieval and saving attendance records per year.
# ============================================================================


def _general_assembly_date_for_year(year: int) -> date:
    march_first = date(year, 3, 1)
    first_saturday = 1 + ((5 - march_first.weekday()) % 7)
    return date(year, 3, first_saturday + 14)


@app.get("/api/secretary/general-assembly/{year}")
async def get_ga_attendance_roster(year: int):
    """Return every coop member with their GA attendance status for the year.

    Defaults each member to status='Absent' (no row) unless an attendance_logs
    row exists with meeting_type='GA' for that member within the year.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    try:
        year_int = int(year)
        member_table = _resolve_member_table(supabase)
        # PostgREST caps every response at 1000 rows, so page through the
        # member table; a single .execute() silently dropped everyone past
        # the first 1000 (the newest members).
        members: list[dict] = []
        offset = 0
        page_size = 1000
        while True:
            members_response = (
                supabase.table(member_table)
                .select("id,membership_id,first_name,last_name")
                .order("last_name")
                .order("id")
                .range(offset, offset + page_size - 1)
                .execute()
            )
            batch = members_response.data or []
            members.extend(batch)
            if len(batch) < page_size:
                break
            offset += page_size

        # Load PDS for middle names (best-effort). Chunked: a single .in_()
        # with thousands of keys overflows the request URL.
        membership_keys = [m.get("membership_id") for m in members if m.get("membership_id")]
        pds_by_membership: dict[str, dict] = {}
        for start in range(0, len(membership_keys), 200):
            chunk = membership_keys[start:start + 200]
            try:
                pds_response = (
                    supabase.table("personal_data_sheet")
                    .select("membership_number_id,first_name,middle_name,surname,created_at")
                    .in_("membership_number_id", chunk)
                    .order("created_at", desc=True)
                    .limit(2000)
                    .execute()
                )
                for row in pds_response.data or []:
                    key = row.get("membership_number_id")
                    if key and key not in pds_by_membership:
                        pds_by_membership[key] = row
            except Exception as exc:  # noqa: BLE001
                print(f"[GA] PDS chunk lookup failed: {exc}")

        # Load existing GA rows for the year.
        ga_by_member: dict[str, dict] = {}
        try:
            ga_rows: list[dict] = []
            ga_offset = 0
            while True:
                ga_page = (
                    supabase.table("general_assembly_attendance")
                    .select("member_id,meeting_date,status,remarks,recorded_at")
                    .gte("meeting_date", f"{year_int}-01-01")
                    .lte("meeting_date", f"{year_int}-12-31")
                    .order("recorded_at", desc=True)
                    .range(ga_offset, ga_offset + 999)
                    .execute()
                ).data or []
                ga_rows.extend(ga_page)
                if len(ga_page) < 1000:
                    break
                ga_offset += 1000
            for row in ga_rows:
                mid = row.get("member_id")
                if mid and mid not in ga_by_member:
                    ga_by_member[mid] = row
        except Exception as exc:  # noqa: BLE001
            print(f"[GA] roster lookup failed: {exc}")

        rows = []
        for m in members:
            mid = m.get("id")
            pds = pds_by_membership.get(m.get("membership_id")) or {}
            first = pds.get("first_name") or m.get("first_name")
            middle = pds.get("middle_name")
            last = pds.get("surname") or pds.get("last_name") or m.get("last_name")
            full_name = " ".join(
                str(p).strip() for p in (first, middle, last) if str(p or "").strip()
            ).strip() or "Unknown Member"

            log = ga_by_member.get(mid)
            rows.append({
                "id": mid,
                "membership_id": m.get("membership_id"),
                "full_name": full_name,
                "status": (log or {}).get("status") or "Absent",
                "remarks": (log or {}).get("remarks") or "",
                "meeting_date": (log or {}).get("meeting_date"),
                "recorded_at": (log or {}).get("recorded_at"),
            })

        return {
            "success": True,
            "year": year_int,
            "default_meeting_date": _general_assembly_date_for_year(year_int).isoformat(),
            "data": rows,
            "count": len(rows),
        }
    except HTTPException as err:
        raise err
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load GA roster: {err}")


@app.post("/api/secretary/general-assembly/save")
async def save_ga_attendance(payload: dict = Body(...)):
    """Bulk-save GA attendance for a given meeting date.

    Body shape:
      {
        "meeting_date": "2026-03-15",
        "recorded_by": "<uuid|null>",
        "entries": [
          { "membership_number_id": "<member.id uuid>", "status": "Present", "remarks": "" },
          ...
        ]
      }

    Upserts one row per member into attendance_logs with meeting_type='GA'.
    Conflict key: (membership_number_id, meeting_date, meeting_type).
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    meeting_date = str(payload.get("meeting_date") or "").strip()
    if not meeting_date:
        raise HTTPException(status_code=400, detail="meeting_date is required.")
    try:
        parsed_meeting_date = datetime.strptime(meeting_date, "%Y-%m-%d").date()
    except ValueError:
        raise HTTPException(status_code=400, detail="meeting_date must be YYYY-MM-DD.")
    expected_meeting_date = _general_assembly_date_for_year(parsed_meeting_date.year)
    if parsed_meeting_date != expected_meeting_date:
        raise HTTPException(
            status_code=400,
            detail=f"General Assembly must be held on {expected_meeting_date.isoformat()} (the third Saturday of March).",
        )

    entries = payload.get("entries") or []
    if not isinstance(entries, list) or not entries:
        raise HTTPException(status_code=400, detail="entries must be a non-empty list.")

    recorded_by = payload.get("recorded_by") or None
    now_iso = datetime.utcnow().isoformat()

    inserted = 0
    updated = 0
    errors = []

    for entry in entries:
        mid = str(entry.get("membership_number_id") or "").strip()
        status = str(entry.get("status") or "").strip()
        remarks = str(entry.get("remarks") or "").strip() or None
        if not mid:
            continue
        if status not in {"Present", "Absent"}:
            errors.append({"member": mid, "error": f"invalid status '{status}'"})
            continue

        # Look up existing row (member_id + meeting_date).
        try:
            existing = (
                supabase.table("general_assembly_attendance")
                .select("id")
                .eq("member_id", mid)
                .eq("meeting_date", meeting_date)
                .limit(1)
                .execute()
            )
            existing_row = (existing.data or [None])[0]
        except Exception as exc:  # noqa: BLE001
            errors.append({"member": mid, "error": f"lookup failed: {exc}"})
            continue

        if existing_row:
            try:
                supabase.table("general_assembly_attendance").update({
                    "status": status,
                    "remarks": remarks,
                    "recorded_at": now_iso,
                    "recorded_by": recorded_by,
                    "updated_at": now_iso,
                }).eq("id", existing_row["id"]).execute()
                updated += 1
            except Exception as exc:  # noqa: BLE001
                errors.append({"member": mid, "error": f"update failed: {exc}"})
        else:
            insert_payload = {
                "member_id": mid,
                "meeting_date": meeting_date,
                "status": status,
                "remarks": remarks,
                "recorded_at": now_iso,
                "recorded_by": recorded_by,
            }
            try:
                supabase.table("general_assembly_attendance").insert(insert_payload).execute()
                inserted += 1
            except Exception as exc:  # noqa: BLE001
                errors.append({"member": mid, "error": f"insert failed: {exc}"})

    return {
        "success": True if not errors else False,
        "inserted": inserted,
        "updated": updated,
        "errors": errors,
        "meeting_date": meeting_date,
    }


# ============================================================================
# SECTION: Bookkeeper — Savings Transaction Approval
# Endpoints for listing pending savings transactions and confirming/rejecting
# them, plus cashier withdrawal transaction listing.
