# ============================================================================
# SECTION: ML — Credit Risk Prediction
# Wraps risk_model.py (HistGradientBoosting bundle, v3.3) to score a loan's
# default probability from the 21-feature contract. Feature assembly lives in
# risk_features.py; this section only fetches the loan row and persists the
# result.
# ============================================================================

class RiskPredictRequest(BaseModel):
    loan_control_number: str
    source: Literal["loans", "non_member_loans"] = "loans"
    scored_by: str | None = None  # auth.uid() of the manager, optional
    force_refresh: bool = False
    attribution_only: bool = False


def _fetch_loan_for_scoring(control_number: str, source: str) -> dict:
    """Load the loan row with the columns the feature assembly needs."""
    table = "non_member_loans" if source == "non_member_loans" else "loans"
    select_cols = (
        "control_number,member_id,loan_amount,principal_amount,term,"
        "interest_rate,monthly_amortization,application_date,disbursal_date,"
        "loan_status,application_status,raw_payload,"
        "loan_type:loan_type_id(code,name)"
        if table == "loans"
        else "control_number,loan_amount,term,application_date,raw_payload"
    )
    resp = (
        supabase.table(table)
        .select(select_cols)
        .eq("control_number", control_number)
        .limit(1)
        .execute()
    )
    rows = resp.data or []
    if not rows:
        raise HTTPException(status_code=404, detail=f"Loan {control_number} not found in {table}.")
    return rows[0]


@app.get("/api/risk/model-info")
async def get_risk_model_info():
    """Model version, operating thresholds and training metrics.

    The UI reads its band cut-offs from here rather than hardcoding them —
    thresholds are recomputed at every retraining.
    """
    try:
        return {"success": True, "data": risk_model_info()}
    except ModelNotAvailableError as e:
        raise HTTPException(status_code=503, detail=str(e))


@app.post("/api/risk/predict")
async def predict_loan_risk(payload: RiskPredictRequest):
    if supabase is None:
        raise HTTPException(status_code=503, detail="Supabase client is not configured.")

    # Return cached row unless force_refresh requested
    if not payload.force_refresh:
        cached = (
            supabase.table("risk_assessments")
            .select("*")
            .eq("loan_control_number", payload.loan_control_number)
            .limit(1)
            .execute()
        )
        if cached.data:
            cached_row = cached.data[0]
            if payload.attribution_only:
                try:
                    cached_features = cached_row.get("features_used") or {}
                    cached_probability = float(cached_row.get("risk_probability"))
                    cached_result = risk_score(cached_features)
                except (ModelNotAvailableError, KeyError, TypeError, ValueError):
                    cached_result = None
                    cached_probability = None

                same_assessment = (
                    cached_result is not None
                    and cached_result.get("model_version") == cached_row.get("model_version")
                    and cached_probability is not None
                    and round(cached_result["probability"], 4) == round(cached_probability, 4)
                )
                if not same_assessment:
                    return {
                        "cached": True,
                        **cached_row,
                        "attribution_available": False,
                        "attribution_error": "An explanation matching this saved score is unavailable.",
                        "drivers": [],
                    }

                return {
                    "cached": True,
                    **cached_row,
                    **cached_result,
                    "probability": cached_probability,
                    "attribution_available": True,
                }

            try:
                cached_result = risk_score(cached_row.get("features_used") or {})
            except (ModelNotAvailableError, KeyError, TypeError, ValueError):
                cached_result = None
            if cached_result:
                return {
                    "cached": True,
                    **cached_row,
                    "risk_label": cached_result["risk_label"],
                    "band": cached_result["band"],
                    "action": cached_result["action"],
                    "band_share": cached_result["band_share"],
                    "band_bad_rate_per_100": cached_result["band_bad_rate_per_100"],
                    "flagged": cached_result["flagged"],
                    "operating_point": cached_result["operating_point"],
                    "never_rejects": cached_result["never_rejects"],
                    "thresholds": cached_result["thresholds"],
                    "drivers": cached_result["drivers"],
                }
            return {"cached": True, **cached_row}

    loan = _fetch_loan_for_scoring(payload.loan_control_number, payload.source)
    member_id = loan.get("member_id")

    # Non-member loans carry no cooperative history or classification
    # snapshot, so the feature assembly is skipped and the loan is scored on
    # its application-level features alone.
    if payload.source == "non_member_loans":
        raw = loan.get("raw_payload") or {}
        features = {
            "LoanAmount": loan.get("loan_amount"),
            "Term": loan.get("term"),
            "MonthlyDue": (raw.get("optionalFields") or {}).get("monthly_amortization"),
            "OccTier": risk_occupation_tier(raw.get("occupation")),
            "HasSnapshot": 0,
            "HasTimeDeposit": 0,
        }
    else:
        try:
            features = risk_assemble_many(supabase, [loan])[0]
        except Exception as e:
            raise HTTPException(status_code=500, detail=f"Failed to assemble risk features: {e}")

    try:
        result = risk_score(features)
    except ModelNotAvailableError as e:
        raise HTTPException(status_code=503, detail=str(e))

    # risk_class records whether the loan is flagged for review at the model's
    # recommended (loose) operating point. It is NOT an approve/deny decision:
    # the model never rejects an application (handoff §4).
    risk_class = 1 if result["flagged"] else 0

    insert_row = {
        "loan_control_number": payload.loan_control_number,
        "member_id": member_id,
        "risk_class": risk_class,
        "risk_probability": round(result["probability"], 4),
        # The assembled input row itself (handoff §4), so the score can be
        # reproduced at audit or retraining time. Storing the driver list
        # instead would record only what the attribution reported.
        "features_used": features,
        "model_version": result.get("model_version"),
        "scored_by": payload.scored_by,
    }

    upsert_resp = (
        supabase.table("risk_assessments")
        .upsert(insert_row, on_conflict="loan_control_number")
        .execute()
    )
    saved = (upsert_resp.data or [insert_row])[0]
    return {
        "cached": False,
        **saved,
        "risk_label": result["risk_label"],
        "band": result["band"],
        "action": result["action"],
        "band_share": result["band_share"],
        "band_bad_rate_per_100": result["band_bad_rate_per_100"],
        "flagged": result["flagged"],
        "operating_point": result["operating_point"],
        "never_rejects": result["never_rejects"],
        "thresholds": result["thresholds"],
        "drivers": result["drivers"],
    }


# ============================================================================
# SECTION: Credit Risk Queue
# Feeds the Credit Risk page across staff portals. All applications remain
# visible; only applications in review are automatically scored or rescored.
# ============================================================================

# Application statuses eligible for automatic scoring. Saved scores remain
# visible after an application moves out of this set.
_CREDIT_RISK_QUEUE_STATUSES = {
    "pending",
    "for approval",
    "for review",
    "for evaluation",
    "under review",
    "submitted",
    "for bookkeeper",
    "for manager",
    "recommended for approval",
    "recommended for bod approval",
    "revised_submitted",
}

# Keep applications visible through the approval and disbursement queues,
# but remove them from Credit Risk once funds have been released.
_CREDIT_RISK_PIPELINE_STATUSES = _CREDIT_RISK_QUEUE_STATUSES | {
    "approved",
    "ready for disbursement",
    "to be disbursed",
    "awaiting disbursement",
}

# How long a risk_assessments row is trusted without rescoring. `member` has
# no updated_at, so a loan's underlying financial context (a new payment, a
# new CBU entry) can change without any timestamp we can compare against —
# a pure time-based TTL is the simplest correct answer available, matching
# every other cache in this file. A loan is rescored immediately regardless
# of this TTL if the stored model_version no longer matches the loaded
# model, so a model upgrade is never served stale.
_RISK_SCORE_STALE_AFTER = timedelta(hours=12)


def _persist_risk_scores(
    loans: list[dict],
    feature_rows: list[dict],
    results: list[dict],
) -> None:
    """Write scores to risk_assessments for audit and retraining (handoff §4).

    Best-effort and non-fatal: a logging failure must not stop a reviewer from
    seeing the queue. Upserts on the control number so rescoring a loan updates
    its row rather than accumulating duplicates.
    """
    rows = []
    for loan, features, result in zip(loans, feature_rows, results):
        control_number = loan.get("control_number")
        if not control_number:
            continue
        rows.append({
            "loan_control_number": control_number,
            "member_id": loan.get("member_id"),
            # Whether the loan crossed the active operating point — a routing
            # signal, never an approve/deny verdict.
            "risk_class": 1 if result["flagged"] else 0,
            "risk_probability": round(result["probability"], 4),
            # The assembled input row, so a score can be reproduced later.
            "features_used": features,
            "model_version": result.get("model_version"),
        })
    if not rows:
        return
    try:
        for i in range(0, len(rows), 100):
            (
                supabase.table("risk_assessments")
                .upsert(rows[i : i + 100], on_conflict="loan_control_number")
                .execute()
            )
    except Exception as err:
        print(f"[credit-risk] score logging failed (non-fatal): {err}")


@app.get("/api/credit-risk/queue")
async def get_credit_risk_queue(refresh: bool = False):
    """Return every application with its saved score; score in-review rows as needed.

    `refresh=true` forces fresh scoring for in-review applications only.
    Historical applications retain the score recorded during review.
    """
    if supabase is None:
        raise HTTPException(status_code=503, detail="Supabase client is not configured.")

    try:
        member_columns = (
            "control_number,member_id,loan_amount,principal_amount,monthly_amortization,"
            "term,interest_rate,application_status,loan_status,application_date,disbursal_date,"
            "raw_payload,"
            "member:member_id(first_name,last_name,membership_id,is_bona_fide),"
            "loan_type:loan_type_id(code,name)"
        )
        nonmember_columns = (
            "control_number,full_name,loan_amount,term,application_status,loan_status,"
            "application_date,application_type,raw_payload"
        )

        def fetch_all_rows(table: str, columns: str) -> list[dict]:
            page_size = 1000
            offset = 0
            rows: list[dict] = []
            while True:
                response = (
                    supabase.table(table)
                    .select(columns)
                    .order("application_date", desc=True)
                    .range(offset, offset + page_size - 1)
                    .execute()
                )
                page = response.data or []
                rows.extend(page)
                if len(page) < page_size:
                    return rows
                offset += page_size

        loan_rows = fetch_all_rows("loans", member_columns)
        nonmember_rows = fetch_all_rows("non_member_loans", nonmember_columns)
        for row in loan_rows:
            row["_risk_source"] = "loans"
        for row in nonmember_rows:
            row["_risk_source"] = "non_member_loans"
        all_loan_rows = loan_rows + nonmember_rows
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load loans: {err}")

    filtered: list[dict] = []
    for row in loan_rows:
        status = str(row.get("loan_status") or row.get("application_status") or "").strip().lower()
        if status in _CREDIT_RISK_QUEUE_STATUSES:
            filtered.append(row)

    # Cache-through against risk_assessments: a loan already scored recently
    # enough, by the currently-loaded model, doesn't need its features
    # reassembled or run through the model again — band/label/action are
    # cheap, pure functions of the stored probability. Only loans that are
    # unscored, stale, or scored by a different model version go through
    # the full assemble+predict path.
    model_version: str | None = None
    thresholds_used: dict | None = None
    scored_rows: list[dict] = []

    def _row_shell(loan: dict) -> dict:
        member = loan.get("member") or {}
        is_nonmember = loan.get("_risk_source") == "non_member_loans"
        member_name = (
            str(loan.get("full_name") or "").strip()
            if is_nonmember
            else f"{member.get('first_name') or ''} {member.get('last_name') or ''}".strip()
        ) or "Unknown"
        loan_type = (
            loan.get("application_type")
            or "Non-Member Loan"
            if is_nonmember
            else (loan.get("loan_type") or {}).get("name")
            or (loan.get("loan_type") or {}).get("code")
            or "N/A"
        )
        return {
            "loan_id": loan.get("control_number"),
            "source": loan.get("_risk_source") or "loans",
            "member_name": member_name,
            "membership_id": str(member.get("membership_id") or "").strip(),
            "member_type": "Non-Member" if is_nonmember else (
                "Member" if bool(member.get("is_bona_fide")) else "Non-Member"
            ),
            "loan_type": loan_type,
            "loan_amount": float(loan.get("loan_amount") or loan.get("principal_amount") or 0),
            "term_months": int(loan.get("term") or 0),
            "application_date": loan.get("application_date"),
            "application_status": loan.get("loan_status") or loan.get("application_status") or "status unavailable",
        }

    cached_by_loan: dict[str, dict] = {}
    control_numbers = [
        str(loan.get("control_number"))
        for loan in all_loan_rows
        if loan.get("control_number")
    ]
    try:
        for start in range(0, len(control_numbers), 500):
            existing_resp = (
                supabase.table("risk_assessments")
                .select("loan_control_number,risk_probability,model_version,scored_at")
                .in_("loan_control_number", control_numbers[start : start + 500])
                .execute()
            )
            for row in existing_resp.data or []:
                cached_by_loan[str(row.get("loan_control_number"))] = row
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load saved risk assessments: {err}")

    if filtered:
        current_model_version: str | None = None
        try:
            current_model_version = risk_model_version()
        except Exception:
            current_model_version = None

        # A manual refresh treats every stored score as stale.
        stale_cutoff = datetime.utcnow() + timedelta(days=1) if refresh else datetime.utcnow() - _RISK_SCORE_STALE_AFTER
        fresh_loans: list[dict] = []
        to_score: list[dict] = []
        for loan in filtered:
            cn = str(loan.get("control_number") or "")
            cached = cached_by_loan.get(cn)
            is_fresh = False
            if cached and current_model_version and cached.get("model_version") == current_model_version:
                raw_scored_at = str(cached.get("scored_at") or "")
                try:
                    parsed_ts = datetime.fromisoformat(raw_scored_at.replace("Z", "+00:00")).replace(tzinfo=None)
                    is_fresh = parsed_ts >= stale_cutoff
                except ValueError:
                    is_fresh = False
            if is_fresh:
                fresh_loans.append(loan)
            else:
                to_score.append(loan)

        try:
            if to_score:
                member_ids = [str(l.get("member_id")) for l in to_score if l.get("member_id")]
                ctx = risk_fetch_context(supabase, member_ids)
                feature_rows = risk_assemble_many(supabase, to_score, ctx=ctx)
                results = risk_score_many(feature_rows)

                for loan, features, result in zip(to_score, feature_rows, results):
                    if not model_version:
                        model_version = result.get("model_version")
                    if thresholds_used is None:
                        thresholds_used = result.get("thresholds")
                    scored_rows.append({
                        **_row_shell(loan),
                        "probability": result["probability"],
                        "band": result["band"],
                        "risk_label": result["risk_label"],
                        "action": result["action"],
                        "band_share": result["band_share"],
                        "band_bad_rate_per_100": result["band_bad_rate_per_100"],
                        "flagged": result["flagged"],
                        "operating_point": result["operating_point"],
                        "drivers": result["drivers"],
                        "model_version": result.get("model_version"),
                    })

                # Handoff §4: log every freshly-scored loan with its input row
                # and model version. Loans served from cache were already
                # logged the last time they were scored, so re-logging them
                # here would only bump scored_at without new information.
                _persist_risk_scores(to_score, feature_rows, results)

            if fresh_loans:
                thr = risk_thresholds()
                for loan in fresh_loans:
                    cn = str(loan.get("control_number") or "")
                    cached = cached_by_loan[cn]
                    probability = float(cached.get("risk_probability") or 0.0)
                    current_band = risk_band(probability, thr)
                    meta = RISK_BAND_META.get(current_band, {})
                    if not model_version:
                        model_version = cached.get("model_version")
                    if thresholds_used is None:
                        thresholds_used = thr
                    scored_rows.append({
                        **_row_shell(loan),
                        "probability": probability,
                        "band": current_band,
                        "risk_label": meta.get("label"),
                        "action": meta.get("action"),
                        "band_share": meta.get("share"),
                        "band_bad_rate_per_100": meta.get("bad_rate_per_100"),
                        "flagged": None,
                        "operating_point": None,
                        # Drivers require the live occlusion pass over the
                        # model; not recomputed for a cache hit. The full
                        # explanation is available by re-scoring the single
                        # loan (POST /api/risk/predict) if a reviewer opens it.
                        "drivers": [],
                        "model_version": cached.get("model_version"),
                        "from_cache": True,
                    })
        except ModelNotAvailableError as e:
            # Model isn't loaded — return unscored rows so the UI can still
            # show the queue with a "model unavailable" note per row.
            scored_rows = [
                {**_row_shell(loan), "probability": None, "band": None,
                 "risk_label": "Unavailable", "drivers": [], "error": str(e)}
                for loan in filtered
            ]
        except Exception as e:
            scored_rows = [
                {**_row_shell(loan), "probability": None, "band": None,
                 "risk_label": "Error", "drivers": [], "error": str(e)}
                for loan in filtered
            ]

    try:
        current_model_version = risk_model_version()
        if thresholds_used is None:
            thresholds_used = risk_thresholds()
    except ModelNotAvailableError:
        current_model_version = None

    stale_cutoff = datetime.utcnow() + timedelta(days=1) if refresh else datetime.utcnow() - _RISK_SCORE_STALE_AFTER
    for loan in nonmember_rows:
        status = str(loan.get("loan_status") or loan.get("application_status") or "").strip().lower()
        if status not in _CREDIT_RISK_QUEUE_STATUSES:
            continue
        control_number = str(loan.get("control_number") or "")
        cached = cached_by_loan.get(control_number)
        is_fresh = False
        if cached and current_model_version and cached.get("model_version") == current_model_version:
            try:
                scored_at = datetime.fromisoformat(str(cached.get("scored_at") or "").replace("Z", "+00:00"))
                is_fresh = scored_at.replace(tzinfo=None) >= stale_cutoff
            except ValueError:
                is_fresh = False

        try:
            if is_fresh:
                probability = float(cached.get("risk_probability") or 0.0)
                band = risk_band(probability, thresholds_used)
                meta = RISK_BAND_META.get(band, {})
                result_row = {
                    **_row_shell(loan),
                    "probability": probability,
                    "band": band,
                    "risk_label": meta.get("label"),
                    "action": meta.get("action"),
                    "band_share": meta.get("share"),
                    "band_bad_rate_per_100": meta.get("bad_rate_per_100"),
                    "drivers": [],
                    "model_version": cached.get("model_version"),
                    "from_cache": True,
                }
            else:
                raw = loan.get("raw_payload") or {}
                optional_fields = raw.get("optionalFields") or {}
                features = {
                    "LoanAmount": loan.get("loan_amount"),
                    "Term": loan.get("term"),
                    "MonthlyDue": optional_fields.get("monthly_amortization"),
                    "OccTier": risk_occupation_tier(raw.get("occupation")),
                    "HasSnapshot": 0,
                    "HasTimeDeposit": 0,
                }
                result = risk_score(features)
                _persist_risk_scores([loan], [features], [result])
                result_row = {
                    **_row_shell(loan),
                    "probability": result["probability"],
                    "band": result["band"],
                    "risk_label": result["risk_label"],
                    "action": result["action"],
                    "band_share": result["band_share"],
                    "band_bad_rate_per_100": result["band_bad_rate_per_100"],
                    "flagged": result["flagged"],
                    "operating_point": result["operating_point"],
                    "drivers": result["drivers"],
                    "model_version": result.get("model_version"),
                }
                model_version = model_version or result.get("model_version")
                thresholds_used = thresholds_used or result.get("thresholds")
            scored_rows.append(result_row)
        except ModelNotAvailableError as err:
            scored_rows.append({
                **_row_shell(loan),
                "probability": None,
                "band": None,
                "risk_label": "Unavailable",
                "drivers": [],
                "error": str(err),
            })
        except Exception as err:
            scored_rows.append({
                **_row_shell(loan),
                "probability": None,
                "band": None,
                "risk_label": "Error",
                "drivers": [],
                "error": str(err),
            })

    # Keep every other application in the queue using its saved, application-
    # time score, but only while it remains in the approval/disbursement
    # pipeline. Released and completed loans do not belong in this queue.
    scored_ids = {str(row.get("loan_id") or "") for row in scored_rows}
    for loan in all_loan_rows:
        status = str(loan.get("loan_status") or loan.get("application_status") or "").strip().lower()
        if status not in _CREDIT_RISK_PIPELINE_STATUSES:
            continue
        control_number = str(loan.get("control_number") or "")
        if control_number in scored_ids:
            continue
        cached = cached_by_loan.get(control_number)
        try:
            probability = float(cached.get("risk_probability")) if cached else None
        except (TypeError, ValueError):
            probability = None

        if probability is not None:
            band = risk_band(probability, thresholds_used) if thresholds_used is not None else None
            meta = RISK_BAND_META.get(band, {})
            scored_rows.append({
                **_row_shell(loan),
                "probability": probability,
                "band": band,
                "risk_label": meta.get("label") or "Previously scored",
                "action": meta.get("action"),
                "band_share": meta.get("share"),
                "band_bad_rate_per_100": meta.get("bad_rate_per_100"),
                "drivers": [],
                "model_version": cached.get("model_version"),
                "scored_at": cached.get("scored_at"),
                "from_cache": True,
            })
            model_version = model_version or cached.get("model_version")
        else:
            scored_rows.append({
                **_row_shell(loan),
                "probability": None,
                "band": None,
                "risk_label": "Not yet scored",
                "drivers": [],
            })

    # Sort by probability desc, unscored rows at the bottom.
    scored_rows.sort(key=lambda r: (r.get("probability") is None, -(r.get("probability") or 0.0)))

    payload = {
        "success": True,
        "data": {
            "server_time": datetime.utcnow().isoformat(),
            "model_version": model_version,
            "thresholds": thresholds_used,
            "count": len(scored_rows),
            "rows": scored_rows,
        },
    }
    return payload


# =============================================================================
# Membership Payments Module
# =============================================================================
# Scalable table for membership-related fees. Currently records the ₱200
# Membership Fee for applicants. The paid-up capital (₱20,000) continues to
# be tracked by personal_data_sheet.initial_paid_up_capital / capital_build_up.

MEMBERSHIP_FEE_AMOUNT = Decimal("200")
INITIAL_PAID_UP_CAPITAL_REQUIRED = Decimal("20000")


# ============================================================================
# SECTION: Cashier — Membership Payments & BOD Payment Status
# Endpoints for listing applicants, creating membership payment records, and
# BOD lookup of payment status per application.
# ============================================================================

class MembershipPaymentCreateRequest(BaseModel):
    application_id: str
    payment_type: Literal["MEMBERSHIP_FEE", "INITIAL_PAID_UP_CAPITAL"] = "MEMBERSHIP_FEE"
    amount: Decimal | None = None
    payment_method: Literal["cash", "gcash", "bank_transfer", "check", "other"] = "cash"
    reference_number: str | None = None
    processed_by: str | None = None
    processed_by_name: str | None = None
    notes: str | None = None


def _next_membership_payment_sequence(prefix: str) -> int:
    """Return the next suffix for one payment-ID namespace.

    The old implementation used the total row count, which could reuse an ID
    after deletions and collided across the fee and paid-up-capital prefixes.
    """
    try:
        resp = supabase.table("membership_payments").select("payment_id").execute()
        highest = 0
        for row in resp.data or []:
            payment_id = str(row.get("payment_id") or "")
            if not payment_id.startswith(prefix):
                continue
            suffix = payment_id[len(prefix):]
            if suffix.isdigit():
                highest = max(highest, int(suffix))
        return highest + 1
    except Exception:
        return 1


def _get_application_payment_summary(application_id: str) -> dict:
    """Aggregate verification flags for the BOD approval gate."""
    clean_id = str(application_id or "").strip()
    empty_response = {
        "application_id": None,
        "membership_fee_paid": False,
        "membership_fee_payment": None,
        "paid_up_capital_paid": False,
        "paid_up_capital_payment": None,
        "paid_up_capital_amount": 0.0,
        "paid_up_capital_satisfied": False,
        "required_paid_up_capital": float(INITIAL_PAID_UP_CAPITAL_REQUIRED),
        "required_membership_fee": float(MEMBERSHIP_FEE_AMOUNT),
    }
    if not clean_id:
        return empty_response

    def _latest_paid_payment(payment_type: str):
        try:
            resp = (
                supabase.table("membership_payments")
                .select("*")
                .eq("application_id", clean_id)
                .eq("payment_type", payment_type)
                .eq("payment_status", "paid")
                .order("payment_date", desc=True)
                .limit(1)
                .execute()
            )
            return (resp.data or [None])[0]
        except Exception:
            return None

    # 1) Membership fee
    fee_payment = _latest_paid_payment("MEMBERSHIP_FEE")
    fee_paid = fee_payment is not None

    # 2) Initial paid-up capital — primary source is a membership_payments record.
    paid_up_payment = _latest_paid_payment("INITIAL_PAID_UP_CAPITAL")
    paid_up_amount = Decimal("0")
    if paid_up_payment is not None:
        try:
            paid_up_amount = Decimal(str(paid_up_payment.get("amount") or 0))
        except Exception:
            paid_up_amount = Decimal("0")

    # Fallback to personal_data_sheet.initial_paid_up_capital for legacy applicants
    if paid_up_amount <= 0:
        try:
            try:
                app_resp = (
                    supabase.table("member_applications")
                    .select("application_id, tin_number, membership_id")
                    .eq("application_id", clean_id)
                    .limit(1)
                    .execute()
                )
            except Exception:
                app_resp = (
                    supabase.table("member_applications")
                    .select("application_id, tin_number")
                    .eq("application_id", clean_id)
                    .limit(1)
                    .execute()
                )
            app_row = (app_resp.data or [{}])[0]
            tin = str(app_row.get("tin_number") or "").strip()
            mem_no = str(app_row.get("membership_id") or "").strip()
            for lookup_key, lookup_value in (("tin_number", tin), ("membership_number_id", mem_no)):
                if paid_up_amount > 0 or not lookup_value:
                    continue
                try:
                    pds = (
                        supabase.table("personal_data_sheet")
                        .select("initial_paid_up_capital")
                        .eq(lookup_key, lookup_value)
                        .order("created_at", desc=True)
                        .limit(1)
                        .execute()
                    )
                    if pds.data:
                        v = pds.data[0].get("initial_paid_up_capital")
                        if v is not None:
                            paid_up_amount = Decimal(str(v))
                except Exception:
                    pass
        except Exception:
            pass

    paid_up_ok = paid_up_amount >= INITIAL_PAID_UP_CAPITAL_REQUIRED

    return {
        "application_id": clean_id,
        "membership_fee_paid": fee_paid,
        "membership_fee_payment": fee_payment,
        "paid_up_capital_paid": paid_up_payment is not None,
        "paid_up_capital_payment": paid_up_payment,
        "paid_up_capital_amount": float(paid_up_amount),
        "paid_up_capital_satisfied": paid_up_ok,
        "required_paid_up_capital": float(INITIAL_PAID_UP_CAPITAL_REQUIRED),
        "required_membership_fee": float(MEMBERSHIP_FEE_AMOUNT),
    }


@app.get("/api/cashier/membership-payments/applicants")
async def list_membership_applicants():
    """List applicants eligible to be charged the membership fee.
    Includes their current membership-payment status for the table UI."""
    if not supabase:
        raise HTTPException(status_code=503, detail="Supabase client is not configured.")
    try:
        base_cols = (
            "application_id, surname, first_name, middle_name, email, contact_number, "
            "application_status, attendance_status, created_at, tin_number"
        )
        try:
            apps_resp = (
                supabase.table("member_applications")
                .select(base_cols + ", membership_id")
                .order("created_at", desc=True)
                .limit(500)
                .execute()
            )
        except Exception:
            # Same fallback as _get_application_payment_summary: membership_id
            # may not exist on older schemas.
            apps_resp = (
                supabase.table("member_applications")
                .select(base_cols)
                .order("created_at", desc=True)
                .limit(500)
                .execute()
            )
        rows = apps_resp.data or []

        eligible_statuses = {"training", "1st training", "first training"}
        filtered = [
            row for row in rows
            if str(row.get("application_status") or "").strip().lower() in eligible_statuses
        ]

        # Batch what _get_application_payment_summary() does per applicant —
        # calling it in a loop cost 2–5 sequential round-trips per row.
        # Results are identical: latest paid payment per (application, type),
        # then the personal_data_sheet fallback (TIN first, then membership id).
        def _chunks(values, size=100):
            values = list(values)
            for i in range(0, len(values), size):
                yield values[i:i + size]

        app_ids = [r.get("application_id") for r in filtered if r.get("application_id")]
        latest_paid: dict[tuple[str, str], dict] = {}
        for chunk in _chunks(app_ids):
            pay_resp = (
                supabase.table("membership_payments")
                .select("*")
                .in_("application_id", chunk)
                .eq("payment_status", "paid")
                .in_("payment_type", ["MEMBERSHIP_FEE", "INITIAL_PAID_UP_CAPITAL"])
                .order("payment_date", desc=True)
                .execute()
            )
            for p in (pay_resp.data or []):
                latest_paid.setdefault((p.get("application_id"), p.get("payment_type")), p)

        def _paid_up_from_payment(p):
            try:
                return Decimal(str((p or {}).get("amount") or 0))
            except Exception:
                return Decimal("0")

        # Legacy fallback: only applicants with no recorded paid-up amount.
        needs_fallback = [
            r for r in filtered
            if _paid_up_from_payment(latest_paid.get((r.get("application_id"), "INITIAL_PAID_UP_CAPITAL"))) <= 0
        ]
        pds_latest: dict[str, dict] = {"tin_number": {}, "membership_number_id": {}}
        for lookup_key, row_key in (("tin_number", "tin_number"), ("membership_number_id", "membership_id")):
            keys = {str(r.get(row_key) or "").strip() for r in needs_fallback} - {""}
            for chunk in _chunks(keys):
                try:
                    pds_resp = (
                        supabase.table("personal_data_sheet")
                        .select(f"{lookup_key}, initial_paid_up_capital, created_at")
                        .in_(lookup_key, chunk)
                        .order("created_at", desc=True)
                        .execute()
                    )
                    for pds in (pds_resp.data or []):
                        pds_latest[lookup_key].setdefault(str(pds.get(lookup_key) or "").strip(), pds)
                except Exception:
                    pass

        results = []
        for row in filtered:
            app_id = row.get("application_id")
            fee_payment = latest_paid.get((app_id, "MEMBERSHIP_FEE"))
            paid_up_payment = latest_paid.get((app_id, "INITIAL_PAID_UP_CAPITAL"))
            paid_up_amount = _paid_up_from_payment(paid_up_payment)
            for lookup_key, row_key in (("tin_number", "tin_number"), ("membership_number_id", "membership_id")):
                lookup_value = str(row.get(row_key) or "").strip()
                if paid_up_amount > 0 or not lookup_value:
                    continue
                v = (pds_latest[lookup_key].get(lookup_value) or {}).get("initial_paid_up_capital")
                if v is not None:
                    try:
                        paid_up_amount = Decimal(str(v))
                    except Exception:
                        pass
            summary = {
                "membership_fee_paid": fee_payment is not None,
                "membership_fee_payment": fee_payment,
                "paid_up_capital_paid": paid_up_payment is not None,
                "paid_up_capital_payment": paid_up_payment,
                "paid_up_capital_amount": float(paid_up_amount),
                "paid_up_capital_satisfied": paid_up_amount >= INITIAL_PAID_UP_CAPITAL_REQUIRED,
            }
            full_name = " ".join(
                part for part in [
                    row.get("first_name"),
                    row.get("middle_name"),
                    row.get("surname"),
                ] if part
            ).strip() or "Unknown Applicant"
            results.append({
                "application_id": app_id,
                "full_name": full_name,
                "email": row.get("email"),
                "contact_number": row.get("contact_number"),
                "application_status": row.get("application_status"),
                "submitted_at": row.get("created_at"),
                "membership_fee_paid": summary.get("membership_fee_paid", False),
                "membership_fee_payment": summary.get("membership_fee_payment"),
                "paid_up_capital_paid": summary.get("paid_up_capital_paid", False),
                "paid_up_capital_payment": summary.get("paid_up_capital_payment"),
                "paid_up_capital_amount": summary.get("paid_up_capital_amount", 0),
                "paid_up_capital_satisfied": summary.get("paid_up_capital_satisfied", False),
            })

        return {"success": True, "data": results}
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to list applicants: {err}")


@app.post("/api/cashier/membership-payments")
async def create_membership_payment(payload: MembershipPaymentCreateRequest):
    """Record a membership-fee payment for an applicant."""
    if not supabase:
        raise HTTPException(status_code=503, detail="Supabase client is not configured.")

    # Verify the applicant exists and is still eligible
    try:
        app_resp = (
            supabase.table("member_applications")
            .select("application_id, surname, first_name, application_status, membership_id, tin_number")
            .eq("application_id", payload.application_id)
            .limit(1)
            .execute()
        )
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load applicant: {err}")

    rows = app_resp.data or []
    if not rows:
        raise HTTPException(status_code=404, detail="Applicant not found.")
    application = rows[0]

    status_value = str(application.get("application_status") or "").strip().lower()
    if status_value in {"member", "official member", "approved", "rejected"}:
        raise HTTPException(
            status_code=400,
            detail="Applicant is no longer eligible (already approved or rejected)."
        )

    # Reject duplicate paid payment for the same application + type
    summary = _get_application_payment_summary(payload.application_id)
    if payload.payment_type == "MEMBERSHIP_FEE" and summary.get("membership_fee_paid"):
        raise HTTPException(
            status_code=400,
            detail="Membership fee has already been recorded for this applicant."
        )
    if payload.payment_type == "INITIAL_PAID_UP_CAPITAL" and summary.get("paid_up_capital_paid"):
        raise HTTPException(
            status_code=400,
            detail="Initial Paid-Up Capital has already been recorded for this applicant."
        )

    # Default amount by type
    if payload.amount is None:
        amount = (
            INITIAL_PAID_UP_CAPITAL_REQUIRED
            if payload.payment_type == "INITIAL_PAID_UP_CAPITAL"
            else MEMBERSHIP_FEE_AMOUNT
        )
    else:
        amount = Decimal(payload.amount)
    if amount <= 0:
        raise HTTPException(status_code=400, detail="Amount must be greater than zero.")
    if payload.payment_type == "INITIAL_PAID_UP_CAPITAL" and amount < INITIAL_PAID_UP_CAPITAL_REQUIRED:
        raise HTTPException(
            status_code=400,
            detail=f"Initial Paid-Up Capital must be at least ₱{INITIAL_PAID_UP_CAPITAL_REQUIRED:,.2f}.",
        )

    # Build payment_id (TTMPCMF-### or TTMPCPC-### sequence).
    prefix = "TTMPCPC-" if payload.payment_type == "INITIAL_PAID_UP_CAPITAL" else "TTMPCMF-"
    insert_row = {
        "application_id": payload.application_id,
        "membership_number_id": application.get("membership_id"),
        "payment_type": payload.payment_type,
        "amount": float(amount),
        "payment_status": "paid",
        "payment_method": payload.payment_method,
        "reference_number": (payload.reference_number or "").strip() or None,
        "processed_by": payload.processed_by,
        "processed_by_name": (payload.processed_by_name or "").strip() or None,
        "notes": (payload.notes or "").strip() or None,
    }

    # Two cashiers can calculate the same next number concurrently. Retry only
    # a payment_id uniqueness collision; other insert errors must be reported.
    insert_resp = None
    payment_id = ""
    for _attempt in range(8):
        payment_id = build_sequence_id(prefix, _next_membership_payment_sequence(prefix))
        candidate = {**insert_row, "payment_id": payment_id}
        try:
            insert_resp = (
                supabase.table("membership_payments")
                .insert(candidate)
                .execute()
            )
            insert_row = candidate
            break
        except Exception as err:
            message = str(err)
            is_payment_id_collision = (
                "membership_payments_payment_id_key" in message
                or ("duplicate key" in message and "payment_id" in message)
            )
            if not is_payment_id_collision:
                raise HTTPException(status_code=500, detail=f"Failed to record payment: {err}")
    else:
        raise HTTPException(
            status_code=409,
            detail="Could not allocate a unique membership payment ID. Please retry.",
        )

    saved = (insert_resp.data or [insert_row])[0]
    if payload.processed_by:
        _correct_audit_actor(
            "membership_payment", payment_id,
            {"id": payload.processed_by, "email": payload.processed_by_name},
        )
    return {
        "success": True,
        "message": "Membership fee recorded successfully.",
        "data": {**saved, "receipt_no": _receipt_no_for("membership_payment", payment_id)},
    }


@app.get("/api/cashier/membership-payments")
async def list_membership_payments(
    status: str | None = None,
    payment_type: str | None = None,
    search: str | None = None,
):
    """List all membership-payment transactions for the table view."""
    if not supabase:
        raise HTTPException(status_code=503, detail="Supabase client is not configured.")
    try:
        q = supabase.table("membership_payments").select("*").order("payment_date", desc=True).limit(500)
        if status:
            q = q.eq("payment_status", status)
        if payment_type:
            q = q.eq("payment_type", payment_type)
        resp = q.execute()
        rows = resp.data or []

        # Enrich with applicant name (read each application once, by id)
        app_ids = {row.get("application_id") for row in rows if row.get("application_id")}
        applicant_lookup: dict[str, dict] = {}
        if app_ids:
            try:
                apps_resp = (
                    supabase.table("member_applications")
                    .select("application_id, surname, first_name, middle_name")
                    .in_("application_id", list(app_ids))
                    .execute()
                )
                for row in (apps_resp.data or []):
                    applicant_lookup[row.get("application_id")] = row
            except Exception:
                pass

        results = []
        for row in rows:
            app = applicant_lookup.get(row.get("application_id")) or {}
            full_name = " ".join(
                part for part in [
                    app.get("first_name"),
                    app.get("middle_name"),
                    app.get("surname"),
                ] if part
            ).strip()
            results.append({**row, "applicant_name": full_name or "Unknown Applicant"})

        if search:
            needle = search.strip().lower()
            results = [
                r for r in results
                if needle in str(r.get("applicant_name") or "").lower()
                or needle in str(r.get("payment_id") or "").lower()
                or needle in str(r.get("reference_number") or "").lower()
            ]

        return {"success": True, "data": results}
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to list payments: {err}")


# ============================================================================
# SECTION: BOD High-Value Loan Decision
# Server-side guard for BOD-only loan approval/rejection on loans > ₱500K.
# RLS alone does not prevent Manager/Cashier from writing bod_approval_payload
# (they share the same "staff update loan workflow" policy). This endpoint
# enforces role = 'bod' before any status transition or payload write.
# Threshold: EXCLUSIVE > ₱500,000 (exactly ₱500K uses the standard Manager queue).
# ============================================================================

class BodLoanDecisionRequest(BaseModel):
    loan_id: str = Field(..., min_length=1)
    decision: Literal["approved", "rejected"]
    actor_user_id: str = Field(..., min_length=1)
    # Required for approve; optional for reject
    resolution_no: str | None = None
    resolution_date: str | None = None   # ISO date string
    signed_form_path: str | None = None
    # Required for reject; optional for approve
    remarks: str | None = None

    @model_validator(mode="after")
    def validate_decision_fields(self):
        if self.decision == "approved":
            missing = []
            if not (self.resolution_no or "").strip():
                missing.append("resolution_no")
            if not (self.resolution_date or "").strip():
                missing.append("resolution_date")
            if missing:
                raise ValueError(
                    f"BOD approval requires: {', '.join(missing)}."
                )
        elif self.decision == "rejected":
            if not (self.remarks or "").strip():
                raise ValueError("BOD rejection requires a remarks/reason.")
        return self


_BOD_LOAN_THRESHOLD = 500_000  # exclusive: > 500,000 needs BOD, exactly 500,000 does not
_BOD_TERMINAL_STATUSES = {"bod rejected"}
_BOD_ELIGIBLE_STATUSES = {"recommended for bod approval"}


@app.post("/api/bod/loan-decision")
async def bod_loan_decision(payload: BodLoanDecisionRequest, background_tasks: BackgroundTasks):
    """BOD approves or rejects a high-value consolidated loan (> ₱500K).

    Guards:
    - Caller must have role='bod' in member_account.
    - Loan must be in 'recommended for bod approval' status.
    - 'bod rejected' is terminal — no further transitions allowed.
    - approve: requires resolution_no + resolution_date → resets to 'recommended for approval'.
    - reject:  requires remarks → sets 'bod rejected' (terminal).
    """
    if not supabase:
        raise HTTPException(status_code=503, detail="Supabase client is not initialized.")

    # 1. Role guard — must be exactly 'bod', derived from DB, never trusted from body.
    try:
        account_resp = (
            supabase.table("member_account")
            .select("role")
            .or_(f"user_id.eq.{payload.actor_user_id},auth_user_id.eq.{payload.actor_user_id}")
            .limit(1)
            .execute()
        )
        account = (account_resp.data or [None])[0]
        if not account or str(account.get("role") or "").strip().lower() != "bod":
            raise HTTPException(
                status_code=403,
                detail="Only BOD accounts can submit a BOD loan decision.",
            )
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Role verification failed: {e}")

    # 2. Load current loan status and amount.
    try:
        loan_resp = (
            supabase.table("loans")
            .select("control_number,loan_status,loan_amount,principal_amount")
            .eq("control_number", payload.loan_id)
            .limit(1)
            .execute()
        )
        loan = (loan_resp.data or [None])[0]
        if not loan:
            raise HTTPException(status_code=404, detail=f"Loan {payload.loan_id} not found.")
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to fetch loan: {e}")

    current_status = str(loan.get("loan_status") or "").strip().lower()

    # 3. Terminal state guard — bod rejected cannot be re-acted on.
    if current_status in _BOD_TERMINAL_STATUSES:
        raise HTTPException(
            status_code=409,
            detail=f"Loan {payload.loan_id} has already been rejected by the BOD and cannot be reprocessed.",
        )

    # 4. Must be in the BOD queue to receive a decision.
    if current_status not in _BOD_ELIGIBLE_STATUSES:
        raise HTTPException(
            status_code=409,
            detail=(
                f"Loan {payload.loan_id} is not awaiting BOD approval "
                f"(current status: '{current_status}'). "
                f"Expected: '{next(iter(_BOD_ELIGIBLE_STATUSES))}'."
            ),
        )

    # 5. Write decision.
    next_status = "recommended for approval" if payload.decision == "approved" else "bod rejected"
    bod_payload = {
        "decision": payload.decision,
        "resolution_no": (payload.resolution_no or "").strip() or None,
        "resolution_date": (payload.resolution_date or "").strip() or None,
        "signed_form_path": payload.signed_form_path or None,
        "remarks": (payload.remarks or "").strip() or None,
        "decided_by": payload.actor_user_id,
        "decided_at": datetime.utcnow().isoformat(),
    }

    try:
        update_resp = (
            supabase.table("loans")
            .update({
                "loan_status": next_status,
                "application_status": next_status,
                "bod_approval_payload": bod_payload,
            })
            .eq("control_number", payload.loan_id)
            .select("control_number,loan_status")
            .limit(1)
            .execute()
        )
        updated = (update_resp.data or [None])[0]
        if not updated:
            raise HTTPException(
                status_code=500,
                detail="Loan update returned no rows. Check RLS policy for the BOD role on the loans table.",
            )
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to write BOD decision: {e}")

    # Tell the member the Board's decision. Queued as a background task so a
    # slow or failed email never affects the decision that was just saved.
    background_tasks.add_task(
        _dispatch_loan_status_email,
        supabase,
        loan_id=payload.loan_id,
        stage="bod",
        action="approve" if payload.decision == "approved" else "reject",
        remarks=payload.remarks if payload.decision == "rejected" else None,
        actor_user_id=payload.actor_user_id,
    )

    return {
        "success": True,
        "loan_id": payload.loan_id,
        "decision": payload.decision,
        "new_status": next_status,
    }


@app.get("/api/bod/membership-approval/{application_id}/payment-status")
async def bod_get_payment_status(application_id: str):
    """Verification summary used by the BOD approval gate."""
    if not supabase:
        raise HTTPException(status_code=503, detail="Supabase client is not configured.")
    summary = _get_application_payment_summary(application_id)
    return {"success": True, "data": summary}


