# ============================================================================
# SECTION: ML — Loan Demand Forecasting Analytics
# Wraps demand_model.py (SARIMAX PKLs) to return forecasts with 80% and 95%
# confidence intervals plus historical actuals for the analytics dashboard.
# ============================================================================

@app.get("/api/analytics/demand/forecast")
async def get_loan_demand_forecast(
    loan_type: str = "consolidated",
    periods: int = 12,
    alpha: float = 0.20,
    months_from_today: int | None = None,
):
    """Return historical training series + N-month forecast for the requested loan type.

    Query params:
      - loan_type: 'consolidated' (default), 'emergency' or 'bonus'
      - periods:   number of months past training end to forecast (default 12)
      - alpha:     1 - confidence level for the band; default 0.20 → 80% CI
                   (a 95% band is always returned too, as lower95/upper95)
      - months_from_today: if set, overrides `periods` so the forecast runs
                   this many months past the current month
    """
    loan_type_clean = (loan_type or "").strip().lower()
    if loan_type_clean not in DEMAND_LOAN_TYPES:
        raise HTTPException(
            status_code=400,
            detail=f"Invalid loan_type. Supported: {', '.join(DEMAND_LOAN_TYPES)}.",
        )

    alpha_clean = max(0.01, min(float(alpha), 0.50))

    try:
        if months_from_today is not None:
            periods = demand_periods_to_cover(loan_type_clean, max(1, min(int(months_from_today), 60)))
        periods_clean = max(1, min(int(periods), 120))  # safety bounds
        payload = demand_get_forecast_payload(
            loan_type=loan_type_clean,  # type: ignore[arg-type]
            periods=periods_clean,
            alpha=alpha_clean,
        )
    except DemandModelNotAvailableError as e:
        raise HTTPException(status_code=503, detail=str(e))
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Forecast failed: {e}")

    return payload


_DEMAND_EXCLUDED_STATUS_WORDS = ("reject", "declin", "cancel", "withdraw")


def _demand_live_loans(loan_type: str, after: str | None) -> list[tuple[datetime, float]]:
    """(application_date, amount) for live loans of `loan_type` applied for
    after the `after` ISO date. Empty (not an error) if Supabase is down, so
    the chart still renders from the CSV."""
    if not supabase:
        return []
    out: list[tuple[datetime, float]] = []
    start = 0
    try:
        while True:
            query = (
                supabase.table("loans")
                .select("loan_amount,principal_amount,application_date,loan_status,loan_types:loan_type_id(name)")
                .not_.is_("application_date", "null")
            )
            if after:
                query = query.gt("application_date", after)
            batch = query.range(start, start + 999).execute().data or []
            for r in batch:
                name = str((r.get("loan_types") or {}).get("name") or "").lower()
                if loan_type not in name:
                    continue
                status = str(r.get("loan_status") or "").lower()
                if any(w in status for w in _DEMAND_EXCLUDED_STATUS_WORDS):
                    continue
                try:
                    d = datetime.fromisoformat(str(r["application_date"])[:10])
                    amount = float(r.get("loan_amount") or r.get("principal_amount") or 0)
                except (TypeError, ValueError):
                    continue
                out.append((d, amount))
            if len(batch) < 1000:
                break
            start += 1000
    except Exception as e:
        logger.warning("Live loans unavailable for demand actuals: %s", e)
        return []
    return out


@app.get("/api/analytics/demand/actuals")
def get_loan_demand_actuals(
    loan_type: str = "consolidated",
    year: int | None = None,
):
    """Monthly disbursement totals from the normalized loan CSV.

    Returns 12 rows (Jan–Dec) for the requested year with `actual` summed by
    LoanType. Months with no rows in the CSV come back with actual=0 so the
    frontend can decide whether to show that month as actual=0 or fall back to
    a forecast for future months.

    Query params:
      - loan_type: 'consolidated', 'emergency' or 'bonus' (case-insensitive)
      - year:      4-digit year; defaults to the latest year present in the CSV.

    Bonus rows come from the main CSV (LoanType=Bonus) plus the separate
    Data/bonus_loan_data.csv, where rows with no LoanType count as Bonus.

    Live loans: the CSV is the source up to its last ApplicationDate; every
    loan in the live `loans` table applied for AFTER that date is added on
    top (by application_date, rejected/cancelled excluded). The cutoff keeps
    the legacy loans that exist in both places from being counted twice, and
    lets any newly filed loan — real or a test/simulated one — show up as an
    actual without re-exporting the CSV. `live_count` per month says how many
    of that month's loans came from the live table.
    """
    lt = (loan_type or "").strip().lower()
    if lt not in ("consolidated", "emergency", "bonus"):
        raise HTTPException(status_code=400, detail="Invalid loan_type. Use 'consolidated', 'emergency' or 'bonus'.")

    # Railway only deploys src/server/, so the deployed copy under
    # Loan_Demand_Data is the one that must exist there; the analytics
    # folder (outside src/server/) is the local-dev fallback.
    _server_data_dir = _Path(__file__).resolve().parent / "Loan_Demand_Data"
    _analytics_data_dir = _REPO_ROOT / "src" / "analytics" / "Loan Demand Forecasting" / "Data"
    data_dir = _server_data_dir if (_server_data_dir / "df_modeling_export (1).csv").exists() else _analytics_data_dir
    rows = _read_csv_resilient(data_dir / "df_modeling_export (1).csv")
    if lt == "bonus":
        rows = rows + [
            {**r, "LoanType": r.get("LoanType") or "Bonus"}
            for r in _read_csv_resilient(data_dir / "bonus_loan_data.csv")
        ]
    if not rows:
        raise HTTPException(status_code=503, detail="Loan demand CSV not found on server.")

    parsed: list[tuple[int, int, float, str]] = []
    years_seen: set[int] = set()
    csv_last_date = ""
    for r in rows:
        raw_type = str(r.get("LoanType") or "").strip().lower()
        if raw_type != lt:
            continue
        date_str = str(r.get("ApplicationDate") or "").strip()
        if not date_str:
            continue
        d = None
        # ISO first; M/D/YYYY is how Excel re-saves dates in pasted data.
        for parse in (datetime.fromisoformat, lambda v: datetime.strptime(v.split(" ")[0], "%m/%d/%Y")):
            try:
                d = parse(date_str)
                break
            except ValueError:
                continue
        if d is None:
            continue
        amount = 0.0
        try:
            amount = float(str(r.get("LoanAmount") or 0).replace(",", "").replace("₱", "").strip() or 0)
        except (TypeError, ValueError):
            amount = 0.0
        parsed.append((d.year, d.month, amount, date_str))
        years_seen.add(d.year)
        csv_last_date = max(csv_last_date, d.date().isoformat())

    live_rows = _demand_live_loans(lt, after=csv_last_date or None)
    for d, amount in live_rows:
        parsed.append((d.year, d.month, amount, "live"))
        years_seen.add(d.year)

    if not years_seen:
        raise HTTPException(status_code=404, detail=f"No CSV rows for loan_type '{lt}'.")

    target_year = year if year is not None else max(years_seen)

    monthly: dict[int, float] = {m: 0.0 for m in range(1, 13)}
    count_by_month: dict[int, int] = {m: 0 for m in range(1, 13)}
    live_by_month: dict[int, int] = {m: 0 for m in range(1, 13)}
    for y, m, amt, source in parsed:
        if y == target_year:
            monthly[m] += amt
            count_by_month[m] += 1
            if source == "live":
                live_by_month[m] += 1

    return {
        "loan_type": lt,
        "year": target_year,
        "available_years": sorted(years_seen),
        "csv_through": csv_last_date or None,
        "live_loan_count": len(live_rows),
        "months": [
            {
                "period": f"{target_year}-{m:02d}",
                "actual": round(monthly[m], 2),
                "loan_count": count_by_month[m],
                "live_count": live_by_month[m],
            }
            for m in range(1, 13)
        ],
    }


# ---------------------------------------------------------------------------
# Auth backfill for imported members
# ---------------------------------------------------------------------------
# Members imported via CSV / SQL migration have rows in `member` and
# `member_account` but no corresponding `auth.users` account, so they cannot
# sign in. This endpoint scans `member_account` for rows with
# auth_user_id IS NULL, provisions a Supabase Auth user using the existing
# `_build_default_password(last_name)` convention (e.g. "Tabiolo1234"), and
# writes auth_user_id + user_id + password back onto member_account.
#
# Email resolution waterfall (first non-empty wins):
#   1. member_account.email
#   2. member.email (if column present)
#   3. personal_data_sheet.email   (joined on membership_number_id)
#   4. member_applications.email   (joined on membership_id)
# Members with no resolvable email are returned in `skipped` with reason.


def _resolve_member_email(supabase: Client, account_row: dict, member_row: dict | None) -> str:
    candidate = str(account_row.get("email") or "").strip()
    if candidate:
        return candidate.lower()

    if member_row:
        candidate = str(member_row.get("email") or "").strip()
        if candidate:
            return candidate.lower()

    membership_id = str(account_row.get("membership_id") or "").strip()
    if not membership_id:
        return ""

    try:
        pds = (
            supabase.table("personal_data_sheet")
            .select("email")
            .eq("membership_number_id", membership_id)
            .limit(1)
            .execute()
        )
        pds_row = (pds.data or [None])[0]
        if pds_row:
            candidate = str(pds_row.get("email") or "").strip()
            if candidate:
                return candidate.lower()
    except Exception:
        pass

    try:
        apps = (
            supabase.table("member_applications")
            .select("email")
            .eq("membership_id", membership_id)
            .order("created_at", desc=True)
            .limit(1)
            .execute()
        )
        app_row = (apps.data or [None])[0]
        if app_row:
            candidate = str(app_row.get("email") or "").strip()
            if candidate:
                return candidate.lower()
    except Exception:
        pass

    return ""


def _resolve_member_last_name(member_row: dict | None, account_row: dict, supabase: Client) -> str:
    if member_row:
        for key in ("surname", "last_name"):
            value = str(member_row.get(key) or "").strip()
            if value:
                return value

    membership_id = str(account_row.get("membership_id") or "").strip()
    if not membership_id:
        return ""

    try:
        pds = (
            supabase.table("personal_data_sheet")
            .select("surname,last_name")
            .eq("membership_number_id", membership_id)
            .limit(1)
            .execute()
        )
        pds_row = (pds.data or [None])[0]
        if pds_row:
            for key in ("surname", "last_name"):
                value = str(pds_row.get(key) or "").strip()
                if value:
                    return value
    except Exception:
        pass

    return ""


# ============================================================================
# SECTION: Admin — Member Auth Backfill & Legacy Linking
# One-off admin utilities: backfill auth.users for imported members, list
# unlinked legacy members, and suggest/confirm legacy→master member links.
# ============================================================================

@app.post("/api/admin/backfill-member-auth")
async def backfill_member_auth(dry_run: bool = False, limit: int | None = None):
    """Provision auth.users accounts for member_account rows missing one.

    Query params:
      - dry_run: if true, returns the list of candidates without creating
        any auth users or writing to member_account.
      - limit: optional cap on how many rows to process this run.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_service_role()

    try:
        missing_response = (
            supabase.table("member_account")
            .select("membership_id,email,role,user_id,auth_user_id")
            .is_("auth_user_id", "null")
            .execute()
        )
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to query member_account: {err}")

    candidates = list(missing_response.data or [])
    # Never (re)create a login for a member who is exiting, terminated or
    # closed -- a closed member's login was removed on purpose (Part C).
    try:
        leaving = {
            r["membership_id"]
            for r in (
                supabase.table("member")
                .select("membership_id")
                .in_("member_status", ["exiting", "terminated", "closed"])
                .execute()
            ).data or []
            if r.get("membership_id")
        }
    except Exception:
        leaving = set()
    candidates = [c for c in candidates if str(c.get("membership_id") or "").strip() not in leaving]
    if isinstance(limit, int) and limit > 0:
        candidates = candidates[:limit]

    # Build the auth.users email → UUID lookup once instead of paging
    # through every user for each candidate. Repeated pagination per row
    # triggered connection drops (WinError 10054) on larger directories.
    existing_auth_by_email: dict[str, str] = {}
    try:
        page = 1
        per_page = 1000
        while True:
            users = supabase.auth.admin.list_users(page=page, per_page=per_page)
            if not users:
                break
            for user in users:
                ue = str(getattr(user, "email", "") or "").strip().lower()
                if ue:
                    uid = _extract_user_id(user)
                    if uid:
                        existing_auth_by_email[ue] = uid
            if len(users) < per_page:
                break
            page += 1
    except Exception as err:
        raise HTTPException(status_code=502, detail=f"Failed to list auth users: {err}")

    created: list[dict[str, Any]] = []
    already_linked: list[dict[str, Any]] = []
    skipped: list[dict[str, Any]] = []

    for row in candidates:
        membership_id = str(row.get("membership_id") or "").strip()
        if not membership_id:
            skipped.append({"membership_id": None, "reason": "missing membership_id"})
            continue

        # Load matching member row for email/last-name fallback.
        member_row: dict | None = None
        try:
            member_response = (
                supabase.table("member")
                .select("*")
                .eq("membership_id", membership_id)
                .limit(1)
                .execute()
            )
            member_row = (member_response.data or [None])[0]
        except Exception:
            member_row = None

        email = _resolve_member_email(supabase, row, member_row)
        is_placeholder_email = False
        if not email:
            # Imported member with no email on file. Generate a deterministic
            # placeholder so they can sign in immediately with a temporary
            # password; staff are expected to collect the member's real email
            # later and update it via the Manage Member screen.
            placeholder_slug = membership_id.lower().replace(" ", "")
            email = f"{placeholder_slug}@ttmpc.local"
            is_placeholder_email = True

        last_name = _resolve_member_last_name(member_row, row, supabase)

        # Check whether an auth.users row already exists for this email (e.g.
        # account was provisioned earlier through another flow but never
        # linked back). If found, just link it without creating a new user.
        existing_user_id: str | None = existing_auth_by_email.get(email)

        if dry_run:
            (already_linked if existing_user_id else created).append({
                "membership_id": membership_id,
                "email": email,
                "would_link_existing": bool(existing_user_id),
                "would_reset_password": bool(existing_user_id),
                "placeholder_email": is_placeholder_email,
            })
            continue

        password: str | None = None
        if existing_user_id:
            # Orphan auth user already exists (e.g. from a half-finished prior
            # backfill). We can't delete it — DELETE on auth.users fires a
            # cleanup trigger that cascades into member/personal_data_sheet
            # and is blocked by the loans FK. Instead, reset its password to
            # the known `<LastName>1234` convention so the credentials become
            # recoverable, then link it.
            auth_user_id = existing_user_id
            link_mode = "linked_existing"
            password = _build_default_password(last_name)
            try:
                supabase.auth.admin.update_user_by_id(
                    auth_user_id,
                    {
                        "password": password,
                        "user_metadata": {
                            "membership_id": membership_id,
                            "role": row.get("role") or "Member",
                        },
                    },
                )
            except Exception as err:
                skipped.append({
                    "membership_id": membership_id,
                    "email": email,
                    "auth_user_id": auth_user_id,
                    "reason": f"auth password reset failed: {err}",
                })
                continue
        else:
            password = _build_default_password(last_name)
            try:
                created_user = supabase.auth.admin.create_user(
                    {
                        "email": email,
                        "password": password,
                        "email_confirm": True,
                        "user_metadata": {
                            "membership_id": membership_id,
                            "role": row.get("role") or "Member",
                        },
                    }
                )
            except Exception as err:
                skipped.append({
                    "membership_id": membership_id,
                    "email": email,
                    "reason": f"auth create failed: {err}",
                })
                continue

            auth_user_id = _extract_user_id(getattr(created_user, "user", None))
            if not auth_user_id:
                skipped.append({
                    "membership_id": membership_id,
                    "email": email,
                    "reason": "auth user created but no id returned",
                })
                continue
            link_mode = "created"

        update_payload: dict[str, Any] = {
            "auth_user_id": auth_user_id,
            "email": email,
            "is_temporary": True,
            # Record that the address is the generated @ttmpc.local placeholder
            # rather than a real inbox. Without this the onboarding guard has no
            # stored signal and these accounts reach the portal on a fake email.
            "is_email_dummy": is_placeholder_email,
        }
        # user_id is never touched here: this call only UPDATEs an existing
        # member_account row, whose user_id already points at the correct
        # member.id (set by the on_member_created trigger when the member row
        # was inserted). Overwriting it with the new auth UUID breaks the FK
        # to public.member, since that UUID is never a member.id.
        if password:
            update_payload["password"] = password

        try:
            supabase.table("member_account").update(update_payload).eq(
                "membership_id", membership_id
            ).execute()
        except Exception as err:
            skipped.append({
                "membership_id": membership_id,
                "email": email,
                "auth_user_id": auth_user_id,
                "reason": f"member_account update failed: {err}",
            })
            continue

        record = {
            "membership_id": membership_id,
            "email": email,
            "auth_user_id": auth_user_id,
            "mode": link_mode,
            "placeholder_email": is_placeholder_email,
        }
        if password:
            record["temporary_password"] = password
        (already_linked if link_mode == "linked_existing" else created).append(record)

    return {
        "success": True,
        "dry_run": dry_run,
        "total_missing": len(missing_response.data or []),
        "processed": len(candidates),
        "created_count": len(created),
        "linked_existing_count": len(already_linked),
        "skipped_count": len(skipped),
        "created": created,
        "linked_existing": already_linked,
        "skipped": skipped,
    }

    return {"success": True, "data": payload}


# =============================================================================
# Legacy Member Link (coop validation UI)
# =============================================================================
# The pre-migration data ("legacy") uses a different ID system: every member
# had a MasterUUID, every loan had a LoanID. We pulled those into Supabase
# but a handful of MasterUUIDs could NOT be auto-mapped to a Supabase member
# (name not in Normalized_Profiles, or blank in Cleaned_Members.csv). These
# endpoints power the bookkeeper-side screen that lets the coop manually pick
# the correct Supabase member for each pending MasterUUID, or mark it as
# having no legacy history.

import csv as _csv
from pathlib import Path as _Path

_MIGRATION_DIR = _Path(__file__).resolve().parent / "migration"
_REPO_ROOT = _Path(__file__).resolve().parent.parent.parent
_NORMALIZED_PROFILES = _REPO_ROOT / "src" / "server" / "migration" / "Normalized_Profiles.csv"
_CLEANED_MEMBERS = _MIGRATION_DIR / "Cleaned_Members.csv"
_MATRIX_CSV = _REPO_ROOT / "src" / "analytics" / "RISK Assesment" / "TTMPC_Credit_Risk" / "Master_Analytical_Matrix.csv"


def _read_csv_resilient(path: _Path) -> list[dict]:
    """Read a CSV that may have been re-saved by Excel in cp1252."""
    if not path.exists():
        return []
    try:
        with path.open("r", encoding="utf-8-sig", newline="") as fh:
            return list(_csv.DictReader(fh))
    except UnicodeDecodeError:
        with path.open("r", encoding="cp1252", newline="") as fh:
            return list(_csv.DictReader(fh))


def _load_legacy_member_index() -> dict[str, dict]:
    """Map MasterUUID -> {name, occupation, address, loan_count} from CSVs."""
    profiles: dict[str, dict] = {}
    for row in _read_csv_resilient(_NORMALIZED_PROFILES):
        mu = (row.get("membership_number_id") or "").strip()
        if not mu:
            continue
        profiles[mu] = {
            "master_uuid": mu,
            "last_name": (row.get("LastName") or "").strip(),
            "first_name": (row.get("FirstName") or "").strip(),
            "middle_name": (row.get("MiddleName") or "").strip(),
            "occupation": (row.get("Occupation") or "").strip(),
            "address": (row.get("Address") or "").strip(),
            "civil_status": (row.get("CivilStatus") or "").strip(),
            "date_of_birth": (row.get("DateOfBirth") or "").strip(),
            "loan_count": 0,
        }

    for row in _read_csv_resilient(_MATRIX_CSV):
        mu = (row.get("MasterUUID") or "").strip()
        if mu and mu in profiles:
            profiles[mu]["loan_count"] += 1

    return profiles


def _load_resolved_master_uuids() -> set[str]:
    """MasterUUIDs already wired into Supabase via Cleaned_Members.csv."""
    resolved: set[str] = set()
    for row in _read_csv_resilient(_CLEANED_MEMBERS):
        mu = (row.get("MasterUUID") or "").strip()
        if mu:
            resolved.add(mu)
    return resolved


@app.get("/api/admin/unlinked-legacy-members")
async def list_unlinked_legacy_members():
    """List MasterUUIDs from legacy data that are NOT yet bridged to a
    Supabase member, AND have not been resolved through the
    legacy_member_link validation table.

    Each entry includes legacy-side info (name, occupation, address,
    loan count) so the coop can identify who the member is.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    profiles = _load_legacy_member_index()
    resolved_via_bridge = _load_resolved_master_uuids()

    # MasterUUIDs already validated via legacy_member_link (either linked or
    # marked as having no history) should NOT be shown again.
    try:
        link_resp = (
            supabase.table("legacy_member_link")
            .select("legacy_master_uuid")
            .execute()
        )
        resolved_via_link = {
            (r.get("legacy_master_uuid") or "").strip()
            for r in (link_resp.data or [])
        }
    except Exception as err:
        # Table may not exist yet; treat as empty rather than 500.
        resolved_via_link = set()

    pending = [
        info for mu, info in profiles.items()
        if mu not in resolved_via_bridge and mu not in resolved_via_link
    ]
    pending.sort(key=lambda r: (r["last_name"].upper(), r["first_name"].upper()))

    return {"success": True, "data": {"pending": pending, "count": len(pending)}}


@app.get("/api/admin/legacy-member-link/candidates")
async def suggest_member_candidates(q: str = "", limit: int = 20):
    """Search Supabase members by name for the dropdown picker."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    query = (
        supabase.table("member")
        .select("id, membership_id, last_name, first_name, middle_name")
        .order("last_name")
        .limit(max(1, min(int(limit or 20), 100)))
    )
    needle = (q or "").strip()
    if needle:
        # Postgres ilike — Supabase chains .or_ for OR across columns.
        pattern = f"%{needle}%"
        query = query.or_(
            f"last_name.ilike.{pattern},first_name.ilike.{pattern},membership_id.ilike.{pattern}"
        )

    try:
        resp = query.execute()
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Member search failed: {err}")

    return {"success": True, "data": resp.data or []}


class _LinkLegacyMemberPayload(BaseModel):
    legacy_master_uuid: str
    member_id: str
    confirmed_by: str | None = None
    notes: str | None = None


@app.post("/api/admin/legacy-member-link/confirm")
async def confirm_legacy_member_link(payload: _LinkLegacyMemberPayload):
    """Coop confirms: this legacy MasterUUID belongs to this Supabase member.

    Inserts into legacy_member_link, then re-links any loans + payments
    in Supabase that still carry that MasterUUID to the correct member_id.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    legacy_uuid = payload.legacy_master_uuid.strip()
    member_id = payload.member_id.strip()
    if not legacy_uuid or not member_id:
        raise HTTPException(status_code=400, detail="legacy_master_uuid and member_id are required.")

    try:
        supabase.table("legacy_member_link").upsert({
            "legacy_master_uuid": legacy_uuid,
            "member_id": member_id,
            "marked_no_history": False,
            "confirmed_by": payload.confirmed_by,
            "notes": payload.notes,
        }).execute()
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to record link: {err}")

    # Re-link loans whose raw_payload.legacy_loan_uuid points to a loan
    # owned by this MasterUUID (per Master_Analytical_Matrix).
    loan_uuids_for_master: set[str] = set()
    for row in _read_csv_resilient(_MATRIX_CSV):
        if (row.get("MasterUUID") or "").strip() == legacy_uuid:
            lid = (row.get("LoanID") or "").strip()
            if lid:
                loan_uuids_for_master.add(lid)

    loans_updated = 0
    if loan_uuids_for_master:
        try:
            loans_resp = (
                supabase.table("loans")
                .select("control_number, raw_payload")
                .filter("raw_payload->>legacy", "eq", "true")
                .execute()
            )
            for row in (loans_resp.data or []):
                rp = row.get("raw_payload") or {}
                if isinstance(rp, dict) and rp.get("legacy_loan_uuid") in loan_uuids_for_master:
                    supabase.table("loans").update({"member_id": member_id}).eq(
                        "control_number", row["control_number"]
                    ).execute()
                    loans_updated += 1
        except Exception as err:
            raise HTTPException(status_code=500, detail=f"Loan relink failed: {err}")

    # Re-link legacy payments by legacy_member_uuid.
    try:
        payments_resp = (
            supabase.table("loan_payments_legacy")
            .update({"member_id": member_id})
            .eq("legacy_member_uuid", legacy_uuid)
            .execute()
        )
        payments_updated = len(payments_resp.data or [])
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Payment relink failed: {err}")

    return {
        "success": True,
        "data": {
            "legacy_master_uuid": legacy_uuid,
            "member_id": member_id,
            "loans_relinked": loans_updated,
            "payments_relinked": payments_updated,
        },
    }


class _NoHistoryPayload(BaseModel):
    legacy_master_uuid: str
    confirmed_by: str | None = None
    notes: str | None = None


@app.post("/api/admin/legacy-member-link/no-history")
async def mark_legacy_member_no_history(payload: _NoHistoryPayload):
    """Coop confirms: this legacy MasterUUID has no real legacy history
    (withdrawn placeholder, or new member only). Removes it from the
    pending list without linking to any Supabase member.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    legacy_uuid = payload.legacy_master_uuid.strip()
    if not legacy_uuid:
        raise HTTPException(status_code=400, detail="legacy_master_uuid is required.")

    try:
        supabase.table("legacy_member_link").upsert({
            "legacy_master_uuid": legacy_uuid,
            "member_id": None,
            "marked_no_history": True,
            "confirmed_by": payload.confirmed_by,
            "notes": payload.notes,
        }).execute()
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to mark no-history: {err}")


# ============================================================================
# SECTION: Account Management (BOD account admin) & member termination
# ----------------------------------------------------------------------------
# ACCOUNT_MANAGEMENT_TERMINATION_PLAN.md, Part A.
#
# One login per person: member_account.role decides which staff portal a
# member gets, while the member portal is open to every member regardless of
# role (memberlogin.jsx never checks it). So "assigning a staff role" is just
# setting role on the member's own login -- they keep their member portal.
#
# Only the BOD holding member_account.can_manage_accounts (the "account
# admin") may assign roles, grant that flag, or terminate members. Every BOD
# keeps role 'bod'; a separate role would fail the ~19 SQL helpers and every
# frontend check that look for exactly 'bod'.
#
# Termination is BOD-only and happens here; the Secretary only views it.
# ============================================================================

ALLOWED_ROLES = {
    "member",
    "bookkeeper",
    "manager",
    "cashier",
    "treasurer",
    "secretary",
    "bod",
}
STAFF_ROLES = ALLOWED_ROLES - {"member"}
_ROLE_LABELS = {"bod": "BOD"}

# Plan §8: on termination the member's CBU pays their remaining loans
# (balance + accrued penalties) first; they receive what's left. This switch
# and compute_cbu_payout() are the one place that rule lives.
CBU_PAYOUT_OFFSETS_LOANS = True


def _norm_role(value: Any) -> str:
    return str(value or "").strip().lower()


def _role_label(role: str) -> str:
    """Stored casing matches the existing rows ('Cashier', 'BOD', 'Member')."""
    clean = _norm_role(role)
    return _ROLE_LABELS.get(clean, clean.capitalize())


class AccountRoleRequest(BaseModel):
    membership_id: str
    role: str  # a staff role, or "member" to remove staff access


class AccountAdminFlagRequest(BaseModel):
    membership_id: str
    enabled: bool


class TerminateMemberRequest(BaseModel):
    membership_id: str
    reason: str
    effective_date: str | None = None
    notes: str | None = None
    # Only when CBU < loans owed (plan §8): "stay" | "exit_when_paid".
    option: str | None = None


_ACCOUNT_COLS = (
    "user_id, auth_user_id, email, role, membership_id, is_active, "
    "is_email_dummy, is_temporary, can_manage_accounts"
)


def _select_accounts(query_builder):
    """Run a member_account select, tolerating a database where
    account_management_part_a.sql hasn't been applied yet (no
    can_manage_accounts column): that just reads as "nobody is an admin"."""
    try:
        return query_builder(_ACCOUNT_COLS).execute().data or []
    except Exception:
        rows = query_builder(_ACCOUNT_COLS.replace(", can_manage_accounts", "")).execute().data or []
        for row in rows:
            row["can_manage_accounts"] = False
        return rows


def _account_by_auth_user(auth_user_id: str) -> dict | None:
    rows = _select_accounts(
        lambda cols: supabase.table("member_account").select(cols).eq("auth_user_id", auth_user_id).limit(1)
    )
    return rows[0] if rows else None


def _account_for_member(membership_id: str) -> dict | None:
    rows = _select_accounts(
        lambda cols: supabase.table("member_account").select(cols).eq("membership_id", membership_id).limit(1)
    )
    return rows[0] if rows else None


def _is_account_admin(account: dict | None) -> bool:
    return bool(account) and _norm_role(account.get("role")) == "bod" and bool(account.get("can_manage_accounts"))


def _account_admin_count() -> int:
    try:
        rows = (
            supabase.table("member_account")
            .select("membership_id")
            .eq("can_manage_accounts", True)
            .ilike("role", "bod")
            .execute()
        ).data or []
        return len(rows)
    except Exception:
        return 0


def _require_account_admin(current_user: dict) -> dict:
    account = _account_by_auth_user(current_user["id"])
    if not _is_account_admin(account):
        raise HTTPException(status_code=403, detail="Only the BOD account administrator can manage accounts.")
    return account


def _member_or_404(membership_id: str) -> dict:
    # Not resolve_member_by_ref(): it tries `id` first, and a non-UUID value
    # like TTMPC-148 makes that query error, which it swallows -> None.
    ref = str(membership_id or "").strip()
    column = "id" if len(ref) == 36 and ref.count("-") == 4 else "membership_id"
    rows = supabase.table("member").select("*").eq(column, ref).limit(1).execute().data or []
    if not rows:
        raise HTTPException(status_code=404, detail=f"Member {membership_id} not found.")
    return rows[0]


def _member_status(member: dict) -> str:
    return _norm_role(member.get("member_status")) or "active"


def _is_leaving(member: dict) -> bool:
    """Exiting, terminated or closed -- no new staff role, no new termination."""
    return _member_status(member) in ("exiting", "terminated", "closed")


# Marks the staff_termination_requests row of an 'exiting' member (plan §8,
# Option 2), so the automatic completion can find and close it.
EXITING_NOTE = "Exiting — CBU applied to loans; leaves when the remaining balance is paid."


def _cbu_withdraw(member_uuid: str, amount: Decimal, deposit_account: str, current_user: dict | None) -> dict:
    """Append a withdrawal line to the member's capital_build_up running
    balance (capital_added < 0). Same rules as the Cashier's CRJ deposit:
    date-only transaction_date, starting balance from the latest real row,
    cbu_deposit_id left to set_cbu_deposit_id()."""
    balance = _member_cbu_balance(member_uuid)
    row = (supabase.table("capital_build_up").insert({
        "member_id": member_uuid,
        "transaction_date": date.today().isoformat(),
        "starting_share_capital": decimal_to_float(money(balance)),
        "capital_added": decimal_to_float(-money(amount)),
        "ending_share_capital": decimal_to_float(money(balance - amount)),
        "deposit_account": deposit_account,
    }).execute().data or [None])[0] or {}
    if current_user and row.get("cbu_deposit_id"):
        _correct_audit_actor("cbu", row["cbu_deposit_id"], current_user)
    return row


async def _apply_cbu_loan_offset(member: dict, settlement: dict, current_user: dict) -> None:
    """Pay the member's loans from their CBU (plan §8): one 'system' loan
    payment per loan, validated through the same approval logic as every
    other payment (penalty first, schedule closed, loan status updated), one
    CBU withdrawal line for the total, and a cbu_payouts 'loan_offset' row per
    loan. No cash moves."""
    applied_rows = [d for d in settlement.get("deductions") or [] if Decimal(str(d.get("applied") or 0)) > 0]
    if not applied_rows:
        return

    # Loan payments first, the CBU withdrawal line last and only for what was
    # actually recorded -- so a failure part-way never takes CBU for a loan
    # that didn't get the payment.
    recorded: list[tuple[dict, str, Decimal]] = []
    for d in applied_rows:
        loan_id = str(d["control_number"])
        applied = money(Decimal(str(d["applied"])))
        schedules = (
            supabase.table("loan_schedules")
            .select("id,due_date,schedule_status")
            .eq("loan_id", loan_id)
            .order("due_date")
            .execute()
        ).data or []
        open_schedule = next(
            (s for s in schedules if _norm_role(s.get("schedule_status")) in {"unpaid", "pending", "overdue", "partially_paid", ""}),
            schedules[-1] if schedules else None,
        )
        if not open_schedule:
            logger.warning("CBU offset skipped for loan %s: no schedule on record", loan_id)
            continue

        reference = f"TTMPCCBU-{uuid4().hex[:10].upper()}"
        d = {**d, "_reference": reference}
        supabase.table("loan_payments").insert({
            "loan_id": loan_id,
            "schedule_id": open_schedule["id"],
            "amount_paid": decimal_to_float(applied),
            "payment_date": datetime.utcnow().isoformat(),
            "penalties": decimal_to_float(money(Decimal(str(d.get("accrued_penalty") or 0)))),
            "deficiency": 0,
            "confirmation_status": "pending_bookkeeper",
            "entered_by_role": "system",
            "payment_reference": reference,
            "transaction_reference": reference,
        }).execute()
        recorded.append((d, loan_id, applied))
        try:
            await approve_bookkeeper_payment(
                reference,
                BookkeeperPaymentDecisionRequest(
                    validated_by=current_user["id"],
                    notes="CBU offset — membership termination",
                ),
                current_user,
            )
        except Exception as exc:
            # The payment stays pending for the Bookkeeper to validate by hand;
            # the CBU is still committed to it.
            logger.warning("CBU offset payment %s for loan %s left pending: %s", reference, loan_id, exc)
            continue

        # The approval computes the balance from loan_payments only, so a
        # legacy loan (payments in loan_payments_legacy) would look unpaid.
        # When the CBU covered this loan in full, close it outright.
        if applied >= money(Decimal(str(d.get("owed") or 0))):
            supabase.table("loans").update(
                {"loan_status": "fully paid", "application_status": "fully paid"}
            ).eq("control_number", loan_id).execute()
            for s in schedules:
                if _norm_role(s.get("schedule_status")) not in {"paid", "completed", "closed"}:
                    supabase.table("loan_schedules").update({"schedule_status": "Paid"}).eq("id", s["id"]).execute()
            # A schedule the approval may have opened for the next installment.
            supabase.table("loan_schedules").update({"schedule_status": "Paid"}).eq("loan_id", loan_id).in_(
                "schedule_status", ["Unpaid", "unpaid", "pending", "overdue"]
            ).execute()

    if not recorded:
        return
    total_applied = money(sum((applied for _, _, applied in recorded), Decimal("0")))
    cbu_row = _cbu_withdraw(member["id"], total_applied, "TERMINATION_LOAN_OFFSET", current_user)
    for d, loan_id, applied in recorded:
        supabase.table("cbu_payouts").insert({
            "membership_id": member["membership_id"],
            "member_id": member["id"],
            "kind": "loan_offset",
            "amount": decimal_to_float(applied),
            "payout_date": date.today().isoformat(),
            "loan_id": loan_id,
            "loan_payment_id": d.get("_reference"),
            "deductions": [{k: v for k, v in d.items() if not k.startswith("_")}],
            "cbu_row_id": cbu_row.get("id"),
            "recorded_by": current_user["id"],
            "recorded_by_email": current_user.get("email"),
        }).execute()


def _set_sign_in_blocked(auth_user_id: str | None, blocked: bool) -> None:
    """member_account.is_active is not checked at sign-in anywhere, so a
    'deactivated' account could still log in. A Supabase Auth ban is what
    actually stops sign-in (and token refresh)."""
    if not auth_user_id:
        return
    try:
        supabase.auth.admin.update_user_by_id(
            auth_user_id, {"ban_duration": "876000h" if blocked else "none"}
        )
    except Exception as exc:
        logger.warning("Could not %s auth user %s: %s", "ban" if blocked else "unban", auth_user_id, exc)


def _audit_account_event(
    membership_id: str, action: str, before: dict, after: dict, email: str | None, current_user: dict
) -> None:
    """Write an 'account' audit row for changes the member_account trigger
    doesn't track (the admin flag), then stamp the real actor on it."""
    try:
        supabase.rpc("audit_write", {
            "p_entity_type": "account",
            "p_entity_id": membership_id,
            "p_action": action,
            "p_before": before,
            "p_after": after,
            "p_context": {"membership_id": membership_id, "email": email},
        }).execute()
    except Exception as exc:
        logger.warning("audit_write failed for account %s: %s", membership_id, exc)
        return
    _correct_audit_actor("account", membership_id, current_user)


def _member_cbu_balance(member_uuid: str) -> Decimal:
    """Latest running CBU balance, ordered the same way as the Cashier's CRJ
    deposit endpoint: date, then cbu_deposit_id's numeric suffix (never the
    random `id`), ignoring the future-dated year-end import placeholder."""
    rows = (
        supabase.table("capital_build_up")
        .select("ending_share_capital,transaction_date,cbu_deposit_id,id")
        .eq("member_id", member_uuid)
        .execute()
    ).data or []
    today = date.today().isoformat()
    rows = [r for r in rows if str(r.get("transaction_date") or "")[:10] <= today]
    if not rows:
        return Decimal("0")

    def order(row: dict) -> tuple:
        digits = "".join(ch for ch in str(row.get("cbu_deposit_id") or "") if ch.isdigit())
        return (str(row.get("transaction_date") or ""), int(digits) if digits else -1, str(row.get("id") or ""))

    latest = max(rows, key=order)
    return Decimal(str(latest.get("ending_share_capital") or 0))


async def compute_cbu_payout(membership_id: str) -> dict:
    """Plan §8 -- the single place the termination settlement rule lives.

    total_cbu      : current CBU balance
    deductions     : remaining loans (balance + accrued penalty) paid from the
                     CBU, oldest loan first, until the CBU runs out
    refundable     : what the member receives (never below 0)
    shortfall      : loans the CBU can't cover (> 0 means the member can't
                     leave yet -- plan §8 "Leftover debt")
    """
    member = _member_or_404(membership_id)
    total_cbu = money(_member_cbu_balance(member["id"]))

    loans: list[dict] = []
    if CBU_PAYOUT_OFFSETS_LOANS:
        capacity = await get_member_debt_capacity(member.get("membership_id") or member["id"])
        active = (capacity.get("data") or {}).get("active_loans") or []
        # Each renewal is a new loan row that pays off the previous one, so
        # only the latest loan per type is still owed (loan renewal rule).
        latest_by_type: dict[str, dict] = {}
        for loan in active:
            key = str(loan.get("loan_type") or "")
            when = str(loan.get("disbursal_date") or loan.get("application_date") or "")
            held = latest_by_type.get(key)
            if not held or when > str(held.get("disbursal_date") or held.get("application_date") or ""):
                latest_by_type[key] = loan
        loans = [l for l in latest_by_type.values() if Decimal(str(l.get("total_with_penalty") or 0)) > 0]
        loans.sort(key=lambda l: str(l.get("disbursal_date") or l.get("application_date") or ""))

    available = total_cbu
    deductions: list[dict] = []
    loans_owed = Decimal("0")
    for loan in loans:
        owed = money(Decimal(str(loan.get("total_with_penalty") or 0)))
        applied = money(min(owed, max(available, Decimal("0"))))
        available -= applied
        loans_owed += owed
        deductions.append({
            "control_number": loan.get("control_number"),
            "loan_type": loan.get("loan_type"),
            "remaining_balance": loan.get("remaining_balance"),
            "accrued_penalty": loan.get("accrued_penalty"),
            "owed": decimal_to_float(owed),
            "applied": decimal_to_float(applied),
        })

    applied_total = money(sum((Decimal(str(d["applied"])) for d in deductions), Decimal("0")))
    return {
        "membership_id": member.get("membership_id"),
        "member_name": resolve_member_full_name(member),
        "total_cbu": decimal_to_float(total_cbu),
        "loans_owed": decimal_to_float(money(loans_owed)),
        "applied_to_loans": decimal_to_float(applied_total),
        "refundable": decimal_to_float(money(max(total_cbu - loans_owed, Decimal("0")))),
        "shortfall": decimal_to_float(money(max(loans_owed - total_cbu, Decimal("0")))),
        "deductions": deductions,
    }


def _names_by_membership(membership_ids: list[str]) -> dict[str, dict]:
    if not membership_ids:
        return {}
    rows = (
        supabase.table("member")
        .select("id,membership_id,first_name,middle_initial,last_name,member_status")
        .in_("membership_id", membership_ids)
        .execute()
    ).data or []
    return {r["membership_id"]: r for r in rows if r.get("membership_id")}


@app.get("/api/admin/accounts/me")
def accounts_me(current_user: dict = _Depends(_get_current_user)):
    """Whether the signed-in user is the account admin (drives the BOD
    sidebar item and the page guard). Never 403s."""
    if supabase is None:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    account = _account_by_auth_user(current_user["id"]) or {}
    return {
        "success": True,
        "role": _norm_role(account.get("role")),
        "can_manage_accounts": _is_account_admin(account),
    }


@app.get("/api/admin/accounts/staff")
def accounts_list_staff(current_user: dict = _Depends(_get_current_user)):
    """Everyone whose login has a staff role, with their names."""
    if supabase is None:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_account_admin(current_user)

    accounts = _select_accounts(
        lambda cols: supabase.table("member_account").select(cols).not_.ilike("role", "member")
    )
    members = _names_by_membership([a["membership_id"] for a in accounts if a.get("membership_id")])
    rows = []
    for acct in accounts:
        role = _norm_role(acct.get("role"))
        if role not in STAFF_ROLES:
            continue
        member = members.get(acct.get("membership_id")) or {}
        rows.append({
            "membership_id": acct.get("membership_id"),
            "name": resolve_member_full_name(member) if member else acct.get("membership_id"),
            "email": acct.get("email"),
            "role": role,
            "is_active": acct.get("is_active") is not False,
            "has_login": bool(acct.get("auth_user_id")),
            "needs_setup": bool(acct.get("is_email_dummy")) or str(acct.get("email") or "").lower().endswith(_SYNTHETIC_EMAIL_DOMAIN),
            "can_manage_accounts": bool(acct.get("can_manage_accounts")),
            "is_you": acct.get("auth_user_id") == current_user["id"],
        })
    role_order = ["bod", "manager", "bookkeeper", "treasurer", "cashier", "secretary"]
    rows.sort(key=lambda r: (role_order.index(r["role"]) if r["role"] in role_order else 99, r["name"] or ""))
    return {"success": True, "data": rows}


@app.get("/api/admin/accounts/member-search")
def accounts_member_search(q: str = "", current_user: dict = _Depends(_get_current_user)):
    """Find a member to assign a role to (by name or membership ID)."""
    if supabase is None:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_account_admin(current_user)

    # Commas and parentheses would break the PostgREST or() filter syntax.
    term = _re.sub(r"[,()*%\\]", " ", str(q or "")).strip()
    if len(term) < 2:
        return {"success": True, "data": []}

    members = (
        supabase.table("member")
        .select("id,membership_id,first_name,middle_initial,last_name,member_status")
        .or_(f"membership_id.ilike.%{term}%,first_name.ilike.%{term}%,last_name.ilike.%{term}%")
        .order("last_name")
        .limit(20)
        .execute()
    ).data or []
    members = [m for m in members if m.get("membership_id") and not _is_leaving(m)]
    ids = [m["membership_id"] for m in members]
    accounts = {
        a["membership_id"]: a
        for a in _select_accounts(
            lambda cols: supabase.table("member_account").select(cols).in_("membership_id", ids or ["-"])
        )
    }
    rows = []
    for m in members:
        acct = accounts.get(m["membership_id"]) or {}
        email = acct.get("email")
        rows.append({
            "membership_id": m["membership_id"],
            "name": resolve_member_full_name(m),
            "role": _norm_role(acct.get("role")) or "member",
            "email": email,
            "has_login": bool(acct.get("auth_user_id")),
            "needs_setup": bool(acct.get("is_email_dummy")) or str(email or "").lower().endswith(_SYNTHETIC_EMAIL_DOMAIN),
        })
    return {"success": True, "data": rows}


@app.post("/api/admin/accounts/role")
def accounts_set_role(payload: AccountRoleRequest, current_user: dict = _Depends(_get_current_user)):
    """Give a member a staff role, change it, or remove it (role='member').
    It is the member's own login either way, so they keep the member portal."""
    if supabase is None:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_account_admin(current_user)

    new_role = _norm_role(payload.role)
    if new_role not in ALLOWED_ROLES:
        raise HTTPException(status_code=400, detail=f"'{payload.role}' is not a valid role.")

    membership_id = str(payload.membership_id or "").strip()
    member = _member_or_404(membership_id)
    if _is_leaving(member):
        raise HTTPException(status_code=400, detail=f"This member is {_member_status(member)}.")
    account = _account_for_member(membership_id)
    if not account:
        raise HTTPException(status_code=404, detail="This member has no account record.")
    if new_role != "member" and not account.get("auth_user_id"):
        raise HTTPException(
            status_code=400,
            detail="This member has no login yet, so a staff role wouldn't let them sign in.",
        )

    current_role = _norm_role(account.get("role"))
    if current_role == new_role:
        return {"success": True, "membership_id": membership_id, "role": new_role, "changed": False}

    is_self = account.get("auth_user_id") == current_user["id"]
    if is_self and new_role != "bod":
        raise HTTPException(status_code=400, detail="You can't remove your own BOD role.")

    # The admin flag only means something on a BOD login; it goes with the role.
    clears_flag = bool(account.get("can_manage_accounts")) and new_role != "bod"
    if clears_flag and _account_admin_count() <= 1:
        raise HTTPException(
            status_code=400,
            detail="This is the last account administrator. Give another BOD member account access first.",
        )

    update = {"role": _role_label(new_role)}
    if clears_flag:
        update["can_manage_accounts"] = False
    try:
        supabase.table("member_account").update(update).eq("membership_id", membership_id).execute()
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to update role: {err}")

    # The member_account audit trigger logged this as change_role; put the
    # real actor on it (the backend writes as service_role).
    _correct_audit_actor("account", membership_id, current_user)
    if clears_flag:
        _audit_account_event(
            membership_id, "update", {"can_manage_accounts": True}, {"can_manage_accounts": False},
            account.get("email"), current_user,
        )

    if account.get("auth_user_id"):
        try:
            supabase.auth.admin.update_user_by_id(account["auth_user_id"], {"app_metadata": {"role": new_role}})
        except Exception:
            pass

    return {"success": True, "membership_id": membership_id, "role": new_role, "changed": True}


@app.post("/api/admin/accounts/admin-flag")
def accounts_set_admin_flag(payload: AccountAdminFlagRequest, current_user: dict = _Depends(_get_current_user)):
    """Grant or remove Account Management access for a BOD member."""
    if supabase is None:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_account_admin(current_user)

    membership_id = str(payload.membership_id or "").strip()
    account = _account_for_member(membership_id)
    if not account:
        raise HTTPException(status_code=404, detail="Account not found.")
    if payload.enabled and _norm_role(account.get("role")) != "bod":
        raise HTTPException(status_code=400, detail="Only BOD members can manage accounts.")
    if bool(account.get("can_manage_accounts")) == bool(payload.enabled):
        return {"success": True, "membership_id": membership_id, "can_manage_accounts": bool(payload.enabled)}
    if not payload.enabled:
        if account.get("auth_user_id") == current_user["id"]:
            raise HTTPException(status_code=400, detail="You can't remove your own account access.")
        if _account_admin_count() <= 1:
            raise HTTPException(status_code=400, detail="There must always be at least one account administrator.")

    try:
        supabase.table("member_account").update({"can_manage_accounts": bool(payload.enabled)}).eq(
            "membership_id", membership_id
        ).execute()
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to update account access: {err}")

    _audit_account_event(
        membership_id, "update",
        {"can_manage_accounts": not payload.enabled}, {"can_manage_accounts": bool(payload.enabled)},
        account.get("email"), current_user,
    )
    return {"success": True, "membership_id": membership_id, "can_manage_accounts": bool(payload.enabled)}


@app.get("/api/admin/accounts/terminate-preview/{membership_id}")
async def accounts_terminate_preview(membership_id: str, current_user: dict = _Depends(_get_current_user)):
    """The settlement BOD sees before confirming a termination."""
    if supabase is None:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_account_admin(current_user)
    member = _member_or_404(membership_id)
    if _is_leaving(member):
        raise HTTPException(status_code=400, detail=f"This member is already {_member_status(member)}.")
    return {"success": True, "data": await compute_cbu_payout(membership_id)}


def _generate_termination_resolution_no() -> str:
    """Produce a resolution number like TERM-2026-0007 by counting existing
    terminations in the current year. Best-effort; falls back to a timestamp
    suffix if the count query fails."""
    year = date.today().year
    prefix = f"TERM-{year}-"
    try:
        rows = (
            supabase.table("staff_termination_requests")
            .select("resolution_no")
            .ilike("resolution_no", f"{prefix}%")
            .execute()
        ).data or []
        max_seq = 0
        for row in rows:
            tail = str(row.get("resolution_no") or "").split("-")[-1]
            try:
                max_seq = max(max_seq, int(tail))
            except (ValueError, TypeError):
                continue
        return f"{prefix}{max_seq + 1:04d}"
    except Exception:
        return f"{prefix}{datetime.utcnow().strftime('%m%d%H%M%S')}"


def _finalize_termination(
    *,
    member: dict,
    account: dict,
    reason: str,
    notes: str | None,
    effective_iso: str,
    cbu_total: Decimal,
    refundable: Decimal,
    actor_id: str | None,
    current_user: dict | None,
    history_row_id: Any = None,
) -> str:
    """Stamp the member terminated (or closed when there is nothing left to
    pay out), lock every way in, write the history row, notify. Returns the
    resolution number. Shared by the direct termination and the automatic
    completion of an exiting member (plan §8)."""
    membership_id = member.get("membership_id")
    resolution_no = _generate_termination_resolution_no()
    today_iso = date.today().isoformat()
    status = "terminated" if refundable > 0 else "closed"

    # 1) The member record. member_status is the authoritative flag.
    supabase.table("member").update({
        "member_status": status,
        "termination_date": effective_iso,
        "termination_resolution_number": resolution_no,
        "termination_cbu_total": decimal_to_float(money(cbu_total)),
    }).eq("membership_id", membership_id).execute()

    # 2) Lock every way in: back to Member (no staff portal), no admin flag,
    #    inactive, and banned in Supabase Auth so sign-in actually fails.
    if account:
        try:
            lock = {"role": "Member", "is_active": False}
            if account.get("can_manage_accounts"):
                lock["can_manage_accounts"] = False
            supabase.table("member_account").update(lock).eq("membership_id", membership_id).execute()
            if current_user:
                _correct_audit_actor("account", membership_id, current_user)
        except Exception as exc:
            logger.warning("Could not lock account for %s: %s", membership_id, exc)
        _set_sign_in_blocked(account.get("auth_user_id"), True)

    # 3) History (reason/notes live here) -- shown to the Secretary.
    history = {
        "resolution_no": resolution_no,
        "resolution_date": today_iso,
        "effective_date": effective_iso,
        "status": "approved",
        "decided_by": actor_id,
        "decided_at": datetime.utcnow().isoformat(),
    }
    try:
        if history_row_id is not None:
            supabase.table("staff_termination_requests").update({
                **history,
                "decision_notes": "Remaining loan balance reached ₱0 — termination completed.",
            }).eq("id", history_row_id).execute()
            row_id = history_row_id
        else:
            created = (supabase.table("staff_termination_requests").insert({
                **history,
                "member_id": membership_id,
                "member_account_id": account.get("user_id"),
                "previous_role": account.get("role"),
                "reason": reason,
                "notes": notes,
                "requested_by": actor_id,
                "requested_by_role": "bod",
                "decision_notes": "BOD-initiated termination.",
            }).execute().data or [None])[0]
            row_id = (created or {}).get("id")
        if current_user and row_id is not None:
            _correct_audit_actor("termination", str(row_id), current_user)
    except Exception as exc:
        logger.warning("Termination history row failed for %s: %s", membership_id, exc)

    # 4) Tell the Secretary (records) and, when CBU is still owed to the
    #    member, the Cashier (payout). The bell reads title/message/redirect_url.
    who = f"{resolve_member_full_name(member)} ({membership_id})"
    notices = [(
        "secretary",
        "Member terminated",
        f"{who} was terminated (resolution {resolution_no}, effective {effective_iso}).",
        "/Secretary_Records",
    )]
    if refundable > 0:
        notices.append((
            "cashier",
            "Member terminated — CBU exit payout pending",
            f"{who} was terminated. CBU to pay out: ₱{money(refundable):,.2f}.",
            "/Cashier_CBU_Exit_Payout",
        ))
    for recipient, title, message, redirect_url in notices:
        try:
            supabase.table("loan_notifications").insert({
                "recipient_role": recipient,
                "title": title,
                "message": message,
                "notification_type": "member_terminated",
                "severity": "warning",
                "redirect_url": redirect_url,
                "is_read": False,
                "created_by": actor_id,
            }).execute()
        except Exception as exc:
            logger.warning("Termination notification to %s failed: %s", recipient, exc)

    # Nothing left to pay out -> Closed now: remove the login, clear personal
    # data (Part C). Never raises.
    if status == "closed":
        _close_member(membership_id, actor_id)

    return resolution_no


@app.post("/api/admin/accounts/terminate")
async def accounts_terminate_member(payload: TerminateMemberRequest, current_user: dict = _Depends(_get_current_user)):
    """BOD account admin terminates a member (plan §8).

    CBU >= remaining loans (incl. penalties): the CBU pays the loans (CBU
    offset), the member is terminated, and the Cashier pays out the rest --
    or the member is Closed straight away when nothing is left.

    CBU < remaining loans: the member can't leave yet. `option` records what
    they chose:
      "stay"             -- nothing changes; kept in the history as withdrawn.
      "exit_when_paid"   -- CBU is applied to the loans now; the member becomes
                            'exiting' (no new loans) and the termination
                            completes automatically when the balance is ₱0.
    """
    if supabase is None:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_account_admin(current_user)

    reason = str(payload.reason or "").strip()
    if not reason:
        raise HTTPException(status_code=400, detail="Enter a reason for the termination.")
    membership_id = str(payload.membership_id or "").strip()
    member = _member_or_404(membership_id)
    if _is_leaving(member):
        raise HTTPException(
            status_code=400,
            detail=f"This member is already {_member_status(member)}.",
        )

    account = _account_for_member(membership_id) or {}
    if account.get("auth_user_id") and account.get("auth_user_id") == current_user["id"]:
        raise HTTPException(status_code=400, detail="You can't terminate your own membership here.")
    if account.get("can_manage_accounts") and _account_admin_count() <= 1:
        raise HTTPException(status_code=400, detail="This member is the last account administrator.")

    notes = (payload.notes or "").strip() or None
    effective_iso = payload.effective_date or date.today().isoformat()
    settlement = await compute_cbu_payout(membership_id)
    total_cbu = Decimal(str(settlement["total_cbu"]))
    shortfall = Decimal(str(settlement["shortfall"]))

    if shortfall > 0:
        option = str(payload.option or "").strip().lower()
        if option not in ("stay", "exit_when_paid"):
            raise HTTPException(
                status_code=409,
                detail=(
                    f"{settlement['member_name']}'s CBU (₱{total_cbu:,.2f}) doesn't cover their loans "
                    f"(₱{Decimal(str(settlement['loans_owed'])):,.2f}). Choose whether they stay or use "
                    "their CBU now and leave once the rest is paid."
                ),
            )

        if option == "stay":
            try:
                created = (supabase.table("staff_termination_requests").insert({
                    "member_id": membership_id,
                    "member_account_id": account.get("user_id"),
                    "previous_role": account.get("role"),
                    "effective_date": effective_iso,
                    "reason": reason,
                    "notes": notes,
                    "status": "rejected",
                    "requested_by": current_user["id"],
                    "requested_by_role": "bod",
                    "decided_by": current_user["id"],
                    "decision_notes": (
                        f"Withdrawn — member chose to stay. CBU ₱{total_cbu:,.2f} did not cover "
                        f"loans of ₱{Decimal(str(settlement['loans_owed'])):,.2f}."
                    ),
                    "decided_at": datetime.utcnow().isoformat(),
                }).execute().data or [None])[0]
                if created and created.get("id") is not None:
                    _correct_audit_actor("termination", str(created["id"]), current_user)
            except Exception as exc:
                logger.warning("Termination history row failed for %s: %s", membership_id, exc)
            return {"success": True, "membership_id": membership_id, "outcome": "stayed", "settlement": settlement}

        # exit_when_paid: CBU goes to the loans now, the member leaves at ₱0.
        await _apply_cbu_loan_offset(member, settlement, current_user)
        supabase.table("member").update({
            "member_status": "exiting",
            "termination_cbu_total": decimal_to_float(money(total_cbu)),
        }).eq("membership_id", membership_id).execute()
        try:
            created = (supabase.table("staff_termination_requests").insert({
                "member_id": membership_id,
                "member_account_id": account.get("user_id"),
                "previous_role": account.get("role"),
                "effective_date": effective_iso,
                "reason": reason,
                "notes": notes,
                "status": "awaiting_bod_confirmation",
                "requested_by": current_user["id"],
                "requested_by_role": "bod",
                "decision_notes": EXITING_NOTE,
            }).execute().data or [None])[0]
            if created and created.get("id") is not None:
                _correct_audit_actor("termination", str(created["id"]), current_user)
        except Exception as exc:
            logger.warning("Exit history row failed for %s: %s", membership_id, exc)
        return {
            "success": True,
            "membership_id": membership_id,
            "outcome": "exiting",
            "settlement": settlement,
            "remaining_loans": decimal_to_float(shortfall),
        }

    # CBU covers everything: offset the loans, then terminate.
    await _apply_cbu_loan_offset(member, settlement, current_user)
    resolution_no = _finalize_termination(
        member=member,
        account=account,
        reason=reason,
        notes=notes,
        effective_iso=effective_iso,
        cbu_total=total_cbu,
        refundable=Decimal(str(settlement["refundable"])),
        actor_id=current_user["id"],
        current_user=current_user,
    )
    return {
        "success": True,
        "membership_id": membership_id,
        "outcome": "terminated" if Decimal(str(settlement["refundable"])) > 0 else "closed",
        "resolution_no": resolution_no,
        "effective_date": effective_iso,
        "settlement": settlement,
    }


async def _complete_exit_if_settled(loan_id: str) -> None:
    """Plan §8, Option 2: once an exiting member's remaining loan balance
    reaches ₱0, their termination completes automatically. Called after a
    payment is validated; never raises (it must not break the payment)."""
    try:
        loan = (
            supabase.table("loans").select("member_id").eq("control_number", loan_id).limit(1).execute()
        ).data or []
        member_uuid = (loan[0] if loan else {}).get("member_id")
        if not member_uuid:
            return
        member = _member_or_404(member_uuid)
        if _member_status(member) != "exiting":
            return
        settlement = await compute_cbu_payout(member["membership_id"])
        if Decimal(str(settlement["loans_owed"])) > 0:
            return

        history = (
            supabase.table("staff_termination_requests")
            .select("id,reason,notes,effective_date,requested_by")
            .eq("member_id", member["membership_id"])
            .eq("decision_notes", EXITING_NOTE)
            .order("requested_at", desc=True)
            .limit(1)
            .execute()
        ).data or [{}]
        pending = history[0]
        _finalize_termination(
            member=member,
            account=_account_for_member(member["membership_id"]) or {},
            reason=pending.get("reason") or "",
            notes=pending.get("notes"),
            effective_iso=date.today().isoformat(),
            cbu_total=Decimal(str(member.get("termination_cbu_total") or 0)),
            refundable=Decimal(str(settlement["total_cbu"])),
            actor_id=pending.get("requested_by"),
            current_user=None,
            history_row_id=pending.get("id"),
        )
    except Exception as exc:
        logger.warning("Exit completion check failed for loan %s: %s", loan_id, exc)


@app.get("/api/admin/accounts/terminated")
async def accounts_list_terminated(current_user: dict = _Depends(_get_current_user)):
    """Members who are exiting, terminated or closed, with their termination
    details and CBU settlement position. Exiting members also show the loan
    balance they still have to pay before they can leave."""
    if supabase is None:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_account_admin(current_user)
    rows = _settlement_rows(["exiting", "terminated", "closed"])
    for row in rows:
        if row["status"] == "exiting":
            try:
                row["loans_left"] = (await compute_cbu_payout(row["membership_id"]))["loans_owed"]
            except Exception as exc:
                logger.warning("Remaining-loan lookup failed for %s: %s", row["membership_id"], exc)
    return {"success": True, "data": rows}


def _settlement_rows(statuses: list[str]) -> list[dict]:
    """Per-member settlement position: CBU at termination, applied to loans,
    paid out in cash so far, and what's still owed to the member (their live
    CBU balance -- every offset and payout is a CBU withdrawal line, so a late
    correction is picked up automatically)."""
    members = (
        supabase.table("member")
        .select(
            "id,membership_id,first_name,middle_initial,last_name,member_status,termination_date,"
            "termination_resolution_number,termination_cbu_total"
        )
        .in_("member_status", statuses)
        .order("termination_date", desc=True)
        .execute()
    ).data or []
    ids = [m["membership_id"] for m in members if m.get("membership_id")]

    moves: dict[str, dict[str, Decimal]] = {}
    reasons: dict[str, str] = {}
    closures: dict[str, dict] = {}
    if ids:
        try:
            for row in (
                supabase.table("member_closures")
                .select("membership_id,auth_deleted_at,auth_delete_error")
                .in_("membership_id", ids)
                .execute()
            ).data or []:
                closures[row["membership_id"]] = row
        except Exception:
            pass  # member_closures not migrated yet
        for row in (
            supabase.table("cbu_payouts").select("membership_id,kind,amount").in_("membership_id", ids).execute()
        ).data or []:
            bucket = moves.setdefault(row["membership_id"], {"loan_offset": Decimal("0"), "payout": Decimal("0")})
            bucket[row["kind"]] = bucket.get(row["kind"], Decimal("0")) + Decimal(str(row.get("amount") or 0))
        try:
            for row in (
                supabase.table("staff_termination_requests")
                .select("member_id,reason,status,requested_at")
                .in_("member_id", ids)
                .in_("status", ["approved", "awaiting_bod_confirmation"])
                .order("requested_at", desc=True)
                .execute()
            ).data or []:
                reasons.setdefault(row.get("member_id"), row.get("reason") or "")
        except Exception:
            pass

    rows = []
    for m in members:
        status = _member_status(m)
        mid = m.get("membership_id")
        applied = moves.get(mid, {}).get("loan_offset", Decimal("0"))
        paid = moves.get(mid, {}).get("payout", Decimal("0"))
        total = Decimal(str(m.get("termination_cbu_total") or 0))
        remaining = max(_member_cbu_balance(m["id"]), Decimal("0")) if status == "terminated" else Decimal("0")
        if status == "exiting":
            payout_label = "Paying remaining loans"
        elif status == "closed":
            payout_label = "Closed"
        elif paid > 0:
            payout_label = "Partially paid"
        else:
            payout_label = "Awaiting payout"
        rows.append({
            "membership_id": mid,
            "name": resolve_member_full_name(m),
            "status": status,
            "resolution_no": m.get("termination_resolution_number"),
            "termination_date": m.get("termination_date"),
            "reason": reasons.get(mid, ""),
            "cbu_total": decimal_to_float(total) if m.get("termination_cbu_total") is not None else None,
            "applied_to_loans": decimal_to_float(applied),
            "refundable": decimal_to_float(max(total - applied, Decimal("0"))),
            "paid_so_far": decimal_to_float(paid),
            "remaining": decimal_to_float(money(remaining)),
            "loans_left": None,
            "payout_status": payout_label,
            # Closed members only: has their login been removed yet (Part C)?
            "login_removed": bool((closures.get(mid) or {}).get("auth_deleted_at")) if status == "closed" else None,
            "login_removal_error": (closures.get(mid) or {}).get("auth_delete_error") if status == "closed" else None,
        })
    return rows


# ----------------------------------------------------------------------------
# Closing a member (plan Part C). When a member becomes Closed -- fully
# settled -- their login is removed from Supabase Auth (so the email is free
# if they re-apply) and their personal contact details are cleared. Their
# name, membership ID, date of birth (credit-risk Age feature, returning-
# member check) and every financial record are kept. member_closures is the
# permanent history row. Every step is idempotent and never raises.
# ----------------------------------------------------------------------------

# Personal fields cleared from the personal data sheet and the application.
# date_of_birth is deliberately kept (see above).
_CLOSE_PERSONAL_FIELDS = [
    "email", "contact_number", "permanent_address", "place_of_birth", "tin_number",
    "gsis_number", "spouse_name", "spouse_occupation", "spouse_date_of_birth",
    "father_name", "mother_name",
]
_CLOSE_NOMINEE_FIELDS = ["Nominee Date of Birth", "Nominee_Address"]


def _closed_email(membership_id: str) -> str:
    return f"closed-{str(membership_id).strip().lower()}{_SYNTHETIC_EMAIL_DOMAIN}"


def _clear_columns(table: str, match: dict, fields: list[str], placeholder_email: str) -> list[str]:
    """Blank `fields` on the rows matching `match`. Email columns get the
    placeholder (they may be NOT NULL / unique); everything else NULL. Falls
    back field by field when a column is missing or refuses NULL. Returns the
    'table.field' names actually cleared."""
    def value_for(field: str):
        return placeholder_email if field.lower() == "email" else None

    def query(update: dict):
        q = supabase.table(table).update(update)
        for col, val in match.items():
            q = q.ilike(col, val) if col == "email" else q.eq(col, val)
        return q.execute()

    try:
        query({f: value_for(f) for f in fields})
        return [f"{table}.{f}" for f in fields]
    except Exception:
        pass
    cleared = []
    for f in fields:
        for candidate in (value_for(f), ""):
            try:
                query({f: candidate})
                cleared.append(f"{table}.{f}")
                break
            except Exception:
                continue
    return cleared


def _close_member(membership_id: str, actor_id: str | None) -> dict:
    """Plan §12: record the closure, clear personal data, free the email on
    the account row, then delete the login. Safe to run again (retry)."""
    result = {"membership_id": membership_id, "login_removed": False, "error": None}
    try:
        member = _member_or_404(membership_id)
        existing = (
            supabase.table("member_closures").select("*").eq("membership_id", membership_id).limit(1).execute()
        ).data or []
        closure = existing[0] if existing else None
        if closure and closure.get("auth_deleted_at"):
            result["login_removed"] = True
            return result

        account = _account_for_member(membership_id) or {}
        auth_user_id = account.get("auth_user_id") or (closure or {}).get("auth_user_id")
        real_email = str(account.get("email") or "").strip().lower()
        placeholder = _closed_email(membership_id)

        # 1) The history row -- written first so a later failure still leaves it.
        if not closure:
            pds = (
                supabase.table("personal_data_sheet")
                .select("first_name,middle_name,surname,date_of_birth,email")
                .eq("membership_number_id", membership_id)
                .limit(1)
                .execute()
            ).data or [{}]
            pds = pds[0]
            if not real_email or real_email.endswith(_SYNTHETIC_EMAIL_DOMAIN):
                real_email = str(pds.get("email") or real_email).strip().lower()
            moves = (
                supabase.table("cbu_payouts").select("kind,amount").eq("membership_id", membership_id).execute()
            ).data or []
            dob = pds.get("date_of_birth")
            closure = (supabase.table("member_closures").insert({
                "membership_id": membership_id,
                "member_id": member["id"],
                "first_name": pds.get("first_name") or member.get("first_name"),
                "middle_name": pds.get("middle_name") or member.get("middle_initial"),
                "surname": pds.get("surname") or member.get("last_name"),
                "date_of_birth": str(dob)[:10] if dob else None,
                "resolution_no": member.get("termination_resolution_number"),
                "termination_date": str(member.get("termination_date") or "")[:10] or None,
                "cbu_total": member.get("termination_cbu_total"),
                "cbu_applied_to_loans": decimal_to_float(sum(
                    (Decimal(str(m.get("amount") or 0)) for m in moves if m.get("kind") == "loan_offset"), Decimal("0"))),
                "cbu_paid_out": decimal_to_float(sum(
                    (Decimal(str(m.get("amount") or 0)) for m in moves if m.get("kind") == "payout"), Decimal("0"))),
                "auth_user_id": auth_user_id,
                "closed_by": actor_id,
            }).execute().data or [None])[0] or {}

        # 2) Clear personal data in the coop's own tables.
        cleared: list[str] = list(closure.get("cleared_fields") or [])

        def note(fields: list[str]):
            for f in fields:
                if f not in cleared:
                    cleared.append(f)

        note(_clear_columns("personal_data_sheet", {"membership_number_id": membership_id}, _CLOSE_PERSONAL_FIELDS, placeholder))
        note(_clear_columns("member_applications", {"membership_id": membership_id}, _CLOSE_PERSONAL_FIELDS, placeholder))
        if real_email and not real_email.endswith(_SYNTHETIC_EMAIL_DOMAIN):
            # Applications filed before a membership ID was assigned.
            note(_clear_columns("member_applications", {"email": real_email}, _CLOSE_PERSONAL_FIELDS, placeholder))
            for table, column in (("loan_email_log", "recipient_email"), ("attendance_logs", "member_email")):
                try:
                    supabase.table(table).update({column: None}).ilike(column, real_email).execute()
                    note([f"{table}.{column}"])
                except Exception:
                    pass
        try:
            supabase.table("loans").update({"user_email": None}).eq("member_id", member["id"]).execute()
            note(["loans.user_email"])
        except Exception:
            pass
        note(_clear_columns("Savings_Transactions", {"membership_number_id": membership_id}, _CLOSE_NOMINEE_FIELDS, placeholder))

        # Profile photo: the profiles row and the files under profiles/<login id>/.
        if auth_user_id:
            try:
                supabase.table("profiles").update({"avatar_url": None}).eq("id", auth_user_id).execute()
                folder = f"profiles/{auth_user_id}"
                files = supabase.storage.from_("Supporting_Documents").list(folder) or []
                paths = [f"{folder}/{f['name']}" for f in files if f.get("name")]
                if paths:
                    supabase.storage.from_("Supporting_Documents").remove(paths)
                note(["profiles.avatar_url"])
            except Exception as exc:
                logger.warning("Avatar cleanup failed for %s: %s", membership_id, exc)

        # 3) Free the email on the account row (keep the row and auth_user_id,
        #    so audit history still resolves the person's name).
        try:
            supabase.table("member_account").update({
                "email": placeholder,
                "pending_email": None,
                "password": None,
                "is_active": False,
                "role": "Member",
                "can_manage_accounts": False,
            }).eq("membership_id", membership_id).execute()
            note(["member_account.email"])
        except Exception as exc:
            logger.warning("Account row cleanup failed for %s: %s", membership_id, exc)

        supabase.table("member_closures").update({"cleared_fields": cleared}).eq(
            "membership_id", membership_id
        ).execute()

        # 4) Delete the login. The auth-delete trigger leaves members alone
        #    (account_management_part_c.sql).
        if not auth_user_id:
            supabase.table("member_closures").update({
                "auth_deleted_at": datetime.utcnow().isoformat(),
                "auth_delete_error": None,
            }).eq("membership_id", membership_id).execute()
            result["login_removed"] = True
            return result
        try:
            supabase.auth.admin.delete_user(auth_user_id)
            deleted = True
        except Exception as exc:
            text = str(exc).lower()
            # Already gone (e.g. an earlier attempt succeeded) counts as done.
            deleted = "not found" in text or "user_not_found" in text
            if not deleted:
                result["error"] = str(exc)
        supabase.table("member_closures").update({
            "auth_deleted_at": datetime.utcnow().isoformat() if deleted else None,
            "auth_delete_error": None if deleted else result["error"],
        }).eq("membership_id", membership_id).execute()
        result["login_removed"] = deleted
    except Exception as exc:
        logger.warning("Closing member %s failed: %s", membership_id, exc)
        result["error"] = str(exc)
    return result


@app.post("/api/admin/accounts/closures/{membership_id}/retry")
def accounts_retry_closure(membership_id: str, current_user: dict = _Depends(_get_current_user)):
    """Re-run the closing steps for a Closed member whose login removal failed."""
    if supabase is None:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_account_admin(current_user)
    member = _member_or_404(membership_id)
    if _member_status(member) != "closed":
        raise HTTPException(status_code=400, detail="Only closed members can have their login removed.")
    outcome = _close_member(member["membership_id"], current_user["id"])
    if not outcome["login_removed"]:
        raise HTTPException(status_code=502, detail=f"Login removal failed again: {outcome['error']}")
    return {"success": True, "data": outcome}


@app.get("/api/bod/membership-approval/{application_id}/returning-member")
def bod_returning_member_check(application_id: str, current_user: dict = _Depends(_get_current_user)):
    """Is this applicant a former member? Matches closed members by surname +
    first name, and date of birth when both have one. Information only."""
    if supabase is None:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role not in ("bod", "secretary"):
        raise HTTPException(status_code=403, detail="Not allowed.")

    app_rows = (
        supabase.table("member_applications")
        .select("first_name,surname,date_of_birth")
        .eq("application_id", application_id)
        .limit(1)
        .execute()
    ).data or []
    if not app_rows:
        return {"success": True, "data": []}
    applicant = app_rows[0]
    surname = str(applicant.get("surname") or "").strip()
    first = str(applicant.get("first_name") or "").strip()
    if not surname or not first:
        return {"success": True, "data": []}

    rows = (
        supabase.table("member_closures")
        .select("membership_id,first_name,middle_name,surname,date_of_birth,closed_at,resolution_no")
        .ilike("surname", surname)
        .ilike("first_name", first)
        .execute()
    ).data or []
    applicant_dob = str(applicant.get("date_of_birth") or "")[:10]
    matches = []
    for r in rows:
        closed_dob = str(r.get("date_of_birth") or "")[:10]
        if applicant_dob and closed_dob and applicant_dob != closed_dob:
            continue  # same name, different person
        matches.append({
            "membership_id": r.get("membership_id"),
            "name": " ".join(p for p in (r.get("first_name"), r.get("middle_name"), r.get("surname")) if p),
            "closed_at": r.get("closed_at"),
            "resolution_no": r.get("resolution_no"),
            "date_of_birth_matches": bool(applicant_dob and closed_dob),
        })
    return {"success": True, "data": matches}


# ----------------------------------------------------------------------------
# Cashier: CBU payout to terminated members (plan §7). No vault movement --
# the Treasurer adjusts the vault by hand, as for every CBU transaction.
# ----------------------------------------------------------------------------

class CbuPayoutRequest(BaseModel):
    membership_id: str
    amount: Decimal = Field(..., gt=0)
    reference: str | None = None
    notes: str | None = None


def _require_cashier(current_user: dict) -> None:
    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role != "cashier":
        raise HTTPException(status_code=403, detail="Only the Cashier can record CBU payouts.")


@app.get("/api/cashier/cbu-payouts")
def cashier_list_cbu_payouts(current_user: dict = _Depends(_get_current_user)):
    """Terminated members still owed CBU, plus the recent payout history."""
    if supabase is None:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_cashier(current_user)

    rows = _settlement_rows(["terminated", "closed"])
    history = (
        supabase.table("cbu_payouts")
        .select("id,membership_id,amount,payout_date,reference,notes,recorded_by_email,created_at")
        .eq("kind", "payout")
        .order("created_at", desc=True)
        .limit(100)
        .execute()
    ).data or []
    names = {r["membership_id"]: r["name"] for r in rows}
    for h in history:
        h["name"] = names.get(h.get("membership_id"), h.get("membership_id"))
    return {
        "success": True,
        "pending": [r for r in rows if r["status"] == "terminated" and r["remaining"] > 0],
        "history": history,
    }


@app.post("/api/cashier/cbu-payouts")
def cashier_record_cbu_payout(payload: CbuPayoutRequest, current_user: dict = _Depends(_get_current_user)):
    """Record cash handed to a terminated member from their CBU. Partial
    payouts are allowed; the member becomes Closed when nothing is left."""
    if supabase is None:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")
    _require_cashier(current_user)

    membership_id = str(payload.membership_id or "").strip()
    member = _member_or_404(membership_id)
    if _member_status(member) != "terminated":
        raise HTTPException(status_code=400, detail="CBU is only paid out to terminated members.")

    amount = money(Decimal(str(payload.amount)))
    remaining = money(max(_member_cbu_balance(member["id"]), Decimal("0")))
    if amount > remaining:
        raise HTTPException(
            status_code=400,
            detail=f"Amount ₱{amount:,.2f} is more than the ₱{remaining:,.2f} still owed to this member.",
        )

    reference = (payload.reference or "").strip() or f"CBUPO-{date.today():%Y%m%d}-{uuid4().hex[:6].upper()}"
    if (supabase.table("cbu_payouts").select("id").eq("reference", reference).limit(1).execute().data or []):
        raise HTTPException(status_code=409, detail=f"A payout with reference {reference} was already recorded.")

    cbu_row = _cbu_withdraw(member["id"], amount, "TERMINATION_PAYOUT", current_user)
    payout = (supabase.table("cbu_payouts").insert({
        "membership_id": membership_id,
        "member_id": member["id"],
        "kind": "payout",
        "amount": decimal_to_float(amount),
        "payout_date": date.today().isoformat(),
        "reference": reference,
        "notes": (payload.notes or "").strip() or None,
        "cbu_row_id": cbu_row.get("id"),
        "recorded_by": current_user["id"],
        "recorded_by_email": current_user.get("email"),
    }).execute().data or [None])[0]

    remaining_after = money(remaining - amount)
    closed = remaining_after <= 0
    if closed:
        supabase.table("member").update({"member_status": "closed"}).eq("membership_id", membership_id).execute()
        # Fully settled -> remove the login, clear personal data (Part C).
        # Runs after the payout is saved and never raises.
        _close_member(membership_id, current_user["id"])

    return {
        "success": True,
        "data": {
            "reference": reference,
            "membership_id": membership_id,
            "name": resolve_member_full_name(member),
            "amount": decimal_to_float(amount),
            "remaining_before": decimal_to_float(remaining),
            "remaining_after": decimal_to_float(max(remaining_after, Decimal("0"))),
            "closed": closed,
            "payout_date": (payout or {}).get("payout_date") or date.today().isoformat(),
            "recorded_by": current_user.get("email"),
            "receipt_no": _receipt_no_for("cbu_payout", (payout or {}).get("id")),
        },
    }


# =============================================================================
# Account Security: email + password change with OTP confirmation
# =============================================================================

import re as _re

_EMAIL_RE_AS = _re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")
_OTP_TTL_MIN = max(1, _OTP_TTL_SECONDS // 60)


def _validate_password_strength(pw: str) -> str | None:
    if not pw or len(pw) < 8:
        return "Password must be at least 8 characters."
    if len(pw) > 128:
        return "Password is too long."
    return None


def _verify_current_password(email: str, password: str) -> bool:
    """Verify a user's current password via Supabase signInWithPassword.
    Uses a short-lived anon client so we don't taint the service-role session."""
    anon_key = os.environ.get("VITE_SUPABASE_ANON_KEY")
    if not (url and anon_key):
        raise HTTPException(status_code=500, detail="Auth not configured")
    try:
        check_client: Client = create_client(url, anon_key)
        resp = check_client.auth.sign_in_with_password({"email": email, "password": password})
        return bool(getattr(resp, "user", None))
    except Exception:
        return False


def _get_member_account_by_auth_user(auth_user_id: str) -> dict[str, Any] | None:
    """Fetch the member_account row for an authenticated user.

    Columns are listed explicitly and must all exist on the table. The previous
    version selected "id, member_id" -- neither of which member_account has
    (its key is membership_id) -- so PostgREST rejected the whole query, the
    except below swallowed it, and every caller saw None. For the onboarding
    gate that read as "nothing outstanding", opening the portal to accounts
    still on their temporary password.

    Raising on failure rather than returning None keeps that class of bug
    loud: a security gate must not fail open because a query broke.
    """
    if not supabase:
        return None
    # One retry: the shared supabase client intermittently drops an HTTP/2
    # connection ("Server disconnected"), which is not a real failure. Still
    # fails closed (500) if the retry also fails.
    last_exc: Exception | None = None
    for attempt in range(2):
        try:
            resp = (
                supabase.table("member_account")
                # membership_id and password are needed by the security-status gate:
                # the former to look up the profile row, the latter because a
                # lingering plaintext bootstrap password means the member has never
                # set one of their own.
                .select(
                    "user_id, auth_user_id, membership_id, email, is_temporary, "
                    "is_email_dummy, pending_email, password"
                )
                .eq("auth_user_id", auth_user_id)
                .limit(1)
                .execute()
            )
            return resp.data[0] if resp.data else None
        except Exception as exc:
            last_exc = exc
            logger.warning("member_account lookup failed (attempt %d/2): %r", attempt + 1, exc)
    raise HTTPException(
        status_code=500,
        detail=f"Could not read account record: {last_exc}",
    )


def _send_otp_or_500(*, to_email: str, code: str, purpose: str) -> None:
    result = _send_otp_email(
        to_email=to_email,
        code=code,
        purpose=purpose,  # type: ignore[arg-type]
        ttl_minutes=_OTP_TTL_MIN,
    )
    if not result.success:
        raise HTTPException(
            status_code=502,
            detail=f"Could not send verification email: {result.error or 'unknown error'}",
        )


# ----- Request / Response models --------------------------------------------

# ============================================================================
# SECTION: Account Settings — Email & Password Change (with OTP)
# Self-service endpoints for changing email/password, including OTP request,
# verification, and direct password change flows.
# ============================================================================

class EmailChangeRequestOtp(BaseModel):
    new_email: str = Field(..., min_length=5, max_length=254)

    @model_validator(mode="after")
    def _normalize(self):
        e = (self.new_email or "").strip().lower()
        if not _EMAIL_RE_AS.match(e):
            raise ValueError("Invalid email format")
        self.new_email = e
        return self


class EmailChangeConfirm(BaseModel):
    code: str = Field(..., min_length=6, max_length=6)


class PasswordChangeDirect(BaseModel):
    current_password: str
    new_password: str = Field(..., min_length=8, max_length=128)


class PasswordChangeRequestOtp(BaseModel):
    """Recovery path — user forgot their current password. Identity is
    proven by access to their email inbox (OTP) instead."""
    new_password: str = Field(..., min_length=8, max_length=128)


class PasswordChangeConfirm(BaseModel):
    code: str = Field(..., min_length=6, max_length=6)


class PasswordChangeSendCode(BaseModel):
    """Recovery path v2 — issue an OTP without requiring the new password
    up front. The new password is submitted together with the code at
    verify time."""
    pass


class PasswordChangeVerifyAndSet(BaseModel):
    code: str = Field(..., min_length=6, max_length=6)
    new_password: str = Field(..., min_length=8, max_length=128)


# ----- Email change ----------------------------------------------------------

@app.post("/api/account/email/request-otp")
def account_email_request_otp(
    payload: EmailChangeRequestOtp,
    current_user: dict = _Depends(_get_current_user),
):
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")

    user_id = current_user["id"]
    current_email = current_user.get("email") or ""

    account = _get_member_account_by_auth_user(user_id)
    is_initial = bool(account and account.get("is_email_dummy"))
    purpose = "email_change_initial" if is_initial else "email_change"

    if payload.new_email == current_email and not is_initial:
        raise HTTPException(status_code=400, detail="New email is the same as your current email.")

    # Identity is proven by (a) the verified session JWT this request carries,
    # and (b) the OTP that will be sent to the new email — which the user must
    # retrieve to complete the change. No current-password re-auth.

    # Reject if the email is already taken by a different auth user.
    try:
        existing = supabase.auth.admin.list_users()
        for u in existing or []:
            if (getattr(u, "email", "") or "").lower() == payload.new_email and str(u.id) != user_id:
                raise HTTPException(status_code=409, detail="That email is already in use.")
    except HTTPException:
        raise
    except Exception:
        pass  # defense-in-depth only; Supabase enforces uniqueness on commit

    try:
        issued = _issue_otp(
            supabase,
            auth_user_id=user_id,
            purpose=purpose,
            payload={"new_email": payload.new_email},
        )
    except PermissionError as exc:
        raise HTTPException(status_code=429, detail=str(exc))
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to issue OTP: {exc}")

    # OTP goes to the NEW email — proves the user owns that inbox.
    _send_otp_or_500(to_email=payload.new_email, code=issued.code, purpose=purpose)

    return {
        "ok": True,
        "purpose": purpose,
        "expires_at": issued.expires_at.isoformat(),
        "message": "A verification code was sent to the new email address.",
    }


@app.post("/api/account/email/confirm")
def account_email_confirm(
    payload: EmailChangeConfirm,
    current_user: dict = _Depends(_get_current_user),
):
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")

    user_id = current_user["id"]
    account = _get_member_account_by_auth_user(user_id)
    is_initial = bool(account and account.get("is_email_dummy"))
    purpose = "email_change_initial" if is_initial else "email_change"

    result = _verify_otp(supabase, auth_user_id=user_id, purpose=purpose, code=payload.code)
    if not result.ok:
        raise HTTPException(status_code=400, detail=result.error or "Invalid code.")

    new_email = (result.payload or {}).get("new_email")
    if not new_email or not _EMAIL_RE_AS.match(new_email):
        raise HTTPException(status_code=500, detail="Stored email payload is invalid.")

    # Commit immediately — OTP-to-new-inbox already proved ownership, so we
    # skip Supabase's secondary confirm link (which would bounce for first-login
    # dummy emails anyway).
    try:
        supabase.auth.admin.update_user_by_id(
            user_id,
            {"email": new_email, "email_confirm": True},
        )
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Email update failed: {exc}")

    if account:
        try:
            # email is synced too: sign-in and password recovery look the
            # account up by it, so a stale value locks the member out.
            supabase.table("member_account").update(
                {"email": new_email, "is_email_dummy": False, "pending_email": None}
            ).eq("auth_user_id", user_id).execute()
        except Exception:
            pass

    return {"ok": True, "new_email": new_email, "is_initial": is_initial}


# ----- Password change -------------------------------------------------------

@app.post("/api/account/password/change-direct")
def account_password_change_direct(
    payload: PasswordChangeDirect,
    current_user: dict = _Depends(_get_current_user),
):
    """One-shot password change for users who know their current password.
    No OTP is sent — the current password itself is the proof of identity."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")

    user_id = current_user["id"]
    current_email = current_user.get("email") or ""
    if not current_email:
        raise HTTPException(status_code=400, detail="Your account has no email on file.")

    err = _validate_password_strength(payload.new_password)
    if err:
        raise HTTPException(status_code=400, detail=err)
    if payload.new_password == payload.current_password:
        raise HTTPException(status_code=400, detail="New password must differ from the current one.")
    if not _verify_current_password(current_email, payload.current_password):
        raise HTTPException(status_code=401, detail="Current password is incorrect.")

    try:
        supabase.auth.admin.update_user_by_id(user_id, {"password": payload.new_password})
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Password update failed: {exc}")

    try:
        supabase.table("member_account").update(
            {"is_temporary": False, "password": None}
        ).eq("auth_user_id", user_id).execute()
    except Exception:
        pass

    return {"ok": True}


@app.post("/api/account/password/request-otp")
def account_password_request_otp(
    payload: PasswordChangeRequestOtp,
    current_user: dict = _Depends(_get_current_user),
):
    """Recovery path — user forgot their current password. We email an OTP to
    their address on file; possession of the inbox is the proof of identity."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")

    user_id = current_user["id"]
    current_email = current_user.get("email") or ""
    if not current_email:
        raise HTTPException(status_code=400, detail="Your account has no email on file.")

    err = _validate_password_strength(payload.new_password)
    if err:
        raise HTTPException(status_code=400, detail=err)

    try:
        issued = _issue_otp(
            supabase,
            auth_user_id=user_id,
            purpose="password_change",
            payload={"new_password": payload.new_password},
        )
    except PermissionError as exc:
        raise HTTPException(status_code=429, detail=str(exc))
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to issue OTP: {exc}")

    _send_otp_or_500(to_email=current_email, code=issued.code, purpose="password_change")

    return {
        "ok": True,
        "expires_at": issued.expires_at.isoformat(),
        "message": "A verification code was sent to your current email address.",
    }


@app.post("/api/account/password/confirm")
def account_password_confirm(
    payload: PasswordChangeConfirm,
    current_user: dict = _Depends(_get_current_user),
):
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")

    user_id = current_user["id"]

    result = _verify_otp(supabase, auth_user_id=user_id, purpose="password_change", code=payload.code)
    if not result.ok:
        raise HTTPException(status_code=400, detail=result.error or "Invalid code.")

    new_password = (result.payload or {}).get("new_password")
    if not new_password or _validate_password_strength(new_password):
        raise HTTPException(status_code=500, detail="Stored password payload is invalid.")

    try:
        supabase.auth.admin.update_user_by_id(user_id, {"password": new_password})
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Password update failed: {exc}")

    # Clear the plaintext temp password and flip is_temporary off.
    try:
        supabase.table("member_account").update(
            {"is_temporary": False, "password": None}
        ).eq("auth_user_id", user_id).execute()
    except Exception:
        pass

    return {"ok": True}


@app.post("/api/account/password/send-code")
def account_password_send_code(
    current_user: dict = _Depends(_get_current_user),
):
    """Recovery path v2 — send an OTP to the user's email on file without
    requiring the new password yet. The new password is provided later at
    /api/account/password/verify-and-set together with the code."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")

    user_id = current_user["id"]
    current_email = current_user.get("email") or ""
    if not current_email:
        raise HTTPException(status_code=400, detail="Your account has no email on file.")

    try:
        issued = _issue_otp(
            supabase,
            auth_user_id=user_id,
            purpose="password_change",
            payload={},
        )
    except PermissionError as exc:
        raise HTTPException(status_code=429, detail=str(exc))
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to issue OTP: {exc}")

    _send_otp_or_500(to_email=current_email, code=issued.code, purpose="password_change")

    return {
        "ok": True,
        "expires_at": issued.expires_at.isoformat(),
        "message": "A verification code was sent to your email address.",
    }


@app.post("/api/account/password/verify-and-set")
def account_password_verify_and_set(
    payload: PasswordChangeVerifyAndSet,
    current_user: dict = _Depends(_get_current_user),
):
    """Recovery path v2 — verify the OTP and set the new password in one
    request. Callers must have first called /api/account/password/send-code."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")

    err = _validate_password_strength(payload.new_password)
    if err:
        raise HTTPException(status_code=400, detail=err)

    user_id = current_user["id"]
    result = _verify_otp(supabase, auth_user_id=user_id, purpose="password_change", code=payload.code)
    if not result.ok:
        raise HTTPException(status_code=400, detail=result.error or "Invalid code.")

    try:
        supabase.auth.admin.update_user_by_id(user_id, {"password": payload.new_password})
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Password update failed: {exc}")

    try:
        supabase.table("member_account").update(
            {"is_temporary": False, "password": None}
        ).eq("auth_user_id", user_id).execute()
    except Exception:
        pass

    return {"ok": True}


# Profile fields a member must supply themselves before the portal unlocks.
#
# Two groups, both required:
#   * Operational  -- contact_number, permanent_address. How the cooperative
#     actually reaches the member.
#   * Credit-risk  -- date_of_birth, occupation, number_of_dependents. These
#     are the ONLY three of the risk model's 21 features that come from the
#     member's own profile (risk_features.py assembles them into Age, OccTier
#     and Dependents). Left blank they reach the model as NaN, so an incomplete
#     profile silently degrades every risk score that member is given. Imputing
#     them is not an option, which makes collecting them up front the fix.
#
# Only member-EDITABLE details belong here. Deliberately excluded:
#   * surname / first_name -- supplied by the cooperative's own records and
#     already populated by the member import.
#   * the whole Membership section (date_of_membership, BOD_resolution_number,
#     number_of_shares, amount, initial_paid_up_capital) -- cooperative
#     financial standing, rendered read-only in the profile UI. A member cannot
#     fill these in, so gating on them would lock them out permanently.
#
# Email is gated separately via is_email_dummy, so it is not repeated here.
#
# Every field here must also be marked `required: true` in PROFILE_SECTIONS
# (Members_Profile.jsx) AND have an input in ProfileStep (AccountSetupGate.jsx).
# Gating on a field the member has no way to fill would lock them out for good.
_REQUIRED_PROFILE_FIELDS = (
    "contact_number",
    "permanent_address",
    "date_of_birth",
    "occupation",
    "number_of_dependents",
)

# number_of_dependents was historically written to a second column. Treat
# either as satisfying the requirement, the way risk_features.py does when it
# builds the Dependents feature -- otherwise members who already answered are
# asked again.
_DEPENDENTS_FALLBACK_COLUMN = "DependentCount"


def _profile_missing_fields(membership_id: str | None) -> list[str]:
    """Disabled: the account-setup gate no longer blocks login on profile
    fields. Members fill these in from their profile page instead. Always
    returns [] so `profile_incomplete` in the security-status response stays
    false regardless of what's on file.
    """
    return []


@app.get("/api/account/security-status")
def account_security_status(current_user: dict = _Depends(_get_current_user)):
    """Onboarding gate consulted by the member route guard.

    Every flag is DERIVED here rather than trusted from the column alone.
    Bulk-imported rows were written before these columns existed, so they carry
    is_temporary = NULL and no is_email_dummy at all -- reading the columns
    straight through let exactly the accounts this gate exists for walk past
    it. Specifically:
      * is_email_dummy also trips on the generated @ttmpc.local address.
      * is_temporary also trips when a plaintext bootstrap `password` is still
        on the row (that column is cleared the moment a real password is set).
    """
    account = _get_member_account_by_auth_user(current_user["id"]) or {}
    email = current_user.get("email") or ""

    is_email_dummy = bool(account.get("is_email_dummy")) or email.lower().endswith(
        _SYNTHETIC_EMAIL_DOMAIN
    )

    is_temporary = bool(account.get("is_temporary")) or bool(account.get("password"))

    missing_profile = _profile_missing_fields(account.get("membership_id"))

    return {
        "ok": True,
        "is_email_dummy": is_email_dummy,
        "is_temporary": is_temporary,
        "profile_incomplete": bool(missing_profile),
        "missing_profile_fields": missing_profile,
        "email": email,
        "pending_email": account.get("pending_email"),
    }


class OnboardingProfilePayload(BaseModel):
    contact_number: str | None = None
    permanent_address: str | None = None
    date_of_birth: str | None = None
    occupation: str | None = None
    number_of_dependents: str | None = None


@app.post("/api/account/onboarding/profile")
def account_onboarding_profile(
    payload: OnboardingProfilePayload,
    current_user: dict = _Depends(_get_current_user),
):
    """Save just the required profile fields from the account-setup gate.

    The gate is a locked modal on the dashboard, so it cannot send the member to
    the full profile page to do this -- that page renders the portal sidebar and
    would hand them the navigation the lock exists to withhold. This writes the
    same personal_data_sheet columns the profile form does, scoped to the two
    fields the gate requires.
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")

    account = _get_member_account_by_auth_user(current_user["id"]) or {}
    membership_id = account.get("membership_id")
    if not membership_id:
        raise HTTPException(status_code=400, detail="Your account has no membership id on file.")

    # Only require whichever fields the gate actually asked for. The gate's
    # form (ProfileStep) only renders inputs for fields still missing per
    # security-status, so a member missing just one of the two never has a
    # chance to fill in the other -- requiring both here unconditionally
    # rejected every such submission with an error for a field the form
    # never showed them.
    still_missing = set(_profile_missing_fields(membership_id))

    contact = str(payload.contact_number or "").strip()
    address = str(payload.permanent_address or "").strip()
    birth = str(payload.date_of_birth or "").strip()
    occupation = str(payload.occupation or "").strip()
    dependents = str(payload.number_of_dependents or "").strip()

    _labels = {
        "contact_number": ("Mobile number", contact),
        "permanent_address": ("Permanent address", address),
        "date_of_birth": ("Date of birth", birth),
        "occupation": ("Occupation", occupation),
        "number_of_dependents": ("Number of dependents", dependents),
    }
    for field, (label, value) in _labels.items():
        if field in still_missing and not value:
            raise HTTPException(status_code=400, detail=f"{label} is required.")

    updates = {}
    if contact:
        # personal_data_sheet.contact_number is text (Simulation findings #9 --
        # it used to be bigint, which silently dropped the leading 0 off every
        # 09xxxxxxxxx number). Store digits only, as text, so the leading 0
        # survives. This also normalises the 09xxxxxxxxx / +639xxxxxxxxx /
        # spaced variants members type into one comparable value.
        digits = _re.sub(r"\D", "", contact)
        if not digits:
            raise HTTPException(status_code=400, detail="Enter a valid mobile number.")
        updates["contact_number"] = digits
    if address:
        updates["permanent_address"] = address
    if birth:
        # Feeds the model's Age feature, so an unparseable date must not be
        # stored -- it would resurface as NaN at scoring time.
        try:
            parsed = datetime.strptime(birth[:10], "%Y-%m-%d").date()
        except ValueError:
            raise HTTPException(status_code=400, detail="Enter a valid date of birth.")
        today = datetime.now().date()
        age = (today - parsed).days / 365.25
        if not (18 <= age <= 100):
            raise HTTPException(
                status_code=400, detail="Date of birth must put you between 18 and 100."
            )
        updates["date_of_birth"] = parsed.isoformat()
    if occupation:
        updates["occupation"] = occupation
    if dependents:
        try:
            count = int(float(dependents))
        except ValueError:
            raise HTTPException(status_code=400, detail="Enter a valid number of dependents.")
        if not (0 <= count <= 20):
            raise HTTPException(status_code=400, detail="Number of dependents must be 0-20.")
        updates["number_of_dependents"] = count

    if not updates:
        raise HTTPException(status_code=400, detail="Nothing to update.")

    try:
        existing = (
            supabase.table("personal_data_sheet")
            .select("personal_data_sheet_id")
            .eq("membership_number_id", membership_id)
            .limit(1)
            .execute()
        )
        if existing.data:
            supabase.table("personal_data_sheet").update(updates).eq(
                "membership_number_id", membership_id
            ).execute()
        else:
            # Imported members can reach the portal with no profile row at all.
            supabase.table("personal_data_sheet").insert(
                {
                    "personal_data_sheet_id": f"pds_{membership_id}_{int(datetime.now().timestamp())}",
                    "membership_number_id": membership_id,
                    **updates,
                }
            ).execute()
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not save your profile: {exc}")

    return {"ok": True, "missing_profile_fields": _profile_missing_fields(membership_id)}


# ============================================================================
# SECTION: Audit log reads
#
# The audit_log table's RLS lets non-BOD staff read only rows where
# actor_user_id = auth.uid(). That never matches for portal staff: every
# cashier/bookkeeper/treasurer write goes through THIS backend on the
# service-role key, so audit_resolve_actor() sees a NULL auth.uid() and stamps
# the row actor_user_id = NULL, actor_role = 'service_role'. The rows exist but
# are invisible to the very staff who created them -- the Cashier audit page
# came back permanently empty.
#
# Reading through the backend (which already holds service role) and scoping by
# the caller's verified role fixes every portal at once, without touching the
# write path or loosening the table's RLS for direct clients.
# ============================================================================

# Roles allowed to open an audit log, and how much they may see.
# BOD sees every row. Every other staff role sees only the actions performed by
# that role (actor_role), e.g. the Cashier sees Cashier activity only — not the
# Bookkeeper's, Members' or other roles' actions on the same records.
_AUDIT_FULL_ACCESS_ROLES = {"bod"}
_AUDIT_STAFF_ROLES = {"manager", "bookkeeper", "treasurer", "cashier", "secretary"}


def _audit_scope_to_role(q, role: str):
    """Limit an audit_log query to what `role` may see. actor_role is stored
    with mixed casing ('Cashier' vs 'bookkeeper'), so match case-insensitively."""
    if role in _AUDIT_FULL_ACCESS_ROLES:
        return q
    return q.ilike("actor_role", role)


def _resolve_staff_role(auth_user_id: str, email: str) -> str:
    """The caller's portal role, from member_account. '' when the account has no role.

    A failed lookup is NOT treated as "no role": the first request after the
    server idles often lands on a stale pooled connection, and swallowing that
    turned a network blip into a false "You do not have access" 403. Retry once
    (a fresh connection usually succeeds), then surface a retryable 503.
    """
    if not supabase:
        return ""

    def lookup() -> list:
        resp = (
            supabase.table("member_account")
            .select("role")
            .or_(f"auth_user_id.eq.{auth_user_id},user_id.eq.{auth_user_id}")
            .limit(1)
            .execute()
        )
        rows = resp.data or []
        if not rows and email:
            resp = (
                supabase.table("member_account")
                .select("role")
                .ilike("email", email)
                .limit(1)
                .execute()
            )
            rows = resp.data or []
        return rows

    try:
        rows = lookup()
    except Exception:
        try:
            rows = lookup()
        except Exception as exc:
            raise HTTPException(
                status_code=503,
                detail=f"Could not verify your role right now, please try again. ({exc})",
            )
    return str((rows[0] if rows else {}).get("role") or "").strip().lower()


@app.get("/api/audit-log")
def read_audit_log(
    current_user: dict = _Depends(_get_current_user),
    module: str | None = None,
    action: str | None = None,
    actor_role: str | None = None,
    date_from: str | None = None,
    date_to: str | None = None,
    search: str | None = None,
    page: int = 1,
    page_size: int = 10,
):
    """Paginated audit log, scoped to what the caller's role may see."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")

    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role not in _AUDIT_FULL_ACCESS_ROLES and role not in _AUDIT_STAFF_ROLES:
        raise HTTPException(status_code=403, detail="You do not have access to the audit log.")

    page = max(1, int(page or 1))
    # 5000 matches the old client-side export ceiling; the on-screen table asks
    # for 10 at a time.
    page_size = min(5000, max(1, int(page_size or 10)))

    def scoped(select_expr: str, *, count_mode: str | None = None):
        q = supabase.table("audit_log").select(
            select_expr, count=count_mode
        ) if count_mode else supabase.table("audit_log").select(select_expr)

        # Role scope, unless BOD (sees everything).
        q = _audit_scope_to_role(q, role)
        # `module` (entity_type) and `action` each accept a comma-separated list,
        # e.g. the "Deposits" filter sends module=savings,cbu.
        modules = [m.strip() for m in (module or "").split(",") if m.strip()]
        if len(modules) == 1:
            q = q.eq("entity_type", modules[0])
        elif modules:
            q = q.in_("entity_type", modules)

        actions = [a.strip() for a in (action or "").split(",") if a.strip()]
        if len(actions) == 1:
            q = q.eq("action", actions[0])
        elif actions:
            q = q.in_("action", actions)
        # The actor_role filter is BOD-only; for anyone else the scope above
        # already pins it to their own role, so a filter can't widen it.
        if actor_role and role in _AUDIT_FULL_ACCESS_ROLES:
            q = q.ilike("actor_role", actor_role.strip())
        if date_from:
            q = q.gte("occurred_at", date_from)
        if date_to:
            q = q.lte("occurred_at", f"{date_to}T23:59:59")
        if search and search.strip():
            s = search.strip()
            q = q.or_(f"entity_id.ilike.%{s}%,actor_email.ilike.%{s}%")
        return q

    start = (page - 1) * page_size

    def run_query():
        return (
            scoped("*", count_mode="exact")
            .order("occurred_at", desc=True)
            .range(start, start + page_size - 1)
            .execute()
        )

    # Same stale-pooled-connection retry as _resolve_staff_role above: the
    # first request after the backend has been idle can hit a dead PostgREST
    # connection and surface as "Server disconnected" even though the query
    # itself is fine. One retry on a fresh connection clears it.
    try:
        resp = run_query()
    except Exception:
        try:
            resp = run_query()
        except Exception as exc:
            raise HTTPException(status_code=500, detail=f"Could not read the audit log: {exc}")

    rows = resp.data or []
    _attach_audit_actor_names(rows)
    _attach_receipt_availability(rows)

    return {
        "ok": True,
        "rows": rows,
        "total": getattr(resp, "count", None) or 0,
        "role": role,
    }


def _attach_audit_actor_names(rows: list[dict]) -> None:
    """Add `actor_name` (and backfill `actor_email`) to each audit row.

    audit_log only stores the actor's auth id/email. Staff accounts link to a
    member record through member_account.membership_id, which holds the real
    name. Two batched lookups for the whole page; a failure just leaves the
    name blank rather than failing the read.
    """
    actor_ids = {str(r.get("actor_user_id")) for r in rows if r.get("actor_user_id")}
    if not actor_ids:
        return
    try:
        accounts = (
            supabase.table("member_account")
            .select("auth_user_id,email,membership_id")
            .in_("auth_user_id", list(actor_ids))
            .execute()
        ).data or []
        membership_ids = list({a["membership_id"] for a in accounts if a.get("membership_id")})
        members = (
            supabase.table("member")
            .select("membership_id,first_name,middle_initial,last_name")
            .in_("membership_id", membership_ids)
            .execute()
        ).data or [] if membership_ids else []
    except Exception as exc:
        logger.warning("Could not resolve audit actor names: %s", exc)
        return

    name_by_membership = {m["membership_id"]: resolve_member_full_name(m) for m in members}
    account_by_id = {str(a["auth_user_id"]): a for a in accounts}
    for r in rows:
        account = account_by_id.get(str(r.get("actor_user_id") or ""))
        if not account:
            continue
        r["actor_name"] = name_by_membership.get(account.get("membership_id"))
        if not r.get("actor_email"):
            r["actor_email"] = account.get("email")


def _attach_receipt_availability(rows: list[dict]) -> None:
    """Add `has_receipt` to each receipt-eligible audit row, so the "View
    receipt" link only shows when one actually exists (e.g. a `cbu` row for
    an ISC reversal or loan-CBU-retention never gets a receipt issued, per
    receipt_is_cbu_deposit() in receipts_04_cbu.sql).

    One lookup per eligible row via the same resolver the receipt endpoint
    uses (_receipt_for_audit_entity), so this can't drift from what
    GET /api/receipts/by-audit actually returns. The audit log page is small
    (10 rows on screen; export maxes at 5000, but no export path renders
    receipt links), so this stays a bounded N calls, not an unbounded scan.
    """
    for r in rows:
        entity_type = r.get("entity_type")
        if entity_type not in _AUDIT_RECEIPT_TYPES:
            continue
        entity_id = str(r.get("entity_id") or "").strip()
        if not entity_id:
            r["has_receipt"] = False
            continue
        try:
            r["has_receipt"] = _receipt_for_audit_entity(entity_type, entity_id) is not None
        except Exception as exc:
            logger.warning("receipt availability check failed for %s %s: %s", entity_type, entity_id, exc)
            r["has_receipt"] = False


@app.get("/api/audit-log/kpis")
def read_audit_log_kpis(current_user: dict = _Depends(_get_current_user)):
    """Headline counts for the audit page, scoped the same way as the rows."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")

    role = _resolve_staff_role(current_user["id"], current_user.get("email") or "")
    if role not in _AUDIT_FULL_ACCESS_ROLES and role not in _AUDIT_STAFF_ROLES:
        raise HTTPException(status_code=403, detail="You do not have access to the audit log.")

    def count(**filters) -> int:
        try:
            q = _audit_scope_to_role(
                supabase.table("audit_log").select("id", count="exact"), role
            )
            for key, value in filters.items():
                if key == "since":
                    q = q.gte("occurred_at", value)
                else:
                    q = q.eq(key, value)
            resp = q.limit(1).execute()
            return getattr(resp, "count", None) or 0
        except Exception:
            return 0

    start_of_day = datetime.now().replace(hour=0, minute=0, second=0, microsecond=0)

    # Each portal's cards reflect the work that role actually does — a fixed
    # set of cash-movement cards read 0 for the Manager, who never moves cash.
    # 'payment' is written by the loan_payments trigger (recorded repayments);
    # 'savings' vs 'withdrawal' are split at the trigger level, so both are
    # exact counts, not derived.
    today = {"since": start_of_day.isoformat()}
    card_specs: dict[str, list[tuple[str, str, dict]]] = {
        "bod": [
            ("loanDisbursements", "Loan Disbursements", {"action": "disburse"}),
            ("loanPayments", "Loan Payments", {"entity_type": "payment"}),
            ("cashDeposits", "Cash Deposits", {"entity_type": "savings"}),
            ("cashWithdrawals", "Cash Withdrawals", {"entity_type": "withdrawal"}),
        ],
        "manager": [
            ("activitiesToday", "Actions Today", today),
            ("loansApproved", "Loans Approved", {"entity_type": "loan", "action": "approve"}),
            ("loansRejected", "Loans Rejected", {"entity_type": "loan", "action": "reject"}),
            ("totalActions", "Total Actions", {}),
        ],
        "bookkeeper": [
            ("activitiesToday", "Actions Today", today),
            ("loansRecommended", "Loans Recommended", {"entity_type": "loan", "action": "recommend"}),
            ("cbuRecorded", "Share Capital Posted", {"entity_type": "cbu"}),
            ("totalActions", "Total Actions", {}),
        ],
        "treasurer": [
            ("activitiesToday", "Actions Today", today),
            ("loanDisbursements", "Loan Disbursements", {"action": "disburse"}),
            ("withdrawalsApproved", "Withdrawals Approved", {"entity_type": "withdrawal", "action": "approve"}),
            ("totalActions", "Total Actions", {}),
        ],
        "cashier": [
            ("loanPayments", "Loan Payments", {"entity_type": "payment"}),
            ("cbuRecorded", "Share Capital Deposits", {"entity_type": "cbu"}),
            ("cashDeposits", "Cash Deposits", {"entity_type": "savings"}),
            ("cashWithdrawals", "Cash Withdrawals", {"entity_type": "withdrawal"}),
        ],
        "secretary": [
            ("activitiesToday", "Actions Today", today),
            ("applicationsReviewed", "Applications Reviewed", {"entity_type": "application"}),
            ("terminations", "Terminations", {"entity_type": "termination"}),
            ("totalActions", "Total Actions", {}),
        ],
    }

    cards = [
        {"key": key, "label": label, "value": count(**filters)}
        for key, label, filters in card_specs.get(role, card_specs["bod"])
    ]
    return {"ok": True, "role": role, "cards": cards}


# =====================================================================
# POS webhook simulator (dev-only) — signs a payload with the shared
# secret and forwards it to the deployed Pos-webhook edge function so
# we can exercise the real pipeline (sig verify → grocery_events →
# GROCERY_TRANSACTIONS → member_grocery_totals) without a live POS.
# =====================================================================

import hmac as _hmac
import hashlib as _hashlib
import uuid as _uuid
from datetime import datetime as _dt, timezone as _tz


# ============================================================================
# SECTION: POS Integration & Dev Simulator
# POS webhook configuration and dev-only endpoints to simulate POS events for
# testing grocery transaction flows. See POS_WEBHOOK_INTEGRATION_NOTES.md.
# ============================================================================

def _pos_webhook_config():
    url = os.environ.get("POS_WEBHOOK_URL") or (
        "https://gcnolzfwmdalltfilmea.supabase.co/functions/v1/Pos-webhook"
    )
    secret = (
        os.environ.get("POS_WEBHOOK_SECRET")
        or os.environ.get("POS_WEBHOOK_SECRET_V2")
        or os.environ.get("VITE_POS_WEBHOOK_SECRET_V2")
    )
    if not secret:
        raise HTTPException(
            status_code=500,
            detail="POS_WEBHOOK_SECRET (or POS_WEBHOOK_SECRET_V2) must be set in .env",
        )
    return url, secret


class PosSimulateRequest(BaseModel):
    membership_id: str = Field(..., description="member.membership_id, e.g. TTMPC-001")
    amount: float = Field(..., gt=0)
    status: Literal["Completed", "On Credit"] = "Completed"
    balance_due: float | None = None
    event_type: Literal["sale", "return", "void"] = "sale"


@app.get("/api/dev/pos-simulator/members")
def dev_pos_simulator_members():
    """Members available for the simulator dropdown."""
    if supabase is None:
        raise HTTPException(500, "Supabase not configured")
    resp = (
        supabase.table("member")
        .select("id, membership_id, first_name, last_name")
        .not_.is_("membership_id", "null")
        .order("membership_id")
        .limit(500)
        .execute()
    )
    return {"members": resp.data or []}


@app.post("/api/dev/simulate-pos-event")
def dev_simulate_pos_event(req: PosSimulateRequest):
    """Sign a synthetic POS payload and POST it to the Pos-webhook edge function.
    Returns the edge function's status + body verbatim."""
    url, secret = _pos_webhook_config()

    event_id = f"evt_sim_{_uuid.uuid4().hex[:16]}"
    grocery_id = f"GR-SIM-{_uuid.uuid4().hex[:10].upper()}"
    event_time = _dt.now(_tz.utc).isoformat().replace("+00:00", "Z")
    balance = req.balance_due if req.balance_due is not None else (
        0.0 if req.status == "Completed" else req.amount
    )

    payload = {
        "event_id": event_id,
        "event_type": req.event_type,
        "event_time": event_time,
        "grocery_id": grocery_id,
        "member_id": req.membership_id,
        "amount_total": round(req.amount, 2),
        "payment_status": req.status,
        "balance_due": round(balance, 2),
    }

    body_bytes = json.dumps(payload, separators=(",", ":")).encode("utf-8")
    signature = _hmac.new(secret.encode("utf-8"), body_bytes, _hashlib.sha256).hexdigest()

    request = urlrequest.Request(
        url,
        data=body_bytes,
        method="POST",
        headers={
            "Content-Type": "application/json",
            "x-pos-signature": signature,
        },
    )

    try:
        with urlrequest.urlopen(request, timeout=15) as resp:
            status_code = resp.status
            response_body = resp.read().decode("utf-8", errors="replace")
    except HTTPError as e:
        status_code = e.code
        response_body = e.read().decode("utf-8", errors="replace") if e.fp else str(e)
    except URLError as e:
        raise HTTPException(502, f"Failed to reach webhook: {e.reason}")

    return {
        "webhook_status": status_code,
        "webhook_response": response_body,
        "payload_sent": payload,
    }


# ---------------------------------------------------------------------------
# Bookkeeper Reports — aggregated dashboard data
# ---------------------------------------------------------------------------

@app.get("/api/bookkeeper/reports")
async def get_bookkeeper_reports():
    """Aggregate all data needed for the Bookkeeper Reports page.

    Returns:
      - kpi: total_loan_portfolio, total_share_capital, total_savings, active_members,
             fully_paid_count, active_loan_count, delinquency_rate, total_penalties_collected
      - loan_type_distribution: count & portfolio value per loan type
      - monthly_collections: last 12 months of validated payment totals
      - membership_growth: last 12 months of new member registrations
      - payment_status_breakdown: validated / pending / rejected counts
      - migs_distribution: MIGS vs Non-MIGS member counts
    """
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase client is not initialized.")

    today = date.today()

    # ── 1. Loans ────────────────────────────────────────────────────────────
    # loan_status on the loans table is unreliable for legacy loans (many are
    # marked 'fully paid' even though outstanding schedule rows remain).
    # Use loan_schedules as the source of truth — same approach as the cashier.
    try:
        loans_resp = (
            supabase.table("loans")
            .select(
                "control_number,member_id,loan_amount,principal_amount,loan_status,application_date,"
                "loan_type:loan_type_id(code,name)"
            )
            .execute()
        )
        all_loans = loans_resp.data or []
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to load loans: {exc}")

    # Collect loan_ids that have at least one outstanding schedule row (paginated).
    _active_schedule_ids: set[str] = set()
    try:
        _offset = 0
        _page = 1000
        while True:
            _batch = (
                supabase.table("loan_schedules")
                .select("loan_id")
                .in_("schedule_status", ["Unpaid", "unpaid", "Pending", "pending", "Overdue", "overdue"])
                .range(_offset, _offset + _page - 1)
                .execute()
            ).data or []
            for _r in _batch:
                if _r.get("loan_id"):
                    _active_schedule_ids.add(str(_r["loan_id"]))
            if len(_batch) < _page:
                break
            _offset += _page
    except Exception:
        _active_schedule_ids = set()

    # Also include loans whose loan_status marks them as in-pipeline (not yet
    # on a schedule but not cancelled/rejected either).
    _pipeline_statuses = {"pending", "approved", "revision_requested", "revised_submitted", "ready for disbursement", "to be disbursed"}
    _excluded_statuses = {"rejected", "cancelled"}
    # loan_status IS authoritative when it already says the loan is done: 432
    # legacy loans are 'fully paid'/'completed'/'closed' but the historical
    # import never closed out their trailing schedule row, so they'd
    # otherwise still match _active_schedule_ids and inflate the active-loan
    # count and delinquency rate (Simulation findings #5).
    _done_statuses = {"fully paid", "completed", "closed"}

    _raw_active = [
        r for r in all_loans
        if str(r.get("loan_status") or "").strip().lower() not in _done_statuses
        and (
            str(r.get("control_number") or "") in _active_schedule_ids
            or (
                str(r.get("loan_status") or "").strip().lower() in _pipeline_statuses
                and str(r.get("loan_status") or "").strip().lower() not in _excluded_statuses
            )
        )
    ]

    # Members renew the same loan type every ~6 months — each renewal is a new
    # loan record. Only the LATEST loan per (member, loan_type) is the current
    # active obligation; predecessors are historical and should not inflate counts.
    # Keep only the most recent loan per (member_id, loan_type_name).
    _latest_by_member_type: dict[tuple, dict] = {}
    for r in sorted(_raw_active, key=lambda x: str(x.get("application_date") or "")):
        mid = str(r.get("member_id") or "")
        lt_name = str((r.get("loan_type") or {}).get("name") or (r.get("loan_type") or {}).get("code") or "Unknown")
        key = (mid, lt_name)
        _latest_by_member_type[key] = r  # later date overwrites earlier

    active_loans = list(_latest_by_member_type.values())

    fully_paid_loans = [
        r for r in all_loans
        if str(r.get("loan_status") or "").strip().lower() in _done_statuses
        or (
            str(r.get("control_number") or "") not in _active_schedule_ids
            and str(r.get("loan_status") or "").strip().lower() not in _pipeline_statuses
            and str(r.get("loan_status") or "").strip().lower() not in _excluded_statuses
        )
    ]

    total_loan_portfolio = sum(
        float(r.get("principal_amount") or r.get("loan_amount") or 0)
        for r in active_loans
    )

    # Loan type distribution (active loans only — deduplicated to latest per member+type)
    type_map: dict[str, dict] = {}
    for r in active_loans:
        lt = (r.get("loan_type") or {})
        name = str(lt.get("name") or lt.get("code") or "Unknown").strip()
        if name not in type_map:
            type_map[name] = {"name": name, "count": 0, "total_amount": 0.0}
        type_map[name]["count"] += 1
        type_map[name]["total_amount"] += float(r.get("principal_amount") or r.get("loan_amount") or 0)

    loan_type_distribution = list(type_map.values())

    # ── 2. Payments ─────────────────────────────────────────────────────────
    # Supabase/PostgREST caps a single .execute() at 1000 rows regardless of
    # filters — with 1600+ payments this was silently dropping rows (incl.
    # the only pending_bookkeeper one) past the cutoff, so pagination is
    # required even though this query has no filter to narrow it.
    try:
        all_payments: list[dict] = []
        page = 1000
        offset = 0
        while True:
            batch = (
                supabase.table("loan_payments")
                .select("id,loan_id,amount_paid,penalties,payment_date,confirmation_status")
                .range(offset, offset + page - 1)
                .execute()
            ).data or []
            if not batch:
                break
            all_payments.extend(batch)
            if len(batch) < page:
                break
            offset += page
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to load payments: {exc}")

    validated_payments = [p for p in all_payments if str(p.get("confirmation_status") or "").strip().lower() == "validated"]
    pending_payments = [p for p in all_payments if str(p.get("confirmation_status") or "").strip().lower() in {"pending_bookkeeper", "pending_verification", "pending"}]
    rejected_payments = [p for p in all_payments if str(p.get("confirmation_status") or "").strip().lower() == "rejected"]

    total_penalties = sum(float(p.get("penalties") or 0) for p in validated_payments)

    # Monthly collections — last 12 months of validated payments
    monthly_collections: dict[str, float] = {}
    for i in range(11, -1, -1):
        ref = date(today.year, today.month, 1) - timedelta(days=i * 30)
        label = ref.strftime("%b %Y")
        monthly_collections[label] = 0.0

    for p in validated_payments:
        raw_date = str(p.get("payment_date") or "").strip()
        if not raw_date:
            continue
        try:
            pd_date = datetime.fromisoformat(raw_date).date()
        except ValueError:
            continue
        label = pd_date.strftime("%b %Y")
        if label in monthly_collections:
            monthly_collections[label] += float(p.get("amount_paid") or 0)

    monthly_collections_list = [
        {"month": k, "collections": round(v, 2)}
        for k, v in monthly_collections.items()
    ]

    # Payment status breakdown
    payment_status_breakdown = {
        "validated": len(validated_payments),
        "pending": len(pending_payments),
        "rejected": len(rejected_payments),
    }

    # Delinquency — loans with no validated payment in last 90 days and still active
    active_loan_ids = {str(r.get("control_number") or "") for r in active_loans}
    recent_cutoff = today - timedelta(days=90)
    recently_paid_ids: set[str] = set()
    for p in validated_payments:
        raw_date = str(p.get("payment_date") or "").strip()
        if not raw_date:
            continue
        try:
            pd_date = datetime.fromisoformat(raw_date).date()
        except ValueError:
            continue
        if pd_date >= recent_cutoff:
            recently_paid_ids.add(str(p.get("loan_id") or "").strip())

    delinquent_ids = active_loan_ids - recently_paid_ids
    delinquency_rate = (len(delinquent_ids) / len(active_loan_ids) * 100) if active_loan_ids else 0.0

    # ── 3. Members ──────────────────────────────────────────────────────────
    try:
        member_table = _resolve_member_table(supabase)
        members_resp = (
            supabase.table(member_table)
            .select("id,membership_id,is_bona_fide,created_at")
            .execute()
        )
        all_members = members_resp.data or []
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Failed to load members: {exc}")

    active_members = [m for m in all_members if m.get("is_bona_fide")]
    total_members = len(all_members)

    # MIGS distribution — read latest snapshot per member from member_classification_temporal.
    # Only counts members who have been scored at least once (by detail view or recompute-all).
    migs_count = 0
    non_migs_count = 0
    unscored_count = 0
    try:
        snap_resp = (
            supabase.table("member_classification_temporal")
            .select("membership_number_id,classification_level_id,accrual_date")
            .order("accrual_date", desc=True)
            .execute()
        )
        # Resolve classification_level_id → code once
        level_ids_resp = (
            supabase.table("classification_level")
            .select("classification_level_id,code")
            .execute()
        )
        level_code_by_id = {
            str(r["classification_level_id"]): str(r.get("code") or "").lower()
            for r in (level_ids_resp.data or [])
        }
        # Keep only the most recent snapshot per member
        seen_snap: set[str] = set()
        for row in (snap_resp.data or []):
            mid = str(row.get("membership_number_id") or "").strip()
            if not mid or mid in seen_snap:
                continue
            seen_snap.add(mid)
            code = level_code_by_id.get(str(row.get("classification_level_id") or ""), "")
            if code == "migs":
                migs_count += 1
            else:
                non_migs_count += 1
        # Members with no snapshot yet
        unscored_count = max(0, total_members - len(seen_snap))
    except Exception:
        # Fallback: approximate with bona-fide status
        migs_count = len(active_members)
        non_migs_count = total_members - migs_count
        unscored_count = 0

    # Membership growth — new registrations last 12 months
    membership_growth: dict[str, int] = {}
    for i in range(11, -1, -1):
        ref = date(today.year, today.month, 1) - timedelta(days=i * 30)
        label = ref.strftime("%b %Y")
        membership_growth[label] = 0

    for m in all_members:
        raw_date = str(m.get("created_at") or "").strip()
        if not raw_date:
            continue
        try:
            m_date = datetime.fromisoformat(raw_date).date()
        except ValueError:
            continue
        label = m_date.strftime("%b %Y")
        if label in membership_growth:
            membership_growth[label] += 1

    membership_growth_list = [
        {"month": k, "new_members": v}
        for k, v in membership_growth.items()
    ]

    # ── 4. Share Capital ────────────────────────────────────────────────────
    # Same figure as the dashboards: each member's current CBU balance
    # (member.share_capital_amount). Reading capital_build_up here missed
    # rows past PostgREST's 1,000-row cap and took the year-end import
    # placeholder as "latest".
    total_share_capital = 0.0
    try:
        total_share_capital = float(_total_member_cbu())
    except Exception:
        total_share_capital = 0.0

    # ── 5. Savings ──────────────────────────────────────────────────────────
    total_savings = 0.0
    try:
        savings_resp = (
            supabase.table("savings_accounts")
            .select("balance")
            .execute()
        )
        total_savings = sum(float(r.get("balance") or 0) for r in (savings_resp.data or []))
    except Exception:
        total_savings = 0.0

    return {
        "success": True,
        "generated_at": datetime.utcnow().isoformat(),
        "kpi": {
            "total_loan_portfolio": round(total_loan_portfolio, 2),
            "total_share_capital": round(total_share_capital, 2),
            "total_savings": round(total_savings, 2),
            "active_members": len(active_members),
            "total_members": total_members,
            "active_loan_count": len(active_loans),
            "active_borrower_count": len({str(r.get("member_id") or "") for r in active_loans if r.get("member_id")}),
            "fully_paid_count": len(fully_paid_loans),
            "delinquency_rate": round(delinquency_rate, 2),
            "total_penalties_collected": round(total_penalties, 2),
        },
        "loan_type_distribution": loan_type_distribution,
        "monthly_collections": monthly_collections_list,
        "membership_growth": membership_growth_list,
        "payment_status_breakdown": payment_status_breakdown,
        "migs_distribution": {
            "migs": migs_count,
            "non_migs": non_migs_count,
            "unscored": unscored_count,
        },
    }

    return {"success": True, "data": {"legacy_master_uuid": legacy_uuid}}


# ============================================================================
# SECTION: Admin — CBU Initial Paid-Up Capital Backfill
# One-time utility to seed capital_build_up rows for members whose initial
# paid-up capital was recorded in membership_payments before the auto-seed
# logic was added to confirm_membership.
# ============================================================================

@app.post("/api/admin/backfill-cbu-initial-capital")
async def backfill_cbu_initial_capital(dry_run: bool = False):
    """Seed capital_build_up rows for confirmed members missing a CBU entry.

    For every member that has a paid INITIAL_PAID_UP_CAPITAL row in
    membership_payments but no row at all in capital_build_up, inserts one
    CBU row using the paid amount as both capital_added and ending_share_capital.

    Query params:
      - dry_run=true  → returns the candidate list without writing anything.
      - dry_run=false → performs the inserts (default).
    """
    if not supabase:
        raise HTTPException(status_code=503, detail="Supabase client is not initialized.")
    _require_service_role()

    # 1. Load all paid INITIAL_PAID_UP_CAPITAL payments.
    try:
        mp_resp = (
            supabase.table("membership_payments")
            .select("application_id, membership_number_id, amount, payment_date")
            .eq("payment_type", "INITIAL_PAID_UP_CAPITAL")
            .eq("payment_status", "paid")
            .limit(2000)
            .execute()
        )
        payment_rows = mp_resp.data or []
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load membership_payments: {err}")

    if not payment_rows:
        return {"dry_run": dry_run, "seeded": 0, "skipped": 0, "details": [], "message": "No paid INITIAL_PAID_UP_CAPITAL payments found."}

    membership_ids = list({str(r["membership_number_id"]).strip() for r in payment_rows if r.get("membership_number_id")})
    application_ids = list({str(r["application_id"]).strip() for r in payment_rows if r.get("application_id")})

    # 2. Load member UUIDs keyed by membership_id.
    member_by_membership: dict[str, str] = {}
    if membership_ids:
        try:
            member_resp = (
                supabase.table("member")
                .select("id, membership_id")
                .in_("membership_id", membership_ids)
                .limit(2000)
                .execute()
            )
            for row in (member_resp.data or []):
                mid = str(row.get("membership_id") or "").strip()
                uuid = str(row.get("id") or "").strip()
                if mid and uuid:
                    member_by_membership[mid] = uuid
        except Exception:
            pass

    # 3. For any payment lacking membership_number_id, resolve via member_applications.
    app_membership: dict[str, str] = {}
    if application_ids:
        try:
            app_resp = (
                supabase.table("member_applications")
                .select("application_id, membership_id")
                .in_("application_id", application_ids)
                .limit(2000)
                .execute()
            )
            for row in (app_resp.data or []):
                app_id = str(row.get("application_id") or "").strip()
                mem_id = str(row.get("membership_id") or "").strip()
                if app_id and mem_id:
                    app_membership[app_id] = mem_id

            extra_mids = [m for m in app_membership.values() if m not in member_by_membership]
            if extra_mids:
                extra_resp = (
                    supabase.table("member")
                    .select("id, membership_id")
                    .in_("membership_id", extra_mids)
                    .limit(2000)
                    .execute()
                )
                for row in (extra_resp.data or []):
                    mid = str(row.get("membership_id") or "").strip()
                    uuid = str(row.get("id") or "").strip()
                    if mid and uuid:
                        member_by_membership[mid] = uuid
        except Exception:
            pass

    # 4. Load the set of member UUIDs that already have at least one CBU row.
    existing_cbu_members: set[str] = set()
    try:
        cbu_resp = (
            supabase.table("capital_build_up")
            .select("member_id")
            .limit(5000)
            .execute()
        )
        for row in (cbu_resp.data or []):
            uid = str(row.get("member_id") or "").strip()
            if uid:
                existing_cbu_members.add(uid)
    except Exception as err:
        raise HTTPException(status_code=500, detail=f"Failed to load capital_build_up: {err}")

    # 5. Process candidates.
    seeded = 0
    skipped = 0
    details = []

    for payment in payment_rows:
        mem_number = str(payment.get("membership_number_id") or "").strip()
        app_id = str(payment.get("application_id") or "").strip()

        member_uuid = member_by_membership.get(mem_number)
        if not member_uuid and app_id:
            resolved_mid = app_membership.get(app_id, "")
            member_uuid = member_by_membership.get(resolved_mid)

        if not member_uuid:
            details.append({"application_id": app_id, "membership_number_id": mem_number, "status": "skipped", "reason": "No confirmed member row found."})
            skipped += 1
            continue

        if member_uuid in existing_cbu_members:
            details.append({"application_id": app_id, "membership_number_id": mem_number, "member_uuid": member_uuid, "status": "skipped", "reason": "CBU row already exists."})
            skipped += 1
            continue

        amount = float(payment.get("amount") or 0)
        tx_date = payment.get("payment_date") or datetime.utcnow().date().isoformat()

        if dry_run:
            details.append({"application_id": app_id, "membership_number_id": mem_number, "member_uuid": member_uuid, "amount": amount, "status": "would_seed"})
            seeded += 1
            continue

        insert_payload = {
            "member_id": member_uuid,
            "transaction_date": tx_date,
            "starting_share_capital": 0.0,
            "capital_added": amount,
            "ending_share_capital": amount,
            "deposit_account": "Initial Paid-Up Capital",
        }
        try:
            supabase.table("capital_build_up").insert(insert_payload).execute()
            existing_cbu_members.add(member_uuid)
            details.append({"application_id": app_id, "membership_number_id": mem_number, "member_uuid": member_uuid, "amount": amount, "status": "seeded"})
            seeded += 1
        except Exception as err:
            details.append({"application_id": app_id, "membership_number_id": mem_number, "member_uuid": member_uuid, "amount": amount, "status": "error", "reason": str(err)})
            skipped += 1

    return {
        "dry_run": dry_run,
        "seeded": seeded,
        "skipped": skipped,
        "details": details,
    }


# ============================================================================
# Receipts (RECEIPT_SYSTEM_PLAN.md §2, §6.3)
# ============================================================================
# Receipts are issued by database triggers (receipts_02_triggers.sql) and read
# only here: the `receipts` table has RLS on with no client policies. Who may
# open a receipt:
#   * its owner (the member) — any login, staff included, sees their own
#   * BOD, Bookkeeper, Manager, Treasurer — every receipt, read-only
#   * Cashier — only a receipt they issued themselves, within a short window
#     after issuing (the pop-up after a release); no lookup list
# Anyone else gets 404, so a receipt's existence isn't revealed.

_RECEIPT_STAFF_ROLES = {"bod", "bookkeeper", "manager", "treasurer"}
_RECEIPT_CASHIER_WINDOW = timedelta(minutes=15)
_RECEIPT_SOURCE_TYPES = {
    "loan_payment", "loan_release", "savings", "cbu",
    "membership_payment", "cbu_payout", "isc", "grocery",
}
_RECEIPT_COLUMNS = "receipt_no,source_type,source_id,member_id,application_id,amount,issued_at,issued_by,snapshot,snapshot_hash"


def _receipt_caller(current_user: dict) -> dict:
    """{id, role, member_id} for the verified caller. member_id is member.id
    (member_account.user_id), the key receipts.member_id uses."""
    auth_id = str(current_user["id"])
    email = current_user.get("email") or ""

    def lookup() -> list:
        rows = (
            supabase.table("member_account")
            .select("role,user_id,membership_id")
            .eq("auth_user_id", auth_id)
            .limit(1)
            .execute()
        ).data or []
        if not rows and email:
            rows = (
                supabase.table("member_account")
                .select("role,user_id,membership_id")
                .eq("email", email)
                .limit(1)
                .execute()
            ).data or []
        return rows

    # Same stale-pooled-connection retry as _resolve_staff_role.
    try:
        rows = lookup()
    except Exception:
        try:
            rows = lookup()
        except Exception as exc:
            raise HTTPException(
                status_code=503,
                detail=f"Could not verify your account right now, please try again. ({exc})",
            )
    row = rows[0] if rows else {}
    return {
        "id": auth_id,
        "role": str(row.get("role") or "").strip().lower(),
        "member_id": str(row.get("user_id") or "") or None,
        "membership_id": str(row.get("membership_id") or "").strip() or None,
    }


def _receipt_issued_at(row: dict) -> datetime | None:
    raw = row.get("issued_at")
    if not raw:
        return None
    try:
        parsed = datetime.fromisoformat(str(raw).replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)


def _authorize_receipt(caller: dict, row: dict) -> bool:
    if caller["member_id"] and str(row.get("member_id") or "") == caller["member_id"]:
        return True
    if caller["role"] in _RECEIPT_STAFF_ROLES:
        return True
    if caller["role"] == "cashier" and str(row.get("issued_by") or "") == caller["id"]:
        issued_at = _receipt_issued_at(row)
        return bool(issued_at and datetime.now(timezone.utc) - issued_at <= _RECEIPT_CASHIER_WINDOW)
    return False


def _log_receipt_view(caller: dict, current_user: dict, row: dict) -> None:
    """Audit a staff member opening someone else's receipt (plan §9). A member
    viewing their own, or staff viewing one they issued, isn't logged. Best-effort: needs receipts_06_audit.sql,
    and a failure never blocks the read."""
    if caller["member_id"] and str(row.get("member_id") or "") == caller["member_id"]:
        return
    # The cashier's pop-up right after recording a transaction is their own
    # receipt, not a lookup of someone else's.
    if str(row.get("issued_by") or "") == caller["id"]:
        return
    try:
        snapshot = row.get("snapshot") or {}
        supabase.table("audit_log").insert({
            "actor_user_id": caller["id"],
            "actor_role": caller["role"] or None,
            "actor_email": current_user.get("email"),
            "entity_type": "receipt",
            "entity_id": row.get("receipt_no"),
            "action": "view",
            "after": None,
            "context": {
                "receipt_no": row.get("receipt_no"),
                "source_type": row.get("source_type"),
                "member_name": (snapshot.get("member") or {}).get("name"),
                "membership_id": (snapshot.get("member") or {}).get("membership_id"),
                "amount": row.get("amount"),
            },
        }).execute()
    except Exception as exc:  # noqa: BLE001
        logger.warning("receipt view audit failed for %s: %s", row.get("receipt_no"), exc)


def _receipt_payload(row: dict) -> dict:
    return {k: row.get(k) for k in (
        "receipt_no", "source_type", "source_id", "amount", "issued_at", "snapshot", "snapshot_hash",
    )}


def _receipt_resolve_owner(row: dict | None) -> dict | None:
    """A membership-fee receipt issued while the payer was still an applicant
    has no member_id. Once the application becomes a member, resolve it so the
    new member can see their own fee receipts."""
    if not row or row.get("member_id") or not row.get("application_id"):
        return row
    try:
        apps = (
            supabase.table("member_applications").select("membership_id")
            .eq("application_id", row["application_id"]).limit(1).execute()
        ).data or []
        membership_id = (apps[0] if apps else {}).get("membership_id")
        if membership_id:
            members = (
                supabase.table("member").select("id")
                .eq("membership_id", membership_id).limit(1).execute()
            ).data or []
            if members:
                return {**row, "member_id": members[0]["id"]}
    except Exception as exc:  # noqa: BLE001
        logger.warning("receipt owner lookup failed for %s: %s", row.get("receipt_no"), exc)
    return row


def _receipt_fetch_one(column: str, value: str, extra: tuple[str, str] | None = None) -> dict | None:
    def run():
        q = supabase.table("receipts").select(_RECEIPT_COLUMNS).eq(column, value)
        if extra:
            q = q.eq(extra[0], extra[1])
        return (q.limit(1).execute()).data or []

    try:
        rows = run()
    except Exception:
        try:
            rows = run()
        except Exception as exc:
            raise HTTPException(status_code=500, detail=f"Could not read the receipt: {exc}")
    return _receipt_resolve_owner(rows[0]) if rows else None


@app.get("/api/receipts/by-source/{source_type}/{source_id}")
def get_receipt_by_source(source_type: str, source_id: str, current_user: dict = _Depends(_get_current_user)):
    """The receipt for one transaction (audit log link, cashier pop-up)."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")
    clean_type = str(source_type or "").strip().lower()
    if clean_type not in _RECEIPT_SOURCE_TYPES:
        raise HTTPException(status_code=404, detail="Receipt not found.")

    caller = _receipt_caller(current_user)
    row = _receipt_fetch_one("source_type", clean_type, ("source_id", str(source_id or "").strip()))
    if not row or not _authorize_receipt(caller, row):
        raise HTTPException(status_code=404, detail="Receipt not found.")
    _log_receipt_view(caller, current_user, row)
    return {"ok": True, "receipt": _receipt_payload(row)}


# audit_log entity_type -> how its entity_id maps to a receipt source.
_AUDIT_RECEIPT_TYPES = {"payment", "disbursement", "cbu", "savings", "withdrawal", "membership_payment", "grocery"}


def _receipt_for_audit_entity(entity_type: str, entity_id: str) -> dict | None:
    """The receipt behind one audit_log row. Most audit rows store the same key
    the receipt uses; CBU stores cbu_deposit_id and savings may store the
    ledger row id, so those two are translated first."""
    if entity_type == "payment":
        return _receipt_fetch_one("source_type", "loan_payment", ("source_id", entity_id))
    if entity_type == "disbursement":
        return _receipt_fetch_one("source_type", "loan_release", ("source_id", entity_id))
    if entity_type == "membership_payment":
        return _receipt_fetch_one("source_type", "membership_payment", ("source_id", entity_id))
    if entity_type == "grocery":
        return _receipt_fetch_one("source_type", "grocery", ("source_id", entity_id))
    if entity_type == "cbu":
        rows = (
            supabase.table("capital_build_up").select("id")
            .or_(f"cbu_deposit_id.eq.{entity_id}" + (f",id.eq.{entity_id}" if _looks_like_uuid(entity_id) else ""))
            .limit(1).execute()
        ).data or []
        return _receipt_fetch_one("source_type", "cbu", ("source_id", str(rows[0]["id"]))) if rows else None
    if entity_type in ("savings", "withdrawal"):
        row = _receipt_fetch_one("source_type", "savings", ("source_id", entity_id))
        if row or not _looks_like_uuid(entity_id):
            return row
        ledger = (
            supabase.table("savings_ledger").select("reference").eq("id", entity_id).limit(1).execute()
        ).data or []
        reference = (ledger[0] if ledger else {}).get("reference")
        return _receipt_fetch_one("source_type", "savings", ("source_id", reference)) if reference else None
    return None


def _looks_like_uuid(value: str) -> bool:
    try:
        UUID(str(value))
        return True
    except (TypeError, ValueError):
        return False


@app.get("/api/receipts/by-audit/{entity_type}/{entity_id}")
def get_receipt_by_audit(entity_type: str, entity_id: str, current_user: dict = _Depends(_get_current_user)):
    """The receipt for an audit log entry ("View receipt" in the audit log)."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")
    clean_type = str(entity_type or "").strip().lower()
    clean_id = re.sub(r"[,()]", "", str(entity_id or "").strip())
    if clean_type not in _AUDIT_RECEIPT_TYPES or not clean_id:
        raise HTTPException(status_code=404, detail="Receipt not found.")

    caller = _receipt_caller(current_user)
    try:
        row = _receipt_for_audit_entity(clean_type, clean_id)
    except HTTPException:
        raise
    except Exception as exc:
        raise HTTPException(status_code=500, detail=f"Could not read the receipt: {exc}")
    if not row or not _authorize_receipt(caller, row):
        raise HTTPException(status_code=404, detail="Receipt not found.")
    _log_receipt_view(caller, current_user, row)
    return {"ok": True, "receipt": _receipt_payload(row)}


@app.get("/api/receipts/{receipt_no}")
def get_receipt(receipt_no: str, current_user: dict = _Depends(_get_current_user)):
    """One receipt by number. 404 when it doesn't exist or isn't the caller's to see."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")

    caller = _receipt_caller(current_user)
    row = _receipt_fetch_one("receipt_no", str(receipt_no or "").strip().upper())
    if not row or not _authorize_receipt(caller, row):
        raise HTTPException(status_code=404, detail="Receipt not found.")
    _log_receipt_view(caller, current_user, row)
    return {"ok": True, "receipt": _receipt_payload(row)}


@app.get("/api/receipts")
def list_receipts(
    current_user: dict = _Depends(_get_current_user),
    search: str | None = None,
    source_type: str | None = None,
    member: str | None = None,
    date_from: str | None = None,
    date_to: str | None = None,
    page: int = 1,
    page_size: int = 10,
):
    """Staff receipt lookup (BOD, Bookkeeper, Manager, Treasurer). Members read
    their own through /api/member/transactions instead."""
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")

    caller = _receipt_caller(current_user)
    if caller["role"] not in _RECEIPT_STAFF_ROLES:
        raise HTTPException(status_code=403, detail="You do not have access to the receipt lookup.")

    page = max(1, int(page or 1))
    page_size = min(50, max(1, int(page_size or 10)))
    start = (page - 1) * page_size

    def clean(text: str | None) -> str:
        # Commas and parentheses would break PostgREST's or() syntax.
        return re.sub(r"[,()]", " ", str(text or "")).strip()

    def run():
        q = supabase.table("receipts").select(_RECEIPT_COLUMNS, count="exact")
        if source_type and source_type.strip().lower() in _RECEIPT_SOURCE_TYPES:
            q = q.eq("source_type", source_type.strip().lower())
        if clean(search):
            q = q.ilike("receipt_no", f"%{clean(search)}%")
        if clean(member):
            m = clean(member)
            q = q.or_(f"snapshot->member->>name.ilike.%{m}%,snapshot->member->>membership_id.ilike.%{m}%")
        if date_from:
            q = q.gte("issued_at", date_from)
        if date_to:
            q = q.lte("issued_at", f"{date_to}T23:59:59+08:00")
        return q.order("issued_at", desc=True).range(start, start + page_size - 1).execute()

    try:
        resp = run()
    except Exception:
        try:
            resp = run()
        except Exception as exc:
            raise HTTPException(status_code=500, detail=f"Could not read receipts: {exc}")

    return {
        "ok": True,
        "rows": [_receipt_payload(r) for r in (resp.data or [])],
        "total": getattr(resp, "count", None) or 0,
        "page": page,
        "page_size": page_size,
    }


# Member transaction feed (RECEIPT_SYSTEM_PLAN.md §3, §6.3) -------------------
# The member's own transactions done through the system, with their status and
# receipt number. Feeds the dashboard's Recent Transaction (page_size=6) and the
# Transactions tab in Statement of Account. Identity comes from the token only;
# these tables are readable by any login (Step 0), so the member's rows are
# picked here, not in the browser.

_MANILA_TZ = timezone(timedelta(hours=8))
_PAYMENT_DONE = {"validated", "confirmed", "bookkeeper_confirmed", "approved"}
_CBU_PAID_BY = {"cash", "check", "gcash", "bank transfer"}  # the Cashier form's "Paid by" options


def _feed_when(value) -> tuple[str, str]:
    """(iso timestamp, YYYY-MM-DD in Philippine time) for sorting and date filters."""
    if not value:
        return "", ""
    try:
        parsed = datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except ValueError:
        return str(value), str(value)[:10]
    if not parsed.tzinfo:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(timezone.utc).isoformat(), parsed.astimezone(_MANILA_TZ).date().isoformat()


def _feed_status(raw: str, done: set[str], pending: set[str]) -> str:
    s = str(raw or "").strip().lower()
    if s in done:
        return "completed"
    if s in pending:
        return "pending"
    if "reject" in s or "cancel" in s:
        return "rejected"
    return "pending"


@app.get("/api/member/transactions")
def member_transactions(
    current_user: dict = _Depends(_get_current_user),
    search: str | None = None,
    type: str | None = None,
    status: str | None = None,
    date_from: str | None = None,
    date_to: str | None = None,
    page: int = 1,
    page_size: int = 10,
):
    if not supabase:
        raise HTTPException(status_code=500, detail="Supabase not configured")

    caller = _receipt_caller(current_user)
    member_id = caller["member_id"]
    membership_id = caller["membership_id"]
    page = max(1, int(page or 1))
    page_size = min(50, max(1, int(page_size or 10)))
    if not member_id:
        return {"ok": True, "rows": [], "total": 0, "page": page, "page_size": page_size}

    def fetch(build):
        try:
            return build().execute().data or []
        except Exception:
            try:
                return build().execute().data or []
            except Exception as exc:
                raise HTTPException(status_code=500, detail=f"Could not load your transactions: {exc}")

    loans = fetch(lambda: supabase.table("loans").select("control_number,loan_type:loan_type_id(name)").eq("member_id", member_id))
    loan_ids = [str(l["control_number"]) for l in loans if l.get("control_number")]
    loan_type_by_id = {str(l["control_number"]): ((l.get("loan_type") or {}).get("name") or "") for l in loans}

    payments = fetch(lambda: supabase.table("loan_payments").select(
        "id,loan_id,amount_paid,penalties,payment_date,confirmation_status,payment_reference,transaction_reference"
    ).in_("loan_id", loan_ids)) if loan_ids else []
    releases = fetch(lambda: supabase.table("disbursement_confirmations").select(
        "id,loan_id,loan_type,loan_amount,net_proceeds,disbursed_at,reference_number"
    ).in_("loan_id", loan_ids)) if loan_ids else []
    savings = fetch(lambda: supabase.table("savings_transaction_queue").select(
        "transaction_id,transaction_type,amount,transaction_status,requested_at"
    ).eq("membership_number_id", membership_id)) if membership_id else []
    savings_accounts = fetch(lambda: supabase.table("savings_accounts").select("account_number").eq("member_id", member_id))
    account_numbers = [a["account_number"] for a in savings_accounts if a.get("account_number")]
    openings = fetch(lambda: supabase.table("savings_ledger").select(
        "reference,amount,posted_at"
    ).in_("account_number", account_numbers).like("reference", "OPEN-%")) if account_numbers else []
    applications = fetch(
        lambda: supabase.table("member_applications").select("application_id").eq("membership_id", membership_id)
    ) if membership_id else []
    application_ids = [a["application_id"] for a in applications if a.get("application_id")]
    fees = fetch(lambda: supabase.table("membership_payments").select(
        "payment_id,payment_type,amount,payment_status,payment_date,created_at,reference_number"
    ).in_("application_id", application_ids)) if application_ids else []
    payouts = fetch(lambda: supabase.table("cbu_payouts").select(
        "id,amount,payout_date,created_at,reference"
    ).eq("member_id", member_id).eq("kind", "payout"))
    isc_lines = fetch(lambda: supabase.table("isc_transactions").select(
        "id,interest_amount,settlement,settled_at"
    ).eq("member_id", member_id).in_("settlement", ["capitalised", "cash"]))
    groceries = fetch(lambda: supabase.table("GROCERY_TRANSACTIONS").select(
        "GroceryID,TransactionDate,GroceryAmount,Status,event_id"
    ).eq("membership_number_id", member_id))
    cbu_rows = fetch(lambda: supabase.table("capital_build_up").select(
        "id,cbu_deposit_id,transaction_date,capital_added,deposit_account,source_loan_id,source_payment_id,source_isc_id,source_backfill_id"
    ).eq("member_id", member_id).gt("capital_added", 0))
    receipts = fetch(lambda: supabase.table("receipts").select("receipt_no,source_type,source_id").eq("member_id", member_id))
    if application_ids:
        # Membership-fee receipts issued before the payer became a member.
        receipts += fetch(
            lambda: supabase.table("receipts").select("receipt_no,source_type,source_id").in_("application_id", application_ids)
        )
    receipt_by_source = {(r["source_type"], str(r["source_id"])): r["receipt_no"] for r in receipts}

    rows: list[dict] = []
    for p in payments:
        when, day = _feed_when(p.get("payment_date"))
        state = _feed_status(p.get("confirmation_status"), _PAYMENT_DONE, {"pending_bookkeeper"})
        rows.append({
            "source_type": "loan_payment",
            "source_id": str(p["id"]),
            "category": "loan",
            "description": f"Loan Payment · {p.get('loan_id')}",
            "amount": decimal_to_float(money(Decimal(str(p.get("amount_paid") or 0)) + Decimal(str(p.get("penalties") or 0)))),
            "direction": "debit",
            "status": state,
            "reference": p.get("payment_reference") or p.get("transaction_reference") or "",
            "when": when,
            "day": day,
        })
    for d in releases:
        when, day = _feed_when(d.get("disbursed_at"))
        loan_type = loan_type_by_id.get(str(d.get("loan_id"))) or d.get("loan_type") or ""
        rows.append({
            "source_type": "loan_release",
            "source_id": str(d["id"]),
            "category": "loan",
            "description": f"Loan Released · {loan_type}" if loan_type else "Loan Released",
            "amount": decimal_to_float(Decimal(str(d.get("net_proceeds") if d.get("net_proceeds") is not None else (d.get("loan_amount") or 0)))),
            "direction": "credit",
            "status": "completed",
            "reference": d.get("reference_number") or "",
            "when": when,
            "day": day,
        })
    for q in savings:
        when, day = _feed_when(q.get("requested_at"))
        is_withdraw = str(q.get("transaction_type") or "").strip().lower().startswith("withdraw")
        rows.append({
            "source_type": "savings",
            "source_id": str(q.get("transaction_id") or ""),
            "category": "savings",
            "description": "Savings Withdrawal" if is_withdraw else "Savings Deposit",
            "amount": decimal_to_float(Decimal(str(q.get("amount") or 0))),
            "direction": "debit" if is_withdraw else "credit",
            "status": _feed_status(q.get("transaction_status"), {"validated", "posted", "completed"}, {"pending_verification", "pending"}),
            "reference": str(q.get("transaction_id") or ""),
            "when": when,
            "day": day,
        })

    for c in cbu_rows:
        # Cashier deposits only — same rule as receipt_is_cbu_deposit() in
        # receipts_04_cbu.sql. System rows (loan CBU retention, paid-up
        # capital, ISC, imports) belong to their parent transaction.
        if (
            str(c.get("deposit_account") or "").strip().lower() not in _CBU_PAID_BY
            or any(c.get(k) for k in ("source_loan_id", "source_payment_id", "source_isc_id", "source_backfill_id"))
        ):
            continue
        when, day = _feed_when(c.get("transaction_date"))
        rows.append({
            "source_type": "cbu",
            "source_id": str(c["id"]),
            "category": "cbu",
            "description": "Capital Build-Up Deposit",
            "amount": decimal_to_float(Decimal(str(c.get("capital_added") or 0))),
            "direction": "credit",
            "status": "completed",
            "reference": c.get("cbu_deposit_id") or "",
            "when": when,
            "day": day,
        })

    for o in openings:
        when, day = _feed_when(o.get("posted_at"))
        rows.append({
            "source_type": "savings", "source_id": str(o["reference"]), "category": "savings",
            "description": "Savings Opening Deposit",
            "amount": decimal_to_float(Decimal(str(o.get("amount") or 0))),
            "direction": "credit", "status": "completed", "reference": str(o["reference"]),
            "when": when, "day": day,
        })
    for f in fees:
        if not str(f.get("payment_id") or "").startswith(("TTMPCMF-", "TTMPCPC-")):
            continue
        when, day = _feed_when(f.get("payment_date") or f.get("created_at"))
        paid_up = str(f.get("payment_type") or "").upper() == "INITIAL_PAID_UP_CAPITAL"
        rows.append({
            "source_type": "membership_payment", "source_id": str(f["payment_id"]), "category": "membership",
            "description": "Initial Paid-Up Capital" if paid_up else "Membership Fee",
            "amount": decimal_to_float(Decimal(str(f.get("amount") or 0))),
            "direction": "debit",
            "status": _feed_status(f.get("payment_status"), {"paid"}, {"pending", "unpaid"}),
            "reference": f.get("reference_number") or f.get("payment_id") or "",
            "when": when, "day": day,
        })
    for po in payouts:
        when, day = _feed_when(po.get("created_at") or po.get("payout_date"))
        rows.append({
            "source_type": "cbu_payout", "source_id": str(po["id"]), "category": "cbu",
            "description": "CBU Exit Payout",
            "amount": decimal_to_float(Decimal(str(po.get("amount") or 0))),
            "direction": "credit", "status": "completed", "reference": po.get("reference") or "",
            "when": when, "day": day,
        })
    for t in isc_lines:
        if Decimal(str(t.get("interest_amount") or 0)) <= 0:
            continue
        when, day = _feed_when(t.get("settled_at"))
        cash = t.get("settlement") == "cash"
        rows.append({
            "source_type": "isc", "source_id": str(t["id"]), "category": "cbu",
            "description": "Interest on Share Capital · " + ("Cash" if cash else "Added to share capital"),
            "amount": decimal_to_float(Decimal(str(t.get("interest_amount") or 0))),
            "direction": "credit", "status": "completed", "reference": "",
            "when": when, "day": day,
        })
    for g in groceries:
        if g.get("Status") != "Completed" or not g.get("event_id"):
            continue
        when, day = _feed_when(g.get("TransactionDate"))
        rows.append({
            "source_type": "grocery", "source_id": str(g["GroceryID"]), "category": "grocery",
            "description": "Grocery Purchase",
            "amount": decimal_to_float(Decimal(str(g.get("GroceryAmount") or 0))),
            "direction": "debit", "status": "completed", "reference": str(g["GroceryID"]),
            "when": when, "day": day,
        })

    for r in rows:
        r["id"] = f"{r['source_type']}:{r['source_id']}"
        r["receipt_no"] = receipt_by_source.get((r["source_type"], r["source_id"])) if r["status"] == "completed" else None

    # Filters
    if type and type.strip().lower() not in ("", "all"):
        rows = [r for r in rows if r["category"] == type.strip().lower()]
    if status and status.strip().lower() not in ("", "all"):
        rows = [r for r in rows if r["status"] == status.strip().lower()]
    if date_from:
        rows = [r for r in rows if r["day"] and r["day"] >= date_from[:10]]
    if date_to:
        rows = [r for r in rows if r["day"] and r["day"] <= date_to[:10]]
    if search and search.strip():
        needle = search.strip().lower()
        rows = [r for r in rows if needle in " ".join(
            str(r.get(k) or "") for k in ("receipt_no", "reference", "description")
        ).lower()]

    rows.sort(key=lambda r: (r["when"], r["id"]), reverse=True)
    start = (page - 1) * page_size
    return {
        "ok": True,
        "rows": rows[start:start + page_size],
        "total": len(rows),
        "page": page,
        "page_size": page_size,
    }
